/// One row in a context menu. Separators divide related action groups and
/// are skipped by keyboard and mouse selection.
#[derive(Debug, Clone, PartialEq, Eq)]
pub enum MenuItem {
    Action(MenuAction),
    ActionWithShortcut { action: MenuAction, shortcut: String },
    LabeledAction { label: String, action: MenuAction },
    Submenu { label: String, items: Vec<MenuItem> },
    Separator,
}

impl MenuItem {
    pub fn action(&self) -> Option<MenuAction> {
        match self {
            MenuItem::Action(action)
            | MenuItem::ActionWithShortcut { action, .. }
            | MenuItem::LabeledAction { action, .. } => Some(*action),
            MenuItem::Submenu { .. } | MenuItem::Separator => None,
        }
    }

    pub fn label(&self) -> Option<&str> {
        match self {
            MenuItem::Action(action) | MenuItem::ActionWithShortcut { action, .. } => {
                Some(action.label())
            }
            MenuItem::LabeledAction { label, .. } => Some(label),
            MenuItem::Submenu { label, .. } => Some(label),
            MenuItem::Separator => None,
        }
    }

    pub fn shortcut(&self) -> Option<&str> {
        match self {
            MenuItem::ActionWithShortcut { shortcut, .. } => Some(shortcut),
            _ => None,
        }
    }

    fn selectable(&self) -> bool {
        !matches!(self, MenuItem::Separator)
    }

    fn submenu(&self) -> Option<&[MenuItem]> {
        match self {
            MenuItem::Submenu { items, .. } => Some(items),
            _ => None,
        }
    }
}

fn menu_scrollbar_track(rect: Rect, total_rows: usize) -> Option<Rect> {
    let visible_rows = usize::from(rect.height.saturating_sub(2));
    (rect.width >= 3 && visible_rows > 0 && total_rows > visible_rows).then_some(Rect {
        x: rect.x + rect.width - 2,
        y: rect.y + 1,
        width: 1,
        height: visible_rows as u16,
    })
}

pub struct MenuLevel {
    pub items: Arc<[MenuItem]>,
    all_items: Arc<[MenuItem]>,
    pub selected: usize,
    pub selection_active: bool,
    pub scroll_offset: usize,
    visible_rows: usize,
    fitted_rows: Option<usize>,
    pub rect: Rect,
}

impl MenuLevel {
    fn new(x: u16, y: u16, items: Vec<MenuItem>) -> Self {
        let content_w = items
            .iter()
            .filter_map(|item| {
                let label = item.label()?;
                let suffix = item
                    .shortcut()
                    .map(|shortcut| shortcut.width() + 2)
                    .unwrap_or(if matches!(item, MenuItem::Submenu { .. }) { 2 } else { 0 });
                Some(label.width() + suffix)
            })
            .max()
            .unwrap_or(0) as u16;
        let width = content_w + 2 + ContextMenu::PAD * 2 + 2;
        let height = items.len() as u16 + 2;
        let selected = items.iter().position(MenuItem::selectable).unwrap_or(0);
        let visible_rows = items.len();
        let items: Arc<[MenuItem]> = items.into();
        Self {
            all_items: items.clone(),
            items,
            selected,
            selection_active: true,
            scroll_offset: 0,
            visible_rows,
            fitted_rows: None,
            rect: Rect { x, y, width, height },
        }
    }

    pub fn fit_to_rows(&mut self, max_rows: usize) {
        if self.fitted_rows == Some(max_rows) {
            return;
        }
        let selected_item = self.items.get(self.selected).cloned();
        let selectable_count = self.all_items.iter().filter(|item| item.selectable()).count();
        let mut separator_budget = max_rows.saturating_sub(selectable_count);
        self.items = if max_rows >= self.all_items.len() {
            self.all_items.clone()
        } else {
            self.all_items
                .iter()
                .filter(|item| match item {
                    MenuItem::Separator if separator_budget > 0 => {
                        separator_budget -= 1;
                        true
                    }
                    MenuItem::Separator => false,
                    _ => true,
                })
                .cloned()
                .collect::<Vec<_>>()
                .into()
        };
        self.selected = selected_item
            .and_then(|selected| self.items.iter().position(|item| *item == selected))
            .or_else(|| self.items.iter().position(MenuItem::selectable))
            .unwrap_or(0);
        self.visible_rows = self.items.len().min(max_rows);
        self.fitted_rows = Some(max_rows);
        self.ensure_selection_visible();
        self.rect.height = self.visible_rows as u16 + 2;
    }

    fn ensure_selection_visible(&mut self) {
        if !self.selection_active || self.visible_rows == 0 || self.items.is_empty() {
            self.scroll_offset = 0;
            return;
        }
        if self.selected < self.scroll_offset {
            self.scroll_offset = self.selected;
        } else if self.selected >= self.scroll_offset + self.visible_rows {
            self.scroll_offset = self.selected + 1 - self.visible_rows;
        }
        self.scroll_offset =
            self.scroll_offset.min(self.items.len().saturating_sub(self.visible_rows));
    }

    fn set_scroll_offset(&mut self, offset: usize) -> bool {
        let offset = offset.min(self.items.len().saturating_sub(self.visible_rows));
        if self.scroll_offset == offset {
            return false;
        }
        self.scroll_offset = offset;
        let end = offset.saturating_add(self.visible_rows).min(self.items.len());
        if (self.selected < offset || self.selected >= end)
            && let Some(relative) = self.items[offset..end].iter().position(MenuItem::selectable)
        {
            self.selected = offset + relative;
        }
        true
    }

    fn scroll_rows(&mut self, delta: isize) -> bool {
        self.set_scroll_offset(self.scroll_offset.saturating_add_signed(delta))
    }

    pub(crate) fn scrollbar_track(&self) -> Option<Rect> {
        menu_scrollbar_track(self.rect, self.items.len())
    }

    pub(crate) fn scrollbar(&self) -> Option<(Rect, (u16, u16))> {
        let track = self.scrollbar_track()?;
        let thumb = viewport_thumb_geometry(
            self.items.len(),
            self.visible_rows,
            self.scroll_offset,
            track.height,
        );
        Some((track, thumb))
    }

    fn replace_items(&mut self, items: Vec<MenuItem>) {
        let items: Arc<[MenuItem]> = items.into();
        self.all_items = items.clone();
        self.items = items;
        self.selected = self.items.iter().position(MenuItem::selectable).unwrap_or(0);
        self.selection_active = true;
        self.scroll_offset = 0;
        self.visible_rows = self.items.len();
        self.fitted_rows = None;
        self.rect.height = self.items.len() as u16 + 2;
    }
}

pub(crate) struct MenuSearch {
    pub label: String,
    pub placeholder: String,
    pub input: TextInput,
    items: Arc<[MenuItem]>,
    lowered_labels: Arc<[String]>,
    fallback: Arc<[MenuItem]>,
}

#[derive(Clone, Copy)]
struct MenuScrollbarDrag {
    depth: usize,
    anchor_y: u16,
    anchor_offset: usize,
}

/// Right-click context menu overlay. The rect includes the border chrome;
/// action rows get a one-cell padding column on each side inside that border,
/// groups are divided by separator rows, and the hover/selection highlight
/// spans the content row including padding, leaving room for an overflow thumb.
pub struct ContextMenu {
    pub levels: Vec<MenuLevel>,
    pub(crate) search: Option<MenuSearch>,
    right_press: (u16, u16),
    right_drag_moved: bool,
    scrollbar_drag: Option<MenuScrollbarDrag>,
    captured_resources: Vec<(MenuAction, Option<MenuActionResource>)>,
}

impl ContextMenu {
    /// Horizontal padding between the menu edge and the item labels.
    pub const PAD: u16 = 1;

    #[cfg(test)]
    fn at(x: u16, y: u16, groups: Vec<Vec<MenuAction>>) -> Self {
        Self::with_groups(
            x,
            y,
            groups
                .into_iter()
                .map(|group| group.into_iter().map(MenuItem::Action).collect())
                .collect(),
        )
    }

    fn with_groups(x: u16, y: u16, groups: Vec<Vec<MenuItem>>) -> Self {
        let mut items = Vec::new();
        for group in groups.into_iter().filter(|group| !group.is_empty()) {
            if !items.is_empty() {
                items.push(MenuItem::Separator);
            }
            items.extend(group);
        }
        ContextMenu {
            levels: vec![MenuLevel::new(x.saturating_sub(1), y.saturating_sub(1), items)],
            search: None,
            right_press: (x, y),
            right_drag_moved: false,
            scrollbar_drag: None,
            captured_resources: Vec::new(),
        }
    }

    fn searchable(
        x: u16,
        y: u16,
        label: impl Into<String>,
        placeholder: impl Into<String>,
        items: Vec<MenuItem>,
        fallback: Vec<MenuItem>,
    ) -> Self {
        let label = label.into();
        let placeholder = placeholder.into();
        let search_items: Arc<[MenuItem]> = items.into();
        let lowered_labels = search_items
            .iter()
            .map(|item| item.label().unwrap_or_default().to_lowercase())
            .collect::<Arc<[String]>>();
        let fallback: Arc<[MenuItem]> = fallback.into();
        let mut visible = fallback.to_vec();
        if !visible.is_empty() && !search_items.is_empty() {
            visible.push(MenuItem::Separator);
        }
        visible.extend(search_items.iter().cloned());
        let mut level = MenuLevel::new(x.saturating_sub(1), y.saturating_sub(1), visible);
        let search_width = label.width() + placeholder.width() + 9;
        level.rect.width = level.rect.width.max(search_width.min(u16::MAX as usize) as u16);
        ContextMenu {
            levels: vec![level],
            search: Some(MenuSearch {
                label,
                placeholder,
                input: TextInput::new(String::new()),
                items: search_items,
                lowered_labels,
                fallback,
            }),
            right_press: (x, y),
            right_drag_moved: false,
            scrollbar_drag: None,
            captured_resources: Vec::new(),
        }
    }

    fn refresh_search(&mut self) {
        let Some(search) = self.search.as_ref() else { return };
        let query = search.input.as_str().trim().to_lowercase();
        let terms = query.split_whitespace().collect::<Vec<_>>();
        let matches = search
            .items
            .iter()
            .zip(search.lowered_labels.iter())
            .filter(|(_, label)| terms.is_empty() || terms.iter().all(|term| label.contains(term)))
            .map(|(item, _)| item.clone())
            .collect::<Vec<_>>();
        let mut visible = search.fallback.to_vec();
        if !matches.is_empty() && !search.fallback.is_empty() {
            visible.push(MenuItem::Separator);
        }
        let first_match = (!terms.is_empty() && !matches.is_empty()).then_some(visible.len());
        visible.extend(matches);
        self.levels.truncate(1);
        self.scrollbar_drag = None;
        if let Some(level) = self.levels.first_mut() {
            level.replace_items(visible);
            if let Some(first_match) = first_match {
                level.selected = first_match;
                level.ensure_selection_visible();
            }
        }
    }

    fn insert_search_text(&mut self, text: &str) -> bool {
        let changed = self.search.as_mut().is_some_and(|search| search.input.insert_str(text));
        if changed {
            self.refresh_search();
        }
        changed
    }

    fn handle_search_key(&mut self, key: &KeyEvent) -> bool {
        let Some(search) = self.search.as_mut() else { return false };
        let changed = search.input.handle_key(key) == InputEvent::Changed;
        if changed {
            self.refresh_search();
        }
        true
    }

    fn actions(&self) -> Vec<MenuAction> {
        fn collect(items: &[MenuItem], actions: &mut Vec<MenuAction>) {
            for item in items {
                if let Some(action) = item.action() {
                    actions.push(action);
                } else if let Some(items) = item.submenu() {
                    collect(items, actions);
                }
            }
        }

        let mut actions = Vec::new();
        if let Some(search) = self.search.as_ref() {
            collect(&search.items, &mut actions);
            collect(&search.fallback, &mut actions);
        } else if let Some(level) = self.levels.first() {
            collect(&level.all_items, &mut actions);
        }
        actions
    }

    fn captured_resource(&self, action: MenuAction) -> Option<Option<MenuActionResource>> {
        self.captured_resources
            .iter()
            .find_map(|(candidate, resource)| (*candidate == action).then(|| resource.clone()))
    }

    /// The item row at a screen cell. Border cells are dead chrome and
    /// never activate an item.
    #[cfg(test)]
    pub fn item_at(&self, x: u16, y: u16) -> Option<usize> {
        self.hit_at(x, y).filter(|(depth, _)| *depth == 0).map(|(_, item)| item)
    }

    pub fn hit_at(&self, x: u16, y: u16) -> Option<(usize, usize)> {
        let (depth, level) =
            self.levels.iter().enumerate().rev().find(|(_, level)| level.rect.contains(x, y))?;
        if level.scrollbar_track().is_some_and(|track| track.contains(x, y)) {
            return None;
        }
        let rect = level.rect;
        let right = rect.x + rect.width.saturating_sub(1);
        let bottom = rect.y + rect.height.saturating_sub(1);
        if x == rect.x || y == rect.y || x == right || y == bottom {
            return None;
        }
        let row = level.scroll_offset + (y - rect.y - 1) as usize;
        level.items.get(row).filter(|item| item.selectable()).map(|_| (depth, row))
    }

    pub fn contains(&self, x: u16, y: u16) -> bool {
        self.levels.iter().any(|level| level.rect.contains(x, y))
    }

    fn scrollbar_at(&self, x: u16, y: u16) -> Option<(usize, Rect)> {
        self.levels.iter().enumerate().rev().find_map(|(depth, level)| {
            level.scrollbar_track().filter(|track| track.contains(x, y)).map(|track| (depth, track))
        })
    }

    fn scroll_at(&mut self, x: u16, y: u16, down: bool) -> bool {
        let Some(depth) = self
            .levels
            .iter()
            .enumerate()
            .rev()
            .find(|(_, level)| level.rect.contains(x, y))
            .map(|(depth, _)| depth)
        else {
            return false;
        };
        self.levels.truncate(depth + 1);
        self.scrollbar_drag = None;
        self.levels[depth].scroll_rows(if down { 3 } else { -3 })
    }

    fn start_scrollbar_drag(&mut self, x: u16, y: u16) -> bool {
        let Some((depth, track)) = self.scrollbar_at(x, y) else {
            return false;
        };
        self.levels.truncate(depth + 1);
        let level = &mut self.levels[depth];
        let relative = y.saturating_sub(track.y).min(track.height.saturating_sub(1));
        let (thumb_y, thumb_height) = viewport_thumb_geometry(
            level.items.len(),
            level.visible_rows,
            level.scroll_offset,
            track.height,
        );
        if relative < thumb_y || relative >= thumb_y.saturating_add(thumb_height) {
            let offset =
                viewport_jump_offset(level.items.len(), level.visible_rows, track.height, relative);
            level.set_scroll_offset(offset);
        }
        self.scrollbar_drag =
            Some(MenuScrollbarDrag { depth, anchor_y: y, anchor_offset: level.scroll_offset });
        true
    }

    fn drag_scrollbar(&mut self, y: u16) -> bool {
        let Some(drag) = self.scrollbar_drag else {
            return false;
        };
        let Some(level) = self.levels.get_mut(drag.depth) else {
            self.scrollbar_drag = None;
            return false;
        };
        let Some(track) = level.scrollbar_track() else {
            self.scrollbar_drag = None;
            return false;
        };
        let offset = viewport_drag_offset(
            level.items.len(),
            level.visible_rows,
            track.height,
            drag.anchor_offset,
            y as i128 - drag.anchor_y as i128,
        );
        level.set_scroll_offset(offset)
    }

    fn finish_scrollbar_drag(&mut self) -> bool {
        self.scrollbar_drag.take().is_some()
    }

    pub(crate) fn scrollbar_dragging(&self, depth: usize) -> bool {
        self.scrollbar_drag.is_some_and(|drag| drag.depth == depth)
    }

    fn selected_action(&self) -> Option<MenuAction> {
        let level = self.levels.last()?;
        if !level.selection_active {
            return None;
        }
        level.items.get(level.selected).and_then(MenuItem::action)
    }

    fn targets_provider_state(&self) -> bool {
        fn item_targets_provider(item: &MenuItem) -> bool {
            match item {
                MenuItem::Action(
                    MenuAction::SelectProviderScope(_)
                    | MenuAction::InvokeProviderAction(_)
                    | MenuAction::RenameManagedMachine(_)
                    | MenuAction::DeleteManagedMachine(_)
                    | MenuAction::RestoreManagedMachine(_)
                    | MenuAction::PurgeManagedMachine(_)
                    | MenuAction::RenameManagedWorkspace(_)
                    | MenuAction::DeleteManagedWorkspace(_)
                    | MenuAction::RestoreManagedWorkspace(_)
                    | MenuAction::PurgeManagedWorkspace(_),
                )
                | MenuItem::LabeledAction {
                    action:
                        MenuAction::SelectProviderScope(_)
                        | MenuAction::InvokeProviderAction(_)
                        | MenuAction::RenameManagedMachine(_)
                        | MenuAction::DeleteManagedMachine(_)
                        | MenuAction::RestoreManagedMachine(_)
                        | MenuAction::PurgeManagedMachine(_)
                        | MenuAction::RenameManagedWorkspace(_)
                        | MenuAction::DeleteManagedWorkspace(_)
                        | MenuAction::RestoreManagedWorkspace(_)
                        | MenuAction::PurgeManagedWorkspace(_),
                    ..
                } => true,
                MenuItem::Submenu { items, .. } => items.iter().any(item_targets_provider),
                MenuItem::Action(_)
                | MenuItem::ActionWithShortcut { .. }
                | MenuItem::LabeledAction { .. }
                | MenuItem::Separator => false,
            }
        }

        if let Some(search) = self.search.as_ref() {
            search.items.iter().chain(search.fallback.iter()).any(item_targets_provider)
        } else {
            self.levels.iter().any(|level| level.all_items.iter().any(item_targets_provider))
        }
    }

    fn action_at(&self, depth: usize, item: usize) -> Option<MenuAction> {
        self.levels.get(depth)?.items.get(item).and_then(MenuItem::action)
    }

    fn open_selected_submenu(&mut self) -> bool {
        let depth = self.levels.len().saturating_sub(1);
        let Some(parent) = self.levels.get(depth) else {
            return false;
        };
        let Some(items) = parent.items.get(parent.selected).and_then(MenuItem::submenu) else {
            return false;
        };
        let x = parent.rect.x.saturating_add(parent.rect.width.saturating_sub(1));
        let y = parent
            .rect
            .y
            .saturating_add(1)
            .saturating_add(parent.selected.saturating_sub(parent.scroll_offset) as u16);
        self.levels.push(MenuLevel::new(x, y, items.to_vec()));
        true
    }

    fn close_submenu(&mut self) -> bool {
        if self.levels.len() > 1 {
            self.levels.pop();
            if self.scrollbar_drag.is_some_and(|drag| drag.depth >= self.levels.len()) {
                self.scrollbar_drag = None;
            }
            true
        } else {
            false
        }
    }

    fn select_at(&mut self, depth: usize, item: usize) -> bool {
        let had_deeper_level = self.levels.len() != depth + 1;
        let Some(level) = self.levels.get_mut(depth) else { return false };
        if !level.items.get(item).is_some_and(MenuItem::selectable) {
            return false;
        }
        let changed = !level.selection_active || level.selected != item || had_deeper_level;
        level.selected = item;
        level.selection_active = true;
        level.ensure_selection_visible();
        self.levels.truncate(depth + 1);
        self.open_selected_submenu();
        changed || self.levels.len() > depth + 1
    }

    /// Keep every action row visible when separators are the only reason the
    /// menu exceeds the available height. Full grouping returns after a resize.
    #[cfg(test)]
    pub fn fit_to_rows(&mut self, max_rows: usize) {
        if let Some(level) = self.levels.first_mut() {
            level.fit_to_rows(max_rows);
        }
    }

    fn select_previous(&mut self) {
        let Some(level) = self.levels.last_mut() else { return };
        if !level.selection_active {
            if let Some(index) = level.items.iter().rposition(MenuItem::selectable) {
                level.selected = index;
                level.selection_active = true;
                level.ensure_selection_visible();
            }
            return;
        }
        if let Some(index) = level
            .items
            .get(..level.selected)
            .and_then(|items| items.iter().rposition(MenuItem::selectable))
        {
            level.selected = index;
            level.ensure_selection_visible();
            let depth = self.levels.len();
            self.levels.truncate(depth);
        }
    }

    fn select_next(&mut self) {
        let Some(level) = self.levels.last_mut() else { return };
        if !level.selection_active {
            if let Some(index) = level.items.iter().position(MenuItem::selectable) {
                level.selected = index;
                level.selection_active = true;
                level.ensure_selection_visible();
            }
            return;
        }
        let start = level.selected.saturating_add(1);
        if let Some(offset) =
            level.items.get(start..).and_then(|items| items.iter().position(MenuItem::selectable))
        {
            level.selected += offset + 1;
            level.ensure_selection_visible();
        }
    }

    fn select_first(&mut self) {
        let Some(level) = self.levels.last_mut() else { return };
        if let Some(index) = level.items.iter().position(MenuItem::selectable) {
            level.selected = index;
            level.selection_active = true;
            level.ensure_selection_visible();
        }
    }

    fn select_last(&mut self) {
        let Some(level) = self.levels.last_mut() else { return };
        if let Some(index) = level.items.iter().rposition(MenuItem::selectable) {
            level.selected = index;
            level.selection_active = true;
            level.ensure_selection_visible();
        }
    }
}

fn pane_context_menu_groups(
    pane: PaneId,
    is_browser: bool,
    external_browser: bool,
) -> Vec<Vec<MenuAction>> {
    let mut browser_actions = Vec::new();
    if is_browser {
        browser_actions.extend([
            MenuAction::BrowserBack(pane),
            MenuAction::BrowserForward(pane),
            MenuAction::BrowserReload(pane),
            MenuAction::BrowserEditUrl(pane),
            MenuAction::BrowserCopyUrl(pane),
        ]);
        if external_browser {
            browser_actions.push(MenuAction::BrowserActivate(pane));
        }
    }
    vec![
        vec![MenuAction::RenameTab(pane), MenuAction::CloseTab(pane)],
        vec![
            MenuAction::NewPaneSmart(pane),
            MenuAction::NewTab(pane),
            MenuAction::NewBrowserTab(pane),
        ],
        browser_actions,
        vec![
            MenuAction::SplitRight(pane),
            MenuAction::SplitDown(pane),
            MenuAction::ClosePane(pane),
        ],
        vec![MenuAction::CopyTabId(pane), MenuAction::CopyPaneId(pane)],
    ]
}

fn client_menu_item(clients: &[ClientInfo], surface: SurfaceId) -> Option<MenuItem> {
    if clients.is_empty() {
        return None;
    }
    let mut items = Vec::new();
    if let Some(current) = clients.iter().find(|client| {
        client.is_self
            && client
                .sizes
                .iter()
                .any(|size| size.surface == surface && size.cols.is_some() && size.rows.is_some())
    }) {
        items.push(MenuItem::Action(MenuAction::UseClientSize { surface, client: current.client }));
    }
    items.extend([
        MenuItem::Action(MenuAction::RestoreAllClientSizing(surface)),
        MenuItem::Separator,
    ]);
    for client in clients {
        let size_info = client.sizes.iter().find(|size| size.surface == surface);
        let reported_size = size_info.and_then(|size| size.cols.zip(size.rows));
        let size_participating = size_info.is_none_or(|size| size.size_participating);
        let identity = client.kind.as_deref().or(client.name.as_deref()).unwrap_or("client");
        let size = reported_size
            .map(|(cols, rows)| format!("{cols}×{rows}"))
            .unwrap_or_else(|| localization::catalog().menu.no_grid.to_string());
        let self_label = if client.is_self {
            format!(" · {}", localization::catalog().menu.this_client)
        } else {
            String::new()
        };
        let sizing_label = if size_participating {
            String::new()
        } else {
            format!(" · {}", localization::catalog().menu.excluded)
        };
        let label = format!("#{} {identity} · {size}{self_label}{sizing_label}", client.client);
        let mut actions = Vec::new();
        if reported_size.is_some() {
            actions.extend([
                MenuItem::Action(MenuAction::UseClientSize { surface, client: client.client }),
                MenuItem::Action(MenuAction::SetClientSizing {
                    surface,
                    client: client.client,
                    enabled: !size_participating,
                }),
            ]);
        }
        if client.client != 0 {
            if !actions.is_empty() {
                actions.push(MenuItem::Separator);
            }
            actions.push(MenuItem::Action(MenuAction::DisconnectClient(client.client)));
        }
        items.push(MenuItem::Submenu { label, items: actions });
    }
    Some(MenuItem::Submenu {
        label: format!("{} ({})", localization::catalog().menu.connected_clients, clients.len()),
        items,
    })
}

/// What a committed rename prompt applies to.
#[derive(Debug, Clone, Copy, PartialEq, Eq)]
pub enum PromptTarget {
    ClientMachine(MachineKey),
    ManagedMachine(MachineKey),
    ConfirmDeleteManagedMachine(MachineKey),
    ConfirmPurgeManagedMachine(MachineKey),
    Workspace(WorkspaceId),
    ManagedWorkspace(WorkspaceId),
    ConfirmPurgeManagedWorkspace(usize),
    Screen(ScreenId),
    Surface(SurfaceId),
    ConnectMachine(MachineConnectRoute),
    ProviderAction(usize),
    ConfirmProviderAction,
    ConfirmLayoutUndo { pane: PaneId, revision: u64 },
}

/// Centered rename dialog: a text input with OK/Cancel buttons. The
/// renderer writes the final geometry back so mouse hit-testing (buttons,
/// dismiss-outside) matches what is drawn.
pub struct Prompt {
    pub label: String,
    pub input: TextInput,
    pub target: PromptTarget,
    /// Dialog rect (set by the renderer each frame).
    pub rect: Rect,
    /// Input / button rects (set by the renderer each frame).
    pub input_rect: Rect,
    pub clear: Rect,
    pub ok: Rect,
    pub cancel: Rect,
}

pub struct PairingDialog {
    pub challenge: PairingChallenge,
    pub rect: Rect,
    pub approve: Rect,
    pub deny: Rect,
}

#[derive(Debug, Clone, PartialEq, Eq)]
pub(crate) enum ConnectionDialogPhase {
    Editing,
    Connecting,
    Starting,
    Failed(String),
}

#[derive(Debug, Clone, PartialEq, Eq)]
pub(crate) struct ConnectionTransaction {
    pub attempt: u64,
    pub target: String,
    pub route: MachineConnectRoute,
    pub phase: ConnectionDialogPhase,
}

impl PairingDialog {
    fn new(challenge: PairingChallenge) -> Self {
        Self { challenge, rect: Rect::default(), approve: Rect::default(), deny: Rect::default() }
    }
}

#[derive(Debug, Default)]
pub struct ShortcutHelp {
    pub rows: Vec<(Action, String)>,
    pub rect: Rect,
    pub scroll_offset: usize,
    pub visible_rows: usize,
    pub close_button: Rect,
    pub scrollbar_track: Rect,
    pub scrollbar_thumb: Rect,
    scrollbar_drag: Option<(u16, usize)>,
}

impl ShortcutHelp {
    fn resolved_rows(config: &Config, surface_only: bool) -> Vec<(Action, String)> {
        let mut rows: Vec<(Action, String)> = config
            .keys
            .resolved_shortcuts()
            .into_iter()
            .filter(|(definition, _)| action_available_in_mode(definition.action, surface_only))
            .map(|(definition, shortcuts)| (definition.action, shortcuts.join(", ")))
            .collect();
        // The default provider-menu chord is contextual to the machine rail,
        // so it is not part of the generic resolved shortcut map.
        if !config.keys.provider_menu_overridden
            && action_available_in_mode(Action::ProviderMenu, surface_only)
        {
            rows.push((Action::ProviderMenu, "m".to_string()));
        }
        for index in 0..config.commands.len() {
            let Some(action) = Action::user_command(index) else { break };
            if !action_available_in_mode(action, surface_only) {
                continue;
            }
            let shortcuts = config.keys.shortcut_labels(action);
            if !shortcuts.is_empty() {
                rows.push((action, shortcuts.join(", ")));
            }
        }
        rows
    }

    fn from_config(config: &Config, surface_only: bool) -> Self {
        Self { rows: Self::resolved_rows(config, surface_only), ..Self::default() }
    }

    fn max_scroll(&self, total_rows: usize) -> usize {
        total_rows.saturating_sub(self.visible_rows)
    }

    fn scroll_by(&mut self, delta: isize, total_rows: usize) {
        self.scroll_offset =
            self.scroll_offset.saturating_add_signed(delta).min(self.max_scroll(total_rows));
    }

    pub(crate) fn scrollbar_geometry(&self, total_rows: usize) -> (u16, u16) {
        viewport_thumb_geometry(
            total_rows,
            self.visible_rows,
            self.scroll_offset,
            self.scrollbar_track.height,
        )
    }

    fn start_scrollbar_drag(&mut self, y: u16, total_rows: usize) {
        if self.scrollbar_track.height == 0 {
            return;
        }
        let relative = y
            .saturating_sub(self.scrollbar_track.y)
            .min(self.scrollbar_track.height.saturating_sub(1));
        let (thumb_y, thumb_height) = self.scrollbar_geometry(total_rows);
        if relative < thumb_y || relative >= thumb_y.saturating_add(thumb_height) {
            self.scroll_offset = viewport_jump_offset(
                total_rows,
                self.visible_rows,
                self.scrollbar_track.height,
                relative,
            );
        }
        self.scrollbar_drag = Some((y, self.scroll_offset));
    }

    fn drag_scrollbar(&mut self, y: u16, total_rows: usize) {
        let Some((anchor_y, anchor_offset)) = self.scrollbar_drag else { return };
        self.scroll_offset = viewport_drag_offset(
            total_rows,
            self.visible_rows,
            self.scrollbar_track.height,
            anchor_offset,
            y as i128 - anchor_y as i128,
        );
    }

    pub(crate) fn scrollbar_dragging(&self) -> bool {
        self.scrollbar_drag.is_some()
    }
}

