/// A durable random id naming this client install for per-client focus
/// memory on the mux (client-focus-v1). Stored next to the TUI config;
/// created on first use.
fn client_focus_identity() -> Option<String> {
    let path = crate::config::config_path().ok()?.parent()?.join("client-id");
    if let Ok(existing) = std::fs::read_to_string(&path) {
        let existing = existing.trim();
        if !existing.is_empty()
            && existing.len() <= 128
            && existing.bytes().all(|byte| byte.is_ascii_graphic())
        {
            return Some(existing.to_string());
        }
    }
    let mut bytes = [0u8; 16];
    getrandom::fill(&mut bytes).ok()?;
    let mut id = String::with_capacity(39);
    id.push_str("client-");
    use std::fmt::Write as _;
    for byte in bytes {
        write!(&mut id, "{byte:02x}").ok()?;
    }
    if let Some(parent) = path.parent() {
        let _ = std::fs::create_dir_all(parent);
    }
    std::fs::write(&path, format!("{id}\n")).ok()?;
    Some(id)
}

fn preserve_client_view(previous: &TreeView, next: &mut TreeView) {
    let workspace_indices = next
        .workspaces
        .iter()
        .enumerate()
        .map(|(index, workspace)| (workspace.id, index))
        .collect::<HashMap<_, _>>();
    if let Some(active) = previous.active_workspace().map(|workspace| workspace.id)
        && let Some(index) = workspace_indices.get(&active).copied()
    {
        next.active_workspace = index;
    }

    for previous_workspace in &previous.workspaces {
        let Some(next_workspace_index) = workspace_indices.get(&previous_workspace.id).copied()
        else {
            continue;
        };
        let next_workspace = &mut next.workspaces[next_workspace_index];
        let screen_indices = next_workspace
            .screens
            .iter()
            .enumerate()
            .map(|(index, screen)| (screen.id, index))
            .collect::<HashMap<_, _>>();
        if let Some(active) =
            previous_workspace.screens.get(previous_workspace.active_screen).map(|screen| screen.id)
            && let Some(index) = screen_indices.get(&active).copied()
        {
            next_workspace.active_screen = index;
        }

        for previous_screen in &previous_workspace.screens {
            let Some(next_screen_index) = screen_indices.get(&previous_screen.id).copied() else {
                continue;
            };
            let next_screen = &mut next_workspace.screens[next_screen_index];
            let pane_indices = next_screen
                .panes
                .iter()
                .enumerate()
                .map(|(index, pane)| (pane.id, index))
                .collect::<HashMap<_, _>>();
            if let Some(zoomed_pane) =
                next_screen.zoomed_pane.filter(|zoomed| pane_indices.contains_key(zoomed))
            {
                next_screen.active_pane = zoomed_pane;
            } else if next_screen.zoomed_pane.is_none()
                && pane_indices.contains_key(&previous_screen.active_pane)
            {
                next_screen.active_pane = previous_screen.active_pane;
            }

            for previous_pane in &previous_screen.panes {
                let Some(next_pane_index) = pane_indices.get(&previous_pane.id).copied() else {
                    continue;
                };
                let next_pane = &mut next_screen.panes[next_pane_index];
                let tab_indices = next_pane
                    .tabs
                    .iter()
                    .enumerate()
                    .map(|(index, tab)| (tab.surface, index))
                    .collect::<HashMap<_, _>>();
                if let Some(active) = previous_pane.active_surface()
                    && let Some(index) = tab_indices.get(&active).copied()
                {
                    next_pane.active_tab = index;
                }
            }
        }
    }
}

const MIN_RAIL_WIDTH: u16 = 10;
const MIN_CONTENT_WIDTH: u16 = 40;
const MIN_TABBED_PANE_HEIGHT: u16 = 3;
const RAIL_REVEAL_HYSTERESIS: u16 = 4;

#[derive(Clone, Copy, Default)]
struct SidebarWidthOverrides {
    workspace: Option<u16>,
    machine: Option<u16>,
    tabs: Option<u16>,
}

fn clamp_rail_width(desired: u16, configured_max: u16, available: u16) -> Option<u16> {
    let configured_max = if configured_max > 0 { configured_max } else { u16::MAX };
    let effective_max = available.min(configured_max);
    // `then_some` evaluates eagerly and would clamp with min > max while the
    // outer terminal is still publishing its initial zero-width geometry.
    (effective_max >= MIN_RAIL_WIDTH).then(|| desired.clamp(MIN_RAIL_WIDTH, effective_max))
}

/// Resolved left and right status segments, in draw order.
type ResolvedStatusSegments = (Vec<StatusSegmentView>, Vec<StatusSegmentView>);

/// The values one status template expansion can interpolate.
struct StatusTemplateValues<'a> {
    session: &'a str,
    workspace: &'a str,
    screen: &'a str,
    screens: &'a str,
    title: &'a str,
    user: &'a str,
}

/// Expand `{variable}` tokens in one left-to-right pass, so an inserted
/// value is never rescanned: a workspace literally named `{screens}` stays
/// `{screens}` in the output. Unknown tokens stay literal.
fn expand_status_tokens(template: &str, values: &StatusTemplateValues<'_>) -> String {
    let mut result = String::with_capacity(template.len() + 16);
    let mut rest = template;
    while let Some(start) = rest.find('{') {
        result.push_str(&rest[..start]);
        let candidate = &rest[start..];
        let Some(end) = candidate.find('}') else {
            result.push_str(candidate);
            return result;
        };
        match &candidate[1..end] {
            "session" => result.push_str(values.session),
            "workspace" => result.push_str(values.workspace),
            "screen" => result.push_str(values.screen),
            "screens" => result.push_str(values.screens),
            "title" => result.push_str(values.title),
            "user" => result.push_str(values.user),
            _ => result.push_str(&candidate[..=end]),
        }
        rest = &candidate[end + 1..];
    }
    result.push_str(rest);
    result
}

/// One status segment resolved for drawing.
#[derive(Clone)]
pub(crate) struct StatusSegmentView {
    pub(crate) text: String,
    pub(crate) fg: Option<Color>,
    pub(crate) bg: Option<Color>,
}

/// Shared stop signal for status workers. `raise` wakes idle waiters
/// immediately, so retiring a worker never waits out a sleep interval, and
/// an idle worker wakes once per interval instead of polling.
struct StatusWorkerStop {
    raised: AtomicBool,
    lock: Mutex<()>,
    condvar: Condvar,
}

impl StatusWorkerStop {
    fn new() -> Self {
        Self { raised: AtomicBool::new(false), lock: Mutex::new(()), condvar: Condvar::new() }
    }

    fn raise(&self) {
        self.raised.store(true, Ordering::Release);
        let _guard = self.lock.lock().unwrap();
        self.condvar.notify_all();
    }

    fn is_raised(&self) -> bool {
        self.raised.load(Ordering::Acquire)
    }

    /// Wait until raised or the duration elapses; returns whether raised.
    fn wait_timeout(&self, duration: Duration) -> bool {
        let deadline = Instant::now() + duration;
        let mut guard = self.lock.lock().unwrap();
        while !self.is_raised() {
            let remaining = deadline.saturating_duration_since(Instant::now());
            if remaining.is_zero() {
                break;
            }
            let (next, _) = self.condvar.wait_timeout(guard, remaining).unwrap();
            guard = next;
        }
        self.is_raised()
    }
}

/// Per-segment status worker: runs one command on its own interval, so one
/// slow command never delays another segment, and publishes on change.
/// The capture path checks the stop flag every poll tick and the idle wait
/// is condvar-based, so a stopped worker exits within milliseconds and an
/// idle worker never busy-polls. The shared `poke` flag coalesces redraw
/// events: when several segments change together, only one event is sent
/// until the event loop consumes it.
struct StatusSegmentWorker {
    index: usize,
    argv: Vec<String>,
    interval: Duration,
    outputs: Arc<Mutex<HashMap<usize, String>>>,
    generation: Arc<AtomicU64>,
    poke: Arc<AtomicBool>,
    events: SyncSender<AppEvent>,
    stop: Arc<StatusWorkerStop>,
}

fn run_status_segment_loop(worker: StatusSegmentWorker) {
    const STATUS_COMMAND_TIMEOUT: Duration = Duration::from_secs(5);
    let StatusSegmentWorker { index, argv, interval, outputs, generation, poke, events, stop } =
        worker;
    let mut pending_notify = false;
    let mut unreaped: Option<std::process::Child> = None;
    while !stop.is_raised() {
        // A previous command stuck in uninterruptible kernel I/O survives
        // SIGKILL; never stack another process behind it, and reap it once
        // the kernel releases it, so stuck processes stay bounded at one
        // per segment with no lasting zombie.
        // A reaped predecessor is dropped by the reassignment below.
        if let Some(child) = unreaped.as_mut()
            && matches!(child.try_wait(), Ok(None))
        {
            if stop.wait_timeout(interval) {
                return;
            }
            continue;
        }
        let (output, stuck_child) = run_status_command(&argv, STATUS_COMMAND_TIMEOUT, &stop);
        unreaped = stuck_child;
        if stop.is_raised() {
            return;
        }
        let changed = {
            let mut map = outputs.lock().unwrap();
            if map.get(&index) != Some(&output) {
                map.insert(index, output);
                true
            } else {
                false
            }
        };
        if changed {
            generation.fetch_add(1, Ordering::Release);
            pending_notify = true;
        }
        try_send_status_poke(&poke, &events, &mut pending_notify);
        // Sleep out the interval, but wake on a short cadence while a poke
        // is still pending so a transiently full event queue delays the
        // update by moments, not by the configured interval. The command
        // itself never re-runs before its interval elapses.
        let deadline = Instant::now() + interval;
        loop {
            let remaining = deadline.saturating_duration_since(Instant::now());
            if remaining.is_zero() {
                break;
            }
            let wait =
                if pending_notify { remaining.min(Duration::from_millis(500)) } else { remaining };
            if stop.wait_timeout(wait) {
                return;
            }
            try_send_status_poke(&poke, &events, &mut pending_notify);
        }
    }
}

/// Attempt to deliver one coalesced status redraw poke. Clears
/// `pending_notify` when this worker's poke was delivered or another
/// worker's poke is already in flight (that draw reads the same shared
/// outputs); releases the poke on a full queue so the retry stays possible.
fn try_send_status_poke(
    poke: &AtomicBool,
    events: &SyncSender<AppEvent>,
    pending_notify: &mut bool,
) {
    if !*pending_notify {
        return;
    }
    if poke.compare_exchange(false, true, Ordering::AcqRel, Ordering::Acquire).is_ok() {
        if events.try_send(AppEvent::StatusCommandsUpdated).is_ok() {
            *pending_notify = false;
        } else {
            poke.store(false, Ordering::Release);
        }
    } else {
        *pending_notify = false;
    }
}

/// Run one status command with a bounded runtime and return its last
/// nonempty stdout line, stripped of escape sequences and length-capped.
/// The capture path uses no reader thread: on Unix the pipe is
/// non-blocking and drained from this loop while the child runs in its own
/// process group (a timeout or stop kills the whole tree), and on Windows
/// stdout goes to a temporary file, which reads without blocking on
/// writers. Setting `stop` makes the call return within one poll tick.
/// The `USER` environment value, read once: template expansion runs on the
/// draw path and the value cannot change within one process.
fn cached_status_user() -> &'static str {
    static USER: std::sync::OnceLock<String> = std::sync::OnceLock::new();
    USER.get_or_init(|| {
        std::env::var("USER").or_else(|_| std::env::var("USERNAME")).unwrap_or_default()
    })
}

/// Returns the segment text plus the child when it could not be reaped
/// (stuck in uninterruptible kernel I/O); the segment loop keeps at most
/// one such child and never starts another command behind it.
fn run_status_command(
    argv: &[String],
    timeout: Duration,
    stop: &StatusWorkerStop,
) -> (String, Option<std::process::Child>) {
    const MAX_STATUS_OUTPUT_CHARS: usize = 200;
    let (captured, stuck_child) = capture_status_output(argv, timeout, stop);
    let text = String::from_utf8_lossy(&captured);
    let line = text.lines().rev().find(|line| !line.trim().is_empty()).unwrap_or("").trim();
    (strip_escape_sequences(line).chars().take(MAX_STATUS_OUTPUT_CHARS).collect(), stuck_child)
}

const MAX_STATUS_OUTPUT_BYTES: usize = 64 * 1024;
const STATUS_POLL_TICK: Duration = Duration::from_millis(25);

#[cfg(unix)]
fn capture_status_output(
    argv: &[String],
    timeout: Duration,
    stop: &StatusWorkerStop,
) -> (Vec<u8>, Option<std::process::Child>) {
    use std::io::Read;

    let Some(program) = argv.first() else { return (Vec::new(), None) };
    let mut command = std::process::Command::new(program);
    command
        .args(&argv[1..])
        .stdin(std::process::Stdio::null())
        .stdout(std::process::Stdio::piped())
        .stderr(std::process::Stdio::null());
    {
        use std::os::unix::process::CommandExt;
        command.process_group(0);
    }
    // Final unlocked stop check directly before the spawn. Holding the
    // raise lock across spawn would let a stalled filesystem block reload
    // and shutdown on the UI thread, so the residual race is resolved the
    // other way: a command that spawns against a concurrent raise is
    // killed at the first poll tick below.
    if stop.is_raised() {
        return (Vec::new(), None);
    }
    let Ok(mut child) = command.spawn() else { return (Vec::new(), None) };
    let mut child_reaped = false;
    let mut stdout = child.stdout.take();
    if let Some(pipe) = stdout.as_ref() {
        use std::os::fd::AsRawFd;
        // SAFETY: fcntl flag update on a pipe fd this function owns.
        let nonblocking = unsafe {
            let fd = pipe.as_raw_fd();
            let flags = libc::fcntl(fd, libc::F_GETFL);
            flags >= 0 && libc::fcntl(fd, libc::F_SETFL, flags | libc::O_NONBLOCK) == 0
        };
        if !nonblocking {
            // Fail closed: a blocking pipe would defeat the deadline and
            // stop checks, so never enter the capture loop with one.
            let reaped = kill_status_command_group(&mut child);
            return (Vec::new(), (!reaped).then_some(child));
        }
    }
    let group = child.id() as i32;
    let deadline = Instant::now() + timeout;
    let mut captured: Vec<u8> = Vec::new();
    let mut exited = false;
    loop {
        // Drain what is available, keeping only the bounded tail so the
        // final line survives even when a command writes more than the cap.
        // Each poll pass reads a bounded amount, so a command that writes
        // continuously cannot keep this loop away from the stop, timeout,
        // and exit checks below.
        if let Some(pipe) = stdout.as_mut() {
            // While the command runs, each pass reads a bounded amount so a
            // continuous writer cannot keep the loop away from the stop and
            // timeout checks. The final pass after exit drains what the pipe
            // buffered (kernels allow enlarged pipes) so the documented last
            // line is the real one; it stays finite so a lingering
            // descendant cannot pin this loop either.
            const EXIT_DRAIN_CAP: usize = 4 * 1024 * 1024;
            let pass_cap = if exited { EXIT_DRAIN_CAP } else { MAX_STATUS_OUTPUT_BYTES };
            let mut chunk = [0u8; 4096];
            let mut drained = 0usize;
            loop {
                if drained >= pass_cap {
                    break;
                }
                match pipe.read(&mut chunk) {
                    Ok(0) => {
                        stdout = None;
                        break;
                    }
                    Ok(read) => {
                        drained += read;
                        captured.extend_from_slice(&chunk[..read]);
                    }
                    Err(error) if error.kind() == std::io::ErrorKind::WouldBlock => break,
                    Err(_) => {
                        stdout = None;
                        break;
                    }
                }
            }
            // Compact to the tail once per pass, not per chunk, so a
            // continuously writing command costs one bounded copy here.
            if captured.len() > MAX_STATUS_OUTPUT_BYTES {
                let excess = captured.len() - MAX_STATUS_OUTPUT_BYTES;
                captured.drain(..excess);
            }
        }
        if exited {
            break;
        }
        if matches!(child.try_wait(), Ok(Some(_))) {
            // One more drain pass picks up bytes written before exit.
            child_reaped = true;
            exited = true;
            continue;
        }
        if stop.is_raised() || Instant::now() >= deadline {
            child_reaped = kill_status_command_group(&mut child);
            exited = true;
            continue;
        }
        std::thread::sleep(STATUS_POLL_TICK);
    }
    // A status command must not outlive its collection: descendants that
    // detached from the exited command (for example `cmd &`) would
    // otherwise accumulate one per interval. Idempotent when the group is
    // already gone.
    // SAFETY: plain syscall on the spawned child's own process group id.
    unsafe {
        libc::kill(-group, libc::SIGKILL);
    }
    (captured, (!child_reaped).then_some(child))
}

#[cfg(windows)]
fn capture_status_output(
    argv: &[String],
    timeout: Duration,
    stop: &StatusWorkerStop,
) -> (Vec<u8>, Option<std::process::Child>) {
    use std::io::{Read, Seek, SeekFrom};
    use std::sync::atomic::AtomicU64;

    static CAPTURE_SEQUENCE: AtomicU64 = AtomicU64::new(0);
    let Some(program) = argv.first() else { return (Vec::new(), None) };
    let path = std::env::temp_dir().join(format!(
        "cmux-status-{}-{}.out",
        std::process::id(),
        CAPTURE_SEQUENCE.fetch_add(1, Ordering::Relaxed)
    ));
    let Ok(file) = std::fs::File::create(&path) else { return (Vec::new(), None) };
    let mut command = std::process::Command::new(program);
    command
        .args(&argv[1..])
        .stdin(std::process::Stdio::null())
        .stdout(std::process::Stdio::from(file))
        .stderr(std::process::Stdio::null());
    // Start suspended so the job assignment below covers the process
    // before it can spawn any descendant; resume only after assignment.
    {
        use std::os::windows::process::CommandExt;
        use windows_sys::Win32::System::Threading::CREATE_SUSPENDED;
        command.creation_flags(CREATE_SUSPENDED);
    }
    // Final unlocked stop check; see the Unix path for the trade-off.
    if stop.is_raised() {
        let _ = std::fs::remove_file(&path);
        return (Vec::new(), None);
    }
    let Ok(mut child) = command.spawn() else {
        let _ = std::fs::remove_file(&path);
        return (Vec::new(), None);
    };
    // The job's kill-on-close limit terminates the whole descendant tree
    // when this function returns, mirroring the Unix process-group kill.
    // Fail closed: without a job there is no tree-kill guarantee, so the
    // suspended child is discarded before it ever runs.
    let job = match StatusCommandJob::assign(&child) {
        Ok(job) => job,
        Err(_) => {
            let _ = child.kill();
            let _ = child.wait();
            let _ = std::fs::remove_file(&path);
            return (Vec::new(), None);
        }
    };
    if resume_suspended_status_child(&child).is_err() {
        job.terminate();
        let _ = child.kill();
        let _ = child.wait();
        let _ = std::fs::remove_file(&path);
        return (Vec::new(), None);
    }
    let mut child_reaped = false;
    let deadline = Instant::now() + timeout;
    loop {
        if matches!(child.try_wait(), Ok(Some(_))) {
            child_reaped = true;
            break;
        }
        // Bound the file while the command runs: a spewing command is
        // killed once the file passes the cap, so it cannot fill the
        // temporary volume for the rest of the timeout. The bound is
        // enforced per poll tick, so up to one tick of disk throughput can
        // land past the cap before the kill; the file is removed below
        // either way.
        let oversized = std::fs::metadata(&path)
            .is_ok_and(|metadata| metadata.len() > MAX_STATUS_OUTPUT_BYTES as u64);
        if oversized || stop.is_raised() || Instant::now() >= deadline {
            job.terminate();
            child_reaped = kill_status_command_group(&mut child);
            break;
        }
        std::thread::sleep(STATUS_POLL_TICK);
    }
    drop(job);
    // A file read never blocks on writers, so lingering descendants cannot
    // pin this call open. Read the bounded tail so the final line survives
    // a command that writes more than the cap.
    let mut captured = Vec::new();
    if let Ok(mut file) = std::fs::File::open(&path) {
        if let Ok(metadata) = file.metadata() {
            let length = metadata.len();
            let cap = MAX_STATUS_OUTPUT_BYTES as u64;
            if length > cap {
                let _ = file.seek(SeekFrom::Start(length - cap));
            }
        }
        let _ = file.take(MAX_STATUS_OUTPUT_BYTES as u64).read_to_end(&mut captured);
    }
    let _ = std::fs::remove_file(&path);
    (captured, (!child_reaped).then_some(child))
}

/// Windows job object with the kill-on-close limit, so every process a
/// status command started dies when the capture returns. Same pattern as
/// the journal hook runner in cmux-tui-core.
#[cfg(windows)]
struct StatusCommandJob {
    handle: windows_sys::Win32::Foundation::HANDLE,
}

#[cfg(windows)]
impl StatusCommandJob {
    fn assign(child: &std::process::Child) -> std::io::Result<Self> {
        use windows_sys::Win32::Foundation::CloseHandle;
        use windows_sys::Win32::System::JobObjects::{
            AssignProcessToJobObject, CreateJobObjectW, JOB_OBJECT_LIMIT_KILL_ON_JOB_CLOSE,
            JOBOBJECT_EXTENDED_LIMIT_INFORMATION, JobObjectExtendedLimitInformation,
            SetInformationJobObject,
        };
        use windows_sys::Win32::System::Threading::{
            OpenProcess, PROCESS_SET_QUOTA, PROCESS_TERMINATE,
        };

        let handle = unsafe { CreateJobObjectW(std::ptr::null(), std::ptr::null()) };
        if handle.is_null() {
            return Err(std::io::Error::last_os_error());
        }
        let job = Self { handle };
        let mut information = JOBOBJECT_EXTENDED_LIMIT_INFORMATION::default();
        information.BasicLimitInformation.LimitFlags = JOB_OBJECT_LIMIT_KILL_ON_JOB_CLOSE;
        let information_size =
            u32::try_from(std::mem::size_of::<JOBOBJECT_EXTENDED_LIMIT_INFORMATION>())
                .expect("Windows job information fits in u32");
        if unsafe {
            SetInformationJobObject(
                job.handle,
                JobObjectExtendedLimitInformation,
                std::ptr::from_ref(&information).cast(),
                information_size,
            )
        } == 0
        {
            return Err(std::io::Error::last_os_error());
        }
        let process = unsafe { OpenProcess(PROCESS_SET_QUOTA | PROCESS_TERMINATE, 0, child.id()) };
        if process.is_null() {
            return Err(std::io::Error::last_os_error());
        }
        let assigned = unsafe { AssignProcessToJobObject(job.handle, process) };
        let assign_error = (assigned == 0).then(std::io::Error::last_os_error);
        unsafe {
            CloseHandle(process);
        }
        if let Some(error) = assign_error {
            return Err(error);
        }
        Ok(job)
    }

    fn terminate(&self) {
        use windows_sys::Win32::System::JobObjects::TerminateJobObject;
        unsafe {
            TerminateJobObject(self.handle, 1);
        }
    }
}

#[cfg(windows)]
impl Drop for StatusCommandJob {
    fn drop(&mut self) {
        use windows_sys::Win32::Foundation::CloseHandle;
        // Kill-on-close terminates any remaining descendants here.
        unsafe {
            CloseHandle(self.handle);
        }
    }
}

/// Resume the suspended status command after its job assignment, same
/// pattern as the journal hook runner in cmux-tui-core.
#[cfg(windows)]
fn resume_suspended_status_child(child: &std::process::Child) -> std::io::Result<()> {
    use windows_sys::Win32::Foundation::{CloseHandle, INVALID_HANDLE_VALUE};
    use windows_sys::Win32::System::Diagnostics::ToolHelp::{
        CreateToolhelp32Snapshot, TH32CS_SNAPTHREAD, THREADENTRY32, Thread32First, Thread32Next,
    };
    use windows_sys::Win32::System::Threading::{OpenThread, ResumeThread, THREAD_SUSPEND_RESUME};

    let snapshot = unsafe { CreateToolhelp32Snapshot(TH32CS_SNAPTHREAD, 0) };
    if snapshot == INVALID_HANDLE_VALUE {
        return Err(std::io::Error::last_os_error());
    }
    let result = (|| {
        let mut thread_entry = THREADENTRY32 {
            dwSize: u32::try_from(std::mem::size_of::<THREADENTRY32>())
                .expect("Windows thread entry size fits in u32"),
            ..THREADENTRY32::default()
        };
        if unsafe { Thread32First(snapshot, &mut thread_entry) } == 0 {
            return Err(std::io::Error::last_os_error());
        }
        loop {
            if thread_entry.th32OwnerProcessID == child.id() {
                let thread =
                    unsafe { OpenThread(THREAD_SUSPEND_RESUME, 0, thread_entry.th32ThreadID) };
                if thread.is_null() {
                    return Err(std::io::Error::last_os_error());
                }
                let resume_result = unsafe { ResumeThread(thread) };
                let resume_error = (resume_result == u32::MAX).then(std::io::Error::last_os_error);
                unsafe {
                    CloseHandle(thread);
                }
                return resume_error.map_or(Ok(()), Err);
            }
            if unsafe { Thread32Next(snapshot, &mut thread_entry) } == 0 {
                return Err(std::io::Error::new(
                    std::io::ErrorKind::NotFound,
                    "suspended status command has no thread to resume",
                ));
            }
        }
    })();
    unsafe {
        CloseHandle(snapshot);
    }
    result
}

/// Kill a status command and, on Unix, its whole process group so every
/// descendant exits with it. Reaping is bounded: a child stuck in
/// uninterruptible kernel I/O survives SIGKILL until the kernel releases
/// it, and blocking on it would transitively hang reload and shutdown.
/// Returns whether the child was reaped; the caller keeps an unreaped
/// child and refuses to start another command behind it.
fn kill_status_command_group(child: &mut std::process::Child) -> bool {
    #[cfg(unix)]
    // SAFETY: plain syscall on the child's own process group id.
    unsafe {
        libc::kill(-(child.id() as i32), libc::SIGKILL);
    }
    let _ = child.kill();
    let deadline = Instant::now() + Duration::from_secs(2);
    loop {
        match child.try_wait() {
            Ok(None) if Instant::now() < deadline => {
                std::thread::sleep(Duration::from_millis(10));
            }
            Ok(None) => return false,
            _ => return true,
        }
    }
}

/// Drop ESC-introduced sequences (CSI/OSC and two-byte escapes) and other
/// control characters so colored tool output degrades to its plain text.
/// Tabs become single spaces.
fn strip_escape_sequences(text: &str) -> String {
    let mut result = String::with_capacity(text.len());
    let mut chars = text.chars().peekable();
    while let Some(character) = chars.next() {
        if character == '\u{1b}' {
            match chars.next() {
                Some('[') => {
                    for terminator in chars.by_ref() {
                        if ('@'..='~').contains(&terminator) {
                            break;
                        }
                    }
                }
                Some(']') => {
                    while let Some(next) = chars.next() {
                        if next == '\u{7}' {
                            break;
                        }
                        if next == '\u{1b}' && chars.peek() == Some(&'\\') {
                            chars.next();
                            break;
                        }
                    }
                }
                _ => {}
            }
            continue;
        }
        if character == '\t' {
            result.push(' ');
        } else if !character.is_control() {
            result.push(character);
        }
    }
    result
}

fn sidebar_layout_for(
    config: &Config,
    visible: bool,
    compact: bool,
    machine_visible: bool,
    size: (u16, u16),
    overrides: SidebarWidthOverrides,
) -> SidebarLayout {
    sidebar_layout_for_state(
        config,
        visible,
        compact,
        machine_visible,
        size,
        overrides.workspace,
        overrides.machine,
        overrides.tabs,
        &HashMap::new(),
        &HashSet::new(),
        None,
    )
}

#[allow(clippy::too_many_arguments)]
fn sidebar_layout_for_state(
    config: &Config,
    visible: bool,
    compact: bool,
    machine_visible: bool,
    size: (u16, u16),
    workspace_override: Option<u16>,
    machine_override: Option<u16>,
    tabs_override: Option<u16>,
    projection_overrides: &HashMap<String, u16>,
    hidden_views: &HashSet<String>,
    previous: Option<&SidebarLayout>,
) -> SidebarLayout {
    let (width, height) = size;
    // The bottom row belongs to the screens status bar unless the user
    // hides it; a hidden bar gives the row back to the panes.
    let content_height = if config.status_bar.visible { height.saturating_sub(1) } else { height };
    if !visible {
        return SidebarLayout {
            content: Rect { x: 0, y: 0, width, height: content_height },
            ..SidebarLayout::default()
        };
    }

    #[derive(Clone, Copy)]
    struct Spec {
        kind: RailKind,
        view_index: usize,
        desired: u16,
        max_width: u16,
        priority: u16,
    }

    let mut specs = config
        .sidebar
        .views
        .iter()
        .enumerate()
        .filter_map(|(view_index, view)| {
            if hidden_views.contains(&view.id) {
                return None;
            }
            if view.includes(SidebarResourceKind::Machines) && !machine_visible {
                return None;
            }
            let kind = match view.legacy_kind() {
                Some(SidebarColumnKind::Machines) => RailKind::Machine,
                Some(SidebarColumnKind::Workspaces) => RailKind::Workspace,
                Some(SidebarColumnKind::Tabs) => RailKind::Tabs,
                None => RailKind::Projection(view_index),
            };
            let width_override = match kind {
                RailKind::Machine => machine_override,
                RailKind::Workspace => workspace_override,
                RailKind::Tabs => tabs_override,
                RailKind::Projection(_) => projection_overrides.get(&view.id).copied(),
            };
            let legacy_width = match kind {
                RailKind::Machine => config.machine_sidebar.width,
                RailKind::Workspace => config.sidebar.width,
                RailKind::Tabs | RailKind::Projection(_) => view.width,
            };
            let desired = if compact && kind == RailKind::Workspace {
                config.sidebar.compact_width
            } else {
                width_override.unwrap_or(if config.sidebar.views_explicit {
                    view.width
                } else {
                    legacy_width
                })
            };
            let max_width = if config.sidebar.views_explicit {
                view.max_width
            } else {
                match kind {
                    RailKind::Machine => config.machine_sidebar.max_width,
                    RailKind::Workspace => config.sidebar.max_width,
                    RailKind::Tabs | RailKind::Projection(_) => view.max_width,
                }
            };
            Some(Spec { kind, view_index, desired, max_width, priority: view.collapse_priority })
        })
        .collect::<Vec<_>>();

    while width
        < MIN_CONTENT_WIDTH.saturating_add(MIN_RAIL_WIDTH.saturating_mul(specs.len() as u16))
    {
        let Some((index, _)) = specs.iter().enumerate().min_by_key(|(_, spec)| spec.priority)
        else {
            break;
        };
        specs.remove(index);
    }

    if let Some(previous) = previous {
        while specs.iter().any(|spec| previous.rail(spec.kind).is_none())
            && width
                < MIN_CONTENT_WIDTH
                    .saturating_add(MIN_RAIL_WIDTH.saturating_mul(specs.len() as u16))
                    .saturating_add(RAIL_REVEAL_HYSTERESIS)
        {
            let Some((index, _)) = specs
                .iter()
                .enumerate()
                .filter(|(_, spec)| previous.rail(spec.kind).is_none())
                .min_by_key(|(_, spec)| spec.priority)
            else {
                break;
            };
            specs.remove(index);
        }
    }

    let mut layout = SidebarLayout::default();
    let mut x = 0u16;
    for (index, spec) in specs.iter().enumerate() {
        let remaining = specs.len().saturating_sub(index + 1) as u16;
        let available = width
            .saturating_sub(MIN_CONTENT_WIDTH)
            .saturating_sub(x)
            .saturating_sub(MIN_RAIL_WIDTH.saturating_mul(remaining));
        let Some(rail_width) = clamp_rail_width(spec.desired, spec.max_width, available) else {
            continue;
        };
        let rect = Rect { x, y: 0, width: rail_width, height };
        match spec.kind {
            RailKind::Machine => layout.machine = Some(rect),
            RailKind::Workspace => layout.workspace = Some(rect),
            RailKind::Tabs => layout.tabs = Some(rect),
            RailKind::Projection(_) => {}
        }
        layout.ordered.push(RailPlacement { kind: spec.kind, view_index: spec.view_index, rect });
        x = x.saturating_add(rail_width);
    }
    layout.content = Rect { x, y: 0, width: width.saturating_sub(x), height: content_height };
    layout
}

fn rail_drag_width(config: &Config, layout: &SidebarLayout, kind: RailKind, x: u16) -> Option<u16> {
    let rail = layout.rail(kind)?;
    let terminal_width = layout.content.x.saturating_add(layout.content.width);
    let other_width = layout
        .ordered
        .iter()
        .filter(|placement| placement.kind != kind)
        .map(|placement| placement.rect.width)
        .fold(0u16, u16::saturating_add);
    let available = terminal_width.saturating_sub(MIN_CONTENT_WIDTH).saturating_sub(other_width);
    let view_index = layout.ordered.iter().find(|placement| placement.kind == kind)?.view_index;
    let view = config.sidebar.views.get(view_index)?;
    let configured_max = if config.sidebar.views_explicit {
        view.max_width
    } else {
        match kind {
            RailKind::Machine => config.machine_sidebar.max_width,
            RailKind::Workspace => config.sidebar.max_width,
            RailKind::Tabs | RailKind::Projection(_) => view.max_width,
        }
    };
    let desired = x.saturating_sub(rail.x).saturating_add(1);
    clamp_rail_width(desired, configured_max, available)
}

fn content_size_for_rect(
    rect: Rect,
    scrollbar: ScrollbarPosition,
    padding: u16,
) -> Option<(u16, u16)> {
    let (_, _, content, _) = pane_parts_for_rect(rect, scrollbar, padding, false);
    (content.width > 0 && content.height > 0).then_some((content.width, content.height))
}

fn browser_content_size_for_rect(
    rect: Rect,
    scrollbar: ScrollbarPosition,
    padding: u16,
) -> Option<(u16, u16)> {
    let (_, _, content, _) = pane_parts_for_rect(rect, scrollbar, padding, true);
    (content.width > 0 && content.height > 0).then_some((content.width, content.height))
}

#[derive(Clone, Copy)]
struct SubtreeMinimumHeight {
    full: u16,
    bar_only: u16,
}

fn minimum_tabbed_height(node: &Node) -> SubtreeMinimumHeight {
    match node {
        Node::Leaf(_) => SubtreeMinimumHeight { full: MIN_TABBED_PANE_HEIGHT, bar_only: 1 },
        Node::Split { dir: SplitDir::Right, a, b, .. } => {
            let first = minimum_tabbed_height(a);
            let second = minimum_tabbed_height(b);
            SubtreeMinimumHeight {
                full: first.full.max(second.full),
                bar_only: first.bar_only.max(second.bar_only),
            }
        }
        Node::Split { dir: SplitDir::Down, ratio, a, b, .. } => {
            let first = minimum_tabbed_height(a);
            let second = minimum_tabbed_height(b);
            SubtreeMinimumHeight {
                full: minimum_split_height(*ratio, first.full, second.full),
                bar_only: minimum_split_height(*ratio, first.bar_only, second.bar_only),
            }
        }
        Node::Stack { panes, .. } => {
            let collapsed_headers =
                u16::try_from(panes.len().saturating_sub(1)).unwrap_or(u16::MAX);
            SubtreeMinimumHeight {
                full: MIN_TABBED_PANE_HEIGHT.saturating_add(collapsed_headers),
                bar_only: 1u16.saturating_add(collapsed_headers),
            }
        }
    }
}

fn minimum_split_height(ratio: f32, first_minimum: u16, second_minimum: u16) -> u16 {
    let fits = |height| {
        let (first, second) =
            split_sides(Rect { width: 1, height, ..Rect::default() }, SplitDir::Down, ratio);
        first.height >= first_minimum && second.height >= second_minimum
    };
    if !fits(u16::MAX) {
        return u16::MAX;
    }

    let mut low = first_minimum.saturating_add(second_minimum).max(2);
    let mut high = u16::MAX;
    while low < high {
        let middle = low + (high - low) / 2;
        if fits(middle) {
            high = middle;
        } else {
            low = middle + 1;
        }
    }
    low
}

fn vertical_split_minimum_heights(
    node: &Node,
    target: SplitId,
) -> Option<(SubtreeMinimumHeight, SubtreeMinimumHeight)> {
    match node {
        Node::Leaf(_) | Node::Stack { .. } => None,
        Node::Split { id, dir, a, b, .. } if *id == target => {
            (*dir == SplitDir::Down).then(|| (minimum_tabbed_height(a), minimum_tabbed_height(b)))
        }
        Node::Split { a, b, .. } => vertical_split_minimum_heights(a, target)
            .or_else(|| vertical_split_minimum_heights(b, target)),
    }
}

fn clamp_ratio_to_minimum_heights(
    height: u16,
    requested: f32,
    first_minimum: u16,
    second_minimum: u16,
) -> Option<f32> {
    let minimum = (f32::from(first_minimum) / f32::from(height)).max(0.05);
    let maximum = (f32::from(height.saturating_sub(second_minimum)) / f32::from(height)).min(0.95);
    (minimum <= maximum).then(|| requested.clamp(minimum, maximum))
}

fn clamp_split_ratio_for_tab_bars(root: &Node, split: SplitId, height: u16, requested: f32) -> f32 {
    let requested = requested.clamp(0.05, 0.95);
    let Some((first_minimum, second_minimum)) = vertical_split_minimum_heights(root, split) else {
        return requested;
    };
    if height == 0 {
        return requested;
    }

    if let Some(clamped) =
        clamp_ratio_to_minimum_heights(height, requested, first_minimum.full, second_minimum.full)
    {
        return clamped;
    }
    clamp_ratio_to_minimum_heights(
        height,
        requested,
        first_minimum.bar_only,
        second_minimum.bar_only,
    )
    .unwrap_or(requested)
}

fn pane_parts_for_rect(
    rect: Rect,
    scrollbar: ScrollbarPosition,
    padding: u16,
    browser_omnibar: bool,
) -> PaneParts<Rect> {
    let (bar, mut content, track) = if rect.width > 2 && rect.height > 2 {
        let reserved_cols = match scrollbar {
            ScrollbarPosition::Column => 3,
            ScrollbarPosition::Border => 2,
        };
        let right_border_x = rect.x + rect.width - 1;
        let track_x = match scrollbar {
            ScrollbarPosition::Column => right_border_x.saturating_sub(1),
            ScrollbarPosition::Border => right_border_x,
        };
        (
            Some(Rect { height: 1, ..rect }),
            Rect {
                x: rect.x + 1,
                y: rect.y + 1,
                width: rect.width.saturating_sub(reserved_cols).max(1),
                height: rect.height - 2,
            },
            Some(Rect { x: track_x, y: rect.y + 1, width: 1, height: rect.height - 2 }),
        )
    } else if rect.width > 2 && rect.height > 0 {
        (
            Some(Rect { height: 1, ..rect }),
            Rect { y: rect.y.saturating_add(1), height: 0, ..rect },
            None,
        )
    } else {
        (None, rect, None)
    };
    // Configured padding: blank cells between border and content, applied
    // only while at least one content cell survives on that axis.
    if content.width > 0 && content.height > 0 {
        let pad_x = padding.min(content.width.saturating_sub(1) / 2);
        let pad_y = padding.min(content.height.saturating_sub(1) / 2);
        content.x = content.x.saturating_add(pad_x);
        content.width = content.width.saturating_sub(pad_x.saturating_mul(2)).max(1);
        content.y = content.y.saturating_add(pad_y);
        content.height = content.height.saturating_sub(pad_y.saturating_mul(2)).max(1);
    }
    let omnibar = if browser_omnibar && content.height >= 2 {
        let row = Rect { height: 1, ..content };
        content.y = content.y.saturating_add(1);
        content.height = content.height.saturating_sub(1);
        Some(row)
    } else {
        None
    };
    (bar, omnibar, content, track)
}

fn stacked_header_parts_for_rect(rect: Rect) -> PaneParts<Rect> {
    (Some(rect), None, Rect { y: rect.y.saturating_add(rect.height), height: 0, ..rect }, None)
}

#[derive(Debug, Clone, PartialEq, Eq)]
pub enum RunOutcome {
    Quit,
    Machine(MachineRequest),
}

struct MachineUpdatePump {
    stop: Arc<AtomicBool>,
    provider: Option<JoinHandle<()>>,
    forwarder: Option<JoinHandle<()>>,
}

enum MachineControllerCommand {
    Perform { request: MachineRequest, preparation: Box<MachineSessionPreparation> },
    SubscribeUpdates,
    AcknowledgeDurableNotice(DurableNoticeDelivery),
    CommitReplacement { action_id: u64, present: bool },
    AbortReplacement(u64),
}

struct MachineSessionPreparation {
    initial_size: Option<(u16, u16)>,
    generation: u64,
    pty_input: PtyInputSender,
    surface_filter: Option<SurfaceId>,
}

struct PreparedMachineSession {
    session: OrderedSession,
    event_worker: SessionEventWorker,
    generation: u64,
    mux_titles: Arc<MuxTitleIngress>,
    mux_recovery_generation: Arc<AtomicU64>,
    tree: TreeView,
    label: String,
    session_available: bool,
    machine: Option<MachineKey>,
}

pub(crate) struct PreparedMachineAction {
    ui: MachineUiState,
    session_mutation: Option<ManagedWorkspaceSessionMutation>,
    session_label: Option<String>,
    session: PreparedMachineSession,
}

struct PendingMachineReplacement {
    action_id: u64,
    present: bool,
    action: PreparedMachineAction,
}

pub(crate) enum MachineControllerCompletion {
    Action {
        result: Result<Box<MachineActionResult>, String>,
        updates: Option<Result<Option<MachineUpdateStream>, String>>,
    },
    ReplacementPrepared {
        action_id: u64,
        action: Box<PreparedMachineAction>,
    },
    ReplacementSettled {
        action_id: u64,
        committed: Result<bool, String>,
        updates: Option<Result<Option<MachineUpdateStream>, String>>,
    },
    Updates(Result<Option<MachineUpdateStream>, String>),
    DurableNoticeAcknowledged {
        delivery: DurableNoticeDelivery,
        result: Result<(), String>,
    },
}

struct MachineActionWorker {
    sender: Option<std::sync::mpsc::SyncSender<MachineControllerCommand>>,
    stop: Arc<AtomicBool>,
    worker: Option<JoinHandle<()>>,
}

#[derive(Debug)]
enum MachineSubmitError {
    Busy(MachineRequest),
    Stopped(MachineRequest),
}

impl MachineActionWorker {
    fn spawn(
        mut controller: Box<dyn MachineController>,
        app_events: SyncSender<AppEvent>,
    ) -> anyhow::Result<Self> {
        let (sender, receiver) = std::sync::mpsc::sync_channel(1);
        let stop = Arc::new(AtomicBool::new(false));
        let worker_stop = stop.clone();
        let worker =
            std::thread::Builder::new().name("machine-actions".into()).spawn(move || {
                let mut next_action_id = 1_u64;
                let mut pending_replacement: Option<(u64, bool)> = None;
                while !worker_stop.load(Ordering::Acquire) {
                    let command = match receiver.recv_timeout(Duration::from_millis(50)) {
                        Ok(command) => command,
                        Err(RecvTimeoutError::Timeout) => continue,
                        Err(RecvTimeoutError::Disconnected) => break,
                    };
                    let completion = match command {
                        MachineControllerCommand::Perform { request, preparation } => {
                            if pending_replacement.is_some() {
                                MachineControllerCompletion::Action {
                                    result: Err(localization::catalog()
                                        .sidebar
                                        .machine_replacement_pending
                                        .to_string()),
                                    updates: None,
                                }
                            } else {
                                match controller.perform(request) {
                                    Ok(MachineActionResult {
                                        ui,
                                        replacement: Some(replacement),
                                        restart_updates,
                                        session_mutation,
                                        session_label,
                                    }) => match prepare_machine_session(
                                        replacement,
                                        &ui,
                                        *preparation,
                                        app_events.clone(),
                                    ) {
                                        Ok(session) => {
                                            let action_id = next_action_id;
                                            next_action_id = next_action_id.wrapping_add(1).max(1);
                                            pending_replacement =
                                                Some((action_id, restart_updates));
                                            MachineControllerCompletion::ReplacementPrepared {
                                                action_id,
                                                action: Box::new(PreparedMachineAction {
                                                    ui,
                                                    session_mutation,
                                                    session_label,
                                                    session,
                                                }),
                                            }
                                        }
                                        Err(error) => {
                                            controller.abort_replacement();
                                            MachineControllerCompletion::Action {
                                                result: Err(error.to_string()),
                                                updates: None,
                                            }
                                        }
                                    },
                                    result => {
                                        let restart_updates = result
                                            .as_ref()
                                            .is_ok_and(|result| result.restart_updates);
                                        let result =
                                            result.map(Box::new).map_err(|error| error.to_string());
                                        let updates = restart_updates.then(|| {
                                            controller
                                                .subscribe_updates()
                                                .map_err(|error| error.to_string())
                                        });
                                        MachineControllerCompletion::Action { result, updates }
                                    }
                                }
                            }
                        }
                        MachineControllerCommand::SubscribeUpdates => {
                            MachineControllerCompletion::Updates(
                                controller.subscribe_updates().map_err(|error| error.to_string()),
                            )
                        }
                        MachineControllerCommand::AcknowledgeDurableNotice(delivery) => {
                            let result = controller
                                .acknowledge_durable_notice(&delivery)
                                .map_err(|error| error.to_string());
                            MachineControllerCompletion::DurableNoticeAcknowledged {
                                delivery,
                                result,
                            }
                        }
                        MachineControllerCommand::CommitReplacement { action_id, present } => {
                            match pending_replacement.take() {
                                Some((pending_id, restart_updates)) if pending_id == action_id => {
                                    let committed = controller
                                        .commit_replacement(present)
                                        .map(|()| true)
                                        .map_err(|error| error.to_string());
                                    if committed.is_err() {
                                        controller.abort_replacement();
                                    }
                                    let updates =
                                        (committed.is_ok() && restart_updates).then(|| {
                                            controller
                                                .subscribe_updates()
                                                .map_err(|error| error.to_string())
                                        });
                                    MachineControllerCompletion::ReplacementSettled {
                                        action_id,
                                        committed,
                                        updates,
                                    }
                                }
                                Some(_) => {
                                    controller.abort_replacement();
                                    MachineControllerCompletion::ReplacementSettled {
                                        action_id,
                                        committed: Err(localization::catalog()
                                            .sidebar
                                            .machine_replacement_stale
                                            .to_string()),
                                        updates: None,
                                    }
                                }
                                None => MachineControllerCompletion::ReplacementSettled {
                                    action_id,
                                    committed: Err(localization::catalog()
                                        .sidebar
                                        .machine_replacement_not_pending
                                        .to_string()),
                                    updates: None,
                                },
                            }
                        }
                        MachineControllerCommand::AbortReplacement(action_id) => {
                            let committed = match pending_replacement.take() {
                                Some((pending_id, _)) if pending_id == action_id => {
                                    controller.abort_replacement();
                                    Ok(false)
                                }
                                Some(_) => {
                                    controller.abort_replacement();
                                    Err(localization::catalog()
                                        .sidebar
                                        .machine_replacement_stale
                                        .to_string())
                                }
                                None => Err(localization::catalog()
                                    .sidebar
                                    .machine_replacement_not_pending
                                    .to_string()),
                            };
                            MachineControllerCompletion::ReplacementSettled {
                                action_id,
                                committed,
                                updates: None,
                            }
                        }
                    };
                    if !send_machine_controller_completion(&app_events, completion, &worker_stop) {
                        break;
                    }
                }
                if pending_replacement.is_some() {
                    controller.abort_replacement();
                }
                controller.close();
            })?;
        Ok(Self { sender: Some(sender), stop, worker: Some(worker) })
    }

    fn perform(
        &self,
        request: MachineRequest,
        preparation: MachineSessionPreparation,
    ) -> Result<(), MachineSubmitError> {
        let Some(sender) = self.sender.as_ref() else {
            return Err(MachineSubmitError::Stopped(request));
        };
        match sender.try_send(MachineControllerCommand::Perform {
            request,
            preparation: Box::new(preparation),
        }) {
            Ok(()) => Ok(()),
            Err(StdTrySendError::Full(command)) => Err(MachineSubmitError::Busy(match command {
                MachineControllerCommand::Perform { request, .. } => request,
                MachineControllerCommand::SubscribeUpdates => {
                    unreachable!("perform returned a subscription command")
                }
                MachineControllerCommand::AcknowledgeDurableNotice(_) => {
                    unreachable!("perform returned a durable notice acknowledgement")
                }
                MachineControllerCommand::CommitReplacement { .. }
                | MachineControllerCommand::AbortReplacement(_) => {
                    unreachable!("perform returned a replacement decision")
                }
            })),
            Err(StdTrySendError::Disconnected(command)) => {
                Err(MachineSubmitError::Stopped(match command {
                    MachineControllerCommand::Perform { request, .. } => request,
                    MachineControllerCommand::SubscribeUpdates => {
                        unreachable!("perform returned a subscription command")
                    }
                    MachineControllerCommand::AcknowledgeDurableNotice(_) => {
                        unreachable!("perform returned a durable notice acknowledgement")
                    }
                    MachineControllerCommand::CommitReplacement { .. }
                    | MachineControllerCommand::AbortReplacement(_) => {
                        unreachable!("perform returned a replacement decision")
                    }
                }))
            }
        }
    }

    fn subscribe_updates(&self) -> bool {
        self.sender.as_ref().is_some_and(|sender| {
            sender.try_send(MachineControllerCommand::SubscribeUpdates).is_ok()
        })
    }

    fn acknowledge_durable_notice(
        &self,
        delivery: DurableNoticeDelivery,
    ) -> Result<(), DurableNoticeDelivery> {
        let Some(sender) = self.sender.as_ref() else {
            return Err(delivery);
        };
        match sender.try_send(MachineControllerCommand::AcknowledgeDurableNotice(delivery)) {
            Ok(()) => Ok(()),
            Err(StdTrySendError::Full(MachineControllerCommand::AcknowledgeDurableNotice(
                delivery,
            )))
            | Err(StdTrySendError::Disconnected(
                MachineControllerCommand::AcknowledgeDurableNotice(delivery),
            )) => Err(delivery),
            Err(StdTrySendError::Full(_)) | Err(StdTrySendError::Disconnected(_)) => {
                unreachable!("durable notice sender returned a different command")
            }
        }
    }

    fn commit_replacement(&self, action_id: u64, present: bool) -> bool {
        self.sender.as_ref().is_some_and(|sender| {
            sender
                .try_send(MachineControllerCommand::CommitReplacement { action_id, present })
                .is_ok()
        })
    }

    fn abort_replacement(&self, action_id: u64) -> bool {
        self.sender.as_ref().is_some_and(|sender| {
            sender.try_send(MachineControllerCommand::AbortReplacement(action_id)).is_ok()
        })
    }

    fn shutdown(&mut self) {
        self.stop.store(true, Ordering::Release);
        self.sender.take();
        if self.worker.as_ref().is_some_and(JoinHandle::is_finished)
            && let Some(worker) = self.worker.take()
        {
            let _ = worker.join();
        }
        // A provider action has a bounded transport deadline but may still be
        // in progress. Dropping the handle detaches that bounded cleanup so
        // quitting the TUI never waits for the provider deadline.
        self.worker.take();
    }
}

impl Drop for MachineActionWorker {
    fn drop(&mut self) {
        self.shutdown();
    }
}

fn prepare_machine_session(
    replacement: MachineSession,
    machine_ui: &MachineUiState,
    preparation: MachineSessionPreparation,
    app_events: SyncSender<AppEvent>,
) -> anyhow::Result<PreparedMachineSession> {
    // The managed-workspace guard runs on every presentation, reused or
    // not: a pooled session can change state while it is not presented, and
    // the guard is the invariant that makes presenting it safe.
    ensure_managed_workspace_guard(&replacement.session, Some(machine_ui))?;
    ensure_initial_for_machine_ui(
        &replacement.session,
        preparation.initial_size,
        Some(machine_ui),
    )?;
    let session_available = machine_ui.session_available;
    let (session, event_worker, mux_titles, mux_recovery_generation) = prepare_ordered_session(
        replacement.session,
        preparation.pty_input,
        app_events,
        preparation.generation,
        preparation.surface_filter,
    )?;
    let tree = session.tree();
    Ok(PreparedMachineSession {
        session,
        event_worker,
        generation: preparation.generation,
        mux_titles,
        mux_recovery_generation,
        tree,
        label: replacement.label,
        session_available,
        machine: replacement.machine,
    })
}

fn send_machine_controller_completion(
    app_events: &SyncSender<AppEvent>,
    mut completion: MachineControllerCompletion,
    stop: &AtomicBool,
) -> bool {
    loop {
        match app_events.try_send(AppEvent::MachineControllerCompleted(Box::new(completion))) {
            Ok(()) => return true,
            Err(TrySendError::Full(AppEvent::MachineControllerCompleted(returned))) => {
                completion = *returned;
                if stop.load(Ordering::Acquire) {
                    return false;
                }
                std::thread::park_timeout(Duration::from_millis(1));
            }
            Err(TrySendError::Full(_)) => {
                unreachable!("machine completion sender returned a different event")
            }
            Err(TrySendError::Disconnected(_)) => return false,
        }
    }
}

impl MachineUpdatePump {
    fn spawn(
        updates: MachineUpdateStream,
        app_events: SyncSender<AppEvent>,
        generation: u64,
    ) -> anyhow::Result<Self> {
        let stop = updates.stop_handle();
        let (updates, _, provider) = updates.into_parts();
        let forwarder_stop = stop.clone();
        let forwarder = match std::thread::Builder::new()
            .name("machine-provider-events".into())
            .spawn(move || {
                while !forwarder_stop.load(Ordering::Acquire) {
                    match updates.recv_timeout(Duration::from_millis(250)) {
                        Ok(update) => {
                            let mut update = Box::new(update);
                            loop {
                                match app_events.try_send(AppEvent::MachineUpdatedForGeneration {
                                    generation,
                                    update,
                                }) {
                                    Ok(()) => break,
                                    Err(TrySendError::Full(
                                        AppEvent::MachineUpdatedForGeneration {
                                            update: returned,
                                            ..
                                        },
                                    )) => {
                                        update = returned;
                                        if forwarder_stop.load(Ordering::Acquire) {
                                            return;
                                        }
                                        std::thread::park_timeout(Duration::from_millis(1));
                                    }
                                    Err(TrySendError::Full(_)) => {
                                        unreachable!(
                                            "machine update sender returned a different event"
                                        )
                                    }
                                    Err(TrySendError::Disconnected(_)) => return,
                                }
                            }
                        }
                        Err(RecvTimeoutError::Timeout) => {}
                        Err(RecvTimeoutError::Disconnected) => break,
                    }
                }
            }) {
            Ok(forwarder) => forwarder,
            Err(error) => {
                stop.store(true, Ordering::Release);
                let _ = provider.join();
                return Err(error.into());
            }
        };
        Ok(Self { stop, provider: Some(provider), forwarder: Some(forwarder) })
    }

    fn stop_and_join(&mut self) {
        self.stop.store(true, Ordering::Release);
        if let Some(forwarder) = self.forwarder.take() {
            let _ = forwarder.join();
        }
        if let Some(provider) = self.provider.take() {
            let _ = provider.join();
        }
    }
}

impl Drop for MachineUpdatePump {
    fn drop(&mut self) {
        self.stop_and_join();
    }
}

fn ensure_initial_for_machine_ui(
    session: &Session,
    initial_size: Option<(u16, u16)>,
    machine_ui: Option<&MachineUiState>,
) -> anyhow::Result<()> {
    let should_create = match machine_ui {
        None => true,
        Some(machine) if !machine.session_available => false,
        Some(machine) => !matches!(
            machine.workspace_creation_policy(),
            Some(WorkspaceCreationPolicy::ProviderOwned { .. })
        ),
    };
    if should_create {
        session.ensure_initial(initial_size)?;
    }
    Ok(())
}

fn recover_initial_workspace_failure(
    result: anyhow::Result<()>,
    machine_ui: Option<&MachineUiState>,
) -> anyhow::Result<Option<String>> {
    match result {
        Ok(()) => Ok(None),
        Err(error) if machine_ui.is_some() => {
            let error = error.to_string();
            let message = if error.contains("failed to open PTY:")
                && (error.contains("Device not configured")
                    || error.contains("No space left on device")
                    || error.contains("Resource temporarily unavailable"))
            {
                localization::catalog().runtime.terminal_capacity_exhausted.to_string()
            } else {
                error
            };
            Ok(Some(message))
        }
        Err(error) => Err(error),
    }
}

fn uses_provider_managed_workspaces(machine_ui: Option<&MachineUiState>) -> bool {
    matches!(
        machine_ui.and_then(MachineUiState::workspace_creation_policy),
        Some(WorkspaceCreationPolicy::ProviderOwned { .. })
    )
}

/// Route core diagnostics to the bounded client log. Core work can run on a
/// reconnect thread while this process owns a raw terminal, so the sink must
/// not echo to stderr.
pub(crate) fn install_mux_diagnostic_logger(mux: &Arc<Mux>) {
    let _ = mux.set_diagnostic_reporter(Arc::new(|message| {
        crate::client_log::warn("mux", message);
    }));
}

fn ensure_managed_workspace_guard(
    session: &Session,
    machine_ui: Option<&MachineUiState>,
) -> anyhow::Result<()> {
    if let Some(machine_ui) = machine_ui {
        validate_machine_session(session, machine_ui)?;
    }
    Ok(())
}

pub fn run_with_machine_updates(
    session: Session,
    session_label: String,
    default_colors: cmux_tui_core::DefaultColors,
    surface_only: Option<SurfaceId>,
    owner_mux: Option<Arc<Mux>>,
    machine_ui: Option<MachineUiState>,
    machine_controller: Option<Box<dyn MachineController>>,
    startup_config: crate::config::StartupConfigSnapshot,
) -> anyhow::Result<RunOutcome> {
    type PanicHook = dyn for<'a> Fn(&std::panic::PanicHookInfo<'a>) + Send + Sync + 'static;
    let previous_panic_hook: Arc<PanicHook> = Arc::from(std::panic::take_hook());
    let previous_panic_hook_for_threads = previous_panic_hook.clone();
    let run_thread = std::thread::current().id();
    let panic_diagnostic = Arc::new(Mutex::new(None));
    let panic_diagnostic_hook = panic_diagnostic.clone();
    std::panic::set_hook(Box::new(move |info| {
        if std::thread::current().id() == run_thread {
            *panic_diagnostic_hook.lock().unwrap() = Some(format_panic_diagnostic(info));
        } else {
            previous_panic_hook_for_threads(info);
        }
    }));
    let result = std::panic::catch_unwind(AssertUnwindSafe(|| {
        run_with_machine_updates_inner(
            session,
            session_label,
            default_colors,
            surface_only,
            owner_mux,
            machine_ui,
            machine_controller,
            startup_config,
        )
    }));
    let _ = std::panic::take_hook();
    std::panic::set_hook(Box::new(move |info| previous_panic_hook(info)));

    let result = report_after_unwind(result, || {
        if let Some(diagnostic) = panic_diagnostic.lock().unwrap().take() {
            eprint!("{diagnostic}");
        }
    });
    match result {
        Ok(result) => result,
        Err(payload) => std::panic::resume_unwind(payload),
    }
}

fn run_with_machine_updates_inner(
    session: Session,
    session_label: String,
    default_colors: cmux_tui_core::DefaultColors,
    surface_only: Option<SurfaceId>,
    owner_mux: Option<Arc<Mux>>,
    machine_ui: Option<MachineUiState>,
    machine_controller: Option<Box<dyn MachineController>>,
    startup_config: crate::config::StartupConfigSnapshot,
) -> anyhow::Result<RunOutcome> {
    if let Session::Local(mux) = &session {
        install_mux_diagnostic_logger(mux);
    }
    if let Some(mux) = owner_mux.as_ref() {
        install_mux_diagnostic_logger(mux);
    }
    let mut config = startup_config.into_config();
    let chrome = ChromeTheme::for_defaults(config.chrome, default_colors);
    config.apply_chrome_defaults(chrome);
    let session_available = machine_ui.as_ref().is_none_or(|machine| machine.session_available);
    // First workspace before the terminal switches modes, so a spawn
    // failure prints a normal error. Spawn at the size the first pane
    // will actually render at (a post-spawn resize makes shells like zsh
    // repaint their prompt, leaving a reverse-video % artifact). The
    // pane's border box eats one cell on every side.
    let initial_size = crossterm::terminal::size().ok().map(|(w, h)| {
        if surface_only.is_some() {
            return (w.max(1), h.max(1));
        }
        let pane = sidebar_layout_for(
            &config,
            true,
            false,
            machine_ui.is_some(),
            (w, h),
            SidebarWidthOverrides::default(),
        )
        .content;
        content_size_for_rect(pane, config.scrollbar.position, config.pane.padding)
            .unwrap_or((1, 1))
    });
    ensure_managed_workspace_guard(&session, machine_ui.as_ref())?;
    let initial_workspace_error = recover_initial_workspace_failure(
        ensure_initial_for_machine_ui(&session, initial_size, machine_ui.as_ref()),
        machine_ui.as_ref(),
    )?;
    let encoder = KeyEncoder::new()?;
    let (tx, rx) = sync_channel::<AppEvent>(APP_EVENT_CAPACITY);
    let owner_reload_worker =
        owner_mux.as_deref().map(|mux| OwnerReloadWorker::spawn(mux, tx.clone())).transpose()?;
    let host_input = HostInputRuntime::new();
    let browser_failure_tx = tx.clone();
    let browser_control_tx = tx.clone();
    let browser_input = BrowserInputDispatcher::spawn(
        move |failure| {
            let _ = browser_failure_tx.send(AppEvent::BrowserResizeFailed(failure));
        },
        move |error| {
            let message = localization::catalog().browser.control_failed(&error);
            let _ = browser_control_tx.send(AppEvent::Mux(MuxEvent::Status(message)));
        },
    )?;
    let failure_tx = tx.clone();
    let pty_failures = Arc::new(PtyFailureIngress::default());
    let failure_ingress = pty_failures.clone();
    let pty_input = PtyInputDispatcher::spawn(move |failure| {
        if failure_ingress.push(failure) {
            // This is a latency hint, not the ownership path. The event loop
            // drains the ingress after every batch and timeout, including
            // when this bounded app channel is currently full.
            let _ = failure_tx.try_send(AppEvent::PtyFailuresReady);
        }
    })?;
    let session_generation = 1;
    let (session, session_event_worker, mux_titles, mux_recovery_generation) =
        start_ordered_session(
            session,
            pty_input.sender(),
            tx.clone(),
            session_generation,
            surface_only,
        )?;
    let stdout_lock = Arc::new(StdoutLock::new(()));
    let machine_action_worker = machine_controller
        .map(|controller| MachineActionWorker::spawn(controller, tx.clone()))
        .transpose()?;

    // One line per launch, so every stretch of the log names the build that
    // produced it. Sink initialization is asynchronous (writer thread), so
    // this never blocks startup however slow the log target is.
    crate::client_log::info("startup", &crate::version_string());
    enable_raw_mode()?;
    // The TUI owns the terminal now: stray stderr writes (panics, libraries)
    // would corrupt the raw-mode screen, so route fd 2 into the client log.
    crate::client_log::redirect_stderr_into_log();
    let mut terminal_restore = TerminalRestoreGuard::new(stdout_lock.clone());
    if let Err(e) = (|| -> anyhow::Result<()> {
        let _guard = stdout_lock.lock();
        stdout_lock.recover_stream_locked()?;
        let mut stdout = std::io::stdout();
        stdout.execute(EnterAlternateScreen)?;
        Ok(())
    })() {
        return Err(terminal_restore.restore_after_error(e));
    }

    // Probe before enabling application input modes. Any keys read alongside
    // terminal replies are parsed and queued into the same app channel below.
    let terminal_probe = crate::ui::graphics::probe_terminal(None);
    let cell_pixels = terminal_probe.cell_pixels;
    if session_available && publishes_global_cell_metrics(surface_only) {
        session.set_cell_pixel_size(cell_pixels.0, cell_pixels.1);
    }
    let graphics_supported =
        terminal_probe.graphics_supported && GraphicsWriter::platform_supported();
    let pending_input = terminal_probe.pending_input;
    let (graphics_fence_waiter, graphics_fence_notifier) = graphics_fence_channel();

    if let Err(e) = (|| -> anyhow::Result<()> {
        let _guard = stdout_lock.lock();
        let mut stdout = std::io::stdout();
        negotiate_host_keyboard_protocol(
            &mut stdout,
            terminal_restore.host_keyboard_protocol_mut(),
        )?;
        stdout.write_all(host_startup_input_modes(surface_only.is_some()).as_bytes())?;
        stdout.flush()?;
        Ok(())
    })() {
        return Err(terminal_restore.restore_after_error(e));
    }

    // Crossterm input has a separate retained ingress. Start this after
    // startup terminal probes so their replies cannot be consumed as key
    // input. Backpressure here must never block mutation completions.
    let input = host_input.producer(tx.clone());
    if let Err(error) = std::thread::Builder::new().name("input".into()).spawn(move || {
        for event in crate::ui::graphics::finish_startup_input(pending_input) {
            if !input.send(event) {
                return;
            }
        }
        let mut graphics_responses = GraphicsResponseFilter::new(graphics_fence_notifier);
        'input: loop {
            if input.ingress.is_closed() {
                break 'input;
            }
            let events = match read_crossterm_event(
                graphics_responses.time_until_expiry(),
                crossterm::event::poll,
                crossterm::event::read,
            ) {
                Ok(Some(event)) => graphics_responses.filter(event),
                Ok(None) => graphics_responses.take_expired(),
                Err(error) => {
                    input.fail(error.to_string());
                    break 'input;
                }
            };
            for event in events {
                if !input.send(event) {
                    break 'input;
                }
            }
        }
    }) {
        return Err(terminal_restore.restore_after_error(error.into()));
    }

    let graphics_writer = if graphics_supported {
        let graphics_ready = tx.clone();
        match GraphicsWriter::spawn(stdout_lock.clone(), graphics_fence_waiter, move || {
            // Latency hint only. The completion stays in GraphicsWriter, and
            // the event loop drains it after every event batch and timeout.
            let _ = graphics_ready.try_send(AppEvent::GraphicsWriterReady);
        }) {
            Ok(writer) => Some(writer),
            Err(error) => return Err(terminal_restore.restore_after_error(error.into())),
        }
    } else {
        None
    };
    let graphics_shutdown = graphics_writer.as_ref().map(GraphicsWriter::shutdown_control);
    terminal_restore.set_graphics_shutdown(graphics_shutdown.clone());

    // Restore the host terminal even if we panic mid-frame.
    let default_hook = std::panic::take_hook();
    let restore_lock = stdout_lock.clone();
    let panic_keyboard_protocol = terminal_restore.host_keyboard_protocol().clone();
    let panic_graphics_shutdown = graphics_shutdown;
    std::panic::set_hook(Box::new(move |info| {
        if let Some(graphics_shutdown) = &panic_graphics_shutdown {
            graphics_shutdown.cancel_for_panic_hook();
        }
        with_panic_stdout_lock(&restore_lock, || {
            let _ = restore_terminal_unlocked(&panic_keyboard_protocol);
        });
        default_hook(info);
    }));

    let backend = CrosstermBackend::new(std::io::stdout());
    let mut terminal = match RatatuiTerminal::new(backend) {
        Ok(terminal) => terminal,
        Err(e) => {
            return Err(terminal_restore.restore_after_error(e.into()));
        }
    };
    let sidebar_view = config.sidebar.view;
    let fallback_cwd = std::env::current_dir().unwrap_or_else(|_| PathBuf::from("."));
    let initial_machine_notice = initial_workspace_error
        .or_else(|| machine_ui.as_ref().and_then(|machine| machine.notice.clone()));
    let machine_selection_intent = machine_ui.as_ref().and_then(|machine| machine.snapshot.active);
    let machine_presented = machine_ui.as_ref().and_then(|machine| machine.snapshot.active);
    let owner_machine = owner_mux
        .as_ref()
        .and_then(|_| machine_ui.as_ref().and_then(|machine| machine.snapshot.active));
    let frontend_journal = match FrontendJournalWorker::spawn() {
        Ok(worker) => worker,
        Err(error) => return Err(terminal_restore.restore_after_error(error)),
    };
    let frontend_projection_id = match FrontendProjectionPublicId::random() {
        Ok(id) => id,
        Err(error) => return Err(terminal_restore.restore_after_error(error.into())),
    };
    let mut app = App {
        session,
        owner_mux,
        owner_machine,
        owner_reload_worker,
        session_event_worker: Some(session_event_worker),
        session_generation,
        app_events: tx,
        frontend_journal,
        frontend_projection_id,
        last_frontend_presentation: None,
        outer_size: (0, 0),
        host_input,
        machine_action_worker,
        machine_action_in_flight: false,
        machine_action_request: None,
        machine_action_connection_attempt: None,
        canceled_machine_connection_attempt: None,
        machine_action_intent_generation: None,
        machine_selection_intent,
        machine_selection_generation: 0,
        machine_presented,
        machine_deleted_rail_index: None,
        machine_provider_reconnect_attempts: 0,
        machine_provider_reconnect_retry_at: None,
        pending_machine_replacement: None,
        machine_update_pump: None,
        machine_update_generation: 0,
        durable_notices: VecDeque::new(),
        recent_durable_notices: VecDeque::new(),
        painted_durable_notice_this_frame: None,
        pending_durable_notice_acks: VecDeque::new(),
        durable_notice_ack_in_flight: None,
        durable_notice_ack_failures: 0,
        durable_notice_ack_retry_at: None,
        config,
        #[cfg(test)]
        config_reload_applications: 0,
        chrome,
        tree: TreeView::default(),
        tab_locations: HashMap::new(),
        render_states: HashMap::new(),
        chrome_row_scratch: ReusableRowBuffer::default(),
        rendered_terminal_sizes: HashMap::new(),
        rendered_terminal_pointer_semantics: HashMap::new(),
        rendered_pane_content_generations: HashMap::new(),
        desired_outer_cursor: OuterCursorSpec::Reset,
        applied_outer_cursor: initial_applied_outer_cursor(surface_only.is_some()),
        host_mouse_capture_applied: initial_host_mouse_capture(surface_only.is_some()),
        graphics_writer,
        next_graphics_submission: 0,
        pending_graphics_submission: None,
        pending_graphics_snapshot: None,
        pending_graphics_affected_rect: None,
        last_graphics_snapshot: Vec::new(),
        graphics_supported,
        graphics_host_scene_reset_pending: false,
        graphics_scene_cache: GraphicsSceneCache::default(),
        graphics_dirty_surfaces: HashSet::new(),
        stdout_lock,
        pane_areas: Vec::new(),
        viewport_projection: ViewportPaneAreaProjection::default(),
        viewport_layout: Vec::new(),
        viewport_stacked_headers: HashSet::new(),
        viewport_states: HashMap::new(),
        viewport_virtual_width: 0,
        viewport_offset: 0,
        pane_focus_history: PaneFocusHistory::default(),
        reported_focus: None,
        client_focus_id: client_focus_identity(),
        rendered_terminal_bounds: HashMap::new(),
        rendered_kitty_graphics: HashMap::new(),
        visible_size_surfaces: HashSet::new(),
        pending_size_releases: HashSet::new(),
        geometry_authority_surface: None,
        prefix_armed: false,
        session_label,
        surface_only,
        sidebar_visible: surface_only.is_none(),
        sidebar_compact: false,
        focus: FocusTarget::Pane,
        sidebar_focus_pending: false,
        machine_ui,
        machine_pointer_context_cache: None,
        sidebar_view,
        sidebar_files: FileBrowser::new(fallback_cwd),
        sidebar_workspace_selection: 0,
        sidebar_recoverable_workspace_selection: 0,
        workspace_rail_selection: WorkspaceRailSelection::default(),
        machine_rail_scroll: 0,
        machine_footer_scroll: 0,
        workspace_rail_scroll: 0,
        workspace_footer_scroll: 0,
        tabs_rail_selection: 0,
        tabs_rail_scroll: 0,
        tabs_footer_scroll: 0,
        projection_rails: HashMap::new(),
        machine_rail_follow_selection: true,
        workspace_rail_follow_selection: true,
        tabs_rail_follow_selection: true,
        sidebar_followed_surface: None,
        sidebar_width: 0,
        machine_sidebar_width: 0,
        tabs_sidebar_width: 0,
        sidebar_layout: SidebarLayout::default(),
        sidebar_plugin_surface: None,
        sidebar_plugin_error: None,
        sidebar_plugin_retry_after_ms: None,
        sidebar_plugin_retry_at: None,
        sidebar_width_override: None,
        machine_sidebar_width_override: None,
        tabs_sidebar_width_override: None,
        projection_sidebar_width_overrides: HashMap::new(),
        hidden_sidebar_views: HashMap::new(),
        content_area: Rect::default(),
        hits: Vec::new(),
        tab_scroll: HashMap::new(),
        hover: None,
        menu: None,
        clients: Vec::new(),
        client_border_labels: HashMap::new(),
        prompt: None,
        connection_transaction: None,
        next_connection_attempt: 1,
        pending_provider_action: None,
        pairing_dialog: None,
        pairing_queue: VecDeque::new(),
        shortcut_help: None,
        omnibar: None,
        toast: None,
        shake_frames: 0,
        selection: None,
        selection_generation: 0,
        status_selection: None,
        rendered_status_message: None,
        logged_status_message: None,
        status_notice_text: None,
        input_revision: 0,
        status_message: initial_machine_notice,
        cell_pixels,
        pointer_shape: false,
        last_browser_hover: None,
        browser_input,
        pty_input,
        deferred_input: DeferredInputQueue::default(),
        pending_pointer_motion: None,
        deferred_input_sequence: 0,
        next_semantic_destination_intent: 0,
        latest_semantic_destination_intent: None,
        semantic_destination_outcomes: HashMap::new(),
        rendered_pointer_frame: RenderedPointerFrame::default(),
        pointer_route_phase: PointerRoutePhase::DrawPending,
        pointer_focus_generation: 0,
        layout_refresh_retries_remaining: 0,
        background_refresh_attempts: 0,
        background_refresh_retry_at: None,
        last_applied_refresh_sequence: 0,
        applied_destination_generation: 0,
        pending_session_completions: VecDeque::new(),
        mux_titles,
        pty_failures,
        mux_recovery_generation,
        drag: None,
        active_pointer_buttons: HashSet::new(),
        ignored_pty_mouse_buttons: HashSet::new(),
        #[cfg(test)]
        timeout_drain_hook: None,
        encoder,
        encode_buf: Vec::with_capacity(64),
        quit: false,
        status_command_outputs: Arc::new(Mutex::new(HashMap::new())),
        status_command_worker_stop: None,
        status_poke_pending: Arc::new(AtomicBool::new(false)),
        status_command_workers: Vec::new(),
        retiring_status_workers: Vec::new(),
        status_outputs_generation: Arc::new(AtomicU64::new(0)),
        status_segments_cache: None,
    };
    app.ensure_status_command_worker();
    if app.session_available() {
        app.session.refresh_clients_background();
    }

    if let Err(error) = app.restart_machine_updates() {
        app.shutdown_runtime_components();
        return Err(terminal_restore.restore_after_error(error));
    }

    if let Some(owner) = app.owner_mux.as_ref() {
        owner.mark_server_lifecycle_ready();
    }

    let result = app.event_loop(&mut terminal, rx);
    app.shutdown_runtime_components();
    let restore_result = terminal_restore.restore();
    match (result, restore_result) {
        (Ok(()), Ok(())) => {}
        (Ok(()), Err(error)) | (Err(error), Ok(())) => return Err(error),
        (Err(error), Err(restore_error)) => {
            return Err(terminal_restore_error(error, restore_error));
        }
    }
    let outcome = app
        .machine_ui
        .and_then(|machine| machine.request)
        .map(RunOutcome::Machine)
        .unwrap_or(RunOutcome::Quit);
    Ok(outcome)
}

fn format_panic_diagnostic(info: &std::panic::PanicHookInfo<'_>) -> String {
    let payload = info
        .payload()
        .downcast_ref::<&str>()
        .copied()
        .or_else(|| info.payload().downcast_ref::<String>().map(String::as_str))
        .unwrap_or("Box<dyn Any>");
    let thread = std::thread::current();
    let thread_name = thread.name().unwrap_or("<unnamed>");
    let location = info
        .location()
        .map(|location| location.to_string())
        .unwrap_or_else(|| "<unknown>".to_string());
    let mut diagnostic = format!("thread '{thread_name}' panicked at {location}:\n{payload}\n");
    let backtrace = std::backtrace::Backtrace::capture();
    if backtrace.status() == std::backtrace::BacktraceStatus::Captured {
        diagnostic.push_str(&format!("{backtrace}\n"));
    }
    diagnostic
}

fn report_after_unwind<T>(
    result: std::thread::Result<T>,
    report: impl FnOnce(),
) -> std::thread::Result<T> {
    if result.is_err() {
        report();
    }
    result
}

struct TerminalRestoreGuard {
    stdout_lock: Arc<StdoutLock>,
    host_keyboard_protocol: HostKeyboardProtocolOwnership,
    graphics_shutdown: Option<GraphicsWriterShutdown>,
    armed: bool,
}

impl TerminalRestoreGuard {
    fn new(stdout_lock: Arc<StdoutLock>) -> Self {
        Self {
            stdout_lock,
            host_keyboard_protocol: HostKeyboardProtocolOwnership::default(),
            graphics_shutdown: None,
            armed: true,
        }
    }

    fn host_keyboard_protocol(&self) -> &HostKeyboardProtocolOwnership {
        &self.host_keyboard_protocol
    }

    fn host_keyboard_protocol_mut(&mut self) -> &mut HostKeyboardProtocolOwnership {
        &mut self.host_keyboard_protocol
    }

    fn set_graphics_shutdown(&mut self, graphics_shutdown: Option<GraphicsWriterShutdown>) {
        self.graphics_shutdown = graphics_shutdown;
    }

    fn restore(&mut self) -> anyhow::Result<()> {
        if !self.armed {
            return Ok(());
        }
        self.armed = false;
        if let Some(graphics_shutdown) = &self.graphics_shutdown {
            graphics_shutdown.cancel_and_wait();
        }
        let result = restore_terminal(Some(&self.stdout_lock), &self.host_keyboard_protocol);
        // The terminal is the user's again; diagnostics from here on must
        // reach it instead of the client log. Explicit restoration disarms
        // the guard, so Drop will not do this (idempotent regardless).
        crate::client_log::restore_stderr_from_log();
        result
    }

    fn restore_after_error(&mut self, error: anyhow::Error) -> anyhow::Error {
        match self.restore() {
            Ok(()) => error,
            Err(restore_error) => terminal_restore_error(error, restore_error),
        }
    }
}

fn terminal_restore_error(error: anyhow::Error, restore_error: anyhow::Error) -> anyhow::Error {
    let error = format!("{error:#}");
    let restore_error = format!("{restore_error:#}");
    anyhow::anyhow!(
        localization::catalog().runtime.terminal_restore_also_failed(&error, &restore_error)
    )
}

impl Drop for TerminalRestoreGuard {
    fn drop(&mut self) {
        if self.armed {
            self.armed = false;
            if let Some(graphics_shutdown) = &self.graphics_shutdown {
                graphics_shutdown.cancel_and_wait();
            }
            with_panic_stdout_lock(&self.stdout_lock, || {
                let _ = restore_terminal_unlocked(&self.host_keyboard_protocol);
            });
            // The terminal is the user's again; exit-time diagnostics should
            // reach it instead of the client log.
            crate::client_log::restore_stderr_from_log();
        }
    }
}

#[derive(Clone, Debug)]
struct HostKeyboardProtocolOwnership {
    // Panic and normal cleanup share this claim. The stdout lock serializes
    // restore attempts, and the first successful pop consumes ownership.
    pushed: Arc<AtomicBool>,
}

impl Default for HostKeyboardProtocolOwnership {
    fn default() -> Self {
        Self { pushed: Arc::new(AtomicBool::new(false)) }
    }
}

impl PartialEq for HostKeyboardProtocolOwnership {
    fn eq(&self, other: &Self) -> bool {
        self.is_pushed() == other.is_pushed()
    }
}

impl Eq for HostKeyboardProtocolOwnership {}

impl HostKeyboardProtocolOwnership {
    fn pushed() -> Self {
        Self { pushed: Arc::new(AtomicBool::new(true)) }
    }

    fn is_pushed(&self) -> bool {
        self.pushed.load(Ordering::Acquire)
    }
}

const HOST_KEYBOARD_FLAGS: KeyboardEnhancementFlags =
    KeyboardEnhancementFlags::DISAMBIGUATE_ESCAPE_CODES
        .union(KeyboardEnhancementFlags::REPORT_ALTERNATE_KEYS)
        .union(KeyboardEnhancementFlags::REPORT_ALL_KEYS_AS_ESCAPE_CODES)
        .union(KeyboardEnhancementFlags::REPORT_ASSOCIATED_TEXT);
const HOST_KEYBOARD_QUERY_TIMEOUT: Duration = Duration::from_millis(150);

fn keyboard_protocol_accepts(
    requested: KeyboardEnhancementFlags,
    accepted: Option<KeyboardEnhancementFlags>,
) -> bool {
    accepted.is_some_and(|flags| flags.contains(requested))
}

fn enable_host_keyboard_protocol(
    stdout: &mut impl Write,
) -> std::io::Result<HostKeyboardProtocolOwnership> {
    let result = stdout.execute(PushKeyboardEnhancementFlags(HOST_KEYBOARD_FLAGS));
    match result {
        Ok(_) => Ok(HostKeyboardProtocolOwnership::pushed()),
        Err(error) if error.kind() == std::io::ErrorKind::Unsupported => {
            Ok(HostKeyboardProtocolOwnership::default())
        }
        Err(error) => Err(error),
    }
}

fn negotiate_host_keyboard_protocol(
    stdout: &mut impl Write,
    ownership: &mut HostKeyboardProtocolOwnership,
) -> std::io::Result<()> {
    negotiate_host_keyboard_protocol_with(
        stdout,
        ownership,
        query_keyboard_enhancement_flags_with_timeout,
    )
}

fn negotiate_host_keyboard_protocol_with(
    stdout: &mut impl Write,
    ownership: &mut HostKeyboardProtocolOwnership,
    query: impl FnOnce(Duration) -> std::io::Result<Option<KeyboardEnhancementFlags>>,
) -> std::io::Result<()> {
    let enabled = enable_host_keyboard_protocol(stdout)?;
    ownership.pushed.store(enabled.is_pushed(), Ordering::Release);
    if !ownership.is_pushed() {
        return Ok(());
    }

    if keyboard_protocol_accepts(
        HOST_KEYBOARD_FLAGS,
        query(HOST_KEYBOARD_QUERY_TIMEOUT).ok().flatten(),
    ) {
        return Ok(());
    }

    disable_host_keyboard_protocol(stdout, ownership)?;
    Ok(())
}

fn disable_host_keyboard_protocol(
    stdout: &mut impl Write,
    ownership: &HostKeyboardProtocolOwnership,
) -> std::io::Result<()> {
    if ownership.pushed.swap(false, Ordering::AcqRel)
        && let Err(error) = stdout.execute(PopKeyboardEnhancementFlags)
    {
        ownership.pushed.store(true, Ordering::Release);
        return Err(error);
    }
    Ok(())
}

fn restore_terminal(
    stdout_lock: Option<&Arc<StdoutLock>>,
    host_keyboard_protocol: &HostKeyboardProtocolOwnership,
) -> anyhow::Result<()> {
    let _guard = stdout_lock.map(|lock| lock.lock());
    if let Some(stdout_lock) = stdout_lock
        && let Err(error) = stdout_lock.recover_stream_locked()
    {
        let _ = disable_raw_mode();
        return Err(error.into());
    }
    restore_terminal_unlocked(host_keyboard_protocol)
}

fn with_panic_stdout_lock(stdout_lock: &Arc<StdoutLock>, restore: impl FnOnce()) {
    // Render panics may recurse on the owner thread. Reentrant acquisition
    // preserves that path while still waiting for a different stdout writer.
    let _guard = stdout_lock.lock();
    if stdout_lock.recover_stream_locked().is_ok() {
        restore();
    } else {
        let _ = disable_raw_mode();
    }
}

fn restore_terminal_unlocked(
    host_keyboard_protocol: &HostKeyboardProtocolOwnership,
) -> anyhow::Result<()> {
    let mut stdout = std::io::stdout();
    // A canceled or failed graphics write may have ended inside a Kitty APC.
    // CAN returns the outer parser to ground before any restoration sequence.
    let _ = stdout.write_all(&[0x18]);
    // A standalone ST is harmless after CAN and closes hosts that retain a
    // string despite cancellation.
    let _ = write!(stdout, "\x1b\\");
    // Reset the mouse pointer shape in case we left it as a hand.
    let _ = write!(stdout, "\x1b]22;default\x07");
    // Cursor color and DECSCUSR shape are outer-terminal global state. Always
    // restore both, including panic/startup-failure paths.
    let _ = write!(stdout, "\x1b]112\x07\x1b[0 q");
    // Restore the conventional host behavior where Shift bypasses capture.
    let _ = write!(stdout, "\x1b[>0s");
    let _ = disable_host_keyboard_protocol(&mut stdout, host_keyboard_protocol);
    let _ = stdout.execute(DisableBracketedPaste);
    let _ = stdout.execute(DisableFocusChange);
    let _ = stdout.execute(DisableMouseCapture);
    let _ = stdout.execute(LeaveAlternateScreen);
    disable_raw_mode()?;
    Ok(())
}

#[cfg(test)]
fn forward_host_input(
    mut read: impl FnMut() -> std::io::Result<Event>,
    input_tx: &SyncSender<AppEvent>,
) {
    loop {
        match read() {
            Ok(event) => {
                if input_tx.send(AppEvent::Input(event)).is_err() {
                    return;
                }
            }
            Err(error) => {
                let _ = input_tx.send(AppEvent::HostInputFailed(error.to_string()));
                return;
            }
        }
    }
}

fn catch_renderer_panic<T>(render: impl FnOnce() -> T) -> anyhow::Result<T> {
    std::panic::catch_unwind(AssertUnwindSafe(render)).map_err(|payload| {
        let message = payload
            .downcast_ref::<String>()
            .map(String::as_str)
            .or_else(|| payload.downcast_ref::<&str>().copied())
            .unwrap_or(localization::catalog().runtime.unknown_panic);
        anyhow::anyhow!(localization::catalog().runtime.renderer_panicked(message))
    })
}

fn localized_clear_history_failure(error: &str) -> &'static str {
    let messages = &localization::catalog().terminal;
    match error {
        CLEAR_HISTORY_UNSUPPORTED_ERROR => messages.clear_history_unsupported,
        cmux_tui_core::CLEAR_HISTORY_FALLBACK_UNREPRESENTABLE_ERROR => {
            messages.clear_history_fallback_unrepresentable
        }
        cmux_tui_core::CLEAR_HISTORY_PRESERVATION_ERROR => {
            messages.clear_history_preservation_impossible
        }
        cmux_tui_core::CLEAR_HISTORY_STREAM_TIMEOUT_ERROR => messages.clear_history_stream_timeout,
        cmux_tui_core::CLEAR_HISTORY_FALLBACK_WRITE_TIMEOUT_ERROR => {
            messages.clear_history_fallback_write_timeout
        }
        "terminal host does not support clear-history" => messages.clear_history_host_unsupported,
        "terminal host has exited" => messages.clear_history_host_exited,
        "terminal host failed to apply clear-history" => messages.clear_history_host_failed,
        "terminal host returned a malformed clear-history response" => {
            messages.clear_history_host_malformed_response
        }
        "remote session did not respond" => messages.clear_history_remote_no_response,
        "remote response wait canceled for shutdown" => messages.clear_history_remote_disconnected,
        _ if error.starts_with("terminal host did not acknowledge ClearHistory:") => {
            messages.clear_history_host_no_response
        }
        _ if error.starts_with("remote transport write failed:") => {
            messages.clear_history_remote_disconnected
        }
        _ if error.starts_with("remote command rejected:") => {
            messages.clear_history_remote_rejected
        }
        _ => messages.clear_history_unexpected,
    }
}

fn classify_clear_history_failure(failure: ClearHistoryFailure) -> anyhow::Error {
    let delivery = failure.delivery();
    let error = failure.into_error();
    if delivery == ClearHistoryDelivery::KnownNotDelivered {
        mark_operation_known_not_delivered(error)
    } else {
        error
    }
}

fn should_claim_clear_history_shortcut(
    surface_kind: SurfaceKind,
    supports_atomic_fallback: bool,
) -> bool {
    surface_kind == SurfaceKind::Pty && supports_atomic_fallback
}

fn adjust_active_tab_after_removal(pane: &mut PaneView, removed_tab_index: usize) {
    if pane.active_tab > removed_tab_index {
        pane.active_tab -= 1;
    } else if pane.active_tab >= pane.tabs.len() {
        pane.active_tab = pane.tabs.len().saturating_sub(1);
    }
}

impl App {
    pub fn is_surface_only(&self) -> bool {
        self.surface_only.is_some()
    }

    fn presenting_owner_session(&self) -> bool {
        if self.owner_mux.is_none() {
            return false;
        }
        match self.owner_machine {
            Some(owner) => self.machine_presented == Some(owner),
            None => self.machine_presented.is_none(),
        }
    }

    fn owner_shutdown_requested(&self) -> bool {
        self.owner_mux.as_ref().is_some_and(|mux| mux.daemon_shutdown_requested())
    }

    pub fn session_available(&self) -> bool {
        self.machine_ui.as_ref().is_none_or(|machine| {
            machine.session_available && self.machine_selection_intent == self.machine_presented
        })
    }

    pub(crate) fn selected_machine(&self) -> Option<MachineKey> {
        self.machine_selection_intent.or(self.machine_presented)
    }

    pub(crate) fn machine_transition(&self) -> Option<MachineTransitionView<'_>> {
        let selected = self.machine_selection_intent?;
        let ui = self.machine_ui.as_ref()?;
        if self.machine_presented == Some(selected) && ui.session_available {
            return None;
        }
        // Switching to a machine whose connection is already warm settles in
        // one round-trip: keep painting the current machine instead of
        // blanking the content with a "connecting" interstitial. Only while
        // the current machine is actually paintable - if its session is gone
        // (it paused; its stream died), "keep painting it" would show a dead
        // screen with no sign a switch is running.
        if self.machine_presented.is_some()
            && self.machine_presented != Some(selected)
            && ui.session_available
            && ui.connection_phase(selected) == MachineConnectionPhase::Ready
        {
            return None;
        }
        let machine = ui.snapshot.machines.iter().find(|machine| machine.key == selected)?;
        Some(MachineTransitionView {
            name: machine.name.as_str(),
            phase: ui.connection_phase(selected),
            status: machine.status,
            progress: ui.connection_progress(selected),
        })
    }

    /// Latest provider progress for a machine that is opening. Presentation
    /// only: dropped when the switch settles, fails, or is re-aimed.
    fn apply_connection_progress(
        &mut self,
        machine_id: String,
        latest: Arc<Mutex<Option<String>>>,
    ) -> RenderAction {
        // Latest-value cell: the pump overwrites it while this update sat in
        // the queue, so this read is the newest stage; an emptied cell means
        // a newer update for this machine already consumed it.
        let Some(message) = latest.lock().unwrap_or_else(|p| p.into_inner()).take() else {
            return RenderAction::None;
        };
        let Some(ui) = self.machine_ui.as_mut() else { return RenderAction::None };
        let Some(key) = ui
            .snapshot
            .machines
            .iter()
            .find(|machine| machine.id == machine_id)
            .map(|machine| machine.key)
        else {
            return RenderAction::None;
        };
        // Progress is only meaningful while an open for this machine is
        // being shown. A late event queued before the open settled (failed,
        // or presented) must not repopulate the stage the settle cleared.
        match ui.connection_phase(key) {
            MachineConnectionPhase::Connecting => {}
            MachineConnectionPhase::Ready
                if self.machine_selection_intent == Some(key)
                    && self.machine_presented != Some(key) =>
            {
                // The aim believed this target was warm, but the provider is
                // narrating an open: the pooled session was dead and a real
                // (re)connect or wake is running. Flip to Connecting so the
                // interstitial appears instead of silently showing the old
                // machine for the whole reconnect.
                ui.set_connection_phase(key, MachineConnectionPhase::Connecting);
            }
            _ => return RenderAction::None,
        }
        ui.set_connection_progress(key, message);
        if self.machine_selection_intent == Some(key) {
            RenderAction::Draw
        } else {
            RenderAction::None
        }
    }

    fn select_machine_intent(&mut self, machine: MachineKey) {
        if self.machine_selection_intent != Some(machine) {
            self.cancel_pointer_interaction();
            self.machine_selection_generation =
                self.machine_selection_generation.wrapping_add(1).max(1);
            self.machine_selection_intent = Some(machine);
            // A fresh aim starts with a fresh interstitial, not the last
            // attempt's progress message.
            if let Some(ui) = self.machine_ui.as_mut() {
                ui.clear_connection_progress(machine);
            }
        }
        let presented_live = self.machine_presented == Some(machine)
            && self.machine_ui.as_ref().is_some_and(|ui| ui.session_available);
        if let Some(ui) = self.machine_ui.as_mut() {
            let phase = if presented_live
                || ui.connection_phase(machine) == MachineConnectionPhase::Ready
            {
                // A warm pooled connection stays Ready: the switch reuses it,
                // so neither the rail badge nor the content interstitial
                // should flash "connecting". A presented machine whose
                // session is gone (it paused; the stream died) is NOT ready:
                // reselecting it starts a real wake, and the interstitial
                // must say so instead of briefly claiming Ready.
                MachineConnectionPhase::Ready
            } else {
                MachineConnectionPhase::Connecting
            };
            ui.set_connection_phase(machine, phase);
        }
    }

    pub fn workspace_creation_policy(&self) -> Option<WorkspaceCreationPolicy> {
        self.machine_ui.as_ref().map_or(
            Some(WorkspaceCreationPolicy::SessionOwned),
            MachineUiState::workspace_creation_policy,
        )
    }

    pub(crate) fn workspace_creation_modes(&self) -> Vec<Option<WorkspaceCreationMode>> {
        match self.workspace_creation_policy() {
            Some(WorkspaceCreationPolicy::SessionOwned) => vec![None],
            Some(WorkspaceCreationPolicy::ProviderOwned { modes, .. }) => {
                modes.into_iter().map(Some).collect()
            }
            None => Vec::new(),
        }
    }

    fn default_workspace_creation_mode(&self) -> Option<Option<WorkspaceCreationMode>> {
        match self.workspace_creation_policy()? {
            WorkspaceCreationPolicy::SessionOwned => Some(None),
            WorkspaceCreationPolicy::ProviderOwned { default_mode, modes } => {
                modes.contains(&default_mode).then_some(Some(default_mode))
            }
        }
    }

    fn reconcile_workspace_rail_selection(&mut self) {
        let actions = self.workspace_sidebar_action_rows();
        let selection_is_valid = match self.workspace_rail_selection {
            WorkspaceRailSelection::Workspace => true,
            WorkspaceRailSelection::Recoverable => self.machine_ui.as_ref().is_some_and(|ui| {
                self.sidebar_recoverable_workspace_selection < ui.recoverable_workspaces().len()
            }),
            WorkspaceRailSelection::Action(target) => {
                actions.iter().any(|action| action.target == target)
            }
        };
        if self.workspace_rail_selection != WorkspaceRailSelection::Workspace && !selection_is_valid
        {
            self.workspace_rail_selection = actions
                .first()
                .map(|action| WorkspaceRailSelection::Action(action.target))
                .unwrap_or(WorkspaceRailSelection::Workspace);
        }
    }

    pub fn workspace_sidebar_focused(&self) -> bool {
        self.focus == FocusTarget::WorkspaceRail
    }

    pub fn machine_sidebar_focused(&self) -> bool {
        self.focus == FocusTarget::MachineRail
    }

    pub fn tabs_sidebar_focused(&self) -> bool {
        self.focus == FocusTarget::TabsRail
    }

    fn sidebar_rail_focused(&self) -> bool {
        matches!(
            self.focus,
            FocusTarget::MachineRail
                | FocusTarget::WorkspaceRail
                | FocusTarget::TabsRail
                | FocusTarget::ProjectionRail(_)
        )
    }

    fn focused_rail_kind(&self) -> Option<RailKind> {
        match self.focus {
            FocusTarget::MachineRail => Some(RailKind::Machine),
            FocusTarget::WorkspaceRail => Some(RailKind::Workspace),
            FocusTarget::TabsRail => Some(RailKind::Tabs),
            FocusTarget::ProjectionRail(index) => Some(RailKind::Projection(index)),
            FocusTarget::Pane => None,
        }
    }

    fn focused_sidebar_view_id(&self) -> Option<String> {
        let rail = self.focused_rail_kind()?;
        self.view_index_for_rail(rail)
            .and_then(|index| self.config.sidebar.views.get(index))
            .map(|view| view.id.clone())
    }

    fn fallback_sidebar_area(&self, kind: RailKind, height: u16) -> Option<Rect> {
        let width_for = |candidate| match candidate {
            RailKind::Machine => self.machine_sidebar_width,
            RailKind::Workspace => self.sidebar_width,
            RailKind::Tabs => self.tabs_sidebar_width,
            RailKind::Projection(_) => 0,
        };
        let width = width_for(kind);
        if width == 0 {
            return None;
        }
        let mut x = 0u16;
        for column in &self.config.sidebar.columns {
            let candidate = match column.kind {
                SidebarColumnKind::Machines => RailKind::Machine,
                SidebarColumnKind::Workspaces => RailKind::Workspace,
                SidebarColumnKind::Tabs => RailKind::Tabs,
            };
            if candidate == kind {
                return Some(Rect { x, y: 0, width, height });
            }
            x = x.saturating_add(width_for(candidate));
        }
        None
    }

    pub fn machine_sidebar_area(&self, height: u16) -> Option<Rect> {
        self.sidebar_layout
            .machine
            .or_else(|| self.fallback_sidebar_area(RailKind::Machine, height))
    }

    pub fn workspace_sidebar_area(&self, height: u16) -> Option<Rect> {
        self.sidebar_layout
            .workspace
            .or_else(|| self.fallback_sidebar_area(RailKind::Workspace, height))
    }

    pub fn tabs_sidebar_area(&self, height: u16) -> Option<Rect> {
        self.sidebar_layout.tabs.or_else(|| self.fallback_sidebar_area(RailKind::Tabs, height))
    }

    pub(crate) fn projection_sidebar_area(&self, index: usize) -> Option<Rect> {
        self.sidebar_layout.rail(RailKind::Projection(index))
    }

    pub(crate) fn projection_sidebar_focused(&self, index: usize) -> bool {
        self.focus == FocusTarget::ProjectionRail(index)
    }

    pub(crate) fn projection_rows(&self, index: usize) -> Vec<ProjectionRow> {
        let Some(spec) = self.config.sidebar.views.get(index) else { return Vec::new() };
        let empty_collapsed = HashSet::new();
        let collapsed = self
            .projection_rails
            .get(&spec.id)
            .map(|state| &state.collapsed)
            .unwrap_or(&empty_collapsed);
        let agents = if spec.includes(SidebarResourceKind::Agents) {
            // Finished reports are historical records, not active agents.
            // Otherwise detached "surface..." rows remain forever after exit.
            self.session
                .agents()
                .into_iter()
                .filter(|agent| !matches!(agent.state.as_str(), "done" | "unknown"))
                .collect::<Vec<_>>()
        } else {
            Vec::new()
        };
        crate::sidebar_projection::rows(
            spec,
            &self.tree,
            &agents,
            self.sidebar_workspace_selection,
            collapsed,
        )
    }

    pub(crate) fn sidebar_action_rows(&self, index: usize) -> Vec<SidebarActionRow> {
        let Some(spec) = self.config.sidebar.views.get(index) else { return Vec::new() };
        let messages = &localization::catalog().sidebar;
        spec.actions
            .iter()
            .flat_map(|action_spec| {
                let action = action_spec.action;
                let label_override = action_spec.label.as_deref();
                if action == Action::NewWorkspace {
                    return self
                        .workspace_creation_modes()
                        .into_iter()
                        .map(|mode| SidebarActionRow {
                            label: match mode {
                                // A configured label renames the plain
                                // button; the provider-specific isolated and
                                // shared variants keep their catalog labels.
                                None => {
                                    label_override.unwrap_or(messages.new_workspace).to_string()
                                }
                                Some(WorkspaceCreationMode::Isolated) => {
                                    messages.new_isolated_workspace.to_string()
                                }
                                Some(WorkspaceCreationMode::Host) => {
                                    messages.new_shared_workspace.to_string()
                                }
                            },
                            target: SidebarActionTarget::CreateWorkspace(mode),
                        })
                        .collect::<Vec<_>>();
                }
                self.action_available(action)
                    .then(|| SidebarActionRow {
                        label: label_override
                            .map(str::to_string)
                            .unwrap_or_else(|| self.action_display_label(action).to_string()),
                        target: SidebarActionTarget::Run(action),
                    })
                    .into_iter()
                    .collect()
            })
            .collect()
    }

    /// Menu items for a configurable `+` button's right-click menu.
    fn plus_menu_items(
        &self,
        plus: &crate::config::PlusButton,
        pane: Option<PaneId>,
    ) -> Vec<MenuItem> {
        plus.menu
            .iter()
            .filter(|spec| self.action_available(spec.action))
            .map(|spec| MenuItem::LabeledAction {
                label: spec
                    .label
                    .clone()
                    .unwrap_or_else(|| self.action_display_label(spec.action).to_string()),
                action: MenuAction::RunConfigured { action: spec.action, pane },
            })
            .collect()
    }

    /// Where the workspace rail's pinned action buttons render.
    pub(crate) fn workspace_actions_position(&self) -> crate::config::ActionsPosition {
        self.view_index_for_rail(RailKind::Workspace)
            .and_then(|index| self.config.sidebar.views.get(index))
            .map(|spec| spec.actions_position)
            .unwrap_or_default()
    }

    /// Expand the configured workspace row label template. The default
    /// template borrows the name, so ordinary draws do not allocate.
    pub(crate) fn workspace_button_label<'a>(
        &self,
        index: usize,
        name: &'a str,
    ) -> std::borrow::Cow<'a, str> {
        let template = &self.config.sidebar.workspace_label;
        if template == "{name}" {
            return std::borrow::Cow::Borrowed(name);
        }
        std::borrow::Cow::Owned(
            template.replace("{index}", &index.to_string()).replace("{name}", name),
        )
    }

    pub(crate) fn projection_rail_state_mut(&mut self, index: usize) -> &mut ProjectionRailState {
        let id = self
            .config
            .sidebar
            .views
            .get(index)
            .map(|view| view.id.clone())
            .unwrap_or_else(|| format!("missing-{index}"));
        self.projection_rails.entry(id).or_default()
    }

    fn invoke_sidebar_action(
        &mut self,
        target: SidebarActionTarget,
    ) -> anyhow::Result<RenderAction> {
        match target {
            SidebarActionTarget::Run(action) => self.run_action(action),
            SidebarActionTarget::CreateWorkspace(mode) => {
                self.create_workspace(mode, None)?;
                Ok(RenderAction::Draw)
            }
        }
    }

    pub(crate) fn sidebar_tab_targets(&self) -> Vec<SidebarTabTarget> {
        if self.workspace_rail_selection != WorkspaceRailSelection::Workspace {
            return Vec::new();
        }
        let workspace_index =
            self.sidebar_workspace_selection.min(self.tree.workspaces.len().saturating_sub(1));
        let Some(workspace) = self.tree.workspaces.get(workspace_index) else {
            return Vec::new();
        };
        workspace
            .screens
            .iter()
            .enumerate()
            .flat_map(|(screen_index, screen)| {
                screen.panes.iter().flat_map(move |pane| {
                    pane.tabs.iter().enumerate().map(move |(tab_index, tab)| {
                        let name = tab
                            .name
                            .as_deref()
                            .filter(|name| !name.is_empty())
                            .or_else(|| (!tab.title.is_empty()).then_some(tab.title.as_str()))
                            .unwrap_or(tab.short_id.as_str())
                            .to_string();
                        let subtitle = if workspace.screens.len() > 1 {
                            format!("{} · {}", screen.display_name(screen_index), pane.short_id)
                        } else {
                            pane.short_id.clone()
                        };
                        let active = workspace_index == self.tree.active_workspace
                            && screen_index == workspace.active_screen
                            && pane.id == screen.active_pane
                            && tab_index == pane.active_tab;
                        SidebarTabTarget {
                            workspace: workspace_index,
                            screen: screen_index,
                            pane: pane.id,
                            index: tab_index,
                            surface: tab.surface,
                            name,
                            subtitle,
                            active,
                        }
                    })
                })
            })
            .collect()
    }

    fn activate_sidebar_tab(&mut self, target: &SidebarTabTarget) -> anyhow::Result<()> {
        if !self.prepare_pty_input_before_mutation() {
            return Ok(());
        }
        if !self.tree.select_surface(target.surface) {
            return Ok(());
        }
        self.follow_sidebar_workspace(target.workspace);
        self.pane_focus_history.record(target.pane);
        self.claim_active_terminal_geometry(true);
        Ok(())
    }

    fn follow_sidebar_workspace(&mut self, index: usize) {
        if self.sidebar_workspace_selection != index {
            self.tabs_rail_selection = 0;
            self.tabs_rail_scroll = 0;
        }
        self.sidebar_workspace_selection = index;
        self.workspace_rail_selection = WorkspaceRailSelection::Workspace;
    }

    fn activate_workspace(&mut self, index: usize) {
        if index >= self.tree.workspaces.len() || !self.prepare_pty_input_before_mutation() {
            return;
        }
        self.follow_sidebar_workspace(index);
        self.tree.active_workspace = index;
        self.select_workspace_for_client(Some(index), None);
    }

    fn activate_projection_target(&mut self, target: ProjectionTarget) -> anyhow::Result<()> {
        match target {
            ProjectionTarget::Workspace { index, .. } => {
                self.activate_workspace(index);
            }
            ProjectionTarget::Pane { workspace, screen, pane } => {
                if !self.prepare_pty_input_before_mutation() {
                    return Ok(());
                }
                self.follow_sidebar_workspace(workspace);
                self.tree.active_workspace = workspace;
                if let Some(workspace_view) = self.tree.workspaces.get_mut(workspace) {
                    workspace_view.active_screen = screen;
                    if let Some(screen_view) = workspace_view.screens.get_mut(screen) {
                        screen_view.active_pane = pane;
                    }
                }
                self.pane_focus_history.record(pane);
                self.claim_active_terminal_geometry(true);
            }
            ProjectionTarget::Surface { workspace, screen, pane, index, surface, .. } => {
                self.activate_sidebar_tab(&SidebarTabTarget {
                    workspace,
                    screen,
                    pane,
                    index,
                    surface,
                    name: String::new(),
                    subtitle: String::new(),
                    active: false,
                })?;
            }
        }
        Ok(())
    }

    pub fn total_sidebar_width(&self) -> u16 {
        let layout_width = self.sidebar_layout.total_width();
        if layout_width > 0 {
            layout_width
        } else {
            self.machine_sidebar_width
                .saturating_add(self.sidebar_width)
                .saturating_add(self.tabs_sidebar_width)
        }
    }

    fn visible_rail_order(&self) -> Vec<RailKind> {
        self.sidebar_layout.ordered.iter().map(|placement| placement.kind).collect()
    }

    fn focusable_rail_order(&self) -> Vec<RailKind> {
        let order = self.visible_rail_order();
        if !order.is_empty() {
            return order;
        }
        let size = (
            self.sidebar_layout.content.x.saturating_add(self.sidebar_layout.content.width),
            self.sidebar_layout.content.height.saturating_add(1),
        );
        if size.0 == 0 || size.1 == 0 {
            return Vec::new();
        }
        let hidden_views = self
            .hidden_sidebar_views
            .get(&self.config.sidebar.active_profile)
            .cloned()
            .unwrap_or_default();
        sidebar_layout_for_state(
            &self.config,
            true,
            self.sidebar_compact,
            self.machine_ui.is_some(),
            size,
            self.sidebar_width_override,
            self.machine_sidebar_width_override,
            self.tabs_sidebar_width_override,
            &self.projection_sidebar_width_overrides,
            &hidden_views,
            None,
        )
        .ordered
        .iter()
        .map(|placement| placement.kind)
        .collect()
    }

    fn rail_kind_for_view(&self, index: usize) -> RailKind {
        self.config.sidebar.views.get(index).and_then(|view| view.legacy_kind()).map_or(
            RailKind::Projection(index),
            |kind| match kind {
                SidebarColumnKind::Machines => RailKind::Machine,
                SidebarColumnKind::Workspaces => RailKind::Workspace,
                SidebarColumnKind::Tabs => RailKind::Tabs,
            },
        )
    }

    pub(crate) fn view_index_for_rail(&self, kind: RailKind) -> Option<usize> {
        self.sidebar_layout
            .ordered
            .iter()
            .find(|placement| placement.kind == kind)
            .map(|placement| placement.view_index)
            .or_else(|| {
                self.config.sidebar.views.iter().enumerate().find_map(|(index, _)| {
                    (self.rail_kind_for_view(index) == kind).then_some(index)
                })
            })
    }

    pub(crate) fn workspace_sidebar_action_rows(&self) -> Vec<SidebarActionRow> {
        self.view_index_for_rail(RailKind::Workspace)
            .map(|index| self.sidebar_action_rows(index))
            .unwrap_or_default()
    }

    fn focus_rail(&mut self, kind: RailKind) {
        self.focus = match kind {
            RailKind::Machine => FocusTarget::MachineRail,
            RailKind::Workspace => FocusTarget::WorkspaceRail,
            RailKind::Tabs => FocusTarget::TabsRail,
            RailKind::Projection(index) => FocusTarget::ProjectionRail(index),
        };
    }

    fn focus_adjacent_rail(&mut self, kind: RailKind, delta: isize) -> bool {
        let order = self.visible_rail_order();
        let Some(index) = order.iter().position(|candidate| *candidate == kind) else {
            return false;
        };
        let next = index as isize + delta;
        let Some(next) = usize::try_from(next).ok().filter(|next| *next < order.len()) else {
            return false;
        };
        self.focus_rail(order[next]);
        true
    }

    fn move_focus_between_sidebar_rails(&mut self, direction: Direction) -> bool {
        let Some(kind) = self.focused_rail_kind() else { return false };
        match direction {
            Direction::Left => {
                self.focus_adjacent_rail(kind, -1);
                true
            }
            Direction::Right => {
                if !self.focus_adjacent_rail(kind, 1) {
                    self.focus = FocusTarget::Pane;
                }
                true
            }
            Direction::Up | Direction::Down => false,
        }
    }

    fn focus_rightmost_sidebar_rail(&mut self) -> bool {
        if !self.sidebar_visible || self.surface_only.is_some() {
            return false;
        }
        let Some(kind) = self.visible_rail_order().last().copied() else {
            return false;
        };
        self.focus_rail(kind);
        true
    }

    fn leave_workspace_sidebar(&mut self) {
        if self.sidebar_rail_focused() {
            self.focus = FocusTarget::Pane;
        }
    }

    fn host_input_is_ready(
        deferred_len: usize,
        deferred_bytes: usize,
        route_settled: bool,
        input: &HostInputMessage,
    ) -> bool {
        match input {
            HostInputMessage::Event(event) => {
                let input_bytes = host_event_retained_bytes(event);
                input_bytes > MAX_DEFERRED_INPUT_BYTES
                    || deferred_len < DEFERRED_INPUT_CAPACITY
                        && deferred_bytes.saturating_add(input_bytes) <= MAX_DEFERRED_INPUT_BYTES
            }
            HostInputMessage::Failed(_) => route_settled && deferred_len == 0,
        }
    }

    fn drain_host_input_batch(&mut self, maximum: usize) -> anyhow::Result<(RenderAction, usize)> {
        let mut action = RenderAction::None;
        let mut drained = 0;
        while drained < maximum && !self.quit {
            let deferred_len = self.deferred_input.len();
            let deferred_bytes = self.deferred_input.retained_bytes();
            let route_settled = !self.session.has_pending_mutations()
                && !self.session.remote_tree_is_stale()
                && self.mux_recovery_generation.load(Ordering::Acquire) == 0
                && self.pending_pointer_motion.is_none();
            let Some(input) = self.host_input.pop_if(|input| {
                Self::host_input_is_ready(deferred_len, deferred_bytes, route_settled, input)
            }) else {
                break;
            };
            let event = match input {
                HostInputMessage::Event(event) => AppEvent::Input(event),
                HostInputMessage::Failed(error) => AppEvent::HostInputFailed(error),
            };
            action = self.handle_event_and_process_machine_requests(event, action)?;
            drained += 1;
        }
        Ok((action, drained))
    }

    fn handle_event_and_process_machine_requests(
        &mut self,
        event: AppEvent,
        mut action: RenderAction,
    ) -> anyhow::Result<RenderAction> {
        action = action.merge(self.handle(event)?);
        action = action.merge(self.process_machine_requests());
        self.mark_pointer_route_for_rebuild(action);
        Ok(action)
    }

    fn event_loop<B: Backend>(
        &mut self,
        terminal: &mut RatatuiTerminal<B>,
        rx: crossbeam_channel::Receiver<AppEvent>,
    ) -> anyhow::Result<()>
    where
        B::Error: Send + Sync + 'static,
    {
        // Initial layout + draw.
        self.draw_terminal(terminal, RenderAction::Draw)?;
        self.emit_graphics()?;
        self.commit_rendered_pointer_frame();
        self.pointer_route_phase = if self.pending_graphics_submission.is_some() {
            PointerRoutePhase::GraphicsProcessingPending
        } else {
            PointerRoutePhase::Fresh
        };
        self.journal_frontend_presentation();
        let mut terminal_paints = TerminalPaintPacer::after_paint(Instant::now());

        let mut replay_ready =
            !self.deferred_input.is_empty() || self.pending_pointer_motion.is_some();
        while !self.quit
            && !crate::shutdown_requested()
            && !self.session.daemon_shutdown_requested()
            && !self.owner_shutdown_requested()
        {
            if replay_ready {
                let replay = self.replay_deferred_input_batch()?;
                let action = terminal_paints.render_immediately(replay.action, Instant::now());
                self.render_action(terminal, action)?;
                self.retry_pending_surface_attach();
                replay_ready = self.replay_can_continue_immediately(replay.disposition);
                continue;
            }
            let (mut action, drained_host_input) = self.drain_host_input_batch(256)?;
            // Block for the first event, then drain whatever queued so a
            // torrent of pty output coalesces into one frame.
            let timeout = if drained_host_input > 0 {
                Duration::ZERO
            } else if self.viewport_animation_active() {
                Duration::from_millis(16)
            } else if self.shake_frames > 0
                || self.selection_auto_scroll_active()
                || self.toast.is_some()
            {
                Duration::from_millis(30)
            } else {
                Duration::from_millis(250)
            };
            let timeout = terminal_paints.wait_timeout(timeout, Instant::now());
            let mut toast_expired_on_timeout = false;
            let first = match rx.recv_timeout(timeout) {
                Ok(event) => Some(event),
                Err(crossbeam_channel::RecvTimeoutError::Timeout) => {
                    if self.shake_frames > 0 {
                        action = RenderAction::Draw;
                    }
                    if self.auto_scroll_selection_tick() {
                        action = action.merge(RenderAction::Draw);
                    }
                    if self.expire_toast() {
                        toast_expired_on_timeout = true;
                        action = action.merge(RenderAction::Draw);
                    }
                    if self.tick_sidebar_files() {
                        action = action.merge(RenderAction::Draw);
                    }
                    None
                }
                Err(crossbeam_channel::RecvTimeoutError::Disconnected) => {
                    let action =
                        terminal_paints.render_immediately(RenderAction::None, Instant::now());
                    self.render_action(terminal, action)?;
                    break;
                }
            };
            // Timeout work can mutate hit-tested state without entering
            // `handle`. Publish its pending render boundary before draining
            // pointer input that arrived concurrently with the timeout.
            self.mark_pointer_route_for_rebuild(action);
            #[cfg(test)]
            if first.is_none()
                && let Some(hook) = self.timeout_drain_hook.take()
            {
                hook(self);
            }
            if let Some(event) = first {
                action = self.handle_event_and_process_machine_requests(event, action)?;
            }
            for _ in 0..256 {
                match rx.try_recv() {
                    Ok(event) => {
                        action = self.handle_event_and_process_machine_requests(event, action)?;
                    }
                    Err(_) => break,
                }
            }
            action = action.merge(self.apply_graphics_completion());
            action = action.merge(self.process_machine_requests());
            // Always drain retained failures. PtyFailuresReady only shortens
            // the idle wait, so a failed try_send cannot create a lost wakeup.
            action = action.merge(self.apply_pty_failures());
            self.ensure_graphics_writer_healthy()?;
            if self.session.take_cancellation_pending() {
                if self.session.has_pending_mutations() {
                    self.session.defer_cancellation();
                } else {
                    self.apply_session_cancellation();
                    action = action.merge(RenderAction::Draw);
                }
            }
            if self.quit {
                break;
            }
            // Keep a toast reintroduced by the timeout drain hook alive for one iteration.
            if !toast_expired_on_timeout && self.expire_toast() {
                action = action.merge(RenderAction::Draw);
            }
            action = action.merge(self.advance_viewport_animation(Instant::now()));
            if self.advance_expired_durable_notice() {
                action = action.merge(RenderAction::Draw);
            }
            self.retry_pending_surface_attach();
            if self.browser_input.resize_retry_due() {
                let mut visible_surfaces =
                    self.pane_areas.iter().map(|area| area.surface).collect::<HashSet<_>>();
                if let Some(surface) = self.sidebar_plugin_surface {
                    visible_surfaces.insert(surface);
                }
                if self.browser_input.visible_resize_retry_due(&visible_surfaces) {
                    self.reassert_visible_surface_sizes();
                }
            }
            if self.session.surface_resize_retry_due() {
                self.reassert_visible_surface_sizes();
            }
            self.retry_sidebar_plugin_if_due();
            self.retry_background_refresh_if_due();
            if self.session.surface_overflow_retry_due() {
                action = action.merge(RenderAction::Draw);
            }
            let now = Instant::now();
            let action = terminal_paints.schedule(action, now);
            let action = if !self.deferred_input.is_empty() || self.pending_pointer_motion.is_some()
            {
                terminal_paints.render_immediately(action, now)
            } else {
                action
            };
            self.render_action(terminal, action)?;
            self.retry_pending_surface_attach();
            if !self.deferred_input.is_empty() || self.pending_pointer_motion.is_some() {
                let replay = self.replay_deferred_input_batch()?;
                let action = terminal_paints.render_immediately(replay.action, Instant::now());
                self.render_action(terminal, action)?;
                self.retry_pending_surface_attach();
                replay_ready = self.replay_can_continue_immediately(replay.disposition);
            }
        }
        Ok(())
    }

    fn restart_machine_updates(&mut self) -> anyhow::Result<()> {
        let Some(worker) = self.machine_action_worker.as_ref() else {
            return Ok(());
        };
        if !worker.subscribe_updates() {
            anyhow::bail!(localization::catalog().sidebar.machine_replacement_worker_stopped)
        }
        Ok(())
    }

    fn replace_machine_updates(
        &mut self,
        updates: Option<MachineUpdateStream>,
    ) -> anyhow::Result<()> {
        let generation = self.machine_update_generation.wrapping_add(1).max(1);
        let next = updates
            .map(|updates| MachineUpdatePump::spawn(updates, self.app_events.clone(), generation))
            .transpose()?;
        if let Some(mut current) = self.machine_update_pump.take() {
            current.stop_and_join();
        }
        self.machine_update_pump = next;
        self.machine_update_generation = generation;
        Ok(())
    }

    fn shutdown_background_workers(&mut self) {
        if let Some(stop) = self.status_command_worker_stop.take() {
            stop.raise();
        }
        // Join, so a status command's process group is reaped before exit.
        // The capture loop observes the flag every poll tick, so each join
        // is bounded by that tick.
        for handle in
            self.status_command_workers.drain(..).chain(self.retiring_status_workers.drain(..))
        {
            let _ = handle.join();
        }
        self.frontend_journal.stop_and_join();
        if let Some(mut updates) = self.machine_update_pump.take() {
            updates.stop_and_join();
        }
        if let Some(mut actions) = self.machine_action_worker.take() {
            actions.shutdown();
        }
        if let Some(mut session_events) = self.session_event_worker.take() {
            session_events.stop_and_join();
        }
        if let Some(mut owner_reload) = self.owner_reload_worker.take() {
            owner_reload.stop_and_join();
        }
    }

    fn shutdown_runtime_components(&mut self) {
        self.shutdown_background_workers();
        self.cancel_pointer_interaction();
        self.session.begin_shutdown();
        let _ = self.pty_input.shutdown(Duration::from_secs(3));
        if let Some(writer) = self.graphics_writer.as_mut() {
            writer.shutdown(Duration::from_millis(200));
        }
        let _ = std::panic::take_hook();
    }

    fn process_machine_requests(&mut self) -> RenderAction {
        self.submit_pending_durable_notice_ack();
        if self.machine_action_in_flight {
            return RenderAction::None;
        }
        if let Some(retry_at) = self.machine_provider_reconnect_retry_at {
            if Instant::now() < retry_at {
                if self
                    .machine_ui
                    .as_ref()
                    .is_some_and(|ui| matches!(ui.request, Some(MachineRequest::ReconnectProvider)))
                {
                    return RenderAction::None;
                }
            } else if let Some(ui) = self.machine_ui.as_mut()
                && ui.request.is_none()
            {
                ui.request = Some(MachineRequest::ReconnectProvider);
            }
        }
        let Some(request) = self.machine_ui.as_mut().and_then(|ui| ui.request.take()) else {
            return RenderAction::None;
        };
        crate::client_log::info(
            "machine",
            &format!("dispatching machine request: {}", request.kind()),
        );
        if let MachineRequest::Switch(machine) = &request {
            self.select_machine_intent(*machine);
        }
        let Some(worker) = self.machine_action_worker.as_ref() else {
            if let Some(ui) = self.machine_ui.as_mut() {
                ui.request = Some(request);
            }
            self.quit = true;
            return RenderAction::None;
        };
        let preparation = MachineSessionPreparation {
            initial_size: content_size_for_rect(
                self.content_area,
                self.config.scrollbar.position,
                self.config.pane.padding,
            ),
            generation: self.session_generation.wrapping_add(1).max(1),
            pty_input: self.pty_input.sender(),
            surface_filter: self.surface_only,
        };
        match worker.perform(request.clone(), preparation) {
            Ok(()) => {
                self.machine_action_connection_attempt = self
                    .connection_transaction
                    .as_ref()
                    .filter(|transaction| {
                        matches!(
                            &request,
                            MachineRequest::Connect { target, route }
                                if target == &transaction.target && route == &transaction.route
                        )
                    })
                    .map(|transaction| transaction.attempt);
                self.machine_action_in_flight = true;
                self.machine_action_request = Some(request);
                self.machine_action_intent_generation = Some(self.machine_selection_generation);
            }
            Err(MachineSubmitError::Busy(request)) => {
                if let Some(ui) = self.machine_ui.as_mut() {
                    ui.request = Some(request);
                }
            }
            Err(MachineSubmitError::Stopped(request)) => {
                if let Some(ui) = self.machine_ui.as_mut() {
                    ui.request = Some(request);
                }
                self.quit = true;
            }
        }
        RenderAction::None
    }

    fn schedule_machine_provider_reconnect(&mut self) {
        self.machine_provider_reconnect_attempts =
            self.machine_provider_reconnect_attempts.saturating_add(1);
        let exponent = self
            .machine_provider_reconnect_attempts
            .saturating_sub(1)
            .min(MACHINE_PROVIDER_RECONNECT_MAX_BACKOFF_EXPONENT);
        self.machine_provider_reconnect_retry_at =
            Some(Instant::now() + Duration::from_secs(1_u64 << exponent));
        if let Some(ui) = self.machine_ui.as_mut()
            && ui.request.is_none()
        {
            ui.request = Some(MachineRequest::ReconnectProvider);
        }
    }

    fn clear_machine_provider_reconnect(&mut self) {
        self.machine_provider_reconnect_attempts = 0;
        self.machine_provider_reconnect_retry_at = None;
    }

    fn connection_attempt_was_canceled(&self, attempt: Option<u64>) -> bool {
        attempt.is_some() && self.canceled_machine_connection_attempt == attempt
    }

    fn take_machine_action_request(&mut self) -> (Option<MachineRequest>, Option<u64>, bool) {
        self.machine_action_intent_generation = None;
        let request = self.machine_action_request.take();
        let attempt = self.machine_action_connection_attempt.take();
        let canceled = self.connection_attempt_was_canceled(attempt);
        if canceled {
            self.canceled_machine_connection_attempt = None;
        }
        (request, attempt, canceled)
    }

    fn connection_request_matches(
        &self,
        request: Option<&MachineRequest>,
        attempt: Option<u64>,
    ) -> bool {
        let Some(transaction) = self.connection_transaction.as_ref() else { return false };
        attempt == Some(transaction.attempt)
            && matches!(
                request,
                Some(MachineRequest::Connect { target, route })
                    if target == &transaction.target && route == &transaction.route
            )
    }

    fn advance_connection_transaction(
        &mut self,
        request: Option<&MachineRequest>,
        attempt: Option<u64>,
        phase: ConnectionDialogPhase,
    ) {
        if self.connection_request_matches(request, attempt)
            && let Some(transaction) = self.connection_transaction.as_mut()
        {
            transaction.phase = phase;
        }
    }

    fn fail_connection_transaction(
        &mut self,
        request: Option<&MachineRequest>,
        attempt: Option<u64>,
        error: String,
    ) -> bool {
        if !self.connection_request_matches(request, attempt) {
            return false;
        }
        self.advance_connection_transaction(
            request,
            attempt,
            ConnectionDialogPhase::Failed(error.clone()),
        );
        self.status_message = Some(error);
        true
    }

    fn report_machine_action_failure(
        &mut self,
        request: Option<&MachineRequest>,
        attempt: Option<u64>,
        message: String,
    ) {
        let is_connection = matches!(request, Some(MachineRequest::Connect { .. }));
        let matched = self.fail_connection_transaction(request, attempt, message.clone());
        if !matched && (!is_connection || self.connection_transaction.is_none()) {
            self.status_message = Some(message);
        }
    }

    fn complete_connection_transaction(
        &mut self,
        request: Option<&MachineRequest>,
        attempt: Option<u64>,
    ) {
        if !self.connection_request_matches(request, attempt) {
            return;
        }
        self.connection_transaction = None;
        if self
            .prompt
            .as_ref()
            .is_some_and(|prompt| matches!(prompt.target, PromptTarget::ConnectMachine(_)))
        {
            self.prompt = None;
        }
    }

    fn fail_machine_action(&mut self, request: Option<&MachineRequest>) {
        crate::client_log::info(
            "machine",
            &format!(
                "machine request failed: {}",
                request.map(MachineRequest::kind).unwrap_or("none")
            ),
        );
        if let Some(MachineRequest::Switch(machine)) = request
            && let Some(ui) = self.machine_ui.as_mut()
        {
            ui.set_connection_phase(*machine, MachineConnectionPhase::Failed);
            // A stale progress message must not sit under "unavailable".
            ui.clear_connection_progress(*machine);
        }
    }

    fn apply_machine_controller_completion(
        &mut self,
        completion: MachineControllerCompletion,
    ) -> RenderAction {
        match completion {
            MachineControllerCompletion::DurableNoticeAcknowledged { delivery, result } => {
                let mut continue_acknowledgements = true;
                if self.durable_notice_ack_in_flight.as_ref() == Some(&delivery) {
                    self.durable_notice_ack_in_flight = None;
                    match result {
                        Ok(()) => {
                            self.durable_notice_ack_failures = 0;
                            self.durable_notice_ack_retry_at = None;
                        }
                        Err(_) => {
                            continue_acknowledgements = false;
                            self.durable_notice_ack_failures =
                                self.durable_notice_ack_failures.saturating_add(1);
                            let exponent = self
                                .durable_notice_ack_failures
                                .saturating_sub(1)
                                .min(DURABLE_NOTICE_ACK_MAX_BACKOFF_EXPONENT);
                            self.durable_notice_ack_retry_at =
                                Some(Instant::now() + Duration::from_secs(1_u64 << exponent));
                            self.schedule_machine_provider_reconnect();
                        }
                    }
                }
                if continue_acknowledgements {
                    self.submit_pending_durable_notice_ack();
                }
                RenderAction::None
            }
            MachineControllerCompletion::Updates(updates) => {
                if let Err(error) = updates
                    .map_err(anyhow::Error::msg)
                    .and_then(|updates| self.replace_machine_updates(updates))
                {
                    self.status_message = Some(format!(
                        "{}: {error}",
                        localization::catalog().sidebar.machine_catalog_updates_failed
                    ));
                    return RenderAction::Draw;
                }
                RenderAction::None
            }
            MachineControllerCompletion::Action { result, updates } => {
                self.machine_action_in_flight = false;
                let (request, connection_attempt, connection_canceled) =
                    self.take_machine_action_request();
                let reconnecting =
                    matches!(request.as_ref(), Some(MachineRequest::ReconnectProvider));
                if connection_canceled {
                    drop((result, updates));
                    return RenderAction::Draw;
                }
                let result = match result {
                    Ok(result) => result,
                    Err(error) => {
                        self.fail_machine_action(request.as_ref());
                        if reconnecting {
                            self.schedule_machine_provider_reconnect();
                        }
                        let message = format!(
                            "{}: {error}",
                            localization::catalog().sidebar.machine_action_failed
                        );
                        self.report_machine_action_failure(
                            request.as_ref(),
                            connection_attempt,
                            message,
                        );
                        return RenderAction::Draw;
                    }
                };
                if reconnecting {
                    self.clear_machine_provider_reconnect();
                }
                let MachineActionResult {
                    ui,
                    replacement,
                    restart_updates: _,
                    session_mutation,
                    session_label,
                } = *result;
                debug_assert!(replacement.is_none());
                let mut action = RenderAction::None;
                drop(replacement);
                if let Some(label) = session_label {
                    self.session_label = label;
                }
                action = action.merge(self.apply_machine_ui_update(ui));
                // Provider notices apply before local mirror errors so they cannot mask them.
                if let Some(mutation) = session_mutation {
                    self.apply_managed_workspace_session_mutation(mutation);
                }
                if let Some(updates) = updates
                    && let Err(error) = updates
                        .map_err(anyhow::Error::msg)
                        .and_then(|updates| self.replace_machine_updates(updates))
                {
                    self.status_message = Some(format!(
                        "{}: {error}",
                        localization::catalog().sidebar.machine_catalog_restart_failed
                    ));
                    action = action.merge(RenderAction::Draw);
                }
                self.complete_connection_transaction(request.as_ref(), connection_attempt);
                action
            }
            MachineControllerCompletion::ReplacementPrepared { action_id, action } => {
                let connection_canceled =
                    self.connection_attempt_was_canceled(self.machine_action_connection_attempt);
                if self.pending_machine_replacement.is_some() {
                    if let Some(worker) = self.machine_action_worker.as_ref() {
                        let _ = worker.abort_replacement(action_id);
                    }
                    self.machine_action_in_flight = false;
                    let (request, connection_attempt, connection_canceled) =
                        self.take_machine_action_request();
                    self.fail_machine_action(request.as_ref());
                    if matches!(request.as_ref(), Some(MachineRequest::ReconnectProvider)) {
                        self.schedule_machine_provider_reconnect();
                    }
                    let message = format!(
                        "{}: {}",
                        localization::catalog().sidebar.machine_action_failed,
                        localization::catalog().sidebar.machine_replacement_pending
                    );
                    if !connection_canceled {
                        self.report_machine_action_failure(
                            request.as_ref(),
                            connection_attempt,
                            message,
                        );
                    }
                    return RenderAction::Draw;
                }
                let request = self.machine_action_request.clone();
                self.advance_connection_transaction(
                    request.as_ref(),
                    self.machine_action_connection_attempt,
                    ConnectionDialogPhase::Starting,
                );
                let present = !connection_canceled
                    && self.machine_action_intent_generation
                        == Some(self.machine_selection_generation)
                    && match self.machine_action_request.as_ref() {
                        Some(MachineRequest::Switch(_)) => action
                            .session
                            .machine
                            .is_none_or(|machine| self.machine_selection_intent == Some(machine)),
                        _ => true,
                    };
                crate::client_log::info(
                    "machine",
                    &format!(
                        "replacement prepared: present={present} canceled={connection_canceled}"
                    ),
                );
                self.pending_machine_replacement =
                    Some(PendingMachineReplacement { action_id, present, action: *action });
                if self
                    .machine_action_worker
                    .as_ref()
                    .is_none_or(|worker| !worker.commit_replacement(action_id, present))
                {
                    self.pending_machine_replacement.take();
                    self.machine_action_in_flight = false;
                    let (request, connection_attempt, connection_canceled) =
                        self.take_machine_action_request();
                    self.fail_machine_action(request.as_ref());
                    if matches!(request.as_ref(), Some(MachineRequest::ReconnectProvider)) {
                        self.schedule_machine_provider_reconnect();
                    }
                    let message = format!(
                        "{}: {}",
                        localization::catalog().sidebar.machine_action_failed,
                        localization::catalog().sidebar.machine_replacement_worker_stopped
                    );
                    if !connection_canceled {
                        self.report_machine_action_failure(
                            request.as_ref(),
                            connection_attempt,
                            message,
                        );
                    }
                    return RenderAction::Draw;
                }
                RenderAction::Draw
            }
            MachineControllerCompletion::ReplacementSettled { action_id, committed, updates } => {
                if self
                    .pending_machine_replacement
                    .as_ref()
                    .is_none_or(|pending| pending.action_id != action_id)
                {
                    self.status_message = Some(format!(
                        "{}: {}",
                        localization::catalog().sidebar.machine_action_failed,
                        localization::catalog().sidebar.machine_replacement_stale
                    ));
                    return RenderAction::Draw;
                }
                let pending = self
                    .pending_machine_replacement
                    .take()
                    .expect("matching pending replacement was checked");
                self.machine_action_in_flight = false;
                let (request, connection_attempt, connection_canceled) =
                    self.take_machine_action_request();
                let reconnecting =
                    matches!(request.as_ref(), Some(MachineRequest::ReconnectProvider));
                let mut action = RenderAction::None;
                match committed {
                    Ok(true) => {
                        if reconnecting {
                            self.clear_machine_provider_reconnect();
                        }
                        let PendingMachineReplacement { present, action: prepared, .. } = pending;
                        let present = present && !connection_canceled;
                        let PreparedMachineAction { ui, session_mutation, session_label, session } =
                            prepared;
                        let target = session.machine;
                        crate::client_log::info(
                            "machine",
                            &format!(
                                "replacement settled: present={present} target={:?} ui_active={:?}",
                                target.map(|k| k.0),
                                ui.snapshot.active.map(|k| k.0),
                            ),
                        );
                        if present {
                            self.machine_presented = target.or(ui.snapshot.active);
                            // A runtime-driven replacement (deleting the open
                            // machine) presents without a Switch dispatch, so
                            // the aim never moved; align it, or every later
                            // keystroke fails the intent==presented gate and
                            // input goes nowhere.
                            if let Some(machine) = self.machine_presented {
                                self.select_machine_intent(machine);
                            }
                            if let Some(machine) = self.machine_presented
                                && let Some(machine_ui) = self.machine_ui.as_mut()
                            {
                                machine_ui.clear_connection_progress(machine);
                            }
                            self.install_prepared_machine_session(session, false);
                            if let Some(label) = session_label {
                                self.session_label = label;
                            }
                            action = action.merge(self.apply_machine_ui_update(ui));
                            // The rail follows the machine that now presents,
                            // not whatever row reconciliation kept (the
                            // deleted machine's recoverable ghost, usually).
                            if let Some(machine) = self.machine_presented
                                && let Some(machine_ui) = self.machine_ui.as_mut()
                            {
                                machine_ui.select_rail_target(MachineRailTarget::Machine(machine));
                            }
                            // Provider notices apply before local mirror errors so they cannot mask them.
                            if let Some(mutation) = session_mutation {
                                self.apply_managed_workspace_session_mutation(mutation);
                            }
                            if self.tree.active_surface().is_some() {
                                self.focus = FocusTarget::Pane;
                            }
                        } else {
                            if let Some(target) = target
                                && let Some(ui) = self.machine_ui.as_mut()
                            {
                                ui.set_connection_phase(target, MachineConnectionPhase::Ready);
                            }
                            drop((ui, session_mutation, session_label, session));
                            action = action.merge(RenderAction::Draw);
                        }
                        self.complete_connection_transaction(request.as_ref(), connection_attempt);
                    }
                    Ok(false) => {
                        crate::client_log::info("machine", "replacement settled: not committed");
                        drop(pending);
                        if reconnecting {
                            self.schedule_machine_provider_reconnect();
                        }
                    }
                    Err(error) => {
                        drop(pending);
                        self.fail_machine_action(request.as_ref());
                        if reconnecting {
                            self.schedule_machine_provider_reconnect();
                        }
                        if !connection_canceled {
                            let message = format!(
                                "{}: {error}",
                                localization::catalog().sidebar.machine_action_failed
                            );
                            self.report_machine_action_failure(
                                request.as_ref(),
                                connection_attempt,
                                message,
                            );
                        }
                        action = action.merge(RenderAction::Draw);
                    }
                }
                if let Some(updates) = updates
                    && let Err(error) = updates
                        .map_err(anyhow::Error::msg)
                        .and_then(|updates| self.replace_machine_updates(updates))
                {
                    self.status_message = Some(format!(
                        "{}: {error}",
                        localization::catalog().sidebar.machine_catalog_restart_failed
                    ));
                    action = action.merge(RenderAction::Draw);
                }
                action
            }
        }
    }

    fn apply_managed_workspace_session_mutation(
        &mut self,
        mutation: ManagedWorkspaceSessionMutation,
    ) {
        if !self.session.workspaces_are_provider_managed()
            && let Err(error) = self.session.mark_workspaces_provider_managed()
        {
            self.status_message = Some(
                localization::catalog()
                    .sidebar
                    .workspace_state_failed
                    .replace("{error}", &error.to_string()),
            );
            return;
        }
        let (workspace_key, rename) = match mutation {
            ManagedWorkspaceSessionMutation::Rename { workspace_key, name } => {
                (workspace_key, Some(name))
            }
            ManagedWorkspaceSessionMutation::Close { workspace_key } => (workspace_key, None),
        };
        let Some(workspace_id) = self
            .tree
            .workspaces
            .iter()
            .find(|workspace| workspace.key == workspace_key)
            .map(|workspace| workspace.id)
        else {
            self.status_message =
                Some(localization::catalog().sidebar.managed_workspace_unavailable.to_string());
            return;
        };
        // Queued mirror failures settle through SessionMutationOutcome::Failed.
        // Missing mirrors must be surfaced here because no operation is queued.
        if let Some(name) = rename {
            self.session.rename_provider_managed_workspace(workspace_id, workspace_key, name);
        } else {
            self.session.close_provider_managed_workspace(workspace_id, workspace_key);
        }
    }

    fn apply_machine_ui_update(&mut self, mut update: MachineUiState) -> RenderAction {
        if self.machine_ui.is_none()
            && self.machine_selection_intent.is_none()
            && self.machine_presented.is_none()
        {
            self.machine_selection_intent = update.snapshot.active;
            self.machine_presented = update.snapshot.active;
        }
        // A machine is "usable" while it is in the catalog and not soft
        // deleted: providers with recovery keep deleted machines listed as
        // Recoverable rows, which can be restored or purged but never
        // presented.
        let machine_usable = |update: &MachineUiState, key: MachineKey| {
            update.snapshot.machines.iter().any(|machine| machine.key == key)
                && update
                    .managed_machine(key)
                    .is_none_or(|managed| managed.status != ManagedMachineStatus::Recoverable)
        };
        update.snapshot.active =
            self.machine_presented.filter(|presented| machine_usable(&update, *presented));
        // A queued switch aimed at a machine that just became unusable (the
        // wake that raced its own deletion) must not survive: it would both
        // fail pointlessly and block the failover below.
        let doomed_request = match &update.request {
            // The wake that raced its own deletion.
            Some(MachineRequest::Switch(target)) => !machine_usable(&update, *target),
            // The stream-loss recovery for the machine being deleted: the
            // provider link is demonstrably alive (this update just arrived
            // over it), and reconnecting would only reopen the deleted
            // machine. Let the failover below aim somewhere usable instead.
            Some(MachineRequest::ReconnectProvider) => {
                self.machine_presented.is_some_and(|presented| !machine_usable(&update, presented))
            }
            _ => false,
        };
        if doomed_request {
            crate::client_log::info(
                "machine",
                "dropped a queued request aimed at a deleted machine",
            );
            update.request = None;
            // An intent left aiming at the deleted machine would fail the
            // input-routing gate forever (intent != presented with nothing
            // queued to repair it): fall back to the still-usable presented
            // machine, or clear it so the failover below takes over.
            if self.machine_selection_intent.is_some_and(|intent| !machine_usable(&update, intent))
            {
                self.machine_selection_intent =
                    self.machine_presented.filter(|presented| machine_usable(&update, *presented));
            }
        }
        // The presented machine was deleted (gone from the catalog, or left
        // behind as a Recoverable row): its session is dead, so input must
        // never route into it, whatever else is queued or in flight.
        let presented_deleted =
            self.machine_presented.is_some_and(|presented| !machine_usable(&update, presented));
        if !presented_deleted {
            // A deferred deletion can recover before failover runs. Do not
            // carry its old slot into a later, unrelated deletion.
            self.machine_deleted_rail_index = None;
        }
        if presented_deleted {
            if self.machine_deleted_rail_index.is_none()
                && let Some(presented) = self.machine_presented
            {
                self.machine_deleted_rail_index = self.machine_ui.as_ref().and_then(|previous| {
                    previous.snapshot.machines.iter().position(|machine| machine.key == presented)
                });
            }
            update.session_available = false;
        }
        // Switch to the next available machine instead of leaving the dead
        // session on screen. "Next" is the usable machine at or after its
        // old list slot, else the last usable one. Deferred (input stays
        // gated above) while another request occupies the queue slot or the
        // user is already aiming somewhere else usable; the next update
        // with a free slot re-enters this path.
        let mut failover_rail_target = None;
        let failed_intent_is_stale = self
            .machine_selection_intent
            .filter(|intent| Some(*intent) != self.machine_presented)
            .is_some_and(|intent| {
                !self.machine_action_in_flight
                    && (update.connection_phase(intent) == MachineConnectionPhase::Failed
                        || self.machine_ui.as_ref().is_some_and(|previous| {
                            previous.connection_phase(intent) == MachineConnectionPhase::Failed
                        }))
            });
        if presented_deleted
            && let Some(presented) = self.machine_presented
            && update.request.is_none()
            && !self.machine_action_in_flight
            && self.machine_selection_intent.is_none_or(|intent| {
                intent == presented || !machine_usable(&update, intent) || failed_intent_is_stale
            })
        {
            let previous_index = self
                .machine_deleted_rail_index
                .or_else(|| {
                    self.machine_ui
                        .as_ref()
                        .and_then(|previous| {
                            previous
                                .snapshot
                                .machines
                                .iter()
                                .position(|machine| machine.key == presented)
                        })
                        .or_else(|| {
                            update
                                .snapshot
                                .machines
                                .iter()
                                .position(|machine| machine.key == presented)
                        })
                })
                .unwrap_or(0);
            let next_key = update
                .snapshot
                .machines
                .iter()
                .enumerate()
                .filter(|(_, machine)| machine_usable(&update, machine.key))
                .map(|(index, machine)| (index, machine.key))
                .fold(None, |best: Option<(usize, MachineKey)>, (index, key)| match best {
                    // Prefer the first usable machine at or after the old
                    // slot; otherwise keep the last usable one before it.
                    Some((chosen, _)) if chosen >= previous_index => best,
                    _ if index >= previous_index => Some((index, key)),
                    _ => Some((index, key)),
                })
                .map(|(_, key)| key);
            match next_key {
                Some(next_key) => {
                    crate::client_log::info(
                        "machine",
                        &format!(
                            "presented machine {} was deleted; switching to {}",
                            presented.0, next_key.0
                        ),
                    );
                    update.request = Some(MachineRequest::Switch(next_key));
                    failover_rail_target = Some(next_key);
                    self.machine_deleted_rail_index = None;
                    // The presented session belongs to a deleted machine:
                    // gate input away from it while the failover switch runs
                    // (a failed switch leaves the rail on the replacement,
                    // where Enter retries).
                    update.session_available = false;
                }
                None => {
                    crate::client_log::info(
                        "machine",
                        &format!(
                            "presented machine {} was deleted; no usable machine remains",
                            presented.0
                        ),
                    );
                    // Nothing usable remains: drop the presentation instead
                    // of routing input into the deleted machine's dead
                    // session. The rail keeps its create and connect rows.
                    self.machine_presented = None;
                    self.machine_selection_intent = None;
                    self.machine_deleted_rail_index = None;
                    update.session_available = false;
                }
            }
        }
        let guard_error = (uses_provider_managed_workspaces(Some(&update))
            && !self.session.workspaces_are_provider_managed())
        .then(|| self.session.mark_workspaces_provider_managed().err())
        .flatten()
        .map(|error| error.to_string());
        if guard_error.is_some() {
            update.session_available = false;
        }
        let provider_changed = self
            .machine_ui
            .as_ref()
            .and_then(|machine| machine.provider.as_ref())
            != update.provider.as_ref()
            || self.machine_ui.as_ref().map(MachineUiState::managed_workspaces).unwrap_or_default()
                != update.managed_workspaces()
            || self.machine_ui.as_ref().map(MachineUiState::managed_machines).unwrap_or_default()
                != update.managed_machines();
        if provider_changed {
            if self.menu.as_ref().is_some_and(ContextMenu::targets_provider_state) {
                self.menu = None;
            }
            if self.prompt.as_ref().is_some_and(|prompt| {
                matches!(
                    prompt.target,
                    PromptTarget::ProviderAction(_)
                        | PromptTarget::ConfirmProviderAction
                        | PromptTarget::ManagedWorkspace(_)
                        | PromptTarget::ConfirmPurgeManagedWorkspace(_)
                        | PromptTarget::ManagedMachine(_)
                        | PromptTarget::ConfirmDeleteManagedMachine(_)
                        | PromptTarget::ConfirmPurgeManagedMachine(_)
                )
            }) {
                self.prompt = None;
                self.pending_provider_action = None;
            }
        }
        if let Some(previous) = self.machine_ui.as_ref() {
            if let Some(MachineRequest::Switch(machine)) = previous.request.as_ref()
                && self.machine_selection_intent == Some(*machine)
                && machine_usable(&update, *machine)
                && update.request.is_none()
            {
                crate::client_log::info(
                    "machine",
                    &format!("preserving the pending switch to {}", machine.0),
                );
                update.request = Some(MachineRequest::Switch(*machine));
            }
            update.extend_connection_phases_from(previous);
            update.reconcile_navigation_from(previous);
        }
        if let Some(next_key) = failover_rail_target {
            // After reconciliation, which would otherwise keep the still
            // listed (recoverable) row selected.
            update.select_rail_target(MachineRailTarget::Machine(next_key));
        }
        let notice = update.notice.clone();
        self.machine_ui = Some(update);
        self.machine_pointer_context_cache = None;
        self.reconcile_workspace_rail_selection();
        if let Some(error) = guard_error {
            self.status_message = Some(error);
        } else if let Some(notice) = notice {
            self.status_notice_text = Some(notice.clone());
            self.status_message = Some(notice);
        }
        RenderAction::Draw
    }

    fn accept_durable_notice(&mut self, notice: DurableProviderNotice) -> RenderAction {
        let delivery = notice.delivery.clone();
        if let Some(queued) =
            self.durable_notices.iter().find(|queued| queued.notice.delivery == delivery)
        {
            if queued.painted_at.is_some() {
                self.queue_durable_notice_ack(delivery);
            }
            return RenderAction::None;
        }
        if self.recent_durable_notices.contains(&delivery) {
            self.queue_durable_notice_ack(delivery);
            return RenderAction::None;
        }
        if self.durable_notices.len() >= DURABLE_NOTICE_QUEUE_CAPACITY {
            // A conforming provider has one delivery in flight, so this only
            // trips for a broken or hostile stream. Leave the new delivery
            // unacknowledged and reconnect so the durable cursor can replay it
            // after queued notices drain.
            self.schedule_machine_provider_reconnect();
            return RenderAction::None;
        }
        let level = match notice.level {
            DurableNoticeLevel::Error => "ERROR",
            DurableNoticeLevel::Warning => "WARN",
            DurableNoticeLevel::Info => "INFO",
        };
        crate::client_log::log(level, "provider-notice", &notice.message);
        self.durable_notices.push_back(QueuedDurableNotice { notice, painted_at: None });
        RenderAction::Draw
    }

    pub(crate) fn durable_notice(&self) -> Option<&DurableProviderNotice> {
        self.durable_notices.front().map(|queued| &queued.notice)
    }

    pub(crate) fn record_durable_notice_painted(&mut self, delivery: DurableNoticeDelivery) {
        self.painted_durable_notice_this_frame = Some(delivery);
    }

    fn commit_successful_durable_notice_paint(&mut self) {
        let Some(delivery) = self.painted_durable_notice_this_frame.take() else {
            return;
        };
        let Some(front) = self.durable_notices.front_mut() else {
            return;
        };
        if front.notice.delivery != delivery || front.painted_at.is_some() {
            return;
        }
        front.painted_at = Some(Instant::now());
        self.remember_durable_notice(delivery.clone());
        self.queue_durable_notice_ack(delivery);
    }

    fn dismiss_painted_durable_notice(&mut self) -> bool {
        if self.durable_notices.front().is_none_or(|front| front.painted_at.is_none()) {
            return false;
        }
        self.durable_notices.pop_front();
        true
    }

    fn durable_notice_banner_row(&self) -> Option<u16> {
        self.durable_notices.front().and_then(|front| front.painted_at).and_then(|_| {
            let content_bottom = self.content_area.y.saturating_add(self.content_area.height);
            if self.surface_only.is_some() {
                content_bottom.checked_sub(1)
            } else {
                Some(content_bottom)
            }
        })
    }

    fn advance_expired_durable_notice(&mut self) -> bool {
        let expired = self.durable_notices.front().is_some_and(|front| {
            front
                .painted_at
                .is_some_and(|painted_at| painted_at.elapsed() >= DURABLE_NOTICE_DISPLAY_DURATION)
        });
        if expired {
            self.durable_notices.pop_front();
        }
        expired
    }

    fn remember_durable_notice(&mut self, delivery: DurableNoticeDelivery) {
        if self.recent_durable_notices.contains(&delivery) {
            return;
        }
        if self.recent_durable_notices.len() == DURABLE_NOTICE_RECENT_CAPACITY {
            self.recent_durable_notices.pop_front();
        }
        self.recent_durable_notices.push_back(delivery);
    }

    fn queue_durable_notice_ack(&mut self, delivery: DurableNoticeDelivery) {
        if self.durable_notice_ack_in_flight.as_ref() == Some(&delivery)
            || self.pending_durable_notice_acks.contains(&delivery)
        {
            return;
        }
        self.pending_durable_notice_acks.push_back(delivery);
    }

    fn submit_pending_durable_notice_ack(&mut self) {
        if self.durable_notice_ack_in_flight.is_some()
            || self.machine_action_in_flight
            || self.pending_machine_replacement.is_some()
        {
            return;
        }
        if let Some(retry_at) = self.durable_notice_ack_retry_at {
            if Instant::now() < retry_at {
                return;
            }
            self.durable_notice_ack_retry_at = None;
        }
        let Some(delivery) = self.pending_durable_notice_acks.pop_front() else {
            return;
        };
        let Some(worker) = self.machine_action_worker.as_ref() else {
            self.pending_durable_notice_acks.push_front(delivery);
            return;
        };
        let in_flight = delivery.clone();
        match worker.acknowledge_durable_notice(delivery) {
            Ok(()) => self.durable_notice_ack_in_flight = Some(in_flight),
            Err(delivery) => self.pending_durable_notice_acks.push_front(delivery),
        }
    }

    fn install_prepared_machine_session(
        &mut self,
        prepared: PreparedMachineSession,
        retire_previous: bool,
    ) {
        self.cancel_pointer_interaction();
        let PreparedMachineSession {
            session,
            event_worker,
            generation,
            mux_titles,
            mux_recovery_generation,
            tree,
            label,
            session_available,
            machine: _,
        } = prepared;
        self.pty_input.activate_session_generation(generation);
        self.session_generation = generation;
        self.last_frontend_presentation = None;
        let previous_session = std::mem::replace(&mut self.session, session);
        let previous_worker = self.session_event_worker.replace(event_worker);
        self.mux_titles = mux_titles;
        self.mux_recovery_generation = mux_recovery_generation;
        self.session_label = label;
        self.reset_session_presentation(tree);
        if let Some(worker) = self.session_event_worker.as_ref() {
            worker.activate();
        }
        if session_available {
            if publishes_global_cell_metrics(self.surface_only) {
                self.session.set_cell_pixel_size(self.cell_pixels.0, self.cell_pixels.1);
            }
            self.session.apply_config(self.config.clone());
            self.session.refresh_clients_background();
        }

        if let Some(mut previous_worker) = previous_worker {
            previous_worker.stop_and_join();
        }
        if retire_previous {
            previous_session.begin_shutdown();
        }
    }

    fn reset_session_presentation(&mut self, tree: TreeView) {
        for surface in self.tab_locations.keys().copied().collect::<Vec<_>>() {
            self.browser_input.forget_surface(surface);
        }
        self.tree = tree;
        self.tab_locations.clear();
        self.rebuild_tab_locations();
        self.render_states.clear();
        self.pane_areas.clear();
        self.viewport_projection.clear();
        self.viewport_layout.clear();
        self.viewport_stacked_headers.clear();
        self.viewport_states.clear();
        self.viewport_virtual_width = 0;
        self.viewport_offset = 0;
        self.pane_focus_history = PaneFocusHistory::default();
        self.pane_focus_history.sync_membership(&self.tree);
        // The adopted tree's focus is the server's own; report only what the
        // user changes afterwards.
        self.reported_focus = self.current_client_focus();
        self.restore_client_focus_from_session();
        self.rendered_terminal_sizes.clear();
        self.rendered_terminal_pointer_semantics.clear();
        self.rendered_pane_content_generations.clear();
        self.rendered_terminal_bounds.clear();
        self.rendered_kitty_graphics.clear();
        self.graphics_scene_cache.invalidate();
        self.graphics_dirty_surfaces.clear();
        self.visible_size_surfaces.clear();
        self.pending_size_releases.clear();
        self.geometry_authority_surface = None;
        self.prefix_armed = false;
        self.sidebar_focus_pending = false;
        self.sidebar_files =
            FileBrowser::new(std::env::current_dir().unwrap_or_else(|_| PathBuf::from(".")));
        self.sidebar_workspace_selection =
            self.tree.active_workspace.min(self.tree.workspaces.len().saturating_sub(1));
        self.sidebar_recoverable_workspace_selection = 0;
        self.workspace_rail_selection = WorkspaceRailSelection::Workspace;
        self.tabs_rail_selection = 0;
        self.tabs_rail_scroll = 0;
        self.tabs_rail_follow_selection = true;
        self.sidebar_followed_surface = None;
        self.sidebar_plugin_surface = None;
        self.sidebar_plugin_error = None;
        self.sidebar_plugin_retry_after_ms = None;
        self.sidebar_plugin_retry_at = None;
        self.hits.clear();
        self.tab_scroll.clear();
        self.hover = None;
        self.menu = None;
        self.clients.clear();
        self.client_border_labels.clear();
        self.prompt = None;
        self.pairing_dialog = None;
        self.pairing_queue.clear();
        self.omnibar = None;
        self.toast = None;
        self.shake_frames = 0;
        self.replace_selection(None);
        self.last_browser_hover = None;
        self.deferred_input.clear();
        self.pending_pointer_motion = None;
        self.deferred_input_sequence = 0;
        self.rendered_pointer_frame = RenderedPointerFrame::default();
        // Retain processed and in-flight graphics state until the replacement
        // session presents its first snapshot. The writer may still present
        // an older accepted submission before the replacement is written.
        self.pointer_route_phase = PointerRoutePhase::DrawPending;
        self.layout_refresh_retries_remaining = 0;
        self.background_refresh_attempts = 0;
        self.background_refresh_retry_at = None;
        self.last_applied_refresh_sequence = 0;
        self.applied_destination_generation = 0;
        self.pending_session_completions.clear();
        self.drag = None;
        self.active_pointer_buttons.clear();
        self.ignored_pty_mouse_buttons.clear();
        self.encode_buf.clear();
    }

    /// A machine that is sleeping or stopped lost its stream BECAUSE it was
    /// paused; reconnecting would start it right back up and make pause
    /// impossible. Present it as asleep instead - the user's next input (or
    /// a rail click) wakes it through the normal switch path.
    fn present_machine_as_asleep_after_stream_loss(&mut self) -> bool {
        let Some(machine) = self.machine_ui.as_mut() else { return false };
        let Some(active) = machine.snapshot.active else { return false };
        if !machine.snapshot.machines.iter().any(|descriptor| {
            descriptor.key == active
                && matches!(
                    descriptor.status,
                    crate::machine::MachineStatus::Sleeping
                        | crate::machine::MachineStatus::Stopped
                )
        }) {
            return false;
        }
        crate::client_log::info(
            "machine",
            &format!("stream lost for sleeping machine {}; presenting as asleep", active.0),
        );
        machine.session_available = false;
        machine.set_connection_phase(active, MachineConnectionPhase::Disconnected);
        // The previous open's narration is stale now; a later wake
        // reuses the same selection intent, so select_machine_intent
        // will not clear it.
        machine.clear_connection_progress(active);
        true
    }

    fn request_current_machine_session(&mut self) -> bool {
        if self.present_machine_as_asleep_after_stream_loss() {
            return true;
        }
        let Some(machine) = self.machine_ui.as_mut() else { return false };
        if machine.request.is_none() {
            let request = machine
                .snapshot
                .active
                .map_or(MachineRequest::ReconnectProvider, MachineRequest::Switch);
            crate::client_log::info(
                "machine",
                &format!("stream lost; queueing {request:?} to reconnect"),
            );
            machine.request = Some(request);
        }
        true
    }

    /// The user typed at a machine whose session is gone (it paused or the
    /// stream died while they were away). Queue a switch back to it: the
    /// provider resumes the VM and the interstitial shows the live loading
    /// states. Returns false when there is nothing sensible to wake.
    fn wake_presented_machine(&mut self) -> bool {
        let Some(presented) = self.machine_presented else { return false };
        // While a switch to a DIFFERENT machine is in flight the key must
        // not re-aim back at the old machine (that could resume a machine
        // the user deliberately left paused). Consume it; the transition
        // interstitial is visible and the switch will settle.
        if self.machine_selection_intent.is_some_and(|intent| intent != presented) {
            return true;
        }
        {
            let Some(machine) = self.machine_ui.as_mut() else { return false };
            if machine.request.is_some() {
                return true;
            }
            machine.request = Some(MachineRequest::Switch(presented));
        }
        self.select_machine_intent(presented);
        if let Some(ui) = self.machine_ui.as_mut() {
            // select_machine_intent keeps the presented machine's phase; the
            // wake is a real reconnect, so the interstitial must show it.
            ui.set_connection_phase(presented, MachineConnectionPhase::Connecting);
        }
        true
    }

    fn render_action<B: Backend>(
        &mut self,
        terminal: &mut RatatuiTerminal<B>,
        action: RenderAction,
    ) -> anyhow::Result<()>
    where
        B::Error: Send + Sync + 'static,
    {
        self.ensure_graphics_writer_healthy()?;
        self.mark_pointer_route_for_rebuild(action);
        match action {
            RenderAction::Draw | RenderAction::Paint => {
                self.draw_terminal(terminal, action)?;
                self.emit_graphics()?;
            }
            RenderAction::Graphics => self.emit_dirty_graphics()?,
            RenderAction::None => {}
        }
        if action.rebuilds_pointer_route() {
            self.commit_rendered_pointer_frame_for(action);
            self.pointer_route_phase = if self.pending_graphics_submission.is_some() {
                PointerRoutePhase::GraphicsProcessingPending
            } else {
                PointerRoutePhase::Fresh
            };
        }
        self.journal_frontend_presentation();
        Ok(())
    }

    fn frontend_presentation_snapshot(&self) -> FrontendPresentationSnapshot {
        let workspace = self.tree.active_workspace();
        let screen = workspace.and_then(|workspace| workspace.active_screen_ref());
        let pane = screen.and_then(|screen| screen.pane(screen.active_pane));
        let tab = pane.and_then(|pane| pane.tabs.get(pane.active_tab));
        let focus = FrontendFocusSnapshot {
            target: match self.focus {
                FocusTarget::Pane => FrontendFocusTarget::Pane,
                FocusTarget::MachineRail => FrontendFocusTarget::MachineRail,
                FocusTarget::WorkspaceRail => FrontendFocusTarget::WorkspaceRail,
                FocusTarget::TabsRail => FrontendFocusTarget::TabsRail,
                FocusTarget::ProjectionRail(_) => FrontendFocusTarget::ProjectionRail,
            },
            workspace_id: workspace.and_then(|workspace| workspace.resource_id.clone()),
            screen_id: screen.and_then(|screen| screen.resource_id.clone()),
            pane_id: pane.and_then(|pane| pane.resource_id.clone()),
            tab_id: tab.and_then(|tab| tab.public_id.clone()),
            content_id: tab.and_then(|tab| tab.content_id.clone()),
        };
        let resize = FrontendResizeSnapshot {
            cols: self.outer_size.0,
            rows: self.outer_size.1,
            cell_width: self.cell_pixels.0,
            cell_height: self.cell_pixels.1,
        };
        let (target, settled) = screen
            .and_then(|screen| self.viewport_states.get(&screen.id))
            .map_or((self.viewport_offset, true), |motion| {
                (motion.target.round() as u64, !motion.animating())
            });
        let viewport = FrontendViewportSnapshot {
            screen_id: screen.and_then(|screen| screen.resource_id.clone()),
            offset: if settled { self.viewport_offset } else { target },
            target,
            settled,
        };
        FrontendPresentationSnapshot { focus, resize, viewport }
    }

    fn frontend_presentation_unchanged(&self) -> bool {
        let Some(previous) = &self.last_frontend_presentation else { return false };
        let workspace = self.tree.active_workspace();
        let screen = workspace.and_then(|workspace| workspace.active_screen_ref());
        let pane = screen.and_then(|screen| screen.pane(screen.active_pane));
        let tab = pane.and_then(|pane| pane.tabs.get(pane.active_tab));
        let target = match self.focus {
            FocusTarget::Pane => FrontendFocusTarget::Pane,
            FocusTarget::MachineRail => FrontendFocusTarget::MachineRail,
            FocusTarget::WorkspaceRail => FrontendFocusTarget::WorkspaceRail,
            FocusTarget::TabsRail => FrontendFocusTarget::TabsRail,
            FocusTarget::ProjectionRail(_) => FrontendFocusTarget::ProjectionRail,
        };
        if previous.focus.target != target
            || previous.focus.workspace_id.as_ref()
                != workspace.and_then(|workspace| workspace.resource_id.as_ref())
            || previous.focus.screen_id.as_ref()
                != screen.and_then(|screen| screen.resource_id.as_ref())
            || previous.focus.pane_id.as_ref() != pane.and_then(|pane| pane.resource_id.as_ref())
            || previous.focus.tab_id.as_ref() != tab.and_then(|tab| tab.public_id.as_ref())
            || previous.focus.content_id.as_ref() != tab.and_then(|tab| tab.content_id.as_ref())
        {
            return false;
        }
        if previous.resize
            != (FrontendResizeSnapshot {
                cols: self.outer_size.0,
                rows: self.outer_size.1,
                cell_width: self.cell_pixels.0,
                cell_height: self.cell_pixels.1,
            })
        {
            return false;
        }
        let (target, settled) = screen
            .and_then(|screen| self.viewport_states.get(&screen.id))
            .map_or((self.viewport_offset, true), |motion| {
                (motion.target.round() as u64, !motion.animating())
            });
        previous.viewport.screen_id.as_ref()
            == screen.and_then(|screen| screen.resource_id.as_ref())
            && previous.viewport.offset == if settled { self.viewport_offset } else { target }
            && previous.viewport.target == target
            && previous.viewport.settled == settled
    }

    fn journal_frontend_presentation(&mut self) {
        if self.outer_size.0 == 0 || self.outer_size.1 == 0 {
            return;
        }
        if self.frontend_presentation_unchanged() {
            return;
        }
        let next = self.frontend_presentation_snapshot();
        let previous = self.last_frontend_presentation.replace(next.clone());
        let generation = format!("{}_{}", self.frontend_projection_id, self.session_generation);
        let session = self.session.inner.clone();
        if previous.as_ref().is_none_or(|previous| previous.focus != next.focus) {
            let focus = next.focus;
            self.frontend_journal.send(
                session.clone(),
                FrontendJournalEvent::Focus {
                    event_id: frontend_journal_event_id(),
                    frontend_projection_id: self.frontend_projection_id.clone(),
                    generation: generation.clone(),
                    target: focus.target,
                    workspace_id: focus.workspace_id,
                    screen_id: focus.screen_id,
                    pane_id: focus.pane_id,
                    tab_id: focus.tab_id,
                    content_id: focus.content_id,
                },
            );
        }
        if previous.as_ref().is_none_or(|previous| previous.resize != next.resize) {
            let resize = next.resize;
            self.frontend_journal.send(
                session.clone(),
                FrontendJournalEvent::Resize {
                    event_id: frontend_journal_event_id(),
                    frontend_projection_id: self.frontend_projection_id.clone(),
                    generation: generation.clone(),
                    cols: resize.cols,
                    rows: resize.rows,
                    cell_width: resize.cell_width,
                    cell_height: resize.cell_height,
                },
            );
        }
        if previous.as_ref().is_none_or(|previous| previous.viewport != next.viewport) {
            let viewport = next.viewport;
            self.frontend_journal.send(
                session,
                FrontendJournalEvent::Viewport {
                    event_id: frontend_journal_event_id(),
                    frontend_projection_id: self.frontend_projection_id.clone(),
                    generation,
                    screen_id: viewport.screen_id,
                    offset: viewport.offset,
                    target: viewport.target,
                    settled: viewport.settled,
                },
            );
        }
    }

    fn mark_pointer_route_for_rebuild(&mut self, action: RenderAction) {
        self.pointer_route_phase = self.pointer_route_phase.with_action(action);
    }

    fn refresh_machine_pointer_context(&mut self) -> Option<Arc<MachinePointerContext>> {
        let Some(ui) = self.machine_ui.as_ref() else {
            self.machine_pointer_context_cache = None;
            return None;
        };
        let matches_live = self.machine_pointer_context_cache.as_ref().is_some_and(|context| {
            context.snapshot == ui.snapshot
                && context.provider == ui.provider
                && context.workspace_creation == ui.workspace_creation_policy()
        });
        if !matches_live {
            self.machine_pointer_context_cache = Some(Arc::new(MachinePointerContext {
                snapshot: ui.snapshot.clone(),
                provider: ui.provider.clone(),
                workspace_creation: ui.workspace_creation_policy(),
            }));
        }
        self.machine_pointer_context_cache.clone()
    }

    fn pointer_hit_identity(
        &self,
        hit: Hit,
        machine_context: Option<&Arc<MachinePointerContext>>,
    ) -> Option<PointerHitIdentity> {
        match hit {
            Hit::NewVm
            | Hit::ConnectMachine
            | Hit::CreateWorkspace { .. }
            | Hit::SidebarAction { action: SidebarActionTarget::CreateWorkspace(_), .. } => {
                machine_context.cloned().map(PointerHitIdentity::MachineContext)
            }
            Hit::Machine { key, .. } => machine_context.cloned().map(|context| {
                PointerHitIdentity::Machine(MachinePointerTarget {
                    context,
                    machine: key,
                    managed: self
                        .machine_ui
                        .as_ref()
                        .and_then(|ui| ui.managed_machine(key))
                        .cloned(),
                })
            }),
            Hit::RecoverableWorkspace { index } => self
                .machine_ui
                .as_ref()
                .and_then(|ui| ui.recoverable_workspaces().get(index).copied())
                .map(|workspace| PointerHitIdentity::RecoverableWorkspace(workspace.id.clone())),
            Hit::SidebarFile { index } => self
                .sidebar_files
                .visible_entry(index)
                .map(|entry| PointerHitIdentity::SidebarFile(entry.path.clone())),
            Hit::SidebarFilterInput => Some(PointerHitIdentity::SidebarFilter(
                self.sidebar_files.current_dir().to_path_buf(),
            )),
            Hit::NewScreen => self
                .tree
                .active_workspace()
                .map(|workspace| PointerHitIdentity::NewScreen(workspace.id)),
            Hit::Tab { pane, index } => self
                .tree
                .pane(pane)
                .and_then(|pane| pane.tabs.get(index))
                .map(|tab| PointerHitIdentity::Tab(tab.surface)),
            Hit::SidebarTab { surface, .. } => Some(PointerHitIdentity::Tab(surface)),
            Hit::ProjectionRow { target: ProjectionTarget::Surface { surface, .. }, .. } => {
                Some(PointerHitIdentity::Tab(surface))
            }
            Hit::Workspace { .. }
            | Hit::ProjectionRow { .. }
            | Hit::ProjectionToggle { .. }
            | Hit::RailPad(_)
            | Hit::SidebarAction { .. }
            | Hit::ScreenEntry { .. }
            | Hit::StatusMessage
            | Hit::CopyStatusMessage
            | Hit::NewTab { .. }
            | Hit::Clients { .. }
            | Hit::Scrollbar { .. }
            | Hit::HorizontalScrollbar { .. }
            | Hit::WorkspaceScrollbar { .. }
            | Hit::RailResize(_)
            | Hit::PaneResize { .. }
            | Hit::TabScroll { .. } => None,
        }
    }

    fn menu_action_resource(&self, action: MenuAction) -> Option<MenuActionResource> {
        match action {
            MenuAction::RenameSurface(surface) => Some(MenuActionResource::Surface(surface)),
            MenuAction::CopyStatusMessage => {
                self.status_message.clone().map(MenuActionResource::StatusMessage)
            }
            MenuAction::BrowserBack(pane)
            | MenuAction::BrowserForward(pane)
            | MenuAction::BrowserReload(pane)
            | MenuAction::BrowserEditUrl(pane)
            | MenuAction::BrowserCopyUrl(pane)
            | MenuAction::BrowserActivate(pane)
            | MenuAction::RenameTab(pane)
            | MenuAction::CopyTabId(pane)
            | MenuAction::CloseTab(pane) => self
                .tree
                .pane(pane)
                .and_then(|pane| pane.active_surface())
                .map(MenuActionResource::Surface),
            MenuAction::RestoreManagedWorkspace(index)
            | MenuAction::PurgeManagedWorkspace(index) => {
                let machine = self.machine_ui.as_ref()?.snapshot.active?;
                self.machine_ui.as_ref()?.recoverable_workspaces().get(index).map(|workspace| {
                    MenuActionResource::ManagedWorkspace {
                        machine,
                        id: workspace.id.clone(),
                        version: workspace.version,
                    }
                })
            }
            MenuAction::SelectProviderScope(index) => {
                let ui = self.machine_ui.as_ref()?;
                ui.provider.as_ref()?.scopes.get(index).map(|scope| {
                    MenuActionResource::ProviderScope {
                        machine: ui.snapshot.active,
                        id: scope.id.clone(),
                    }
                })
            }
            MenuAction::InvokeProviderAction(index) => {
                let ui = self.machine_ui.as_ref()?;
                ui.provider.as_ref()?.actions.get(index).map(|action| {
                    MenuActionResource::ProviderAction {
                        machine: ui.snapshot.active,
                        id: action.id.clone(),
                    }
                })
            }
            MenuAction::CreateMachineFrom(index) => self
                .machine_ui
                .as_ref()?
                .creation_sources
                .get(index)
                .map(|source| MenuActionResource::MachineCreationSource(source.id.clone())),
            MenuAction::ConnectMachineTarget(index) => {
                self.machine_ui.as_ref()?.connection_targets.get(index).map(|target| {
                    MenuActionResource::MachineConnectionTarget(target.target.clone())
                })
            }
            MenuAction::ActivateSidebarProfile(index) => self
                .config
                .sidebar
                .profiles
                .get(index)
                .map(|profile| MenuActionResource::SidebarProfile(profile.id.clone())),
            MenuAction::SetSidebarViewVisible { view, .. } => {
                self.config.sidebar.views.get(view).map(|view| MenuActionResource::SidebarView {
                    profile: self.config.sidebar.active_profile.clone(),
                    view: view.id.clone(),
                })
            }
            _ => None,
        }
    }

    fn rendered_menu_snapshot(&self, reuse_owners: bool) -> Option<Arc<[RenderedMenuLevel]>> {
        let menu = self.menu.as_ref()?;
        if reuse_owners
            && let Some(rendered) = self.rendered_pointer_frame.menu.as_ref()
            && rendered.len() == menu.levels.len()
            && rendered.iter().zip(&menu.levels).all(|(rendered, live)| {
                rendered.rect == live.rect
                    && rendered.scroll_offset == live.scroll_offset
                    && Arc::ptr_eq(&rendered.items, &live.items)
            })
        {
            return Some(rendered.clone());
        }
        Some(Arc::from(
            menu.levels
                .iter()
                .map(|level| RenderedMenuLevel {
                    rect: level.rect,
                    scroll_offset: level.scroll_offset,
                    items: level.items.clone(),
                    resources: level
                        .items
                        .iter()
                        .map(|item| {
                            item.action().and_then(|action| {
                                menu.captured_resource(action)
                                    .unwrap_or_else(|| self.menu_action_resource(action))
                            })
                        })
                        .collect::<Vec<_>>()
                        .into(),
                })
                .collect::<Vec<_>>(),
        ))
    }

    fn rendered_pane_route(&self, area: &PaneArea) -> RenderedPaneRoute {
        RenderedPaneRoute {
            pane: area.pane,
            surface: area.surface,
            kind: self.surface_kind(area.surface),
            rect: area.rect,
            bar: area.bar,
            omnibar: area.omnibar,
            omnibar_source_x: area.omnibar_source_x(),
            content: area.content,
            content_source_x: area.content_source_x(),
            track: area.track,
            terminal_input: self.terminal_input_rect(area),
        }
    }

    fn commit_rendered_pointer_frame(&mut self) {
        self.commit_rendered_pointer_frame_for(RenderAction::Draw);
    }

    fn commit_rendered_pointer_frame_for(&mut self, action: RenderAction) {
        if self.outer_size.0 == 0 || self.outer_size.1 == 0 {
            self.rendered_pointer_frame = RenderedPointerFrame::default();
            return;
        }
        let pairing = self
            .pairing_dialog
            .as_ref()
            .map(|dialog| (dialog.challenge.id, dialog.rect, dialog.approve, dialog.deny));
        let prompt = self.prompt.as_ref().map(|prompt| {
            (prompt.target, prompt.rect, prompt.input_rect, prompt.clear, prompt.ok, prompt.cancel)
        });
        let omnibar = self.omnibar.as_ref().map(|state| (state.pane, state.surface));
        let sidebar_plugin = (self.config.sidebar.plugin.is_some() && self.sidebar_visible)
            .then(|| (self.sidebar_plugin_rect(), self.sidebar_plugin_surface));
        let machine_rail = self.sidebar_layout.machine;
        let workspace_rail = self.sidebar_layout.workspace;
        let tabs_rail = self.sidebar_layout.tabs;
        let projection_rails = self
            .sidebar_layout
            .ordered
            .iter()
            .filter_map(|placement| match placement.kind {
                RailKind::Projection(_) => Some((placement.kind, placement.rect)),
                _ => None,
            })
            .collect::<Vec<_>>()
            .into();
        let pointer_map_generation = self.session.pointer_map_generation();
        let reuse_owners = action == RenderAction::Paint
            && self.rendered_pointer_frame.pointer_map_generation == pointer_map_generation;
        let machine_context = if reuse_owners {
            self.rendered_pointer_frame.machine_context.clone()
        } else {
            self.refresh_machine_pointer_context()
        };
        let menu = self.rendered_menu_snapshot(reuse_owners);
        let panes_match = self.rendered_pointer_frame.panes.len() == self.pane_areas.len()
            && self
                .rendered_pointer_frame
                .panes
                .iter()
                .zip(&self.pane_areas)
                .all(|(rendered, area)| *rendered == self.rendered_pane_route(area));
        let panes = if panes_match {
            self.rendered_pointer_frame.panes.clone()
        } else {
            self.pane_areas
                .iter()
                .map(|area| self.rendered_pane_route(area))
                .collect::<Vec<_>>()
                .into()
        };
        let hits_match = reuse_owners
            && self.rendered_pointer_frame.hits.len() == self.hits.len()
            && self
                .rendered_pointer_frame
                .hits
                .iter()
                .zip(&self.hits)
                .all(|(rendered, (rect, hit))| rendered.rect == *rect && rendered.hit == *hit);
        let hits = if hits_match {
            self.rendered_pointer_frame.hits.clone()
        } else {
            self.hits
                .iter()
                .enumerate()
                .map(|(index, (rect, hit))| {
                    let reused_identity = reuse_owners
                        .then(|| {
                            self.rendered_pointer_frame
                                .hits
                                .get(index)
                                .filter(|rendered| rendered.hit == *hit)
                                .and_then(|rendered| rendered.identity.clone())
                        })
                        .flatten();
                    RenderedHitRoute {
                        rect: *rect,
                        hit: *hit,
                        identity: reused_identity.or_else(|| {
                            self.pointer_hit_identity(*hit, machine_context.as_ref()).map(Arc::new)
                        }),
                    }
                })
                .collect::<Vec<_>>()
                .into()
        };
        let terminal_pointer_semantics = if *self.rendered_pointer_frame.terminal_pointer_semantics
            == self.rendered_terminal_pointer_semantics
        {
            self.rendered_pointer_frame.terminal_pointer_semantics.clone()
        } else {
            Arc::new(self.rendered_terminal_pointer_semantics.clone())
        };
        let pane_content_generations = if *self.rendered_pointer_frame.pane_content_generations
            == self.rendered_pane_content_generations
        {
            self.rendered_pointer_frame.pane_content_generations.clone()
        } else {
            Arc::new(self.rendered_pane_content_generations.clone())
        };
        self.rendered_pointer_frame = RenderedPointerFrame {
            pairing,
            prompt,
            menu,
            omnibar,
            sidebar_plugin,
            machine_rail,
            workspace_rail,
            tabs_rail,
            projection_rails,
            hits,
            panes,
            terminal_pointer_semantics,
            pane_content_generations,
            machine_context,
            pointer_map_generation,
        };
    }

    fn pairing_identity_matches_rendered_frame(&self) -> bool {
        self.pairing_dialog.as_ref().map(|dialog| dialog.challenge.id)
            == self.rendered_pointer_frame.pairing.as_ref().map(|pairing| pairing.0)
    }

    fn replay_can_continue_immediately(&self, disposition: DeferredReplayDisposition) -> bool {
        matches!(
            disposition,
            DeferredReplayDisposition::RenderBoundary | DeferredReplayDisposition::Yield
        ) && (!self.deferred_input.is_empty() || self.pending_pointer_motion.is_some())
            && !self.next_replay_pointer_route_is_stale()
    }

    fn pointer_replay_barrier(action: RenderAction) -> DeferredReplayDisposition {
        // RenderBoundary promises the event loop that rendering this batch can
        // make the next replay attempt progress.
        if action.rebuilds_pointer_route() {
            DeferredReplayDisposition::RenderBoundary
        } else {
            DeferredReplayDisposition::Blocked
        }
    }

    fn retains_input_sequence(&self, sequence: u64) -> bool {
        self.pending_pointer_motion.is_some_and(|pointer| pointer.sequence == sequence)
            || self.deferred_input.iter().any(|input| input.sequence == sequence)
    }

    fn mark_semantic_destination_failed(&mut self, intent: u64) {
        if let Some(outcome) = self.semantic_destination_outcomes.get_mut(&intent) {
            *outcome = SemanticDestinationOutcome::Failed;
        }
    }

    fn retire_deferred_semantic_result(&mut self, input: &DeferredInput) {
        if let Some(intent) = input.admission.semantic_result {
            self.mark_semantic_destination_failed(intent);
        }
    }

    fn semantic_dependency_outcome(
        &self,
        admission: &DeferredInputAdmission,
    ) -> Option<SemanticDestinationOutcome> {
        admission.semantic_dependency.map(|intent| {
            self.semantic_destination_outcomes
                .get(&intent)
                .copied()
                .unwrap_or(SemanticDestinationOutcome::Failed)
        })
    }

    fn clear_finished_semantic_destinations(&mut self) {
        if self.deferred_input.is_empty()
            && !self
                .semantic_destination_outcomes
                .values()
                .any(|outcome| *outcome == SemanticDestinationOutcome::Pending)
        {
            self.latest_semantic_destination_intent = None;
            self.semantic_destination_outcomes.clear();
        }
    }

    fn replay_deferred_input_batch(&mut self) -> anyhow::Result<DeferredReplayOutcome> {
        const MAX_REPLAYED_INPUTS: usize = 256;
        let mut action = RenderAction::None;
        // A replayed event can discover that its destination mirror is still
        // unavailable and append itself again. Only process the queue snapshot
        // that existed at entry so a blocked attach cannot spin this frame.
        let replay_count = self
            .deferred_input
            .len()
            .saturating_add(usize::from(self.pending_pointer_motion.is_some()))
            .min(MAX_REPLAYED_INPUTS);
        let mut replayed = 0;
        while replayed < replay_count {
            let pointer_is_next = self.pending_pointer_motion.as_ref().is_some_and(|pointer| {
                self.deferred_input.front().is_none_or(|input| pointer.sequence < input.sequence)
            });
            if pointer_is_next {
                if self.pending_pointer_motion.is_some_and(|pointer| {
                    pointer.focus_generation != self.pointer_focus_generation
                }) {
                    self.pending_pointer_motion = None;
                    replayed += 1;
                    continue;
                }
                if self
                    .pending_pointer_motion
                    .is_some_and(|pointer| self.pointer_route_is_stale_for_mouse(&pointer.event))
                {
                    return Ok(DeferredReplayOutcome {
                        action,
                        disposition: Self::pointer_replay_barrier(action),
                    });
                }
                let pointer = self.pending_pointer_motion.take().unwrap();
                replayed += 1;
                let pointer_action = self.handle_replayed_input(
                    TerminalInput::Mouse(pointer.event),
                    pointer.sequence,
                    Some(ReplayedInputContext {
                        pointer: Some(DeferredPointerInput {
                            focus_generation: pointer.focus_generation,
                            pointer_map_generation: self
                                .rendered_pointer_frame
                                .pointer_map_generation,
                            route: None,
                        }),
                        admission: None,
                    }),
                )?;
                action = action.merge(pointer_action);
                action = action.merge(self.process_machine_requests());
                // A missing mirror can retain the same logical input again.
                // Stop here so later sequences cannot overtake it.
                if self.retains_input_sequence(pointer.sequence) {
                    return Ok(DeferredReplayOutcome {
                        action,
                        disposition: DeferredReplayDisposition::Blocked,
                    });
                }
                continue;
            }
            if self.session.has_pending_mutations()
                || self.session.remote_tree_is_stale()
                || self.mux_recovery_generation.load(Ordering::Acquire) != 0
            {
                return Ok(DeferredReplayOutcome {
                    action,
                    disposition: DeferredReplayDisposition::Blocked,
                });
            }
            let Some(input) = self.deferred_input.front() else { break };
            match self.semantic_dependency_outcome(&input.admission) {
                Some(SemanticDestinationOutcome::Pending) => {
                    return Ok(DeferredReplayOutcome {
                        action,
                        disposition: DeferredReplayDisposition::Blocked,
                    });
                }
                Some(SemanticDestinationOutcome::Failed) => {
                    let input = self.deferred_input.pop_front().unwrap();
                    self.retire_deferred_semantic_result(&input);
                    self.status_message = Some(
                        localization::catalog()
                            .terminal
                            .deferred_input_destination_changed
                            .to_string(),
                    );
                    action = action.merge(RenderAction::Draw);
                    replayed += 1;
                    continue;
                }
                Some(SemanticDestinationOutcome::Resolved(surface))
                    if !input.admission.client_owned
                        && !Self::input_accepts_semantic_destination(&input.event)
                        && self.input_destination(&input.event) != Some(surface) =>
                {
                    let input = self.deferred_input.pop_front().unwrap();
                    self.retire_deferred_semantic_result(&input);
                    self.status_message = Some(
                        localization::catalog()
                            .terminal
                            .deferred_input_destination_changed
                            .to_string(),
                    );
                    action = action.merge(RenderAction::Draw);
                    replayed += 1;
                    continue;
                }
                Some(SemanticDestinationOutcome::Resolved(_)) | None => {}
            }
            if input
                .pointer
                .as_ref()
                .is_some_and(|pointer| pointer.focus_generation != self.pointer_focus_generation)
            {
                self.deferred_input.pop_front();
                replayed += 1;
                continue;
            }
            if let TerminalInput::Mouse(mouse) = &input.event
                && self.pointer_route_is_stale_for_mouse(mouse)
            {
                return Ok(DeferredReplayOutcome {
                    action,
                    disposition: Self::pointer_replay_barrier(action),
                });
            }
            let input = self.deferred_input.pop_front().unwrap();
            replayed += 1;
            let replay_context =
                ReplayedInputContext { pointer: input.pointer, admission: Some(input.admission) };
            let input_action =
                self.handle_replayed_input(input.event, input.sequence, Some(replay_context))?;
            action = action.merge(input_action);
            action = action.merge(self.process_machine_requests());
            // A missing mirror can retain the same logical input again.
            // Stop here so later sequences cannot overtake it.
            if self.retains_input_sequence(input.sequence) {
                return Ok(DeferredReplayOutcome {
                    action,
                    disposition: DeferredReplayDisposition::Blocked,
                });
            }
        }
        let has_remaining_input =
            !self.deferred_input.is_empty() || self.pending_pointer_motion.is_some();
        let disposition = if !has_remaining_input {
            DeferredReplayDisposition::Drained
        } else if replayed >= MAX_REPLAYED_INPUTS {
            DeferredReplayDisposition::Yield
        } else if self.next_replay_pointer_route_is_stale() {
            Self::pointer_replay_barrier(action)
        } else {
            DeferredReplayDisposition::Blocked
        };
        self.clear_finished_semantic_destinations();
        Ok(DeferredReplayOutcome { action, disposition })
    }

    #[cfg(test)]
    fn replay_deferred_input(&mut self) -> anyhow::Result<RenderAction> {
        Ok(self.replay_deferred_input_batch()?.action)
    }

    fn pointer_route_is_globally_stale(&self) -> bool {
        self.session.has_pending_pointer_mutations()
            || self.session.remote_tree_is_stale()
            || self.mux_recovery_generation.load(Ordering::Acquire) != 0
            || self.pointer_route_phase.invalidates_all_pointer_routes()
    }

    fn pointer_route_is_stale_for_mouse(&self, mouse: &MouseEvent) -> bool {
        if self.pointer_route_is_globally_stale() {
            return true;
        }
        if Self::mouse_opens_cmux_context_menu(mouse) {
            // The menu is owned by cmux rather than the browser bitmap or a
            // graphics scene. Keep global and layout barriers above, but do
            // not wait for content admission this press never enters.
            return false;
        }
        if self.pending_graphics_changes_cell(mouse.column, mouse.row) {
            return true;
        }
        if !matches!(
            self.pointer_route_phase,
            PointerRoutePhase::GraphicsRenderPending | PointerRoutePhase::GraphicsProcessingPending
        ) {
            return false;
        }
        let route = self.rendered_pointer_frame.route_for_mouse(mouse);
        let Some((surface, rendered_generation)) = route.browser_content_generation() else {
            return false;
        };
        rendered_generation.is_none_or(|generation| {
            !self
                .session
                .surface(surface)
                .is_some_and(|surface| surface.browser_accepts_pointer_frame(generation))
        })
    }

    fn graphics_share_pointer_route(
        &self,
        processed: GraphicIdentity,
        pending: GraphicIdentity,
    ) -> bool {
        if !processed.same_pointer_layout(pending) {
            return false;
        }
        let surface_id = processed.surface;
        match (processed.pointer_frame_seq, pending.pointer_frame_seq) {
            (None, None) => true,
            (Some(processed), Some(pending)) if processed == pending => true,
            (Some(processed), Some(pending)) => {
                self.session.surface(surface_id).is_some_and(|surface| {
                    surface.browser_pointer_frame_is_in_current_route(processed)
                        && surface.browser_pointer_frame_is_in_current_route(pending)
                })
            }
            (None, Some(_)) | (Some(_), None) => false,
        }
    }

    fn graphics_changed_rect_bound(
        &self,
        previous: &[GraphicIdentity],
        next: &[GraphicIdentity],
    ) -> Option<Rect> {
        previous
            .iter()
            .filter(|graphic| {
                !next
                    .iter()
                    .any(|candidate| self.graphics_share_pointer_route(**graphic, *candidate))
            })
            .chain(next.iter().filter(|graphic| {
                !previous
                    .iter()
                    .any(|candidate| self.graphics_share_pointer_route(**graphic, *candidate))
            }))
            .map(|graphic| graphic.rect)
            .reduce(bounding_rect)
    }

    fn pending_graphics_changes_cell(&self, x: u16, y: u16) -> bool {
        if self.pointer_route_phase != PointerRoutePhase::GraphicsProcessingPending
            || self.pending_graphics_submission.is_none()
        {
            return false;
        }
        if self.pending_graphics_affected_rect.is_some_and(|rect| rect.contains(x, y)) {
            return true;
        }
        let pending = self.pending_graphics_snapshot.as_deref().unwrap_or(&[]);
        let graphic_at = |snapshot: &[GraphicIdentity]| {
            snapshot.iter().copied().find(|graphic| graphic.rect.contains(x, y))
        };
        match (graphic_at(&self.last_graphics_snapshot), graphic_at(pending)) {
            (Some(processed), Some(pending)) => {
                !self.graphics_share_pointer_route(processed, pending)
            }
            (None, None) => false,
            (Some(_), None) | (None, Some(_)) => true,
        }
    }

    fn next_replay_pointer_route_is_stale(&self) -> bool {
        if self.pointer_route_is_globally_stale() {
            return true;
        }
        let pending_motion_is_next = self.pending_pointer_motion.as_ref().is_some_and(|pointer| {
            self.deferred_input.front().is_none_or(|input| pointer.sequence < input.sequence)
        });
        if pending_motion_is_next {
            return self
                .pending_pointer_motion
                .as_ref()
                .is_some_and(|pointer| self.pointer_route_is_stale_for_mouse(&pointer.event));
        }
        self.deferred_input.front().is_some_and(|input| match &input.event {
            TerminalInput::Mouse(mouse) => self.pointer_route_is_stale_for_mouse(mouse),
            _ => false,
        })
    }

    fn apply_session_completion(&mut self, completion: SessionCompletion) {
        if self.surface_only.is_some() {
            return;
        }
        let semantic_intent = completion.semantic_intent;
        match completion.action {
            SessionCompletionAction::SurfaceCreated { surface } => {
                self.resolve_semantic_destination(semantic_intent, surface);
                self.select_created_surface(surface);
            }
            SessionCompletionAction::BrowserTabCreated { surface } => {
                self.resolve_semantic_destination(semantic_intent, surface);
                self.select_created_surface(surface);
                let pane = self
                    .tab_locations
                    .get(&surface)
                    .and_then(|[workspace, screen, pane, _]| {
                        self.tree
                            .workspaces
                            .get(*workspace)
                            .and_then(|workspace| workspace.screens.get(*screen))
                            .and_then(|screen| screen.panes.get(*pane))
                    })
                    .filter(|pane| {
                        pane.active_surface() == Some(surface)
                            && pane
                                .tabs
                                .get(pane.active_tab)
                                .is_some_and(|tab| tab.kind == SurfaceKind::Browser)
                    })
                    .map(|pane| pane.id);
                if let Some(pane) = pane {
                    self.focus_omnibar_with_buffer(pane, String::new(), false);
                }
            }
            SessionCompletionAction::LayoutUndoConfirmation { pane, revision, closes_panes } => {
                self.cancel_pty_mouse_drag();
                let label = self.layout_undo_confirmation_label(&closes_panes);
                self.prompt = Some(Prompt::new(
                    label,
                    String::new(),
                    PromptTarget::ConfirmLayoutUndo { pane, revision },
                ));
            }
            SessionCompletionAction::LayoutUndoUnavailable => {
                self.status_message =
                    Some(localization::catalog().sidebar.layout_nothing_to_undo.to_string());
            }
            SessionCompletionAction::LayoutUndoStale => {
                self.status_message =
                    Some(localization::catalog().sidebar.layout_undo_stale.to_string());
            }
        }
    }

    fn resolve_semantic_destination(&mut self, intent: Option<u64>, surface: SurfaceId) {
        let Some(intent) = intent else { return };
        let outcome = if self.tab_locations.contains_key(&surface) {
            SemanticDestinationOutcome::Resolved(surface)
        } else {
            SemanticDestinationOutcome::Failed
        };
        if let Some(current) = self.semantic_destination_outcomes.get_mut(&intent) {
            *current = outcome;
        }
    }

    fn layout_undo_confirmation_label(&self, closes_panes: &[PaneId]) -> String {
        let identities = closes_panes
            .iter()
            .map(|pane_id| {
                self.tree.pane(*pane_id).map_or_else(
                    || pane_id.to_string(),
                    |pane| {
                        let tabs = pane
                            .tabs
                            .iter()
                            .map(|tab| tab.short_id.as_str())
                            .collect::<Vec<_>>()
                            .join(", ");
                        if tabs.is_empty() {
                            pane.short_id.clone()
                        } else {
                            format!("{} [{}]", pane.short_id, tabs)
                        }
                    },
                )
            })
            .collect::<Vec<_>>()
            .join("; ");
        localization::catalog().sidebar.confirm_layout_undo.replace("{items}", &identities)
    }

    fn select_created_surface(&mut self, surface: SurfaceId) {
        let Some([workspace_index, screen_index, pane_index, tab_index]) =
            self.tab_locations.get(&surface).copied()
        else {
            return;
        };
        self.tree.active_workspace = workspace_index;
        let Some(workspace) = self.tree.workspaces.get_mut(workspace_index) else { return };
        workspace.active_screen = screen_index;
        let Some(screen) = workspace.screens.get_mut(screen_index) else { return };
        let Some(pane_id) = screen.panes.get(pane_index).map(|pane| pane.id) else { return };
        screen.active_pane = pane_id;
        if let Some(pane) = screen.panes.get_mut(pane_index) {
            pane.active_tab = tab_index;
        }
        self.pane_focus_history.record(pane_id);
        self.claim_active_terminal_geometry(true);
    }

    fn apply_session_cancellation(&mut self) {
        self.deferred_input.clear();
        self.latest_semantic_destination_intent = None;
        self.semantic_destination_outcomes.clear();
        self.prefix_armed = false;
        self.pending_session_completions.clear();
        self.pending_size_releases.clear();
        self.status_message = Some(localization::catalog().session.operation_canceled.to_string());
    }

    fn apply_pty_failures(&mut self) -> RenderAction {
        let failures = self.pty_failures.take();
        let mut action = RenderAction::None;
        for failure in failures {
            action = action.merge(self.apply_pty_operation_failure(failure));
        }
        action
    }

    fn apply_pty_operation_failure(&mut self, failure: PtyOperationFailure) -> RenderAction {
        if failure.session_generation != self.session_generation {
            return RenderAction::None;
        }
        if failure.label == "relaunch sidebar plugin" {
            self.sidebar_focus_pending = false;
        }
        if failure.kind == Some(PtyInputKind::Motion)
            && failure.delivery == PtyOperationDelivery::KnownNotDelivered
            && let Some(surface) = failure.surface_id.and_then(|id| self.session.surface(id))
        {
            surface.reset_mouse_motion_dedupe();
        }
        let matches_active_press =
            failure.surface_id.zip(failure.reservation_id).is_some_and(
                |(surface, reservation_id)| {
                    matches!(&self.drag, Some(Drag::PtyMouse { surface: active_surface, reservation_id: active_reservation, .. }) if *active_surface == surface && *active_reservation == reservation_id)
                },
            );
        let failed_active_press = failure.kind == Some(PtyInputKind::Press)
            && failure.delivery == PtyOperationDelivery::KnownNotDelivered
            && matches_active_press;
        let recovery_release_required = failure.kind == Some(PtyInputKind::Press)
            && failure.delivery == PtyOperationDelivery::Ambiguous
            && matches_active_press;
        if failed_active_press || (failure.lane_failed && !recovery_release_required) {
            self.drag = None;
        }
        self.status_message = Some(if failure.label == TERMINAL_EXITED_LABEL {
            localization::catalog().terminal.pty_input_exited.to_string()
        } else if failure.label == "attach surface"
            && failure.delivery == PtyOperationDelivery::Ambiguous
        {
            format!(
                "{}: {}",
                localization::catalog().terminal.attach_outcome_unknown,
                failure.error
            )
        } else if failure.label == "clear terminal history"
            && failure.delivery == PtyOperationDelivery::Ambiguous
        {
            localization::catalog().terminal.clear_history_outcome_unknown.to_string()
        } else if failure.label == "clear terminal history" {
            let detail = localized_clear_history_failure(&failure.error);
            format!("{}: {}", localization::catalog().terminal.clear_history_failed, detail)
        } else {
            format!("{}: {}", localization::catalog().terminal.operation_failed, failure.error)
        });
        RenderAction::Draw
    }

    fn apply_mux_titles(&mut self) -> bool {
        let titles = self.mux_titles.take_dirty();
        self.apply_mux_title_snapshot(titles)
    }

    fn reapply_mux_titles(&mut self) -> bool {
        let titles = self.mux_titles.snapshot();
        self.apply_mux_title_snapshot(titles)
    }

    fn apply_mux_title_snapshot(&mut self, titles: HashMap<SurfaceId, Arc<str>>) -> bool {
        if titles.is_empty() {
            return false;
        }
        let mut changed = false;
        for (surface, title) in titles {
            let Some([workspace, screen, pane, tab]) = self.tab_locations.get(&surface).copied()
            else {
                continue;
            };
            let Some(tab) = self
                .tree
                .workspaces
                .get_mut(workspace)
                .and_then(|workspace| workspace.screens.get_mut(screen))
                .and_then(|screen| screen.panes.get_mut(pane))
                .and_then(|pane| pane.tabs.get_mut(tab))
            else {
                continue;
            };
            if tab.title.as_str() != title.as_ref() {
                tab.title = title.to_string();
                changed = true;
            }
        }
        changed
    }

    fn replace_tree(&mut self, mut tree: TreeView) {
        let previous_active = self.active_pane();
        let selected_workspace = self
            .tree
            .workspaces
            .get(self.sidebar_workspace_selection)
            .map(|workspace| workspace.id);
        preserve_client_view(&self.tree, &mut tree);
        let first_adoption = self.reported_focus.is_none();
        if first_adoption {
            // First adopted tree: its focus is the server's own baseline.
            self.reported_focus = tree
                .active_screen()
                .and_then(|screen| screen.panes.iter().find(|pane| pane.id == screen.active_pane))
                .map(|pane| crate::session::ClientFocus { pane: pane.id, tab: pane.active_tab });
        }
        if let Some(surface) = self.surface_only
            && !tree.select_surface(surface)
        {
            tree = TreeView::default();
            self.quit = true;
        }
        let live_browsers = tree
            .workspaces
            .iter()
            .flat_map(|workspace| workspace.screens.iter())
            .flat_map(|screen| screen.panes.iter())
            .flat_map(|pane| pane.tabs.iter())
            .filter(|tab| tab.kind == SurfaceKind::Browser)
            .map(|tab| tab.surface)
            .collect::<HashSet<_>>();
        let removed_browsers = self
            .tree
            .workspaces
            .iter()
            .flat_map(|workspace| workspace.screens.iter())
            .flat_map(|screen| screen.panes.iter())
            .flat_map(|pane| pane.tabs.iter())
            .filter(|tab| tab.kind == SurfaceKind::Browser)
            .map(|tab| tab.surface)
            .filter(|surface| !live_browsers.contains(surface))
            .collect::<Vec<_>>();
        for surface in removed_browsers {
            self.browser_input.forget_surface(surface);
        }
        let live_screens = tree
            .workspaces
            .iter()
            .flat_map(|workspace| workspace.screens.iter())
            .map(|screen| screen.id)
            .collect::<HashSet<_>>();
        self.viewport_states.retain(|screen, _| live_screens.contains(screen));
        self.pane_focus_history.sync_membership(&tree);
        self.tree = tree;
        self.sidebar_workspace_selection = selected_workspace
            .and_then(|selected| {
                self.tree.workspaces.iter().position(|workspace| workspace.id == selected)
            })
            .unwrap_or_else(|| {
                self.sidebar_workspace_selection.min(self.tree.workspaces.len().saturating_sub(1))
            });
        if self.active_pane() != previous_active
            && let Some(active) = self.active_pane()
        {
            self.pane_focus_history.record(active);
        }
        if first_adoption {
            self.restore_client_focus_from_session();
        }
        self.rebuild_tab_locations();
        self.reapply_mux_titles();
    }

    fn replace_authoritative_tree(&mut self, tree: TreeView, destination_generation: u64) {
        if tree.pane_revision.is_none() {
            self.pane_focus_history.reconcile_membership(&tree);
        } else {
            self.pane_focus_history.sync_membership(&tree);
        }
        let live_surfaces = tree
            .workspaces
            .iter()
            .flat_map(|workspace| workspace.screens.iter())
            .flat_map(|screen| screen.panes.iter())
            .flat_map(|pane| pane.tabs.iter())
            .map(|tab| tab.surface)
            .collect::<HashSet<_>>();
        let removed_surfaces = self
            .tab_locations
            .keys()
            .copied()
            .filter(|surface| !live_surfaces.contains(surface))
            .collect::<Vec<_>>();
        for surface in removed_surfaces {
            self.retire_surface_state(surface);
        }
        self.replace_tree(tree);
        self.session.reconcile_retired_surfaces(&self.tree);
        self.claim_active_terminal_geometry(false);
        self.applied_destination_generation =
            self.applied_destination_generation.max(destination_generation);
    }

    fn retire_surface_state(&mut self, surface: SurfaceId) {
        if matches!(&self.drag, Some(Drag::PtyMouse { surface: active, .. }) if *active == surface)
        {
            self.cancel_pty_release_reservation();
            self.drag = None;
        }
        self.render_states.remove(&surface);
        self.rendered_kitty_graphics.remove(&surface);
        self.graphics_scene_cache.invalidate();
        self.graphics_dirty_surfaces.remove(&surface);
        self.rendered_terminal_sizes.remove(&surface);
        self.rendered_terminal_pointer_semantics.remove(&surface);
        self.rendered_pane_content_generations.remove(&surface);
        self.rendered_terminal_bounds.remove(&surface);
        self.visible_size_surfaces.remove(&surface);
        self.pending_size_releases.remove(&surface);
        self.mux_titles.remove(surface);
        self.session.retire_surface_input(surface);
        self.session.forget_surface(surface);
        if self.sidebar_plugin_surface == Some(surface) {
            self.session.invalidate_sidebar_plugin_sync();
            self.sidebar_plugin_surface = None;
            self.sidebar_plugin_error =
                Some(localization::catalog().sidebar.plugin_exited.to_string());
            if self.config.sidebar.plugin.is_some() {
                self.leave_workspace_sidebar();
            }
        }
        if self.selection.is_some_and(|selection| selection.surface == surface) {
            self.replace_selection(None);
        }
        if self.omnibar.as_ref().is_some_and(|state| state.surface == surface) {
            self.omnibar = None;
        }
        if self.last_browser_hover.is_some_and(|(hovered, _, _, _)| hovered == surface) {
            self.last_browser_hover = None;
        }
        self.browser_input.forget_surface(surface);
    }

    fn rebuild_tab_locations(&mut self) {
        self.tab_locations.clear();
        for (workspace_index, workspace) in self.tree.workspaces.iter().enumerate() {
            for (screen_index, screen) in workspace.screens.iter().enumerate() {
                for (pane_index, pane) in screen.panes.iter().enumerate() {
                    for (tab_index, tab) in pane.tabs.iter().enumerate() {
                        self.tab_locations.insert(
                            tab.surface,
                            [workspace_index, screen_index, pane_index, tab_index],
                        );
                    }
                }
            }
        }
    }

    /// Remove a retired view from the client cache before the authoritative
    /// topology refresh arrives. The backend projection still owns parent
    /// pane, screen, and workspace collapse.
    fn remove_surface_from_cached_tree(&mut self, surface: SurfaceId) {
        let Some([workspace_index, screen_index, pane_index, tab_index]) =
            self.tab_locations.get(&surface).copied()
        else {
            self.remove_surface_from_cached_tree_scan_and_rebuild_locations(surface);
            return;
        };

        let location_is_current = self
            .tree
            .workspaces
            .get(workspace_index)
            .and_then(|workspace| workspace.screens.get(screen_index))
            .and_then(|screen| screen.panes.get(pane_index))
            .and_then(|pane| pane.tabs.get(tab_index))
            .is_some_and(|tab| tab.surface == surface);
        if !location_is_current {
            self.remove_surface_from_cached_tree_scan_and_rebuild_locations(surface);
            return;
        }

        let shifted_tabs = {
            let pane =
                &mut self.tree.workspaces[workspace_index].screens[screen_index].panes[pane_index];
            pane.tabs.remove(tab_index);
            adjust_active_tab_after_removal(pane, tab_index);
            pane.tabs
                .iter()
                .enumerate()
                .skip(tab_index)
                .map(|(tab_index, tab)| (tab.surface, tab_index))
                .collect::<Vec<_>>()
        };

        self.tab_locations.remove(&surface);
        for (shifted_surface, shifted_index) in shifted_tabs {
            self.tab_locations.insert(
                shifted_surface,
                [workspace_index, screen_index, pane_index, shifted_index],
            );
        }
    }

    /// Repair the cache from the tree and rebuild `tab_locations` if the index was missing or stale.
    /// This path is defensive only. Normal surface exits use the indexed path
    /// above and touch one pane instead of scanning the entire topology.
    fn remove_surface_from_cached_tree_scan_and_rebuild_locations(&mut self, surface: SurfaceId) {
        for workspace in &mut self.tree.workspaces {
            for screen in &mut workspace.screens {
                for pane in &mut screen.panes {
                    let Some(index) = pane.tabs.iter().position(|tab| tab.surface == surface)
                    else {
                        continue;
                    };
                    pane.tabs.remove(index);
                    adjust_active_tab_after_removal(pane, index);
                }
            }
        }
        self.rebuild_tab_locations();
    }

    fn apply_session_completions_through(&mut self, authoritative_generation: u64) -> bool {
        let mut applied = false;
        while self
            .pending_session_completions
            .front()
            .is_some_and(|completion| completion.mutation_generation <= authoritative_generation)
        {
            let completion = self.pending_session_completions.pop_front().unwrap();
            self.apply_session_completion(completion);
            applied = true;
        }
        applied
    }

    fn complete_remote_tree_refresh(&self, refresh_stale: bool) {
        let background_dirty = self.session.take_background_refresh_dirty();
        if self.session.remote_tree_is_stale() {
            if refresh_stale || background_dirty {
                self.session.refresh_remote_tree_if_stale();
            }
        } else if background_dirty {
            self.session.refresh_remote_tree_background();
        }
    }

    fn accept_refresh_sequence(&mut self, refresh_sequence: u64) -> bool {
        if refresh_sequence <= self.last_applied_refresh_sequence {
            return false;
        }
        self.last_applied_refresh_sequence = refresh_sequence;
        true
    }

    fn schedule_background_refresh_retry(&mut self) -> bool {
        if self.background_refresh_attempts >= BACKGROUND_REFRESH_RETRIES {
            self.background_refresh_retry_at = None;
            return false;
        }
        self.background_refresh_attempts += 1;
        let delay_seconds = 1_u64 << u32::from(self.background_refresh_attempts.saturating_sub(1));
        self.background_refresh_retry_at =
            Some(Instant::now() + Duration::from_secs(delay_seconds.min(30)));
        true
    }

    fn retry_background_refresh_if_due(&mut self) {
        if self.background_refresh_retry_at.is_some_and(|retry_at| Instant::now() >= retry_at) {
            self.background_refresh_retry_at = None;
            self.session.refresh_remote_tree_background();
        }
    }

    fn ensure_graphics_writer_healthy(&self) -> anyhow::Result<()> {
        let Some(failure) = self.graphics_writer.as_ref().and_then(GraphicsWriter::failure) else {
            return Ok(());
        };
        let messages = &localization::catalog().graphics;
        let message = if failure.parser_reset_required {
            messages.parser_recovery_failed
        } else {
            messages.output_failed
        };
        anyhow::bail!("{message}")
    }

    fn draw_terminal<B: Backend>(
        &mut self,
        terminal: &mut RatatuiTerminal<B>,
        action: RenderAction,
    ) -> anyhow::Result<()>
    where
        B::Error: Send + Sync + 'static,
    {
        let lock = self.stdout_lock.clone();
        let _guard = lock.lock();
        lock.recover_stream_locked()?;
        self.ensure_graphics_writer_healthy()?;
        self.painted_durable_notice_this_frame = None;
        catch_renderer_panic(|| {
            terminal.draw(|frame| {
                self.prepare_frame_layout(frame.area(), action);
                crate::ui::draw(self, frame);
            })
        })??;
        if self.graphics_host_scene_reset_pending {
            if let Some(writer) = &self.graphics_writer {
                writer.invalidate_host_scene();
            }
            self.graphics_scene_cache.invalidate();
            self.graphics_host_scene_reset_pending = false;
        }
        self.commit_successful_durable_notice_paint();
        self.submit_pending_durable_notice_ack();
        if let Some(sequence) =
            outer_cursor_escape_if_changed(self.applied_outer_cursor, self.desired_outer_cursor)
        {
            let mut stdout = std::io::stdout();
            stdout.write_all(sequence.as_bytes())?;
            stdout.flush()?;
            self.applied_outer_cursor = Some(self.desired_outer_cursor);
        }
        let desired_mouse_capture = self.desired_host_mouse_capture();
        if let Some(sequence) = host_mouse_capture_escape_if_changed(
            self.host_mouse_capture_applied,
            desired_mouse_capture,
        ) {
            let mut stdout = std::io::stdout();
            stdout.write_all(sequence.as_bytes())?;
            stdout.flush()?;
            self.host_mouse_capture_applied = Some(desired_mouse_capture);
        }
        Ok(())
    }

    /// Full-TUI clients always capture host mouse input. A scoped attach
    /// client mirrors the inner terminal's mouse-tracking state instead, so
    /// the host terminal keeps native click and selection handling whenever
    /// the inner application did not request mouse input.
    ///
    /// The state is read from the scoped surface's terminal itself (the
    /// mirror a daemon replay restores and live output keeps current), never
    /// from the rendered-frame projection: `draw_content` removes a
    /// surface's rendered semantics at the start of every draw and restores
    /// them only after a successful render, so a frame whose pane render
    /// failed or was skipped (renderer error while daemon output is applied,
    /// zero-sized pane during layout churn) must not release capture the
    /// inner application still holds. When the state is momentarily
    /// unknowable (terminal lock contended, surface gone during teardown)
    /// the client keeps the capture it last applied instead of toggling the
    /// host.
    fn desired_host_mouse_capture(&self) -> bool {
        let Some(surface_id) = self.surface_only else { return true };
        let canonical = self
            .session
            .surface(surface_id)
            .and_then(|surface| surface.try_pointer_semantics())
            .and_then(|probe| match probe {
                PointerSemanticProbe::Ready(semantics) => Some(semantics.mouse_tracking),
                PointerSemanticProbe::Contended => None,
            });
        canonical.unwrap_or_else(|| self.host_mouse_capture_applied.unwrap_or(false))
    }

    /// A scoped attach client mirrors the inner terminal's input modes onto
    /// the host terminal, but the host can silently drop those modes without
    /// the client ever seeing it: app-side session restore can write a reset
    /// into the Ghostty surface after the client's capture-on burst, or the
    /// host can re-initialize the surface on relaunch. The per-frame capture
    /// (and cursor) sync is edge-triggered on the last applied state, so a
    /// dropped mode is never re-asserted and the bridge tab loses mouse input
    /// until the inner application happens to toggle modes (btop never does).
    ///
    /// Focus-in and resize are the two host-visible signals that the host may
    /// have re-initialized: Ghostty emits a focus-in report on every window
    /// re-activation and app reopen, and the reattached surface is resized to
    /// the new window's geometry. Clearing the applied host bookkeeping on
    /// those events forces the next frame to re-derive the canonical inner
    /// state and re-emit it, recovering any mode the host silently dropped.
    /// Scoped clients only: a full TUI owns the whole host surface and
    /// re-emits its modes through its own lifecycle.
    fn reassert_scoped_host_terminal_state(&mut self) {
        if self.surface_only.is_none() {
            return;
        }
        // Keep the last applied state when the inner terminal cannot be
        // probed. Clearing it here would make the next frame guess `false`
        // and release host capture during a transient lock/contention.
        let probe_available = self
            .surface_only
            .and_then(|surface_id| self.session.surface(surface_id))
            .and_then(|surface| surface.try_pointer_semantics())
            .is_some_and(|probe| matches!(probe, PointerSemanticProbe::Ready(_)));
        if probe_available {
            self.host_mouse_capture_applied = None;
        }
        // The previous frame may have applied an authored style. If the
        // inner application reset DECSCUSR, clear the desired style now so
        // focus or resize cannot replay stale cursor state onto the host.
        if self
            .surface_only
            .and_then(|surface_id| self.session.surface(surface_id))
            .is_some_and(|surface| !surface.cursor_style_authored())
        {
            self.desired_outer_cursor = OuterCursorSpec::Reset;
        }
        self.applied_outer_cursor = None;
    }

    fn prepare_frame_layout(&mut self, area: ratatui::layout::Rect, action: RenderAction) {
        let size = (area.width, area.height);
        if action == RenderAction::Draw || self.outer_size != size {
            self.sync_layout(size);
        }
        if area.width == 0 || area.height == 0 {
            self.clear_empty_frame_geometry();
        }
    }

    fn clear_empty_frame_geometry(&mut self) {
        self.sidebar_layout = SidebarLayout::default();
        self.sidebar_width = 0;
        self.machine_sidebar_width = 0;
        self.tabs_sidebar_width = 0;
        self.content_area = Rect::default();
        self.hits.clear();
        self.pane_areas.clear();
        self.viewport_projection.clear();
        self.viewport_layout.clear();
        self.viewport_stacked_headers.clear();
        self.viewport_virtual_width = 0;
        self.viewport_offset = 0;
        self.rendered_terminal_sizes.clear();
        self.rendered_terminal_bounds.clear();
        self.rendered_kitty_graphics.clear();
        self.rendered_terminal_pointer_semantics.clear();
        self.rendered_pane_content_generations.clear();
    }

    pub(crate) fn reset_frame_cursor_spec(&mut self) {
        // Scoped attach is transparent to the host cursor. Do not schedule a
        // reset merely because a frame starts when the host state is already
        // the initial reset. Once a scoped inner application stops authoring
        // DECSCUSR, however, every normal frame must derive Reset so a stale
        // authored style cannot survive without a focus or resize event.
        let authored = self
            .surface_only
            .and_then(|surface_id| self.session.surface(surface_id))
            .is_some_and(|surface| surface.cursor_style_authored());
        if self.surface_only.is_none() || !authored {
            self.desired_outer_cursor = OuterCursorSpec::Reset;
        }
    }

    pub(crate) fn use_terminal_cursor_spec(
        &mut self,
        color: Rgb,
        shape: CursorShape,
        blinking: bool,
    ) {
        self.desired_outer_cursor = OuterCursorSpec::Terminal { color, shape, blinking };
    }

    fn frame_only_browser_update(&self, id: SurfaceId) -> bool {
        if !self.graphics_supported {
            return false;
        }
        let Some(area) = self.pane_areas.iter().find(|area| area.surface == id) else {
            return false;
        };
        let Some(surface) = self.session.surface(id) else {
            return false;
        };
        surface.kind() == SurfaceKind::Browser
            && surface.browser_frame_metadata().is_some()
            && area.content.width > 0
            && area.content.height > 0
    }

    fn mark_graphics_clean(&self, dirty_surfaces: Option<&HashSet<SurfaceId>>) {
        let mut visited = HashSet::new();
        for area in &self.pane_areas {
            if dirty_surfaces.is_none_or(|dirty| dirty.contains(&area.surface))
                && visited.insert(area.surface)
                && let Some(surface) = self.session.surface(area.surface)
            {
                surface.take_dirty();
            }
        }
    }

    fn track_graphics_submission(&mut self, submission: u64, snapshot: Vec<GraphicIdentity>) {
        let previous =
            self.pending_graphics_snapshot.as_deref().unwrap_or(&self.last_graphics_snapshot);
        if let Some(changed) = self.graphics_changed_rect_bound(previous, &snapshot) {
            self.pending_graphics_affected_rect = Some(
                self.pending_graphics_affected_rect
                    .map_or(changed, |affected| bounding_rect(affected, changed)),
            );
        }
        self.pending_graphics_submission = Some(submission);
        self.pending_graphics_snapshot = Some(snapshot);
    }

    fn graphic_occlusion_rects(&self) -> Vec<Rect> {
        let mut rects: Vec<Rect> = self
            .menu
            .as_ref()
            .map(|menu| menu.levels.iter().map(|level| level.rect).collect())
            .unwrap_or_default();
        rects.extend(self.prompt.as_ref().map(|prompt| prompt.rect));
        rects.extend(self.pairing_dialog.as_ref().map(|dialog| dialog.rect));
        rects.extend(self.shortcut_help.as_ref().map(|help| help.rect));
        rects.extend(crate::ui::toast_rect(self));
        rects
    }

    fn graphics_pane_scene_key(
        &self,
        area: PaneArea,
        surface: Option<&SurfaceHandle>,
    ) -> GraphicsPaneSceneKey {
        let (terminal_bounds, source) = match surface {
            None => (None, GraphicsSceneSourceKey::Unavailable),
            Some(surface) => match surface.kind() {
                SurfaceKind::Browser => (
                    None,
                    GraphicsSceneSourceKey::Browser { frame: surface.browser_frame_metadata() },
                ),
                SurfaceKind::Pty => {
                    let snapshot =
                        self.rendered_kitty_graphics.get(&area.surface).map(|snapshot| {
                            KittySceneSnapshotKey {
                                identity: Arc::as_ptr(snapshot) as usize,
                                generation: snapshot.generation,
                            }
                        });
                    (
                        self.rendered_terminal_bounds.get(&area.surface).copied(),
                        GraphicsSceneSourceKey::Pty { snapshot },
                    )
                }
            },
        };
        GraphicsPaneSceneKey {
            surface: area.surface,
            content: area.content,
            content_source_x: area.content_source_x(),
            full_content_width: area.content_size().0,
            terminal_bounds,
            source,
        }
    }

    fn emit_graphics(&mut self) -> anyhow::Result<()> {
        self.emit_graphics_with_scope(false)
    }

    fn emit_dirty_graphics(&mut self) -> anyhow::Result<()> {
        self.emit_graphics_with_scope(true)
    }

    fn emit_graphics_with_scope(&mut self, dirty_only: bool) -> anyhow::Result<()> {
        if !self.graphics_supported {
            return Ok(());
        }
        let dirty_surfaces = std::mem::take(&mut self.graphics_dirty_surfaces);
        let occluders = self.graphic_occlusion_rects();
        let context = GraphicsSceneContextKey {
            session_generation: self.session_generation,
            cell_pixels: self.cell_pixels,
            occluders: occluders.clone(),
        };
        let context_changed = self.graphics_scene_cache.context.as_ref() != Some(&context);
        let full_scan = !dirty_only || context_changed;
        self.mark_graphics_clean((!full_scan).then_some(&dirty_surfaces));
        let mut updates = Vec::new();
        for index in 0..self.pane_areas.len() {
            let area = self.pane_areas[index];
            if !full_scan && !dirty_surfaces.contains(&area.surface) {
                continue;
            }
            let surface = self.session.surface(area.surface);
            let key = self.graphics_pane_scene_key(area, surface.as_ref());
            let unchanged = !context_changed
                && self
                    .graphics_scene_cache
                    .projections
                    .get(&area.surface)
                    .is_some_and(|cached| cached.key == key);
            if unchanged {
                continue;
            }
            let placements =
                Arc::from(self.graphic_placements_for_area(area, surface.as_ref(), &occluders));
            updates.push((area.surface, key, placements));
        }

        let visible = full_scan.then(|| {
            self.pane_areas.iter().map(|area| area.surface).collect::<HashSet<SurfaceId>>()
        });
        let removed = visible.as_ref().is_some_and(|visible| {
            self.graphics_scene_cache.projections.keys().any(|surface| !visible.contains(surface))
        });
        let projection_changed = !updates.is_empty();
        if context_changed {
            self.graphics_scene_cache.context = Some(context);
            self.graphics_scene_cache.projections.clear();
        }
        if let Some(visible) = &visible {
            self.graphics_scene_cache.projections.retain(|surface, _| visible.contains(surface));
        }
        for (surface, key, placements) in updates {
            self.graphics_scene_cache
                .projections
                .insert(surface, CachedGraphicsProjection { key, placements });
            #[cfg(test)]
            {
                *self.graphics_scene_cache.projection_rebuilds.entry(surface).or_default() += 1;
            }
        }
        let scene_changed = context_changed || removed || projection_changed;
        #[cfg(test)]
        if scene_changed {
            self.graphics_scene_cache.rebuilds += 1;
        }
        let scene = self
            .pane_areas
            .iter()
            .filter_map(|area| {
                self.graphics_scene_cache
                    .projections
                    .get(&area.surface)
                    .map(|cached| cached.placements.clone())
            })
            .collect::<Vec<_>>();
        let snapshot = scene
            .iter()
            .flat_map(|placements| placements.iter())
            .filter(|placement| placement.is_browser_frame())
            .map(|placement| self.graphic_identity(placement))
            .collect::<Vec<_>>();
        let submitted_snapshot =
            self.pending_graphics_snapshot.as_ref().unwrap_or(&self.last_graphics_snapshot);
        if !scene_changed && &snapshot == submitted_snapshot {
            if self.pointer_route_phase == PointerRoutePhase::GraphicsRenderPending {
                self.pointer_route_phase = if self.pending_graphics_submission.is_some() {
                    PointerRoutePhase::GraphicsProcessingPending
                } else {
                    PointerRoutePhase::Fresh
                };
            }
            return Ok(());
        }
        let Some(writer) = &self.graphics_writer else {
            return Ok(());
        };
        self.next_graphics_submission = self.next_graphics_submission.wrapping_add(1).max(1);
        let submission = self.next_graphics_submission;
        if writer.submit_scene(submission, self.session_generation, scene) {
            self.track_graphics_submission(submission, snapshot);
            self.pointer_route_phase = PointerRoutePhase::GraphicsProcessingPending;
        }
        Ok(())
    }

    fn graphic_identity(&self, placement: &GraphicPlacement) -> GraphicIdentity {
        GraphicIdentity {
            session_generation: placement.key.image.namespace,
            surface: placement.key.image.surface,
            rect: placement.rect,
            seq: placement.image.generation,
            pointer_frame_seq: placement.pointer_frame_seq,
        }
    }

    fn graphic_placements_for_area(
        &self,
        area: PaneArea,
        surface: Option<&SurfaceHandle>,
        occluders: &[Rect],
    ) -> Vec<GraphicPlacement> {
        let mut placements = Vec::new();
        let Some(surface) = surface else { return placements };
        if area.content.width == 0 || area.content.height == 0 {
            return placements;
        }
        match surface.kind() {
            SurfaceKind::Browser => {
                if Self::graphic_occluded(area.content, occluders) {
                    return placements;
                }
                let Some(update) = surface.browser_frame_update() else { return placements };
                let frame = Arc::new(update.frame);
                let source = area.viewport.and_then(|clip| {
                    browser_frame_source_crop(
                        &frame,
                        clip.content_source_x,
                        area.content.width,
                        clip.full_content_width,
                    )
                    .map(|(x, width)| GraphicSourceRect {
                        x,
                        y: 0,
                        width,
                        height: frame.image_height,
                    })
                });
                placements.push(GraphicPlacement::browser_frame(
                    self.session_generation,
                    area.surface,
                    area.content,
                    frame,
                    update.pointer_frame_seq,
                    source,
                ));
            }
            SurfaceKind::Pty => {
                let Some(snapshot) = self.rendered_kitty_graphics.get(&area.surface) else {
                    return placements;
                };
                let pane = self
                    .rendered_terminal_bounds
                    .get(&area.surface)
                    .copied()
                    .unwrap_or(area.content);
                let images = snapshot
                    .images
                    .iter()
                    .map(|image| {
                        (
                            image.id,
                            kitty_graphic_image(self.session_generation, area.surface, image),
                        )
                    })
                    .collect::<HashMap<_, _>>();
                placements.extend(snapshot.placements.iter().filter_map(|placement| {
                    let image = images.get(&placement.image_id)?.clone();
                    let placement = kitty_graphic_placement(
                        pane,
                        area.content_source_x(),
                        self.cell_pixels,
                        image,
                        placement,
                    )?;
                    (!Self::graphic_occluded(placement.rect, occluders)).then_some(placement)
                }));
            }
        }
        placements
    }

    fn graphic_occluded(rect: Rect, occluders: &[Rect]) -> bool {
        occluders.iter().any(|occluder| rects_intersect(rect, *occluder))
    }

    fn apply_graphics_completion(&mut self) -> RenderAction {
        let Some(completion) =
            self.graphics_writer.as_ref().and_then(GraphicsWriter::take_completion)
        else {
            return RenderAction::None;
        };
        match completion {
            GraphicsCompletion::Processed(processing) => {
                self.commit_graphics_processing(processing);
                RenderAction::None
            }
            GraphicsCompletion::TimedOut { id, session_generation } => {
                self.retry_graphics_after_timeout(id, session_generation)
            }
            GraphicsCompletion::Failed => self.disable_graphics_after_failure(),
        }
    }

    fn reset_unconfirmed_graphics(&mut self) {
        self.pending_graphics_submission = None;
        self.pending_graphics_snapshot = None;
        self.pending_graphics_affected_rect = None;
        self.last_graphics_snapshot.clear();
        self.graphics_scene_cache.invalidate();
        self.rendered_pane_content_generations
            .retain(|_, generation| !matches!(generation, PaneContentGeneration::Browser(_)));
        self.commit_rendered_pane_content_generations();
        self.pointer_route_phase = PointerRoutePhase::DrawPending;
    }

    fn retry_graphics_after_timeout(&mut self, id: u64, session_generation: u64) -> RenderAction {
        if self.pending_graphics_submission != Some(id)
            || self.session_generation != session_generation
        {
            return RenderAction::None;
        }
        self.reset_unconfirmed_graphics();
        RenderAction::Draw
    }

    fn disable_graphics_after_failure(&mut self) -> RenderAction {
        self.reset_unconfirmed_graphics();
        self.graphics_supported = false;
        if let Some(mut writer) = self.graphics_writer.take() {
            writer.shutdown(Duration::from_millis(200));
        }
        RenderAction::Draw
    }

    fn commit_graphics_processing(&mut self, processing: GraphicsProcessing) {
        let settles_latest = self.pending_graphics_submission == Some(processing.id);
        let belongs_to_current_session = processing.session_generation == self.session_generation;
        let current_browser_authorities = belongs_to_current_session.then(|| {
            processing
                .graphics
                .iter()
                .filter(|graphic| {
                    self.session
                        .surface(graphic.surface)
                        .is_some_and(|surface| surface.kind() == SurfaceKind::Browser)
                })
                .filter_map(|graphic| {
                    graphic.pointer_frame_seq.map(|authority| (graphic.surface, authority))
                })
                .collect::<Vec<_>>()
        });
        self.last_graphics_snapshot = processing
            .graphics
            .iter()
            .map(|graphic| GraphicIdentity {
                session_generation: processing.session_generation,
                surface: graphic.surface,
                rect: graphic.rect,
                seq: graphic.seq,
                pointer_frame_seq: graphic.pointer_frame_seq,
            })
            .collect();
        if settles_latest {
            self.pending_graphics_submission = None;
            self.pending_graphics_snapshot = None;
            self.pending_graphics_affected_rect = None;
        } else if let Some(pending) = self.pending_graphics_snapshot.as_deref() {
            self.pending_graphics_affected_rect =
                self.graphics_changed_rect_bound(&self.last_graphics_snapshot, pending);
        }
        if let Some(current_browser_authorities) = current_browser_authorities {
            self.rendered_pane_content_generations
                .retain(|_, generation| !matches!(generation, PaneContentGeneration::Browser(_)));
            for (surface, generation) in current_browser_authorities {
                if let Some(handle) = self.session.surface(surface)
                    && handle.browser_acknowledge_pointer_frame(generation)
                {
                    let _ = self.browser_input.enqueue(BrowserInputEvent {
                        surface_id: surface,
                        surface: handle,
                        kind: BrowserInputKind::Presented { frame_seq: generation },
                    });
                }
                self.rendered_pane_content_generations
                    .insert(surface, PaneContentGeneration::Browser(generation));
            }
            self.commit_rendered_pane_content_generations();
        }
        if settles_latest
            && self.pointer_route_phase == PointerRoutePhase::GraphicsProcessingPending
        {
            self.pointer_route_phase = PointerRoutePhase::Fresh;
        }
    }

    fn commit_rendered_pane_content_generations(&mut self) {
        if *self.rendered_pointer_frame.pane_content_generations
            != self.rendered_pane_content_generations
        {
            self.rendered_pointer_frame.pane_content_generations =
                Arc::new(self.rendered_pane_content_generations.clone());
        }
    }

    #[cfg(test)]
    fn browser_graphic_occluded(&self, rect: Rect) -> bool {
        Self::graphic_occluded(rect, &self.graphic_occlusion_rects())
    }

    fn refresh_cell_pixels(&mut self) {
        let next = crate::ui::graphics::detect_cell_pixels(Some(self.cell_pixels));
        let changed = self.cell_pixels != next;
        if changed {
            if !self.prepare_pty_input_before_mutation() {
                return;
            }
            self.cell_pixels = next;
            self.browser_input.clear_resize_failures();
        }
        // Repeat unchanged measurements too. The mux publishes a new global
        // default only after every surface converges, so this reconciles a
        // transient failure or an acknowledgement that timed out after the
        // authoritative host committed.
        if publishes_global_cell_metrics(self.surface_only) {
            self.session.set_cell_pixel_size(next.0, next.1);
        }
    }

    fn reload_config(&mut self) {
        #[cfg(test)]
        {
            self.config_reload_applications += 1;
        }
        let focused_projection_id = match self.focus {
            FocusTarget::ProjectionRail(index) => {
                self.config.sidebar.views.get(index).map(|view| view.id.clone())
            }
            _ => None,
        };
        let mut config = crate::config::load();
        config.apply_chrome_defaults(self.chrome);
        let shortcut_rows = self
            .shortcut_help
            .as_ref()
            .map(|_| ShortcutHelp::resolved_rows(&config, self.surface_only.is_some()));
        self.sidebar_plugin_error = None;
        self.sidebar_plugin_retry_after_ms = None;
        self.sidebar_plugin_retry_at = None;
        self.session.apply_config(config.clone());
        self.sidebar_view = config.sidebar.view;
        self.config = config;
        let valid_view_ids =
            self.config.sidebar.views.iter().map(|view| view.id.clone()).collect::<HashSet<_>>();
        self.projection_rails.retain(|id, _| valid_view_ids.contains(id));
        self.projection_sidebar_width_overrides.retain(|id, _| valid_view_ids.contains(id));
        if let Some(id) = focused_projection_id {
            if let Some((index, view)) =
                self.config.sidebar.views.iter().enumerate().find(|(_, view)| view.id == id)
            {
                let kind =
                    view.legacy_kind().map_or(RailKind::Projection(index), |kind| match kind {
                        SidebarColumnKind::Machines => RailKind::Machine,
                        SidebarColumnKind::Workspaces => RailKind::Workspace,
                        SidebarColumnKind::Tabs => RailKind::Tabs,
                    });
                self.focus_rail(kind);
            } else {
                self.focus = FocusTarget::Pane;
            }
        }
        if let (Some(help), Some(rows)) = (self.shortcut_help.as_mut(), shortcut_rows) {
            help.rows = rows;
            help.scroll_offset = help.scroll_offset.min(help.max_scroll(help.rows.len()));
        }
        self.sidebar_followed_surface = None;
        self.ensure_status_command_worker();
    }

    /// Stop any running status command worker and start a new one when the
    /// visible status bar has command segments. Called at startup and after
    /// every config reload.
    fn ensure_status_command_worker(&mut self) {
        if let Some(stop) = self.status_command_worker_stop.take() {
            stop.raise();
        }
        // Stopped workers observe the flag at every capture poll tick, so
        // they exit within milliseconds. Keep their handles and enforce a
        // hard bound anyway, so even a reload storm cannot stack live
        // worker generations; a join past the bound is bounded by that same
        // poll tick.
        const MAX_RETIRING_STATUS_WORKERS: usize = 32;
        self.retiring_status_workers.append(&mut self.status_command_workers);
        self.retiring_status_workers.retain(|handle| !handle.is_finished());
        while self.retiring_status_workers.len() > MAX_RETIRING_STATUS_WORKERS {
            let handle = self.retiring_status_workers.remove(0);
            let _ = handle.join();
        }
        // A fresh map per generation: a stopped worker mid-command can only
        // write into its own orphaned map, never under an index that now
        // belongs to a different segment.
        self.status_command_outputs = Arc::new(Mutex::new(HashMap::new()));
        self.status_outputs_generation = Arc::new(AtomicU64::new(1));
        self.status_poke_pending = Arc::new(AtomicBool::new(false));
        self.status_segments_cache = None;
        if !self.config.status_bar.visible || self.is_surface_only() {
            return;
        }
        let commands = self.config.status_bar.command_segments();
        if commands.is_empty() {
            return;
        }
        let stop = Arc::new(StatusWorkerStop::new());
        for (index, argv, interval) in commands {
            let outputs = self.status_command_outputs.clone();
            let generation = self.status_outputs_generation.clone();
            let poke = self.status_poke_pending.clone();
            let events = self.app_events.clone();
            let worker_stop = stop.clone();
            match std::thread::Builder::new().name(format!("status-segment-{index}")).spawn(
                move || {
                    run_status_segment_loop(StatusSegmentWorker {
                        index,
                        argv,
                        interval,
                        outputs,
                        generation,
                        poke,
                        events,
                        stop: worker_stop,
                    });
                },
            ) {
                Ok(handle) => self.status_command_workers.push(handle),
                Err(error) => {
                    crate::client_log::stderr_log!(
                        "status-segment",
                        "cmux-tui: could not start a status segment worker: {error}"
                    );
                }
            }
        }
        self.status_command_worker_stop = Some(stop);
    }

    /// Resolve the configured status segments to displayable text: literal
    /// segments expand `{variable}`s, command segments read the worker's
    /// latest output. The resolved result is cached against a fingerprint
    /// of every expansion input, so an ordinary draw reuses the previous
    /// strings instead of re-expanding templates.
    pub(crate) fn resolved_status_segments(&mut self) -> Arc<ResolvedStatusSegments> {
        static EMPTY: std::sync::OnceLock<Arc<ResolvedStatusSegments>> = std::sync::OnceLock::new();
        if self.config.status_bar.left.is_empty() && self.config.status_bar.right.is_empty() {
            return EMPTY.get_or_init(|| Arc::new((Vec::new(), Vec::new()))).clone();
        }
        let fingerprint = self.status_segments_fingerprint();
        if self.status_segments_cache.as_ref().map(|(cached, _)| *cached) != Some(fingerprint) {
            let resolved = Arc::new(self.resolve_status_segments_now());
            self.status_segments_cache = Some((fingerprint, resolved));
        }
        self.status_segments_cache
            .as_ref()
            .map(|(_, resolved)| Arc::clone(resolved))
            .unwrap_or_else(|| EMPTY.get_or_init(|| Arc::new((Vec::new(), Vec::new()))).clone())
    }

    /// Allocation-free hash of every input `resolve_status_segments_now`
    /// reads: command outputs (via the workers' change counter) plus the
    /// interpolated session, workspace, screen, and title values. The
    /// frequently-changing tab title participates only when a configured
    /// template actually uses `{title}`, so ordinary title churn does not
    /// rebuild fixed segments.
    fn status_segments_fingerprint(&self) -> u64 {
        use std::hash::{Hash, Hasher};
        let mut hasher = std::collections::hash_map::DefaultHasher::new();
        self.status_outputs_generation.load(Ordering::Acquire).hash(&mut hasher);
        self.session_label.hash(&mut hasher);
        if let Some(workspace) = self.tree.active_workspace() {
            workspace.name.hash(&mut hasher);
            workspace.screens.len().hash(&mut hasher);
            workspace.active_screen.hash(&mut hasher);
            if let Some(screen) = workspace.screens.get(workspace.active_screen) {
                screen.name.hash(&mut hasher);
            }
        }
        if self.status_templates_use("{title}")
            && let Some(tab) = self
                .tree
                .active_screen()
                .and_then(|screen| screen.pane(screen.active_pane))
                .and_then(|pane| pane.tabs.get(pane.active_tab))
        {
            tab.name.hash(&mut hasher);
            tab.title.hash(&mut hasher);
        }
        hasher.finish()
    }

    /// Whether any configured literal status segment contains `token`.
    fn status_templates_use(&self, token: &str) -> bool {
        self.config.status_bar.left.iter().chain(self.config.status_bar.right.iter()).any(
            |segment| match &segment.content {
                crate::config::StatusSegmentContent::Text(template) => template.contains(token),
                crate::config::StatusSegmentContent::Command { .. } => false,
            },
        )
    }

    fn resolve_status_segments_now(&self) -> ResolvedStatusSegments {
        let outputs = self.status_command_outputs.lock().unwrap();
        let mut index = 0usize;
        let mut resolve = |segments: &[crate::config::StatusSegment]| {
            segments
                .iter()
                .map(|segment| {
                    let text = match &segment.content {
                        crate::config::StatusSegmentContent::Text(template) => {
                            self.expand_status_template(template)
                        }
                        crate::config::StatusSegmentContent::Command { .. } => {
                            outputs.get(&index).cloned().unwrap_or_default()
                        }
                    };
                    index += 1;
                    StatusSegmentView { text, fg: segment.fg, bg: segment.bg }
                })
                .collect::<Vec<_>>()
        };
        let left = resolve(&self.config.status_bar.left);
        let right = resolve(&self.config.status_bar.right);
        (left, right)
    }

    /// `{session}`, `{workspace}`, `{screen}`, `{screens}`, `{title}`, and
    /// `{user}`. Unknown braces stay literal.
    fn expand_status_template(&self, template: &str) -> String {
        if !template.contains('{') {
            return template.to_string();
        }
        let workspace = self.tree.active_workspace();
        let workspace_name = workspace.map(|ws| ws.name.clone()).unwrap_or_default();
        let screens = workspace.map(|ws| ws.screens.len()).unwrap_or(0).to_string();
        let screen_name = workspace
            .and_then(|ws| {
                ws.screens.get(ws.active_screen).map(|screen| screen.display_name(ws.active_screen))
            })
            .unwrap_or_default();
        let title = self
            .tree
            .active_screen()
            .and_then(|screen| screen.pane(screen.active_pane))
            .and_then(|pane| pane.tabs.get(pane.active_tab))
            .map(|tab| tab.name.clone().unwrap_or_else(|| tab.title.clone()))
            .unwrap_or_default();
        expand_status_tokens(
            template,
            &StatusTemplateValues {
                session: &self.session_label,
                workspace: &workspace_name,
                screen: &screen_name,
                screens: &screens,
                title: &title,
                user: cached_status_user(),
            },
        )
    }

    fn focused_surface_cwd(&self) -> Option<PathBuf> {
        let surface = self.tree.active_surface()?;
        self.session.surface_cwd(surface).map(PathBuf::from)
    }

    fn sync_sidebar_files_to_focus(&mut self, force: bool) -> bool {
        if self.config.sidebar.plugin.is_some()
            || self.sidebar_view != SidebarView::Files
            || self.sidebar_files.is_pinned()
        {
            return false;
        }
        let focused = self.tree.active_surface();
        if !force && focused == self.sidebar_followed_surface {
            return false;
        }
        self.sidebar_followed_surface = focused;
        let Some(cwd) = self.focused_surface_cwd() else { return false };
        self.sidebar_files.follow_focused_cwd(&cwd)
    }

    fn tick_sidebar_files(&mut self) -> bool {
        if self.config.sidebar.plugin.is_some()
            || self.sidebar_view != SidebarView::Files
            || !self.sidebar_visible
        {
            return false;
        }
        // The cwd follow can be a synchronous socket round-trip for remote
        // sessions; the event loop ticks up to ~33x/sec, so gate it behind the
        // same 2s refresh cadence as the directory reload.
        let now = Instant::now();
        let mut changed = false;
        if self.sidebar_files.refresh_due(now)
            && !self.sidebar_files.is_pinned()
            && let Some(cwd) = self.focused_surface_cwd()
        {
            changed |= self.sidebar_files.follow_focused_cwd(&cwd);
        }
        changed | self.sidebar_files.tick(now)
    }

    fn write_window_title(&self, title: &str) -> anyhow::Result<()> {
        let lock = self.stdout_lock.clone();
        let _guard = lock.lock();
        lock.recover_stream_locked()?;
        self.ensure_graphics_writer_healthy()?;
        let mut stdout = std::io::stdout();
        stdout.write_all(&cmux_tui_core::server::window_title_osc(title))?;
        stdout.flush()?;
        Ok(())
    }

    fn viewport_animation_active(&self) -> bool {
        self.config.viewport.animation
            && self
                .active_screen_id()
                .and_then(|screen| self.viewport_states.get(&screen))
                .is_some_and(ViewportMotion::animating)
    }

    fn advance_viewport_animation(&mut self, now: Instant) -> RenderAction {
        if !self.config.viewport.animation {
            return RenderAction::None;
        }
        let Some(screen) = self.active_screen_id() else {
            return RenderAction::None;
        };
        let maximum =
            self.viewport_virtual_width.saturating_sub(u64::from(self.content_area.width));
        let (offset, settled) = {
            let Some(motion) = self.viewport_states.get_mut(&screen) else {
                return RenderAction::None;
            };
            let was_animating = motion.animating();
            let _ = motion.update(now);
            (motion.offset().min(maximum), was_animating && !motion.animating())
        };
        if offset == self.viewport_offset {
            return if settled { RenderAction::Draw } else { RenderAction::None };
        }
        self.viewport_offset = offset;
        self.reclip_viewport_panes();
        if settled { RenderAction::Draw } else { RenderAction::Paint }
    }

    fn reclip_viewport_panes(&mut self) {
        if self.viewport_layout.is_empty() {
            return;
        }
        let Some(screen) = self.tree.active_screen() else {
            self.pane_areas.clear();
            self.viewport_projection.clear();
            return;
        };
        if !self.viewport_projection.is_for_screen(screen.id) {
            self.viewport_projection.rebuild(PaneAreaProjection {
                screen,
                layout: &self.viewport_layout,
                stacked_headers: &self.viewport_stacked_headers,
                area: self.content_area,
                scrollbar_position: self.config.scrollbar.position,
                pane_padding: self.config.pane.padding,
                surface_only: self.surface_only,
                viewport_offset: Some(self.viewport_offset),
            });
        }
        self.viewport_projection.project_into(
            &mut self.pane_areas,
            self.content_area,
            self.viewport_offset,
        );
    }

    fn sync_viewport_motion(
        &mut self,
        screen: ScreenId,
        active_pane: PaneId,
        active_rect: Option<VirtualRect>,
        area: Rect,
        virtual_width: u64,
        now: Instant,
    ) -> u64 {
        let maximum = virtual_width.saturating_sub(u64::from(area.width));
        let animate = self.config.viewport.animation;
        let motion = self.viewport_states.entry(screen).or_insert_with(|| ViewportMotion::new(now));
        let geometry = ViewportGeometry {
            active_span: active_rect.map(|rect| (rect.x, rect.width)),
            viewport_x: u64::from(area.x),
            viewport_width: area.width,
            virtual_width,
        };
        let reveal_active =
            motion.last_active_pane != Some(active_pane) || motion.last_geometry != Some(geometry);
        let mut target = (motion.target.round() as u64).min(maximum);
        if reveal_active && let Some(rect) = active_rect {
            let left = rect.x.saturating_sub(u64::from(area.x));
            let right = left.saturating_add(rect.width);
            if left < target {
                target = left;
            } else if right > target.saturating_add(u64::from(area.width)) {
                target = right.saturating_sub(u64::from(area.width));
            }
        }
        motion.retarget(target.min(maximum), animate, now);
        motion.last_active_pane = Some(active_pane);
        motion.last_geometry = Some(geometry);
        motion.offset().min(maximum)
    }

    fn set_viewport_target(&mut self, target: u64, animate: bool) -> bool {
        let Some(screen) = self.active_screen_id() else { return false };
        let maximum =
            self.viewport_virtual_width.saturating_sub(u64::from(self.content_area.width));
        let target = target.min(maximum);
        let now = Instant::now();
        let motion = self.viewport_states.entry(screen).or_insert_with(|| ViewportMotion::new(now));
        let changed = motion.target.round() as u64 != target || motion.offset() != target;
        motion.retarget(target, animate && self.config.viewport.animation, now);
        changed
    }

    /// Refresh the tree snapshot, recompute the active screen's layout
    /// (each pane's border box eats one cell on every side), and push
    /// content sizes to surfaces.
    fn sync_layout(&mut self, size: (u16, u16)) {
        let (width, height) = size;
        self.outer_size = size;
        let sidebar_layout = if self.surface_only.is_some() {
            SidebarLayout {
                content: Rect { x: 0, y: 0, width, height },
                ..SidebarLayout::default()
            }
        } else {
            let hidden_views = self
                .hidden_sidebar_views
                .get(&self.config.sidebar.active_profile)
                .cloned()
                .unwrap_or_default();
            let previous =
                (!self.sidebar_layout.ordered.is_empty()).then_some(&self.sidebar_layout);
            sidebar_layout_for_state(
                &self.config,
                self.sidebar_visible,
                self.sidebar_compact,
                self.machine_ui.is_some(),
                size,
                self.sidebar_width_override,
                self.machine_sidebar_width_override,
                self.tabs_sidebar_width_override,
                &self.projection_sidebar_width_overrides,
                &hidden_views,
                previous,
            )
        };
        self.sidebar_layout = sidebar_layout;
        self.sidebar_width = self.sidebar_layout.workspace.map_or(0, |rect| rect.width);
        self.machine_sidebar_width = self.sidebar_layout.machine.map_or(0, |rect| rect.width);
        self.tabs_sidebar_width = self.sidebar_layout.tabs.map_or(0, |rect| rect.width);
        if self.sidebar_width == 0 && self.focus == FocusTarget::WorkspaceRail {
            self.focus = FocusTarget::Pane;
        }
        if self.machine_sidebar_width == 0 && self.focus == FocusTarget::MachineRail {
            self.focus = FocusTarget::Pane;
        }
        if self.tabs_sidebar_width == 0 && self.focus == FocusTarget::TabsRail {
            self.focus = FocusTarget::Pane;
        }
        if let FocusTarget::ProjectionRail(index) = self.focus
            && self.sidebar_layout.rail(RailKind::Projection(index)).is_none()
        {
            self.focus = FocusTarget::Pane;
        }
        let area = self.sidebar_layout.content;
        self.content_area = area;
        if self.surface_only.is_none() {
            let _ = self.sync_sidebar_plugin(false);
        }
        self.replace_tree(self.session.tree());
        self.claim_active_terminal_geometry(false);
        if self.surface_only.is_none() {
            self.sidebar_workspace_selection =
                self.sidebar_workspace_selection.min(self.tree.workspaces.len().saturating_sub(1));
            self.sync_sidebar_files_to_focus(false);
        }
        self.pane_areas.clear();
        let Some(screen) = self.tree.active_screen().cloned() else {
            self.viewport_projection.clear();
            self.viewport_layout.clear();
            self.viewport_stacked_headers.clear();
            self.viewport_virtual_width = 0;
            self.viewport_offset = 0;
            let hidden = self
                .visible_size_surfaces
                .difference(&self.pending_size_releases)
                .copied()
                .collect::<Vec<_>>();
            if hidden.is_empty() || self.prepare_pty_input_before_mutation() {
                for surface in hidden {
                    if self.session.release_surface_size(surface) {
                        self.pending_size_releases.insert(surface);
                    }
                }
            }
            return;
        };
        let viewport_enabled = self.surface_only.is_none()
            && screen.zoomed_pane.is_none()
            && !screen.viewport_splits.is_empty();
        let layout: ViewportLayoutResult = if self.surface_only.is_some() {
            layout_screen(&Node::Leaf(screen.active_pane), area, Some(screen.active_pane)).into()
        } else if let Some(pane) = screen.zoomed_pane {
            layout_screen(&Node::Leaf(pane), area, Some(pane)).into()
        } else if viewport_enabled {
            layout_screen_with_viewport(
                &screen.layout,
                area,
                Some(screen.active_pane),
                screen.viewport_base_width.unwrap_or(1.0),
                &screen.viewport_splits,
            )
        } else {
            layout_screen(&screen.layout, area, Some(screen.active_pane)).into()
        };
        let viewport_enabled = viewport_enabled && layout.virtual_width > u64::from(area.width);
        self.viewport_layout = if viewport_enabled { layout.panes.clone() } else { Vec::new() };
        self.viewport_stacked_headers =
            if viewport_enabled { layout.stacked_headers.clone() } else { HashSet::new() };
        self.viewport_virtual_width = layout.virtual_width;
        self.viewport_offset = if viewport_enabled {
            self.sync_viewport_motion(
                screen.id,
                screen.active_pane,
                layout.rect_of(screen.active_pane),
                area,
                layout.virtual_width,
                Instant::now(),
            )
        } else {
            0
        };
        let pane_projection = PaneAreaProjection {
            screen: &screen,
            layout: &layout.panes,
            stacked_headers: &layout.stacked_headers,
            area,
            scrollbar_position: self.config.scrollbar.position,
            pane_padding: self.config.pane.padding,
            surface_only: self.surface_only,
            viewport_offset: viewport_enabled.then_some(self.viewport_offset),
        };
        if viewport_enabled {
            self.viewport_projection.rebuild(pane_projection);
            self.viewport_projection.project_into(&mut self.pane_areas, area, self.viewport_offset);
        } else {
            self.viewport_projection.clear();
            rebuild_pane_areas(&mut self.pane_areas, pane_projection);
        }

        // Size and attach every pane crossed by a short animation up front.
        // Paint-only ticks can then reveal cached surfaces without socket
        // work. Expensive jumps settle immediately and synchronize only the
        // destination viewport instead of saturating the ordered PTY lane.
        let target_offset = viewport_enabled.then(|| {
            let maximum = layout.virtual_width.saturating_sub(u64::from(area.width));
            self.viewport_states
                .get(&screen.id)
                .map_or(self.viewport_offset, |motion| motion.target.round() as u64)
                .min(maximum)
        });
        let size_leases = if let Some(target_offset) =
            target_offset.filter(|target| *target != self.viewport_offset)
        {
            if let Some(leases) = swept_viewport_size_leases(
                PaneAreaProjection {
                    screen: &screen,
                    layout: &layout.panes,
                    stacked_headers: &layout.stacked_headers,
                    area,
                    scrollbar_position: self.config.scrollbar.position,
                    pane_padding: self.config.pane.padding,
                    surface_only: self.surface_only,
                    viewport_offset: Some(self.viewport_offset),
                },
                target_offset,
            ) {
                leases
            } else {
                if let Some(motion) = self.viewport_states.get_mut(&screen.id) {
                    motion.retarget(target_offset, false, Instant::now());
                }
                self.viewport_offset = target_offset;
                self.viewport_projection.project_into(
                    &mut self.pane_areas,
                    area,
                    self.viewport_offset,
                );
                visible_pane_size_leases(&self.pane_areas)
            }
        } else {
            visible_pane_size_leases(&self.pane_areas)
        };

        let visible = size_leases.iter().map(|lease| lease.surface).collect::<HashSet<_>>();
        let hidden = self
            .visible_size_surfaces
            .difference(&visible)
            .filter(|surface| !self.pending_size_releases.contains(surface))
            .copied()
            .collect::<Vec<_>>();
        if !hidden.is_empty() && !self.prepare_pty_input_before_mutation() {
            return;
        }
        for surface in hidden {
            if self.session.release_surface_size(surface) {
                self.pending_size_releases.insert(surface);
            }
        }
        let resurfaced =
            visible.intersection(&self.pending_size_releases).copied().collect::<HashSet<_>>();
        let mut newly_visible =
            visible.difference(&self.visible_size_surfaces).copied().collect::<HashSet<_>>();
        newly_visible.extend(resurfaced.iter().copied());
        self.visible_size_surfaces.extend(visible.iter().copied());

        // Keep inactive tabs attached for instant rendering, but give only
        // active tabs in the swept viewport a sizing lease. The settling draw
        // releases panes outside the final viewport.
        for lease in size_leases {
            let Some(pane) = screen.pane(lease.pane) else { continue };
            let content_size = lease.content_size;
            for tab in &pane.tabs {
                if self.surface_only.is_some_and(|surface| surface != tab.surface) {
                    continue;
                }
                if self.session.has_surface(tab.surface) {
                    continue;
                }
                let size = (tab.surface == lease.surface)
                    .then_some(content_size)
                    .filter(|(cols, rows)| *cols > 0 && *rows > 0);
                if self.session.can_attach_surface(tab.surface)
                    && self.prepare_pty_input_before_mutation()
                {
                    self.session.attach_surface(tab.surface, size);
                }
            }
            let Some(surface) = self.session.surface(lease.surface) else { continue };
            let desired = content_size;
            if surface.kind() == SurfaceKind::Browser
                && self.browser_input.resize_failed(lease.surface, desired)
            {
                continue;
            }
            let needs = newly_visible.contains(&lease.surface)
                || !self.session.has_surface_size_report(lease.surface)
                || surface.resize_needed(content_size.0, content_size.1, false);
            let resize_decision = if resurfaced.contains(&lease.surface) {
                self.session.surface_resize_reclaim_decision(lease.surface, desired)
            } else {
                self.session.surface_resize_decision(lease.surface, desired, needs)
            };
            if let SurfaceResizeDecision::NeedsQueue(claim) = resize_decision
                && self.prepare_pty_input_before_mutation()
            {
                let accepted = if resurfaced.contains(&lease.surface) {
                    self.enqueue_surface_size_reclaim(
                        lease.surface,
                        surface,
                        content_size.0,
                        content_size.1,
                        Some(claim),
                    )
                } else {
                    self.enqueue_surface_resize(
                        lease.surface,
                        surface,
                        content_size.0,
                        content_size.1,
                        false,
                        Some(claim),
                    )
                };
                if accepted && resurfaced.contains(&lease.surface) {
                    self.pending_size_releases.remove(&lease.surface);
                }
            }
        }
    }

    pub fn sidebar_plugin_rect(&self) -> Rect {
        self.workspace_sidebar_area(self.content_area.height.saturating_add(1))
            .map(|area| Rect { width: area.width.saturating_sub(1), ..area })
            .unwrap_or_default()
    }

    fn sync_sidebar_plugin(&mut self, relaunch: bool) -> bool {
        if self.config.sidebar.plugin.is_none() {
            self.session.invalidate_sidebar_plugin_sync();
            self.sidebar_plugin_surface = None;
            self.sidebar_plugin_error = None;
            self.sidebar_plugin_retry_after_ms = None;
            self.sidebar_plugin_retry_at = None;
            self.sidebar_focus_pending = false;
            return false;
        }
        if self.sidebar_width < 3 || !self.sidebar_visible {
            self.session.invalidate_sidebar_plugin_sync();
            self.sidebar_plugin_surface = None;
            self.sidebar_plugin_error = None;
            self.sidebar_plugin_retry_after_ms = None;
            self.sidebar_plugin_retry_at = None;
            self.leave_workspace_sidebar();
            self.sidebar_focus_pending = false;
            return false;
        }
        let rect = self.sidebar_plugin_rect();
        if rect.width == 0 || rect.height == 0 {
            return false;
        }
        let terminal_failure =
            self.sidebar_plugin_error.is_some() && self.sidebar_plugin_retry_after_ms.is_none();
        if !relaunch && (self.sidebar_plugin_retry_at.is_some() || terminal_failure) {
            return false;
        }
        if relaunch && !self.prepare_pty_input_before_mutation() {
            return false;
        }
        self.session.sidebar_plugin((rect.width, rect.height), relaunch);
        true
    }

    fn retry_sidebar_plugin_if_due(&mut self) {
        if self.sidebar_plugin_retry_at.is_none_or(|retry_at| Instant::now() < retry_at) {
            return;
        }
        if matches!(self.drag, Some(Drag::PtyMouse { .. })) {
            self.sidebar_plugin_retry_at = Some(Instant::now() + Duration::from_millis(250));
            return;
        }
        self.sidebar_plugin_retry_at = None;
        self.sidebar_plugin_retry_after_ms = None;
        if !self.sync_sidebar_plugin(true) {
            self.sidebar_plugin_retry_at = Some(Instant::now() + Duration::from_millis(250));
        }
    }

    fn apply_sidebar_plugin_status(&mut self, status: SidebarPluginSurface, relaunch: bool) {
        if self.config.sidebar.plugin.is_none() {
            self.session.invalidate_sidebar_plugin_sync();
            self.sidebar_plugin_surface = None;
            self.sidebar_plugin_error = None;
            self.sidebar_plugin_retry_after_ms = None;
            self.sidebar_plugin_retry_at = None;
            self.sidebar_focus_pending = false;
            return;
        }
        if !self.sidebar_visible {
            self.session.invalidate_sidebar_plugin_sync();
            self.sidebar_plugin_surface = None;
            self.sidebar_plugin_error = None;
            self.sidebar_plugin_retry_after_ms = None;
            self.sidebar_plugin_retry_at = None;
            self.leave_workspace_sidebar();
            self.sidebar_focus_pending = false;
            return;
        }
        let had_surface = self.sidebar_plugin_surface.is_some();
        self.sidebar_plugin_surface = status.surface_id;
        self.sidebar_plugin_error = status.error;
        self.sidebar_plugin_retry_after_ms = status.retry_after_ms;
        self.sidebar_plugin_retry_at =
            status.retry_after_ms.map(|delay_ms| Instant::now() + Duration::from_millis(delay_ms));
        if had_surface && self.sidebar_plugin_surface.is_none() {
            self.session.invalidate_sidebar_plugin_sync();
        }
        if self.sidebar_focus_pending && (self.sidebar_plugin_surface.is_some() || relaunch) {
            self.sidebar_focus_pending = false;
            if self.sidebar_plugin_surface.is_some() {
                self.focus = FocusTarget::WorkspaceRail;
                self.menu = None;
                self.prompt = None;
                self.omnibar = None;
                self.replace_selection(None);
            }
        }
        if self.workspace_sidebar_focused() && self.sidebar_plugin_surface.is_none() {
            self.leave_workspace_sidebar();
        }
    }

    fn handle(&mut self, event: AppEvent) -> anyhow::Result<RenderAction> {
        let action = self.handle_inner(event, None, None)?;
        self.mark_pointer_route_for_rebuild(action);
        Ok(action)
    }

    fn handle_replayed_input(
        &mut self,
        input: TerminalInput,
        sequence: u64,
        replay_context: Option<ReplayedInputContext>,
    ) -> anyhow::Result<RenderAction> {
        let action =
            self.handle_inner(AppEvent::NormalizedInput(input), Some(sequence), replay_context)?;
        self.mark_pointer_route_for_rebuild(action);
        Ok(action)
    }

    fn handle_inner(
        &mut self,
        event: AppEvent,
        input_sequence: Option<u64>,
        replay_context: Option<ReplayedInputContext>,
    ) -> anyhow::Result<RenderAction> {
        let event = match event {
            AppEvent::SessionScoped { generation, event }
                if generation == self.session_generation =>
            {
                *event
            }
            AppEvent::SessionScoped { .. } => return Ok(RenderAction::None),
            event => event,
        };
        let event = match event {
            AppEvent::Input(input) => {
                let mut input = TerminalInput::from_event(input);
                if let TerminalInput::Keyboard(key) = &mut input {
                    key.resolve_macos_option_as_alt(self.config.keys.macos_option_as_alt);
                    if key.is_composing() || key.is_modifier_only() {
                        return Ok(RenderAction::None);
                    }
                }
                self.input_revision = self.input_revision.wrapping_add(1);
                input = match input {
                    TerminalInput::Keyboard(key) => match self.resolve_keyboard_ingress(key) {
                        KeyboardIngress::Routed(input) => input,
                        KeyboardIngress::Handled(action) => {
                            let dismissed = self.dismiss_painted_durable_notice();
                            return Ok(if dismissed {
                                action.merge(RenderAction::Draw)
                            } else {
                                action
                            });
                        }
                        KeyboardIngress::Ignored => return Ok(RenderAction::None),
                    },
                    input => input,
                };
                if input.retained_bytes() > MAX_DEFERRED_INPUT_BYTES {
                    self.status_message = Some(
                        match &input {
                            TerminalInput::Paste(_) => {
                                localization::catalog().terminal.paste_text_too_large
                            }
                            TerminalInput::Keyboard(_) | TerminalInput::ClearHistoryKey(_) => {
                                localization::catalog().terminal.keyboard_text_too_large
                            }
                            _ => unreachable!("fixed-size input cannot exceed the byte limit"),
                        }
                        .to_string(),
                    );
                    return Ok(RenderAction::Draw);
                }
                AppEvent::NormalizedInput(input)
            }
            event => event,
        };
        if matches!(
            &event,
            AppEvent::NormalizedInput(
                TerminalInput::Keyboard(_)
                    | TerminalInput::FrontendAction { .. }
                    | TerminalInput::ClearHistoryKey(_)
                    | TerminalInput::Paste(_)
            )
        ) {
            let current_pairing = self.pairing_dialog.as_ref().map(|dialog| dialog.challenge.id);
            let replayed_pairing_changed = replay_context
                .as_ref()
                .and_then(|context| context.admission.as_ref())
                .is_some_and(|admission| admission.pairing_request != current_pairing);
            if replayed_pairing_changed || !self.pairing_identity_matches_rendered_frame() {
                // Pairing approval is a trusted action. Input captured before
                // the current pairing identity was visible must never approve
                // it or reach UI covered by a replacement dialog.
                return Ok(RenderAction::None);
            }
        }
        match &event {
            AppEvent::Mux(MuxEvent::LayoutChanged(_)) => {
                self.session.refresh_remote_tree_if_stale();
            }
            AppEvent::NormalizedInput(input) if input.is_routable() => {
                self.session.refresh_remote_tree_if_stale();
            }
            AppEvent::Mux(MuxEvent::TreeChanged) => {
                if self.session.remote_tree_is_stale() {
                    self.session.refresh_remote_tree_if_stale();
                } else {
                    self.session.refresh_remote_tree_background();
                }
            }
            _ => {}
        }
        if matches!(&event, AppEvent::Mux(MuxEvent::TreeChanged | MuxEvent::LayoutChanged(_))) {
            self.session.clear_surface_sync_failures();
        }
        if let AppEvent::NormalizedInput(TerminalInput::Mouse(
            mouse @ MouseEvent { kind: MouseEventKind::Moved, .. },
        )) = &event
        {
            let mouse = *mouse;
            if self.pointer_route_is_stale_for_mouse(&mouse)
                || self.fresh_pointer_motion_must_follow_deferred(input_sequence)
            {
                self.retain_pointer_motion_with_sequence(
                    mouse,
                    input_sequence,
                    replay_context
                        .as_ref()
                        .and_then(|context| context.pointer.as_ref())
                        .map(|pointer| pointer.focus_generation),
                );
                return Ok(RenderAction::None);
            }
        }
        let event = match event {
            AppEvent::NormalizedInput(input @ TerminalInput::Mouse(mouse))
                if self.pointer_route_is_stale_for_mouse(&mouse)
                    && !self.input_can_update_pending_mutation(&input) =>
            {
                return Ok(self.defer_input_with_sequence(
                    input,
                    input_sequence,
                    replay_context.as_ref().and_then(|context| context.pointer.clone()),
                    replay_context.as_ref().and_then(|context| context.admission.clone()),
                ));
            }
            event => event,
        };
        let event = match event {
            AppEvent::NormalizedInput(
                input @ (TerminalInput::Keyboard(_)
                | TerminalInput::FrontendAction { .. }
                | TerminalInput::ClearHistoryKey(_)
                | TerminalInput::Mouse(_)
                | TerminalInput::Paste(_)),
            ) if self.fresh_input_must_follow_deferred(&input, input_sequence)
                && !self.input_can_overtake_deferred(&input) =>
            {
                return Ok(self.defer_input_with_sequence(
                    input,
                    input_sequence,
                    replay_context.as_ref().and_then(|context| context.pointer.clone()),
                    replay_context.as_ref().and_then(|context| context.admission.clone()),
                ));
            }
            event => event,
        };
        let client_owned = match &event {
            AppEvent::NormalizedInput(input) => {
                replay_context.as_ref().and_then(|context| context.admission.as_ref()).map_or_else(
                    || self.input_is_client_owned(input),
                    |admission| admission.client_owned,
                )
            }
            _ => false,
        };
        let missing_surface = match &event {
            AppEvent::NormalizedInput(input) if !client_owned => self
                .missing_input_surface_for_admission(
                    input,
                    replay_context.as_ref().and_then(|context| context.admission.as_ref()),
                ),
            _ => None,
        };
        let mut terminal_pointer_admission = None;
        if let AppEvent::NormalizedInput(input) = &event {
            let pointer_has_capture = match input {
                TerminalInput::Mouse(mouse) => self.pointer_has_capture(mouse.kind),
                _ => false,
            };
            if let TerminalInput::Mouse(mouse) = input
                && !pointer_has_capture
            {
                let rendered_route = self.rendered_pointer_route_for_mouse(mouse);
                let replayed_route_changed = replay_context
                    .as_ref()
                    .and_then(|context| context.pointer.as_ref())
                    .is_some_and(|pointer| {
                        pointer.route.as_ref().is_some_and(|expected| {
                            pointer.pointer_map_generation
                                != self.rendered_pointer_frame.pointer_map_generation
                                || expected != &rendered_route
                        })
                    });
                if replayed_route_changed {
                    return Ok(RenderAction::None);
                }
                if !Self::mouse_opens_cmux_context_menu(mouse)
                    && let Some((surface, expected_generation)) =
                        rendered_route.browser_content_generation()
                    && missing_surface != Some(surface)
                {
                    let Some(expected_generation) = expected_generation else {
                        return Ok(RenderAction::None);
                    };
                    if !self.session.surface(surface).is_some_and(|surface| {
                        surface.browser_accepts_pointer_frame(expected_generation)
                    }) {
                        return Ok(RenderAction::None);
                    }
                }
                match self.terminal_pointer_admission_for_route(
                    &rendered_route,
                    mouse,
                    missing_surface,
                ) {
                    TerminalPointerAdmissionResult::NotTerminal => {}
                    TerminalPointerAdmissionResult::Ready(admission) => {
                        terminal_pointer_admission = Some(admission);
                    }
                    TerminalPointerAdmissionResult::Rejected => {
                        return Ok(RenderAction::None);
                    }
                    TerminalPointerAdmissionResult::Contended => {
                        if mouse.kind == MouseEventKind::Moved {
                            self.retain_pointer_motion_with_sequence(
                                *mouse,
                                input_sequence,
                                replay_context
                                    .as_ref()
                                    .and_then(|context| context.pointer.as_ref())
                                    .map(|pointer| pointer.focus_generation),
                            );
                        } else {
                            self.defer_input_with_sequence(
                                TerminalInput::Mouse(*mouse),
                                input_sequence,
                                replay_context.as_ref().and_then(|context| context.pointer.clone()),
                                replay_context
                                    .as_ref()
                                    .and_then(|context| context.admission.clone()),
                            );
                        }
                        // Parsing will release the semantic lock and normally
                        // wake us through SurfaceOutput. The idle replay tick
                        // is the bounded fallback, so do not synchronously
                        // paint through the same blocking terminal lock.
                        return Ok(RenderAction::None);
                    }
                }
            }
            if let Some(admission) =
                replay_context.as_ref().and_then(|context| context.admission.as_ref())
                && !pointer_has_capture
            {
                let follows_pending_route =
                    matches!(
                        input,
                        TerminalInput::Keyboard(_)
                            | TerminalInput::FrontendAction { .. }
                            | TerminalInput::ClearHistoryKey(_)
                            | TerminalInput::Paste(_)
                    ) && admission.destination_intent.is_some_and(|intent| {
                        self.session.destination_mutation_committed() >= intent
                            && self.session.destination_mutation_started() == intent
                    });
                let follows_semantic_route = admission.semantic_dependency.is_some_and(|intent| {
                    matches!(
                        self.semantic_destination_outcomes.get(&intent),
                        Some(SemanticDestinationOutcome::Resolved(surface))
                            if Self::input_accepts_semantic_destination(input)
                                && self.tab_locations.contains_key(surface)
                    )
                });
                let follows_captured_action_route = matches!(
                    input,
                    TerminalInput::FrontendAction { action, .. }
                        if !action_is_frontend_local(*action)
                            && admission.destination.is_some_and(|surface| {
                                self.tab_locations.contains_key(&surface)
                            })
                );
                let follows_sidebar_focus =
                    admission.sidebar_focus_intent && self.workspace_sidebar_focused();
                if !admission.client_owned
                    && !follows_pending_route
                    && !follows_semantic_route
                    && !follows_captured_action_route
                    && !follows_sidebar_focus
                    && self.input_destination(input) != admission.destination
                {
                    if !matches!(input, TerminalInput::Mouse(_)) {
                        self.status_message = Some(
                            localization::catalog()
                                .terminal
                                .deferred_input_destination_changed
                                .to_string(),
                        );
                        return Ok(RenderAction::Draw);
                    }
                    return Ok(RenderAction::None);
                }
            }
        }
        if let AppEvent::NormalizedInput(TerminalInput::Mouse(
            mouse @ MouseEvent { kind: MouseEventKind::Moved, .. },
        )) = &event
            && let Some(surface) = missing_surface
        {
            self.queue_surface_attach(surface);
            self.retain_pointer_motion_with_sequence(
                *mouse,
                input_sequence,
                replay_context
                    .as_ref()
                    .and_then(|context| context.pointer.as_ref())
                    .map(|pointer| pointer.focus_generation),
            );
            return Ok(RenderAction::None);
        }
        let event = match event {
            AppEvent::NormalizedInput(
                input @ (TerminalInput::Keyboard(_)
                | TerminalInput::FrontendAction { .. }
                | TerminalInput::ClearHistoryKey(_)
                | TerminalInput::Mouse(_)
                | TerminalInput::Paste(_)),
            ) if missing_surface.is_some() && !self.input_can_update_pending_mutation(&input) => {
                let surface = missing_surface.unwrap();
                self.queue_surface_attach(surface);
                return Ok(self.defer_input_with_sequence(
                    input,
                    input_sequence,
                    replay_context.as_ref().and_then(|context| context.pointer.clone()),
                    replay_context.as_ref().and_then(|context| context.admission.clone()),
                ));
            }
            AppEvent::NormalizedInput(
                input @ (TerminalInput::Keyboard(_)
                | TerminalInput::FrontendAction { .. }
                | TerminalInput::ClearHistoryKey(_)
                | TerminalInput::Mouse(_)
                | TerminalInput::Paste(_)),
            ) if !matches!(
                &input,
                TerminalInput::Mouse(MouseEvent { kind: MouseEventKind::Moved, .. })
            ) && (self.session.has_pending_mutations()
                || self.session.remote_tree_is_stale()
                || self.mux_recovery_generation.load(Ordering::Acquire) != 0
                || matches!(&input, TerminalInput::Mouse(mouse) if self.pointer_route_is_stale_for_mouse(mouse)))
                && !self.input_can_update_pending_mutation(&input) =>
            {
                return Ok(self.defer_input_with_sequence(
                    input,
                    input_sequence,
                    replay_context.as_ref().and_then(|context| context.pointer.clone()),
                    replay_context.as_ref().and_then(|context| context.admission.clone()),
                ));
            }
            event => event,
        };
        match event {
            AppEvent::HostInputReady => Ok(RenderAction::None),
            AppEvent::GraphicsWriterReady => Ok(self.apply_graphics_completion()),
            AppEvent::MuxTitlesReady => {
                Ok(if self.apply_mux_titles() { RenderAction::Paint } else { RenderAction::None })
            }
            AppEvent::StatusCommandsUpdated => {
                self.status_poke_pending.store(false, Ordering::Release);
                Ok(if self.config.status_bar.visible && !self.is_surface_only() {
                    RenderAction::Draw
                } else {
                    RenderAction::None
                })
            }
            AppEvent::MuxSubscriptionRecovered {
                recovery_generation,
                destination_generation,
                result,
            } => {
                if recovery_generation != self.mux_recovery_generation.load(Ordering::Acquire) {
                    return Ok(RenderAction::None);
                }
                match result {
                    Ok(tree) => {
                        let empty = tree.workspaces.is_empty();
                        self.replace_authoritative_tree(tree, destination_generation);
                        self.session.refresh_clients_background();
                        if empty {
                            if self.request_current_machine_session() {
                                return Ok(RenderAction::Draw);
                            }
                            self.quit = true;
                            return Ok(RenderAction::None);
                        }
                        self.status_message = Some(
                            localization::catalog().session.mux_subscription_recovered.to_string(),
                        );
                    }
                    Err(error) => {
                        if self
                            .mux_recovery_generation
                            .compare_exchange(
                                recovery_generation,
                                0,
                                Ordering::AcqRel,
                                Ordering::Acquire,
                            )
                            .is_err()
                        {
                            return Ok(RenderAction::None);
                        }
                        self.deferred_input.clear();
                        self.latest_semantic_destination_intent = None;
                        self.semantic_destination_outcomes.clear();
                        self.prefix_armed = false;
                        self.session.invalidate_remote_tree();
                        self.session.refresh_remote_tree_if_stale();
                        self.status_message = Some(
                            localization::catalog()
                                .session
                                .mux_subscription_recovery_failed(&error),
                        );
                    }
                }
                Ok(RenderAction::Draw)
            }
            AppEvent::MuxRecoveryComplete { recovery_generation } => {
                if recovery_generation != self.mux_recovery_generation.load(Ordering::Acquire) {
                    return Ok(RenderAction::None);
                }
                if self
                    .mux_recovery_generation
                    .compare_exchange(recovery_generation, 0, Ordering::AcqRel, Ordering::Acquire)
                    .is_err()
                {
                    return Ok(RenderAction::None);
                }
                Ok(RenderAction::Draw)
            }
            AppEvent::SidebarPluginUpdated { status, relaunch } => {
                self.apply_sidebar_plugin_status(status, relaunch);
                Ok(RenderAction::Draw)
            }
            #[cfg(test)]
            AppEvent::MachineUiUpdated(update) => Ok(self.apply_machine_ui_update(*update)),
            AppEvent::MachineUpdatedForGeneration { generation, update } => {
                if generation != self.machine_update_generation {
                    return Ok(RenderAction::None);
                }
                Ok(match *update {
                    MachineUpdate::Ui(update) => self.apply_machine_ui_update(*update),
                    MachineUpdate::DurableNotice(notice) => self.accept_durable_notice(notice),
                    MachineUpdate::ConnectionProgress { machine_id, latest } => {
                        self.apply_connection_progress(machine_id, latest)
                    }
                })
            }
            AppEvent::MachineControllerCompleted(completion) => {
                Ok(self.apply_machine_controller_completion(*completion))
            }
            AppEvent::Mux(MuxEvent::Empty) => {
                // A genuinely emptied workspace list and a dead event
                // transport both end the event stream with this event, but
                // only the former is a clean exit. The remote reader records
                // why it stopped; consult that BEFORE any machine-session
                // request so a machine or provider surface cannot swallow the
                // dead transport into a stuck reconnect (issue 11042). A
                // deliberate local disconnect records no reason. The one
                // machine response that outranks the error is a sleeping or
                // stopped machine, whose stream loss is the designed result
                // of pausing it.
                if let Some(reason) = self.session.transport_disconnect_reason() {
                    if self.present_machine_as_asleep_after_stream_loss() {
                        return Ok(RenderAction::Draw);
                    }
                    crate::client_log::error(
                        "session",
                        &format!("remote event transport lost: {reason}"),
                    );
                    anyhow::bail!(localization::catalog().runtime.session_transport_lost());
                }
                if self.request_current_machine_session() {
                    return Ok(RenderAction::Draw);
                }
                self.quit = true;
                Ok(RenderAction::None)
            }
            AppEvent::Mux(MuxEvent::SurfaceExited(id)) => {
                self.retire_surface_state(id);
                self.remove_surface_from_cached_tree(id);
                if self.surface_only == Some(id) {
                    self.quit = true;
                    return Ok(RenderAction::None);
                }
                Ok(RenderAction::Draw)
            }
            AppEvent::Mux(MuxEvent::SurfaceResized { surface, cols, rows, reservation_id }) => {
                self.session.confirm_surface_resize(surface, (cols, rows), reservation_id);
                // This acknowledges geometry already computed by the host-resize draw.
                // Re-running layout here creates an acknowledgement feedback loop while
                // the outer terminal is being dragged; only repaint terminal content.
                Ok(RenderAction::Paint)
            }
            AppEvent::Mux(MuxEvent::SurfaceResizeFailed {
                surface,
                cols,
                rows,
                error,
                retry_after_ms,
                reservation_id,
            }) => {
                if self.session.note_surface_resize_failure(
                    surface,
                    (cols, rows),
                    retry_after_ms,
                    reservation_id,
                ) {
                    self.status_message = Some(
                        localization::catalog()
                            .graphics
                            .browser_surface_resize_failed(surface, cols, rows, &error),
                    );
                    Ok(RenderAction::Draw)
                } else {
                    Ok(RenderAction::None)
                }
            }
            AppEvent::Mux(MuxEvent::Status(message)) => {
                self.status_message = Some(message);
                Ok(RenderAction::Draw)
            }
            AppEvent::Mux(MuxEvent::GraphicsStatus(status)) => {
                let messages = &localization::catalog().graphics;
                let message = match status {
                    GraphicsStatus::KittyImageBudgetWorkerStartFailed { error } => {
                        messages.kitty_image_budget_worker_start_failed(&error)
                    }
                    // Kitty quota updates are advisory: the mux disables graphics
                    // for an unresponsive surface and the terminal remains usable.
                    // Keep the structured event available to logs and remote
                    // observers, but do not replace user-facing command status
                    // with a diagnostic the user cannot act on.
                    GraphicsStatus::KittyImageBudgetUpdateFailed { retry_exhausted, summary } => {
                        crate::client_log::log(
                            "WARN",
                            "kitty-graphics",
                            &messages.kitty_image_budget_update_failed(retry_exhausted, &summary),
                        );
                        return Ok(RenderAction::None);
                    }
                    GraphicsStatus::CellPixelUpdateRetriesExhausted {
                        attempts,
                        remaining,
                        cell_pixels,
                    } => messages.cell_pixel_update_retries_exhausted(
                        attempts,
                        remaining,
                        cell_pixels,
                    ),
                };
                self.status_message = Some(message);
                Ok(RenderAction::Draw)
            }
            AppEvent::Mux(MuxEvent::ConfigReloadRequested) => {
                if self.presenting_owner_session() {
                    return Ok(RenderAction::None);
                }
                self.reload_config();
                Ok(RenderAction::Draw)
            }
            AppEvent::OwnerConfigReloadRequested => {
                let owner = self.owner_mux.clone();
                let request = owner.as_ref().map(|mux| mux.begin_config_reload_application());
                self.reload_config();
                if let (Some(owner), Some(request)) = (owner, request) {
                    crate::session::apply_config_to_local_owner(&owner, &self.config);
                    owner.complete_config_reload_application(request);
                }
                Ok(RenderAction::Draw)
            }
            AppEvent::Mux(MuxEvent::WindowTitleRequested(title)) => {
                self.write_window_title(&title)?;
                Ok(RenderAction::None)
            }
            AppEvent::Mux(MuxEvent::SurfaceOutput(id)) => {
                self.graphics_dirty_surfaces.insert(id);
                if self.sidebar_plugin_surface == Some(id) {
                    return Ok(RenderAction::Paint);
                }
                if self.frame_only_browser_update(id) {
                    Ok(RenderAction::Graphics)
                } else {
                    Ok(RenderAction::Paint)
                }
            }
            AppEvent::Mux(MuxEvent::PairingRequested(challenge)) => {
                let duplicate = self
                    .pairing_dialog
                    .as_ref()
                    .is_some_and(|dialog| dialog.challenge.id == challenge.id)
                    || self.pairing_queue.iter().any(|queued| queued.id == challenge.id);
                if !duplicate {
                    if self.pairing_dialog.is_none() {
                        self.cancel_pointer_interaction();
                        self.pairing_dialog = Some(PairingDialog::new(challenge));
                    } else {
                        self.pairing_queue.push_back(challenge);
                    }
                }
                Ok(RenderAction::Draw)
            }
            AppEvent::Mux(MuxEvent::PairingResolved { request }) => {
                self.pairing_queue.retain(|challenge| challenge.id != request);
                if self.pairing_dialog.as_ref().is_some_and(|dialog| dialog.challenge.id == request)
                {
                    self.cancel_pointer_interaction();
                    self.pairing_dialog = self.pairing_queue.pop_front().map(PairingDialog::new);
                }
                Ok(RenderAction::Draw)
            }
            AppEvent::Mux(
                MuxEvent::ClientAttached { .. }
                | MuxEvent::ClientChanged { .. }
                | MuxEvent::ClientDetached(_)
                | MuxEvent::ClientListInvalidated,
            ) => {
                self.session.refresh_clients_background();
                Ok(RenderAction::Draw)
            }
            AppEvent::Mux(_) => Ok(RenderAction::Draw),
            AppEvent::BrowserResizeFailed(failure) => {
                self.status_message =
                    Some(localization::catalog().graphics.browser_surface_resize_failed(
                        failure.surface_id,
                        failure.cols,
                        failure.rows,
                        &failure.error,
                    ));
                Ok(RenderAction::Draw)
            }
            AppEvent::PtyFailuresReady => Ok(self.apply_pty_failures()),
            AppEvent::PtyOperationFailed(failure) => Ok(self.apply_pty_operation_failure(failure)),
            AppEvent::SurfaceAttachSettled { outcome } => {
                match outcome {
                    SurfaceAttachOutcome::Attached => {
                        self.claim_active_terminal_geometry(false);
                    }
                    SurfaceAttachOutcome::Deferred => {}
                    SurfaceAttachOutcome::Retired { surface } => {
                        self.retire_surface_state(surface);
                        self.remove_surface_from_cached_tree(surface);
                        self.session.refresh_remote_tree_if_stale();
                    }
                    SurfaceAttachOutcome::Failed {
                        surface,
                        operation,
                        error,
                        reconnect_required,
                    } => {
                        if reconnect_required {
                            self.deferred_input
                                .retain(|input| input.admission.destination != Some(surface));
                            self.status_message = Some(
                                localization::catalog()
                                    .attach
                                    .surface_sync_unknown(surface, operation, &error),
                            );
                        } else {
                            self.status_message = Some(
                                localization::catalog()
                                    .attach
                                    .surface_sync_failed(surface, operation, &error),
                            );
                        }
                    }
                }
                if !self.session.has_pending_mutations()
                    && !self.session.remote_tree_is_stale()
                    && !self.deferred_input.is_empty()
                {
                    self.pointer_route_phase = PointerRoutePhase::DrawPending;
                }
                Ok(RenderAction::Draw)
            }
            AppEvent::ClearHistorySucceeded {
                surface,
                input_revision,
                selection_at_invocation,
                selection_generation,
            } => {
                let Some(handle) = self.session.surface(surface) else {
                    return Ok(RenderAction::None);
                };
                if self.input_revision == input_revision {
                    let _ = handle.scroll_to_bottom();
                }
                self.render_states.remove(&surface);
                if self.selection_generation == selection_generation
                    && self.selection == selection_at_invocation
                    && self.selection.is_some_and(|selection| selection.surface == surface)
                {
                    self.replace_selection(None);
                }
                Ok(RenderAction::Draw)
            }
            AppEvent::SessionMutationSettled { outcome, impact } => {
                self.session.settle_pending_mutation(impact);
                let (semantic_intent, outcome) = match outcome {
                    SessionMutationOutcome::SemanticIntent { intent, outcome } => {
                        (Some(intent), *outcome)
                    }
                    outcome => (None, outcome),
                };
                match outcome {
                    SessionMutationOutcome::SemanticIntent { .. } => {
                        unreachable!("semantic mutation outcomes are unwrapped once")
                    }
                    SessionMutationOutcome::Success { tree } => {
                        if let Some(tree) = tree {
                            self.replace_tree(tree);
                        }
                        // A visible remote surface can require a separate
                        // resize after attach when the peer lacks atomic
                        // initial sizing. Retry the deferred authority claim
                        // after that resize settles.
                        self.claim_active_terminal_geometry(false);
                        self.layout_refresh_retries_remaining = 0;
                    }
                    SessionMutationOutcome::AuthoritativeMutationSucceeded {
                        tree,
                        authoritative_generation,
                        destination_generation,
                        completion,
                    } => {
                        self.session.clear_surface_sync_failures();
                        self.replace_authoritative_tree(tree, destination_generation);
                        self.layout_refresh_retries_remaining = 0;
                        if let Some(completion) = completion {
                            self.pending_session_completions.push_back(completion);
                        }
                        self.apply_session_completions_through(authoritative_generation);
                    }
                    SessionMutationOutcome::IdentityRefreshSucceeded {
                        tree,
                        authoritative_generation,
                        destination_generation,
                        refresh_sequence,
                    } => {
                        if !self.accept_refresh_sequence(refresh_sequence) {
                            let applied_completion =
                                self.apply_session_completions_through(authoritative_generation);
                            return Ok(if applied_completion {
                                RenderAction::Draw
                            } else {
                                RenderAction::None
                            });
                        }
                        self.session.clear_surface_sync_failures();
                        self.session.reconcile_retired_surfaces(&tree);
                        self.replace_authoritative_tree(tree, destination_generation);
                        self.layout_refresh_retries_remaining = 0;
                        self.background_refresh_attempts = 0;
                        self.background_refresh_retry_at = None;
                        self.apply_session_completions_through(authoritative_generation);
                        self.complete_remote_tree_refresh(true);
                        self.session.reconcile_ambiguous_creations();
                    }
                    SessionMutationOutcome::CommittedTreeStale { error, completion } => {
                        if let Some(completion) = completion {
                            self.pending_session_completions.push_back(completion);
                        }
                        self.layout_refresh_retries_remaining = LAYOUT_REFRESH_RETRIES;
                        if let Some(error) = error {
                            self.status_message = Some(
                                localization::catalog()
                                    .sidebar
                                    .layout_refresh_failed
                                    .replace("{error}", error.as_str()),
                            );
                        }
                        self.session.invalidate_remote_tree();
                        self.session.refresh_remote_tree_if_stale();
                    }
                    SessionMutationOutcome::IdentityRefreshFailed { error, refresh_sequence } => {
                        if !self.accept_refresh_sequence(refresh_sequence) {
                            return Ok(RenderAction::None);
                        }
                        self.status_message = Some(
                            localization::catalog()
                                .sidebar
                                .layout_stale
                                .replace("{error}", error.as_str()),
                        );
                        let refresh_stale = self.layout_refresh_retries_remaining > 0;
                        if refresh_stale {
                            self.layout_refresh_retries_remaining -= 1;
                            self.session.invalidate_remote_tree();
                        }
                        self.complete_remote_tree_refresh(refresh_stale);
                        return Ok(RenderAction::Draw);
                    }
                    SessionMutationOutcome::SurfaceSyncFailed {
                        surface,
                        operation,
                        error,
                        reconnect_required,
                    } => {
                        if self
                            .pending_pointer_motion
                            .is_some_and(|pointer| pointer.destination == Some(surface))
                        {
                            self.pending_pointer_motion = None;
                        }
                        if reconnect_required {
                            self.deferred_input
                                .retain(|input| input.admission.destination != Some(surface));
                            self.status_message = Some(
                                localization::catalog()
                                    .attach
                                    .surface_sync_unknown(surface, operation, &error),
                            );
                        } else {
                            self.status_message = Some(
                                localization::catalog()
                                    .attach
                                    .surface_sync_failed(surface, operation, &error),
                            );
                        }
                    }
                    SessionMutationOutcome::SurfaceSizeReleased { surface } => {
                        let expected = self.pending_size_releases.remove(&surface);
                        if expected {
                            self.visible_size_surfaces.remove(&surface);
                        } else if self.visible_size_surfaces.remove(&surface) {
                            // A release already in flight can settle after the
                            // pane becomes visible. Force the next draw to
                            // reclaim its lease even if geometry is unchanged.
                            self.session.invalidate_surface_size_report(surface);
                        }
                    }
                    SessionMutationOutcome::SurfaceSizeReleaseFailed { surface, error } => {
                        if self.pending_size_releases.remove(&surface) {
                            self.session.invalidate_surface_size_report(surface);
                            if self.pane_areas.iter().any(|area| area.surface == surface) {
                                self.visible_size_surfaces.remove(&surface);
                            }
                            self.status_message = Some(
                                localization::catalog()
                                    .layout
                                    .surface_size_release_failed(surface, &error),
                            );
                        }
                    }
                    SessionMutationOutcome::SurfaceSizeReleaseCanceled { surface } => {
                        self.pending_size_releases.remove(&surface);
                    }
                    SessionMutationOutcome::ClientSizingChanged => {
                        self.session.refresh_clients_background();
                    }
                    SessionMutationOutcome::CreationResponseAmbiguous(error) => {
                        crate::client_log::stderr_log!(
                            "session",
                            "cmux-tui: session creation response was ambiguous: {error}"
                        );
                        self.status_message =
                            Some(localization::catalog().session.creation_reconciling.to_string());
                        self.layout_refresh_retries_remaining = LAYOUT_REFRESH_RETRIES;
                        self.session.invalidate_remote_tree();
                        self.session.refresh_remote_tree_if_stale();
                        return Ok(RenderAction::Draw);
                    }
                    SessionMutationOutcome::MutationTimedOut(error) => {
                        crate::client_log::stderr_log!(
                            "session",
                            "cmux-tui: session operation timed out: {error}"
                        );
                        if let Some(intent) = semantic_intent {
                            // A peer without creation receipts cannot identify
                            // which surface, if any, a timed-out creation made.
                            // Fail only that route so dependent input is never
                            // guessed onto whichever surface became active.
                            self.mark_semantic_destination_failed(intent);
                        }
                        self.status_message =
                            Some(localization::catalog().session.operation_reconciling.to_string());
                        self.layout_refresh_retries_remaining = LAYOUT_REFRESH_RETRIES;
                        self.session.invalidate_remote_tree();
                        self.session.refresh_remote_tree_if_stale();
                        return Ok(RenderAction::Draw);
                    }
                    SessionMutationOutcome::Failed(error) => {
                        crate::client_log::stderr_log!(
                            "session",
                            "cmux-tui: session operation failed: {error}"
                        );
                        if let Some(intent) = semantic_intent {
                            self.mark_semantic_destination_failed(intent);
                            self.status_message =
                                Some(localization::catalog().session.operation_failed.to_string());
                            return Ok(RenderAction::Draw);
                        }
                        self.deferred_input.clear();
                        self.prefix_armed = false;
                        self.pending_session_completions.clear();
                        self.status_message =
                            Some(localization::catalog().session.operation_failed.to_string());
                        return Ok(RenderAction::Draw);
                    }
                    SessionMutationOutcome::Canceled => {
                        if let Some(intent) = semantic_intent {
                            self.mark_semantic_destination_failed(intent);
                            self.status_message = Some(
                                localization::catalog().session.operation_canceled.to_string(),
                            );
                            return Ok(RenderAction::Draw);
                        }
                        if self.session.has_pending_mutations() {
                            self.session.defer_cancellation();
                            return Ok(RenderAction::None);
                        }
                        self.apply_session_cancellation();
                        return Ok(RenderAction::Draw);
                    }
                }
                self.session.refresh_remote_tree_if_stale();
                if self.session.has_pending_mutations() || self.session.remote_tree_is_stale() {
                    return Ok(RenderAction::Draw);
                }
                Ok(RenderAction::Draw)
            }
            AppEvent::RemoteTreeUpdated { refresh_sequence, destination_generation, result } => {
                if !self.accept_refresh_sequence(refresh_sequence) {
                    return Ok(RenderAction::None);
                }
                let refreshed = match result {
                    Ok(tree) => {
                        self.session.reconcile_retired_surfaces(&tree);
                        self.replace_authoritative_tree(tree, destination_generation);
                        self.layout_refresh_retries_remaining = 0;
                        self.background_refresh_attempts = 0;
                        self.background_refresh_retry_at = None;
                        true
                    }
                    Err(error) => {
                        let retrying = self.schedule_background_refresh_retry();
                        let template = if retrying {
                            localization::catalog().sidebar.refresh_remote_tree_retrying
                        } else {
                            localization::catalog().sidebar.refresh_remote_tree_stopped
                        };
                        self.status_message = Some(
                            template
                                .replace("{attempts}", &BACKGROUND_REFRESH_RETRIES.to_string())
                                .replace("{error}", error.as_str()),
                        );
                        let _ = self.session.take_background_refresh_dirty();
                        false
                    }
                };
                if refreshed {
                    self.complete_remote_tree_refresh(true);
                    self.session.reconcile_ambiguous_creations();
                }
                Ok(RenderAction::Draw)
            }
            AppEvent::ClientsUpdated { generation, result } => {
                if generation != self.session.client_refresh_generation() {
                    return Ok(RenderAction::None);
                }
                match result {
                    Ok(clients) => self.replace_clients(clients),
                    Err(error) => {
                        self.status_message = Some(
                            localization::catalog()
                                .sidebar
                                .clients_list_failed
                                .replace("{error}", error.as_str()),
                        );
                    }
                }
                Ok(RenderAction::Draw)
            }
            AppEvent::NormalizedInput(input) => {
                let admission =
                    replay_context.as_ref().and_then(|context| context.admission.as_ref());
                let semantic_result = admission.and_then(|value| value.semantic_result);
                let semantic_destination = self.semantic_destination_for_input(&input, admission);
                let action_destination = if matches!(&input, TerminalInput::FrontendAction { .. }) {
                    semantic_destination.or_else(|| admission.and_then(|value| value.destination))
                } else {
                    semantic_destination
                };
                let action_fallback_destination = self
                    .input_creates_session_destination(&input)
                    .then(|| admission.and_then(|value| value.destination))
                    .flatten()
                    .filter(|fallback| Some(*fallback) != action_destination);
                self.dispatch_terminal_input(
                    input,
                    input_sequence,
                    terminal_pointer_admission,
                    semantic_result,
                    action_destination,
                    action_fallback_destination,
                )
            }
            AppEvent::HostInputFailed(error) => {
                anyhow::bail!(localization::catalog().runtime.host_input_failed(&error))
            }
            AppEvent::Input(_) => unreachable!("raw input is normalized before dispatch"),
            AppEvent::SessionScoped { .. } => {
                unreachable!("session-scoped events are unwrapped before dispatch")
            }
        }
    }

    fn dispatch_terminal_input(
        &mut self,
        input: TerminalInput,
        input_sequence: Option<u64>,
        terminal_pointer_admission: Option<TerminalPointerAdmission>,
        semantic_result: Option<u64>,
        action_destination: Option<SurfaceId>,
        action_fallback_destination: Option<SurfaceId>,
    ) -> anyhow::Result<RenderAction> {
        let semantic_result =
            if semantic_result.is_none() && self.input_creates_session_destination(&input) {
                self.clear_finished_semantic_destinations();
                let intent = self.allocate_semantic_destination_intent();
                self.latest_semantic_destination_intent = Some(intent);
                Some(intent)
            } else {
                semantic_result
            };
        match input {
            TerminalInput::Keyboard(key) => {
                let dismissed = !key.is_release() && self.dismiss_painted_durable_notice();
                let action = self.handle_direct_keyboard_to(key, action_destination)?;
                Ok(if dismissed { action.merge(RenderAction::Draw) } else { action })
            }
            TerminalInput::FrontendAction { action, prefix } => {
                let dismissed = self.dismiss_painted_durable_notice();
                let action = self.run_resolved_action_with_semantic_intent(
                    action,
                    prefix,
                    semantic_result,
                    action_destination,
                    action_fallback_destination,
                )?;
                Ok(if dismissed { action.merge(RenderAction::Draw) } else { action })
            }
            TerminalInput::ClearHistoryKey(input) => {
                let dismissed = self.dismiss_painted_durable_notice();
                let action = self.run_clear_history_shortcut_to(input, action_destination);
                Ok(if dismissed { action.merge(RenderAction::Draw) } else { action })
            }
            TerminalInput::Mouse(mouse) => {
                if matches!(mouse.kind, MouseEventKind::Down(_))
                    && self.durable_notice_banner_row() == Some(mouse.row)
                    && self.dismiss_painted_durable_notice()
                {
                    return Ok(RenderAction::Draw);
                }
                let dismissed = matches!(
                    mouse.kind,
                    MouseEventKind::Down(_)
                        | MouseEventKind::ScrollUp
                        | MouseEventKind::ScrollDown
                        | MouseEventKind::ScrollLeft
                        | MouseEventKind::ScrollRight
                ) && self.dismiss_painted_durable_notice();
                let action = self.handle_mouse_with_sequence(
                    mouse,
                    input_sequence,
                    terminal_pointer_admission,
                )?;
                Ok(if dismissed { action.merge(RenderAction::Draw) } else { action })
            }
            TerminalInput::Paste(text) => {
                let dismissed = self.dismiss_painted_durable_notice();
                let action = self.handle_paste_to(text, action_destination)?;
                Ok(if dismissed { action.merge(RenderAction::Draw) } else { action })
            }
            TerminalInput::FocusGained => {
                self.advance_pointer_focus_generation();
                self.reassert_scoped_host_terminal_state();
                self.reassert_visible_surface_sizes();
                Ok(RenderAction::Draw)
            }
            TerminalInput::FocusLost => {
                let action = if self.cancel_pointer_interaction() {
                    RenderAction::Draw
                } else {
                    RenderAction::None
                };
                self.advance_pointer_focus_generation();
                Ok(action)
            }
            TerminalInput::Resize => {
                self.reassert_scoped_host_terminal_state();
                if self.graphics_supported {
                    self.graphics_host_scene_reset_pending = true;
                }
                self.refresh_cell_pixels();
                self.render_states.clear();
                self.sidebar_plugin_surface = None;
                Ok(RenderAction::Draw)
            }
        }
    }

    fn handle_paste_to(
        &mut self,
        text: String,
        destination: Option<SurfaceId>,
    ) -> anyhow::Result<RenderAction> {
        let action = self.handle_paste_to_inner(text, destination)?;
        Ok(action.merge(self.painted_status_message_action()))
    }

    fn handle_paste_to_inner(
        &mut self,
        text: String,
        destination: Option<SurfaceId>,
    ) -> anyhow::Result<RenderAction> {
        // A context menu acts on the resources visible when it opened. Keep a
        // status message alive while the menu owns input so status actions can
        // still validate and copy that exact message.
        if self.menu.is_none() && !self.status_message_hovered() {
            self.status_message = None;
        }
        if self.pairing_dialog.is_some() || self.shortcut_help.is_some() {
            Ok(RenderAction::Draw)
        } else if let Some(prompt) = self.prompt.as_mut() {
            prompt.input.insert_str(&text);
            Ok(RenderAction::Draw)
        } else if let Some(state) = self.omnibar.as_mut() {
            clear_omnibar_selection(state);
            state.input.insert_str(&text);
            Ok(RenderAction::Draw)
        } else if let Some(menu) = self.menu.as_mut() {
            menu.insert_search_text(&text);
            Ok(RenderAction::Draw)
        } else if self.machine_sidebar_focused() || self.tabs_sidebar_focused() {
            Ok(RenderAction::Draw)
        } else if self.workspace_sidebar_focused() {
            if self.config.sidebar.plugin.is_some() {
                self.paste_sidebar(&text);
                Ok(if self.status_message.is_some() {
                    RenderAction::Draw
                } else {
                    RenderAction::None
                })
            } else {
                if self.sidebar_view == SidebarView::Files {
                    self.sidebar_files.insert_filter_text(&text);
                }
                Ok(RenderAction::Draw)
            }
        } else {
            if let Some(surface) = destination {
                self.paste_to_surface(&text, surface);
            } else {
                self.paste(&text);
            }
            Ok(if self.status_message.is_some() { RenderAction::Draw } else { RenderAction::None })
        }
    }

    fn input_can_update_pending_mutation(&self, input: &TerminalInput) -> bool {
        if matches!(
            input,
            TerminalInput::Keyboard(_)
                | TerminalInput::FrontendAction { .. }
                | TerminalInput::ClearHistoryKey(_)
        ) && (self.pairing_dialog.is_some()
            || self.shortcut_help.is_some()
            || self.prompt.is_some()
            || self.menu.is_some()
            || self.omnibar.is_some()
            || self.machine_sidebar_focused()
            || self.workspace_sidebar_focused() && self.config.sidebar.plugin.is_none())
        {
            return true;
        }
        match input {
            TerminalInput::FrontendAction { action, .. }
                if action_is_frontend_local(*action) || *action == Action::Detach =>
            {
                return true;
            }
            _ => {}
        }
        if let TerminalInput::Mouse(mouse) = input
            && self.pointer_has_capture(mouse.kind)
        {
            // Once a press has been admitted, its drag and release belong to
            // that frontend-local capture. Let the gesture finish against its
            // stable target even while a backend mutation rebuilds routing.
            return true;
        }
        matches!(
            (input, &self.drag),
            (
                TerminalInput::Mouse(MouseEvent {
                    kind: MouseEventKind::Drag(MouseButton::Left)
                        | MouseEventKind::Up(MouseButton::Left),
                    ..
                }),
                Some(Drag::HorizontalScrollbar { .. })
            ) | (
                TerminalInput::Mouse(MouseEvent {
                    kind: MouseEventKind::Drag(MouseButton::Left)
                        | MouseEventKind::Up(MouseButton::Left),
                    ..
                }),
                Some(Drag::ResizeSplit { .. })
            ) | (
                TerminalInput::Mouse(MouseEvent {
                    kind: MouseEventKind::Drag(MouseButton::Left)
                        | MouseEventKind::Up(MouseButton::Left),
                    ..
                }),
                Some(Drag::Select { .. })
            ) | (
                TerminalInput::Mouse(MouseEvent {
                    kind: MouseEventKind::Drag(MouseButton::Left)
                        | MouseEventKind::Up(MouseButton::Left),
                    ..
                }),
                Some(Drag::Browser { .. })
            ) | (
                TerminalInput::Mouse(MouseEvent {
                    kind: MouseEventKind::Drag(_) | MouseEventKind::Up(_),
                    ..
                }),
                Some(Drag::PtyMouse { .. })
            ) | (
                TerminalInput::Mouse(MouseEvent {
                    kind: MouseEventKind::Up(MouseButton::Left),
                    ..
                }),
                Some(Drag::TabArm { .. })
            ) | (
                TerminalInput::Mouse(MouseEvent {
                    kind: MouseEventKind::Drag(MouseButton::Left)
                        | MouseEventKind::Up(MouseButton::Left),
                    ..
                }),
                Some(Drag::WorkspaceArm { .. } | Drag::Workspace { .. })
            )
        )
    }

    fn input_can_overtake_deferred(&self, input: &TerminalInput) -> bool {
        if matches!(input, TerminalInput::FrontendAction { action: Action::Detach, .. }) {
            return true;
        }
        if let TerminalInput::Mouse(mouse) = input
            && self.pointer_has_capture(mouse.kind)
        {
            return true;
        }
        matches!(
            (input, &self.drag),
            (
                TerminalInput::Mouse(MouseEvent {
                    kind: MouseEventKind::Drag(_) | MouseEventKind::Up(_),
                    ..
                }),
                Some(
                    Drag::HorizontalScrollbar { .. }
                        | Drag::ResizeSplit { .. }
                        | Drag::Select { .. }
                        | Drag::Browser { .. }
                        | Drag::PtyMouse { .. }
                        | Drag::WorkspaceArm { .. }
                        | Drag::TabArm { .. }
                )
            )
        )
    }

    /// Prefix syntax is resolved exactly once at host ingress. Frontend-owned
    /// suffixes can therefore survive a backend refresh without consulting
    /// mutable parser state during replay.
    fn input_is_client_owned(&self, input: &TerminalInput) -> bool {
        matches!(
            input,
            TerminalInput::FrontendAction { action, .. } if action_is_frontend_local(*action)
        )
    }

    fn input_accepts_semantic_destination(input: &TerminalInput) -> bool {
        matches!(
            input,
            TerminalInput::Keyboard(_)
                | TerminalInput::FrontendAction { .. }
                | TerminalInput::ClearHistoryKey(_)
                | TerminalInput::Paste(_)
        )
    }

    fn semantic_destination_for_input(
        &self,
        input: &TerminalInput,
        admission: Option<&DeferredInputAdmission>,
    ) -> Option<SurfaceId> {
        if !Self::input_accepts_semantic_destination(input) {
            return None;
        }
        let intent = admission?.semantic_dependency?;
        match self.semantic_destination_outcomes.get(&intent) {
            Some(SemanticDestinationOutcome::Resolved(surface)) => Some(*surface),
            Some(SemanticDestinationOutcome::Pending | SemanticDestinationOutcome::Failed)
            | None => None,
        }
    }

    fn input_creates_session_destination(&self, input: &TerminalInput) -> bool {
        let TerminalInput::FrontendAction { action, .. } = input else { return false };
        action_creates_destination(*action)
            && (*action != Action::NewWorkspace
                || self.workspace_creation_policy() == Some(WorkspaceCreationPolicy::SessionOwned))
    }

    fn allocate_semantic_destination_intent(&mut self) -> u64 {
        self.next_semantic_destination_intent =
            self.next_semantic_destination_intent.wrapping_add(1).max(1);
        let intent = self.next_semantic_destination_intent;
        let previous =
            self.semantic_destination_outcomes.insert(intent, SemanticDestinationOutcome::Pending);
        debug_assert!(previous.is_none(), "live semantic destination intent reused");
        intent
    }

    fn advance_pointer_focus_generation(&mut self) {
        self.pointer_focus_generation = self.pointer_focus_generation.wrapping_add(1);
        self.deferred_input.retain(|input| !matches!(&input.event, TerminalInput::Mouse(_)));
        self.pending_pointer_motion = None;
        self.active_pointer_buttons.clear();
        self.ignored_pty_mouse_buttons.clear();
    }

    #[cfg(test)]
    fn defer_input(&mut self, input: impl Into<TerminalInput>) -> RenderAction {
        self.defer_input_with_sequence(input.into(), None, None, None)
    }

    fn defer_input_with_sequence(
        &mut self,
        input: TerminalInput,
        replay_sequence: Option<u64>,
        replay_pointer: Option<DeferredPointerInput>,
        replay_admission: Option<DeferredInputAdmission>,
    ) -> RenderAction {
        // Admission belongs to the input's arrival, not to whichever pane is
        // focused when asynchronous mutations later replay it. Preserve the
        // complete original admission whenever an input must wait again.
        let admission = if let Some(admission) = replay_admission {
            admission
        } else {
            self.clear_finished_semantic_destinations();
            let destination_started = self.session.destination_mutation_started();
            let client_owned = self.input_is_client_owned(&input);
            let semantic_dependency =
                if client_owned { None } else { self.latest_semantic_destination_intent };
            let semantic_result = self
                .input_creates_session_destination(&input)
                .then(|| self.allocate_semantic_destination_intent());
            if let Some(intent) = semantic_result {
                self.latest_semantic_destination_intent = Some(intent);
            }
            DeferredInputAdmission {
                destination: self.input_destination(&input),
                destination_intent: (destination_started > self.applied_destination_generation)
                    .then_some(destination_started),
                semantic_dependency,
                semantic_result,
                sidebar_focus_intent: self.sidebar_focus_pending && input.is_keyboard_or_paste(),
                pairing_request: replay_sequence
                    .is_none()
                    .then(|| self.pairing_dialog.as_ref().map(|dialog| dialog.challenge.id))
                    .flatten(),
                client_owned,
            }
        };
        let pointer = if replay_sequence.is_some() {
            replay_pointer
        } else if let TerminalInput::Mouse(mouse) = &input {
            Some(DeferredPointerInput {
                focus_generation: self.pointer_focus_generation,
                pointer_map_generation: self.rendered_pointer_frame.pointer_map_generation,
                route: Self::mouse_requires_rendered_route(mouse.kind)
                    .then(|| self.rendered_pointer_route_for_mouse(mouse)),
            })
        } else {
            None
        };
        let sequence = replay_sequence.unwrap_or_else(|| self.next_deferred_input_sequence());
        let replace_motion = replay_sequence.is_none()
            && match (&input, self.deferred_input.back()) {
                (
                    TerminalInput::Mouse(MouseEvent { kind: MouseEventKind::Moved, .. }),
                    Some(DeferredInput {
                        event: TerminalInput::Mouse(MouseEvent { kind: MouseEventKind::Moved, .. }),
                        admission: previous_admission,
                        pointer: previous_pointer,
                        ..
                    }),
                ) => {
                    *previous_admission == admission
                        && previous_pointer.as_ref().map(|pointer| pointer.focus_generation)
                            == pointer.as_ref().map(|pointer| pointer.focus_generation)
                }
                (
                    TerminalInput::Mouse(MouseEvent { kind: MouseEventKind::Drag(button), .. }),
                    Some(DeferredInput {
                        event:
                            TerminalInput::Mouse(MouseEvent {
                                kind: MouseEventKind::Drag(previous),
                                ..
                            }),
                        admission: previous_admission,
                        pointer: previous_pointer,
                        ..
                    }),
                ) => {
                    button == previous
                        && *previous_admission == admission
                        && previous_pointer.as_ref().map(|pointer| pointer.focus_generation)
                            == pointer.as_ref().map(|pointer| pointer.focus_generation)
                }
                _ => false,
            };
        if replace_motion {
            self.deferred_input.replace_back(DeferredInput {
                event: input,
                admission,
                pointer,
                sequence,
            });
            return RenderAction::None;
        }
        let input_bytes = input.retained_bytes();
        let prioritize_release =
            matches!(&input, TerminalInput::Mouse(MouseEvent { kind: MouseEventKind::Up(_), .. }));
        while self.deferred_input.retained_bytes().saturating_add(input_bytes)
            > MAX_DEFERRED_INPUT_BYTES
        {
            if !prioritize_release {
                self.status_message =
                    Some(localization::catalog().terminal.deferred_input_queue_full.to_string());
                return RenderAction::Draw;
            }
            let Some(removed) = self.deferred_input.pop_front() else { break };
            self.retire_deferred_semantic_result(&removed);
        }
        let input = DeferredInput { event: input, admission, pointer, sequence };
        if replay_sequence.is_some() {
            // A replayed input keeps its original chronological position.
            let index = self
                .deferred_input
                .iter()
                .position(|queued| queued.sequence > sequence)
                .unwrap_or(self.deferred_input.len());
            self.deferred_input.insert(index, input);
        } else {
            self.deferred_input.push_back(input);
        }
        RenderAction::None
    }

    fn next_deferred_input_sequence(&mut self) -> u64 {
        self.deferred_input_sequence = self.deferred_input_sequence.saturating_add(1);
        self.deferred_input_sequence
    }

    #[cfg(test)]
    fn retain_pointer_motion(&mut self, event: MouseEvent) {
        self.retain_pointer_motion_with_sequence(event, None, None);
    }

    fn retain_pointer_motion_with_sequence(
        &mut self,
        event: MouseEvent,
        replay_sequence: Option<u64>,
        replay_focus_generation: Option<u64>,
    ) {
        let sequence = replay_sequence.unwrap_or_else(|| self.next_deferred_input_sequence());
        let focus_generation = replay_focus_generation.unwrap_or(self.pointer_focus_generation);
        let destination = self.input_destination(&TerminalInput::Mouse(event));
        let retained = PendingPointerMotion { event, destination, focus_generation, sequence };
        let Some(pending) = self.pending_pointer_motion else {
            self.pending_pointer_motion = Some(retained);
            return;
        };
        if pending.sequence == sequence {
            self.pending_pointer_motion = Some(retained);
            return;
        }
        let (earlier, later) = if pending.sequence < sequence {
            (pending.sequence, sequence)
        } else {
            (sequence, pending.sequence)
        };
        let has_discrete_barrier = self.deferred_input.iter().any(|input| {
            input.sequence > earlier
                && input.sequence < later
                && !matches!(
                    input.event,
                    TerminalInput::Mouse(MouseEvent { kind: MouseEventKind::Moved, .. })
                )
        });
        if !has_discrete_barrier {
            if pending.sequence < sequence {
                self.pending_pointer_motion = Some(retained);
            }
            return;
        }
        if pending.sequence < sequence {
            if self.spill_retained_pointer_motion(pending) {
                self.pending_pointer_motion = Some(retained);
            }
        } else if !self.spill_retained_pointer_motion(retained) {
            // Under queue pressure preserve the earlier motion before its
            // discrete barrier and discard the newer passive sample.
            self.pending_pointer_motion = Some(retained);
        }
    }

    fn spill_retained_pointer_motion(&mut self, pending: PendingPointerMotion) -> bool {
        if self.deferred_input.len() >= DEFERRED_INPUT_CAPACITY
            || self.deferred_input.retained_bytes().saturating_add(DEFERRED_INPUT_FIXED_BYTES)
                > MAX_DEFERRED_INPUT_BYTES
        {
            return false;
        }
        let input = DeferredInput {
            event: TerminalInput::Mouse(pending.event),
            admission: DeferredInputAdmission {
                destination: pending.destination,
                destination_intent: None,
                semantic_dependency: None,
                semantic_result: None,
                sidebar_focus_intent: false,
                pairing_request: None,
                client_owned: false,
            },
            pointer: Some(DeferredPointerInput {
                focus_generation: pending.focus_generation,
                pointer_map_generation: self.rendered_pointer_frame.pointer_map_generation,
                route: None,
            }),
            sequence: pending.sequence,
        };
        let index = self
            .deferred_input
            .iter()
            .position(|queued| queued.sequence > pending.sequence)
            .unwrap_or(self.deferred_input.len());
        self.deferred_input.insert(index, input);
        true
    }

    fn mouse_requires_rendered_route(kind: MouseEventKind) -> bool {
        kind != MouseEventKind::Moved
    }

    fn mouse_opens_cmux_context_menu(mouse: &MouseEvent) -> bool {
        mouse.kind == MouseEventKind::Down(MouseButton::Right)
            && (mouse.modifiers.contains(KeyModifiers::SHIFT)
                || mouse.modifiers.contains(KeyModifiers::ALT))
    }

    fn rendered_pointer_route_for_mouse(&self, mouse: &MouseEvent) -> PointerRouteIdentity {
        let route = self.rendered_pointer_frame.route_for_mouse(mouse);
        if Self::mouse_opens_cmux_context_menu(mouse) {
            // The menu press never enters the pane's application; async output
            // must not change its recorded route.
            route.normalized_for_cmux_menu()
        } else {
            route
        }
    }

    fn pointer_has_capture(&self, kind: MouseEventKind) -> bool {
        match kind {
            MouseEventKind::Drag(button) | MouseEventKind::Up(button) => {
                self.active_pointer_buttons.contains(&button)
            }
            _ => false,
        }
    }

    fn fresh_pointer_motion_must_follow_deferred(&self, input_sequence: Option<u64>) -> bool {
        input_sequence.is_none()
            && self
                .deferred_input
                .iter()
                .any(|input| matches!(input.event, TerminalInput::Mouse(_)))
    }

    fn fresh_input_must_follow_deferred(
        &self,
        input: &TerminalInput,
        input_sequence: Option<u64>,
    ) -> bool {
        if input_sequence.is_some()
            || self.deferred_input.is_empty() && self.pending_pointer_motion.is_none()
        {
            return false;
        }
        match input {
            TerminalInput::Keyboard(_)
            | TerminalInput::FrontendAction { .. }
            | TerminalInput::ClearHistoryKey(_)
            | TerminalInput::Paste(_) => true,
            TerminalInput::Mouse(MouseEvent { kind: MouseEventKind::Moved, .. }) => false,
            TerminalInput::Mouse(_) => self.active_pointer_buttons.is_empty(),
            _ => false,
        }
    }

    fn terminal_pointer_admission_for_route(
        &self,
        rendered_route: &PointerRouteIdentity,
        mouse: &MouseEvent,
        missing_surface: Option<SurfaceId>,
    ) -> TerminalPointerAdmissionResult {
        if Self::mouse_opens_cmux_context_menu(mouse) {
            // The menu is owned by cmux rather than the terminal
            // application: the press never forwards bytes, so encoder
            // semantics and content-generation admission cannot gate it.
            // Geometry barriers (pending paints, pointer-map mutations)
            // still defer it through the route staleness checks.
            return TerminalPointerAdmissionResult::NotTerminal;
        }
        let Some((surface, input_rect, expected_snapshot)) =
            rendered_route.terminal_pointer_snapshot()
        else {
            return TerminalPointerAdmissionResult::NotTerminal;
        };
        let Some(expected_snapshot) = expected_snapshot else {
            return if missing_surface == Some(surface) {
                TerminalPointerAdmissionResult::NotTerminal
            } else {
                TerminalPointerAdmissionResult::Rejected
            };
        };
        if missing_surface == Some(surface) {
            return TerminalPointerAdmissionResult::Ready(TerminalPointerAdmission {
                surface,
                semantics: expected_snapshot.semantics,
                encoding: TerminalPointerEncoding::None,
            });
        }
        let Some(surface_handle) = self.session.surface(surface) else {
            return TerminalPointerAdmissionResult::Rejected;
        };

        let cell_width = u32::from(self.cell_pixels.0.max(1));
        let cell_height = u32::from(self.cell_pixels.1.max(1));
        let position = (
            (mouse.column as f32 - input_rect.x as f32 + 0.5) * cell_width as f32,
            (mouse.row as f32 - input_rect.y as f32 + 0.5) * cell_height as f32,
        );
        let screen_size = (
            u32::from(input_rect.width).saturating_mul(cell_width),
            u32::from(input_rect.height).saturating_mul(cell_height),
        );
        let input = |action, button, any_button_pressed| MouseInput {
            action,
            button,
            mods: Self::ghostty_mouse_mods(mouse.modifiers),
            position,
            screen_size,
            cell_size: (cell_width, cell_height),
            any_button_pressed,
        };
        let bypasses_terminal_mouse = mouse.modifiers.contains(KeyModifiers::SHIFT)
            || matches!(
                (mouse.kind, self.drag.as_ref()),
                (MouseEventKind::Down(_), Some(Drag::PtyMouse { .. }))
            );
        let guarded = if bypasses_terminal_mouse {
            None
        } else {
            match mouse.kind {
                MouseEventKind::Down(button) => {
                    let press =
                        input(MouseAction::Press, Some(Self::ghostty_mouse_button(button)), true);
                    let release = MouseInput {
                        action: MouseAction::Release,
                        any_button_pressed: false,
                        ..press
                    };
                    let mut press_output = PtyInputBytes::new();
                    let mut release_output = PtyInputBytes::new();
                    let encoded = surface_handle.encode_mouse_press_pair_if_snapshot(
                        expected_snapshot,
                        press,
                        release,
                        &mut press_output,
                        &mut release_output,
                    );
                    encoded.map(|encoded| {
                        (
                            encoded,
                            TerminalPointerEncoding::PressPair {
                                press: press_output,
                                release: release_output,
                            },
                        )
                    })
                }
                MouseEventKind::ScrollUp
                | MouseEventKind::ScrollDown
                | MouseEventKind::ScrollLeft
                | MouseEventKind::ScrollRight
                | MouseEventKind::Moved => {
                    let (action, button) = match mouse.kind {
                        MouseEventKind::ScrollUp => {
                            (MouseAction::Press, Some(GhosttyMouseButton::WheelUp))
                        }
                        MouseEventKind::ScrollDown => {
                            (MouseAction::Press, Some(GhosttyMouseButton::WheelDown))
                        }
                        MouseEventKind::ScrollLeft => {
                            (MouseAction::Press, Some(GhosttyMouseButton::WheelLeft))
                        }
                        MouseEventKind::ScrollRight => {
                            (MouseAction::Press, Some(GhosttyMouseButton::WheelRight))
                        }
                        MouseEventKind::Moved => (MouseAction::Motion, None),
                        _ => unreachable!("guarded by the outer pointer-kind match"),
                    };
                    let mut output = PtyInputBytes::new();
                    let encoded = surface_handle.encode_mouse_if_snapshot(
                        expected_snapshot,
                        input(action, button, false),
                        &mut output,
                    );
                    encoded.map(|encoded| (encoded, TerminalPointerEncoding::Single(output)))
                }
                MouseEventKind::Drag(_) | MouseEventKind::Up(_) => None,
            }
        };
        let encoding = match guarded {
            Some((GuardedMouseEncode::Encoded(Ok(())), encoding)) => encoding,
            Some((GuardedMouseEncode::Contended, _)) => {
                return TerminalPointerAdmissionResult::Contended;
            }
            Some((GuardedMouseEncode::Encoded(Err(_)), _))
            | Some((GuardedMouseEncode::SemanticsChanged, _))
            | Some((GuardedMouseEncode::ContentChanged, _)) => {
                return TerminalPointerAdmissionResult::Rejected;
            }
            None => match surface_handle.try_pointer_snapshot() {
                Some(PointerSnapshotProbe::Contended) => {
                    return TerminalPointerAdmissionResult::Contended;
                }
                Some(PointerSnapshotProbe::Ready(live)) if live == expected_snapshot => {
                    TerminalPointerEncoding::None
                }
                Some(PointerSnapshotProbe::Ready(_)) | None => {
                    return TerminalPointerAdmissionResult::Rejected;
                }
            },
        };
        TerminalPointerAdmissionResult::Ready(TerminalPointerAdmission {
            surface,
            semantics: expected_snapshot.semantics,
            encoding,
        })
    }

    fn input_destination(&self, input: &TerminalInput) -> Option<SurfaceId> {
        match input {
            TerminalInput::Keyboard(_)
            | TerminalInput::ClearHistoryKey(_)
            | TerminalInput::Paste(_)
                if self.prompt.is_none()
                    && self.shortcut_help.is_none()
                    && self.omnibar.is_none()
                    && self.focus == FocusTarget::Pane =>
            {
                self.active_surface()
            }
            TerminalInput::FrontendAction { action, .. }
                if !action_is_frontend_local(*action) && self.focus == FocusTarget::Pane =>
            {
                self.active_surface()
            }
            TerminalInput::Mouse(mouse) => self
                .pane_area_at(mouse.column, mouse.row)
                .filter(|area| area.content.contains(mouse.column, mouse.row))
                .map(|area| area.surface),
            _ => None,
        }
    }

    fn active_pane(&self) -> Option<PaneId> {
        self.tree.active_screen().map(|screen| screen.active_pane)
    }

    fn pane_for_surface(&self, surface: SurfaceId) -> Option<PaneId> {
        let [workspace, screen, pane, _] = self.tab_locations.get(&surface).copied()?;
        self.tree
            .workspaces
            .get(workspace)?
            .screens
            .get(screen)?
            .panes
            .get(pane)
            .map(|pane| pane.id)
    }

    fn active_surface(&self) -> Option<SurfaceId> {
        self.tree.active_surface()
    }

    /// Adopt this client's own remembered focus from the mux (or the
    /// session's last reported focus when this client has none), when the
    /// server has one whose pane still exists in the adopted tree; otherwise
    /// the tree's own focus stays. Sets the report baseline either way.
    fn restore_client_focus_from_session(&mut self) {
        let Some(client_id) = self.client_focus_id.clone() else { return };
        let Some(focus) = self.session.client_focus(&client_id) else { return };
        let mut location = None;
        for (workspace_index, workspace) in self.tree.workspaces.iter().enumerate() {
            for (screen_index, screen) in workspace.screens.iter().enumerate() {
                if let Some(pane) = screen.panes.iter().find(|pane| pane.id == focus.pane) {
                    let tab = focus.tab.min(pane.tabs.len().saturating_sub(1));
                    location = Some((workspace_index, screen_index, pane.id, tab));
                }
            }
        }
        let Some((workspace_index, screen_index, pane_id, tab_index)) = location else { return };
        self.tree.active_workspace = workspace_index;
        if let Some(workspace) = self.tree.workspaces.get_mut(workspace_index) {
            workspace.active_screen = screen_index;
            if let Some(screen) = workspace.screens.get_mut(screen_index) {
                screen.active_pane = pane_id;
                if let Some(pane) = screen.panes.iter_mut().find(|pane| pane.id == pane_id) {
                    pane.active_tab = tab_index;
                }
            }
        }
        self.sidebar_workspace_selection =
            workspace_index.min(self.tree.workspaces.len().saturating_sub(1));
        self.pane_focus_history.record(pane_id);
        self.reported_focus = Some(crate::session::ClientFocus { pane: pane_id, tab: tab_index });
    }

    /// Report the client's focus (pane and tab; the server derives workspace
    /// and screen at restore time) to the server's focus memory. The first
    /// observation after adopting a tree is recorded as the baseline without
    /// sending, so attaching never mutates the server; only later user
    /// navigation does.
    fn current_client_focus(&self) -> Option<crate::session::ClientFocus> {
        let screen = self.tree.active_screen()?;
        let pane = screen.panes.iter().find(|pane| pane.id == screen.active_pane)?;
        Some(crate::session::ClientFocus { pane: pane.id, tab: pane.active_tab })
    }

    fn report_client_focus(&mut self) {
        let Some(focus) = self.current_client_focus() else { return };
        match self.reported_focus {
            None => self.reported_focus = Some(focus),
            Some(previous) if previous == focus => {}
            Some(previous) => {
                self.session.report_focus(Some(previous), focus, self.client_focus_id.as_deref());
                self.reported_focus = Some(focus);
            }
        }
    }

    fn claim_active_terminal_geometry(&mut self, force: bool) {
        self.report_client_focus();
        let terminal = self.tree.active_screen().and_then(|screen| {
            let pane = screen.panes.iter().find(|pane| pane.id == screen.active_pane)?;
            let tab = pane.tabs.get(pane.active_tab)?;
            (tab.kind == SurfaceKind::Pty).then_some(tab.surface)
        });
        let Some(surface) = terminal else {
            self.geometry_authority_surface = None;
            return;
        };
        if !force && self.geometry_authority_surface == Some(surface) {
            return;
        }
        if !self.session.terminal_geometry_claim_ready(surface) {
            // Keep the previous terminal authoritative until the new remote
            // placement has both an attached mirror and a server-side size
            // lease. Attach/resize settlement retries this transition.
            return;
        }
        self.geometry_authority_surface = Some(surface);
        self.session.claim_terminal_geometry(surface);
    }

    fn active_surface_handle(&self) -> Option<SurfaceHandle> {
        self.active_surface().and_then(|id| self.session.surface(id))
    }

    fn active_surface_with_handle(&self) -> Option<(SurfaceId, SurfaceHandle)> {
        let id = self.active_surface()?;
        Some((id, self.session.surface(id)?))
    }

    fn missing_input_surface(&self, input: &TerminalInput) -> Option<SurfaceId> {
        self.missing_input_surface_for_admission(input, None)
    }

    fn missing_input_surface_for_admission(
        &self,
        input: &TerminalInput,
        admission: Option<&DeferredInputAdmission>,
    ) -> Option<SurfaceId> {
        let surface = match input {
            TerminalInput::Keyboard(_)
            | TerminalInput::ClearHistoryKey(_)
            | TerminalInput::Paste(_) => self
                .semantic_destination_for_input(input, admission)
                .or_else(|| self.active_surface())?,
            TerminalInput::FrontendAction { action: Action::SendPrefix, .. } => self
                .semantic_destination_for_input(input, admission)
                .or_else(|| self.active_surface())?,
            TerminalInput::Mouse(mouse) => {
                let area = self.pane_area_at(mouse.column, mouse.row)?;
                area.content.contains(mouse.column, mouse.row).then_some(area.surface)?
            }
            _ => return None,
        };
        (!self.session.surface_is_ready_for_input(surface)).then_some(surface)
    }

    fn queue_surface_attach(&mut self, surface: SurfaceId) {
        if !self.session.can_attach_surface(surface) {
            return;
        }
        let size = self
            .pane_areas
            .iter()
            .find(|area| area.surface == surface)
            .map(PaneArea::content_size)
            .filter(|(cols, rows)| *cols > 0 && *rows > 0);
        self.session.attach_surface(surface, size);
    }

    fn retry_pending_surface_attach(&mut self) {
        let surface = self
            .deferred_input
            .iter()
            .filter(|input| match &input.event {
                TerminalInput::Mouse(mouse) => !self.pointer_route_is_stale_for_mouse(mouse),
                _ => true,
            })
            .filter_map(|input| {
                self.missing_input_surface_for_admission(&input.event, Some(&input.admission))
            })
            .find(|surface| self.session.can_attach_surface(*surface))
            .or_else(|| {
                self.pending_pointer_motion
                    .filter(|pointer| !self.pointer_route_is_stale_for_mouse(&pointer.event))
                    .and_then(|pointer| {
                        self.missing_input_surface(&TerminalInput::Mouse(pointer.event))
                    })
                    .filter(|surface| self.session.can_attach_surface(*surface))
            });
        if let Some(surface) = surface {
            self.queue_surface_attach(surface);
        }
    }

    fn active_screen_id(&self) -> Option<ScreenId> {
        self.tree.active_screen().map(|screen| screen.id)
    }

    fn reassert_visible_surface_sizes(&mut self) {
        if self.config.sidebar.plugin.is_some()
            && self.sidebar_visible
            && self.sidebar_width >= 3
            && let Some(surface) = self.sidebar_surface_handle()
        {
            let rect = self.sidebar_plugin_rect();
            if rect.width > 0 && rect.height > 0 {
                let desired = (rect.width, rect.height);
                let needs_barrier = surface.resize_needed(rect.width, rect.height, true);
                if let Some(surface_id) = self.sidebar_plugin_surface
                    && !(surface.kind() == SurfaceKind::Browser
                        && self.browser_input.resize_failed(surface_id, desired))
                {
                    match self.session.surface_resize_decision(
                        surface_id,
                        (rect.width, rect.height),
                        needs_barrier,
                    ) {
                        SurfaceResizeDecision::Noop => {
                            if surface.kind() != SurfaceKind::Browser {
                                let _ = surface.reassert_size(rect.width, rect.height);
                            }
                        }
                        SurfaceResizeDecision::AlreadyClaimed | SurfaceResizeDecision::Failed => {}
                        SurfaceResizeDecision::NeedsQueue(claim)
                            if self.prepare_pty_input_before_mutation() =>
                        {
                            self.enqueue_surface_resize(
                                surface_id,
                                surface,
                                rect.width,
                                rect.height,
                                true,
                                Some(claim),
                            );
                        }
                        SurfaceResizeDecision::NeedsQueue(_) => {}
                    }
                }
            }
        }
        for index in 0..self.pane_areas.len() {
            let area = self.pane_areas[index];
            if area.content.width == 0 || area.content.height == 0 {
                continue;
            }
            if !self.session.has_surface(area.surface) && !self.prepare_pty_input_before_mutation()
            {
                return;
            }
            let desired = area.content_size();
            if let Some(surface) = self.session.surface(area.surface) {
                if surface.kind() == SurfaceKind::Browser
                    && self.browser_input.resize_failed(area.surface, desired)
                {
                    continue;
                }
                let needs_barrier = surface.resize_needed(desired.0, desired.1, true);
                match self.session.surface_resize_decision(area.surface, desired, needs_barrier) {
                    SurfaceResizeDecision::Noop => {
                        if surface.kind() != SurfaceKind::Browser {
                            let _ = surface.reassert_size(desired.0, desired.1);
                        }
                    }
                    SurfaceResizeDecision::AlreadyClaimed | SurfaceResizeDecision::Failed => {}
                    SurfaceResizeDecision::NeedsQueue(claim)
                        if self.prepare_pty_input_before_mutation() =>
                    {
                        self.enqueue_surface_resize(
                            area.surface,
                            surface,
                            desired.0,
                            desired.1,
                            true,
                            Some(claim),
                        );
                    }
                    SurfaceResizeDecision::NeedsQueue(_) => {}
                }
            } else if self.session.can_attach_surface(area.surface)
                && self.prepare_pty_input_before_mutation()
            {
                self.session.attach_surface(area.surface, Some(desired));
            }
        }
    }

    pub fn dragging_scrollbar(&self) -> Option<SurfaceId> {
        match self.drag {
            Some(Drag::Scrollbar { surface, .. }) => Some(surface),
            _ => None,
        }
    }

    pub(crate) fn horizontal_scrollbar_state(&self) -> Option<(u64, u16, u64)> {
        let viewport_width = self.content_area.width;
        if viewport_width == 0 || self.viewport_virtual_width <= u64::from(viewport_width) {
            return None;
        }
        Some((self.viewport_virtual_width, viewport_width, self.viewport_offset))
    }

    fn scroll_horizontal_viewport(&mut self, delta: i16, animate: bool) -> bool {
        let Some(screen) = self.active_screen_id() else { return false };
        let Some((content_width, viewport_width, _)) = self.horizontal_scrollbar_state() else {
            return false;
        };
        let maximum = content_width.saturating_sub(u64::from(viewport_width));
        let current = self
            .viewport_states
            .get(&screen)
            .map_or(self.viewport_offset, |motion| motion.target.round() as u64);
        self.set_viewport_target(
            current.saturating_add_signed(i64::from(delta)).min(maximum),
            animate,
        )
    }

    /// Start a horizontal scrollbar drag. Grabbing the thumb freezes it at
    /// its rendered offset; clicking the track jumps first and anchors there.
    fn start_horizontal_scrollbar_drag(&mut self, track: Rect, x: u16) {
        let Some((content_width, viewport_width, offset)) = self.horizontal_scrollbar_state()
        else {
            return;
        };
        if track.width == 0 {
            return;
        }
        let relative = x.saturating_sub(track.x).min(track.width - 1);
        let (thumb_x, thumb_width) =
            horizontal_thumb_geometry(content_width, viewport_width, offset, track.width);
        let on_thumb = relative >= thumb_x && relative < thumb_x.saturating_add(thumb_width);
        let anchor_offset = if on_thumb {
            self.set_viewport_target(offset, false);
            offset
        } else {
            let Some(target) =
                horizontal_offset_at(content_width, viewport_width, track.width, relative)
            else {
                return;
            };
            self.set_viewport_target(target, true);
            target
        };
        self.drag = Some(Drag::HorizontalScrollbar { track, anchor_x: x, anchor_offset });
    }

    pub fn dragging_workspace_scrollbar(&self) -> bool {
        matches!(self.drag, Some(Drag::WorkspaceScrollbar { .. }))
    }

    fn enqueue_surface_resize(
        &mut self,
        surface_id: SurfaceId,
        surface: SurfaceHandle,
        cols: u16,
        rows: u16,
        reassert: bool,
        claim: Option<SurfaceResizeClaim>,
    ) -> bool {
        if surface.kind() == SurfaceKind::Browser {
            let Some(claim) = claim else { return false };
            let ownership = self.session.surface_resize_ownership.clone();
            self.browser_input.enqueue(BrowserInputEvent {
                surface_id,
                surface,
                kind: BrowserInputKind::Resize {
                    cols,
                    rows,
                    reassert,
                    _claim: Some(Box::new(claim)),
                    on_result: Some(Box::new(move |accepted| {
                        record_surface_resize_dispatch_result(
                            &ownership,
                            surface_id,
                            (cols, rows),
                            accepted,
                        );
                    })),
                },
            })
        } else {
            let Some(claim) = claim else { return false };
            self.session.resize_surface(surface_id, surface, cols, rows, reassert, claim)
        }
    }

    fn enqueue_surface_size_reclaim(
        &mut self,
        surface_id: SurfaceId,
        surface: SurfaceHandle,
        cols: u16,
        rows: u16,
        claim: Option<SurfaceResizeClaim>,
    ) -> bool {
        if surface.kind() == SurfaceKind::Browser {
            self.enqueue_surface_resize(surface_id, surface, cols, rows, true, claim)
        } else {
            let Some(claim) = claim else { return false };
            self.session.reclaim_surface_size(surface_id, surface, cols, rows, claim)
        }
    }

    pub fn tab_drag(&self) -> Option<TabDragView> {
        match self.drag {
            Some(Drag::Tab { surface, target }) => Some(TabDragView { surface, target }),
            _ => None,
        }
    }

    pub fn workspace_drag(&self) -> Option<(WorkspaceId, Option<usize>)> {
        match self.drag {
            Some(Drag::Workspace { workspace, target }) => Some((workspace, target)),
            _ => None,
        }
    }

    pub fn surface_scroll_offset(&self, surface: SurfaceId) -> u64 {
        self.session
            .surface(surface)
            .and_then(|surface| surface.scrollbar().map(|scrollbar| scrollbar.offset))
            .unwrap_or(0)
    }

    fn replace_selection(&mut self, selection: Option<Selection>) {
        self.selection_generation = self.selection_generation.wrapping_add(1);
        self.selection = selection;
    }

    fn visible_input_state(&self, destination: Option<SurfaceId>) -> VisibleInputState {
        let pty_surface = destination
            .or_else(|| self.active_surface())
            .filter(|surface| self.tree.surface_kind(*surface) == SurfaceKind::Pty);
        VisibleInputState {
            pty_surface,
            selection: self.selection,
            scroll_offset: pty_surface.map_or(0, |surface| self.surface_scroll_offset(surface)),
        }
    }

    fn painted_status_message_action(&self) -> RenderAction {
        if self
            .rendered_status_message
            .as_ref()
            .is_some_and(|rendered| self.status_message.as_deref() != Some(rendered.text.as_str()))
        {
            RenderAction::Draw
        } else {
            RenderAction::None
        }
    }

    fn visible_input_action(&self, before: VisibleInputState) -> RenderAction {
        let status_action = self.painted_status_message_action();
        let action = if self.selection != before.selection
            || before
                .pty_surface
                .is_some_and(|surface| self.surface_scroll_offset(surface) != before.scroll_offset)
        {
            RenderAction::Draw
        } else {
            RenderAction::None
        };
        action.merge(status_action)
    }

    pub(crate) fn reset_rendered_status_message(&mut self) {
        // Per-frame render reset. `logged_status_message` deliberately
        // survives it: a message that stays visible across redraws is one
        // event, not one per frame. Dismissal (`hide_status_message`) clears
        // it, so a message that reappears later logs again.
        self.rendered_status_message = None;
    }

    pub(crate) fn present_status_message(&mut self, rect: Rect, text: String) {
        if self.status_selection.as_ref().is_some_and(|selection| selection.text != text) {
            self.status_selection = None;
            if matches!(self.drag, Some(Drag::StatusMessage { .. })) {
                self.drag = None;
            }
        }
        // Every visible status message passes through here; persist each new
        // one so warnings survive the session in the client log. Provider
        // notices ("VM created") share the status line but are not errors.
        if self.logged_status_message.as_deref() != Some(text.as_str()) {
            if self.status_notice_text.as_deref() == Some(text.as_str()) {
                crate::client_log::info("status", &text);
            } else {
                crate::client_log::error("status", &text);
            }
            self.logged_status_message = Some(text.clone());
        }
        self.rendered_status_message = Some(RenderedStatusMessage { rect, text });
    }

    pub(crate) fn hide_status_message(&mut self) {
        self.rendered_status_message = None;
        self.logged_status_message = None;
        // The notice marker only describes the currently shown message; a
        // later status with the same text is a fresh event and must be
        // classified on its own.
        self.status_notice_text = None;
        self.status_selection = None;
        if matches!(self.drag, Some(Drag::StatusMessage { .. })) {
            self.drag = None;
        }
    }

    pub(crate) fn status_message_cell_selected(&self, text: &str, cell: u16) -> bool {
        self.status_selection.as_ref().is_some_and(|selection| selection.contains(text, cell))
    }

    fn status_message_hovered(&self) -> bool {
        self.hover.is_some_and(|(x, y)| {
            self.rendered_status_message
                .as_ref()
                .is_some_and(|rendered| rendered.rect.contains(x, y))
                || self
                    .hits
                    .iter()
                    .any(|(rect, hit)| *hit == Hit::CopyStatusMessage && rect.contains(x, y))
        })
    }

    fn begin_status_message_selection(&mut self, x: u16) -> bool {
        let Some(rendered) = self.rendered_status_message.clone() else { return false };
        if rendered.rect.width == 0 || !rendered.rect.contains(x, rendered.rect.y) {
            return false;
        }
        let cell = x.saturating_sub(rendered.rect.x).min(rendered.rect.width - 1);
        self.status_selection =
            Some(StatusMessageSelection { text: rendered.text, anchor: cell, head: cell });
        self.drag = Some(Drag::StatusMessage { rect: rendered.rect });
        true
    }

    fn selection_auto_scroll_active(&self) -> bool {
        matches!(self.drag, Some(Drag::Select { auto_scroll: Some(_), .. }))
    }

    fn auto_scroll_selection_tick(&mut self) -> bool {
        let Some(Drag::Select { content, source_x, auto_scroll: Some(dir), col }) = self.drag
        else {
            return false;
        };
        let Some(surface_id) = self.selection.map(|sel| sel.surface) else { return false };
        let Some(surface) = self.session.surface(surface_id) else { return false };
        let content =
            self.current_selection_geometry(surface_id).map_or(content, |(content, _)| content);
        let moved = surface.scroll_delta(dir as isize).unwrap_or(false);
        let edge_row = if dir < 0 { 0 } else { content.height.saturating_sub(1) };
        let offset = self.surface_scroll_offset(surface_id);
        if let Some(mut selection) = self.selection {
            selection.head = (
                col.min(content.width.saturating_sub(1).saturating_add(source_x)),
                offset + edge_row as u64,
            );
            self.replace_selection(Some(selection));
        }
        moved
    }

    /// Content size for a pane filling `rect`.
    fn size_of_rect(&self, rect: Rect) -> Option<(u16, u16)> {
        content_size_for_rect(rect, self.config.scrollbar.position, self.config.pane.padding)
    }

    /// Size hint for splitting `pane`: the second side of its rect.
    fn split_size_hint(&self, pane: PaneId, dir: SplitDir) -> Option<(u16, u16)> {
        let area = self.pane_areas.iter().find(|a| a.pane == pane)?;
        let (_, b) = split_sides(area.logical_rect(), dir, 0.5);
        self.size_of_rect(b)
    }

    fn pane_creation_selector_candidates(
        &self,
        pane: PaneId,
        fallback_pane: Option<PaneId>,
    ) -> anyhow::Result<Vec<cmux_tui_core::ResourceSelectors>> {
        let mut candidates = Vec::with_capacity(2);
        for pane in [Some(pane), fallback_pane].into_iter().flatten() {
            if let Some(selectors) = self.tree.resource_selectors_for_pane(Some(pane))
                && !candidates.contains(&selectors)
            {
                candidates.push(selectors);
            }
        }
        Ok(candidates)
    }

    fn split_pane(
        &mut self,
        pane: PaneId,
        fallback_pane: Option<PaneId>,
        dir: SplitDir,
        semantic_intent: Option<u64>,
    ) -> anyhow::Result<()> {
        let hint = self.split_size_hint(pane, dir);
        if !self.prepare_pty_input_before_mutation() {
            return Ok(());
        }
        let selector_candidates = self.pane_creation_selector_candidates(pane, fallback_pane)?;
        self.session.split_for_semantic_intent(
            pane,
            dir,
            hint,
            selector_candidates,
            semantic_intent,
        )
    }

    fn new_terminal_tab(
        &mut self,
        pane: Option<PaneId>,
        fallback_pane: Option<PaneId>,
        semantic_intent: Option<u64>,
    ) -> anyhow::Result<()> {
        let pane = pane.or_else(|| self.active_pane());
        let selector_candidates = pane
            .map(|pane| self.pane_creation_selector_candidates(pane, fallback_pane))
            .transpose()?
            .unwrap_or_default();
        self.session.new_tab_for_semantic_intent(
            pane,
            self.terminal_tab_size_hint(pane),
            selector_candidates,
            semantic_intent,
        )
    }

    /// Run one configured user command as a new PTY tab in the target pane.
    /// The server defaults the working directory to the pane's current
    /// directory when the command has no configured `cwd`.
    fn run_user_command(&mut self, index: usize, pane: Option<PaneId>) -> anyhow::Result<()> {
        // `action_available` already rejects user commands for single-surface
        // clients; keep the invariant local so no future route can create a
        // tab this mode cannot reach.
        if self.is_surface_only() {
            return Ok(());
        }
        let Some(command) = self.config.commands.get(index) else {
            return Ok(());
        };
        let pane = pane.or_else(|| self.active_pane());
        self.session.run_command(
            command.run.clone(),
            pane,
            command.cwd.clone(),
            self.terminal_tab_size_hint(pane),
        )
    }

    fn terminal_tab_size_hint(&self, pane: Option<PaneId>) -> Option<(u16, u16)> {
        match pane {
            Some(pane) => {
                self.pane_areas.iter().find(|area| area.pane == pane).map(PaneArea::content_size)
            }
            None => self
                .active_pane()
                .and_then(|pane| self.terminal_tab_size_hint(Some(pane)))
                .or_else(|| self.size_of_rect(self.content_area)),
        }
    }

    fn new_pane_smart(
        &mut self,
        pane: Option<PaneId>,
        fallback_pane: Option<PaneId>,
        semantic_intent: Option<u64>,
    ) -> anyhow::Result<()> {
        let Some(pane) = pane.or_else(|| self.active_pane()) else {
            return Ok(());
        };
        let Some(hint) = self.tree.active_screen().and_then(|screen| {
            let mut panes = Vec::new();
            screen.layout.pane_ids(&mut panes);
            let mut local_area = self.content_area;
            if !screen.viewport_splits.is_empty() {
                let owner = screen.layout.viewport_column_owner(pane, &screen.viewport_splits)?;
                panes.retain(|candidate| {
                    screen.layout.viewport_column_owner(*candidate, &screen.viewport_splits)
                        == Some(owner)
                });
                let width = match owner {
                    ViewportColumn::Base => screen.viewport_base_width.unwrap_or(1.0),
                    ViewportColumn::Split(split) => {
                        screen.viewport_splits.get(&split).copied().unwrap_or(1.0)
                    }
                };
                local_area.width =
                    ((f32::from(self.content_area.width) * width).round() as u16).max(1);
            }
            panes.push(PaneId::MAX);
            let layout = zellij_default_pane_layout(&panes)?;
            let rect =
                layout_screen(&layout, local_area, Some(PaneId::MAX)).rect_of(PaneId::MAX)?;
            self.size_of_rect(rect)
        }) else {
            return Ok(());
        };
        if !self.prepare_pty_input_before_mutation() {
            return Ok(());
        }
        let selector_candidates = self.pane_creation_selector_candidates(pane, fallback_pane)?;
        self.session.new_pane_for_semantic_intent(
            pane,
            Some(hint),
            selector_candidates,
            semantic_intent,
        )
    }

    fn new_pane_right(
        &mut self,
        pane: Option<PaneId>,
        fallback_pane: Option<PaneId>,
        semantic_intent: Option<u64>,
    ) -> anyhow::Result<()> {
        let Some(pane) = pane.or_else(|| self.active_pane()) else {
            return Ok(());
        };
        let width = ((f32::from(self.content_area.width) * DEFAULT_VIEWPORT_PANE_WIDTH).round()
            as u16)
            .clamp(1, self.content_area.width.max(1));
        let rect = Rect { width, ..self.content_area };
        let hint = self.size_of_rect(rect);
        if self.prepare_pty_input_before_mutation() {
            let selector_candidates =
                self.pane_creation_selector_candidates(pane, fallback_pane)?;
            self.session.new_pane_right_for_semantic_intent(
                pane,
                DEFAULT_VIEWPORT_PANE_WIDTH,
                hint,
                selector_candidates,
                semantic_intent,
            )?;
        }
        Ok(())
    }

    fn new_workspace(&mut self, semantic_intent: Option<u64>) -> anyhow::Result<()> {
        let Some(mode) = self.default_workspace_creation_mode() else {
            self.status_message = Some(
                if self.workspace_creation_policy().is_none() {
                    localization::catalog().sidebar.no_active_session
                } else {
                    localization::catalog().sidebar.managed_workspace_unsupported
                }
                .to_string(),
            );
            return Ok(());
        };
        self.create_workspace(mode, semantic_intent)
    }

    fn create_workspace(
        &mut self,
        mode: Option<WorkspaceCreationMode>,
        semantic_intent: Option<u64>,
    ) -> anyhow::Result<()> {
        if let Some(mode) = mode {
            self.request_managed_workspace(mode);
            return Ok(());
        }
        if self.workspace_creation_policy() != Some(WorkspaceCreationPolicy::SessionOwned) {
            self.status_message =
                Some(localization::catalog().sidebar.managed_workspace_unsupported.to_string());
            return Ok(());
        }
        if !self.prepare_pty_input_before_mutation() {
            return Ok(());
        }
        self.session.new_workspace_for_semantic_intent(
            self.size_of_rect(self.content_area),
            semantic_intent,
        )
    }

    fn request_managed_workspace(&mut self, mode: WorkspaceCreationMode) {
        let supported = matches!(
            self.workspace_creation_policy(),
            Some(WorkspaceCreationPolicy::ProviderOwned { modes, .. }) if modes.contains(&mode)
        );
        if !supported {
            self.status_message =
                Some(localization::catalog().sidebar.managed_workspace_unsupported.to_string());
            return;
        }
        let Some(machine) = self.machine_ui.as_ref().and_then(|ui| ui.snapshot.active) else {
            self.status_message =
                Some(localization::catalog().sidebar.no_active_session.to_string());
            return;
        };
        let request = match mode {
            WorkspaceCreationMode::Isolated => {
                MachineRequest::CreateManagedIsolatedWorkspace(machine)
            }
            WorkspaceCreationMode::Host => MachineRequest::CreateManagedHostWorkspace(machine),
        };
        if let Some(ui) = self.machine_ui.as_mut() {
            ui.request = Some(request);
        }
    }

    fn managed_machine(&self, key: MachineKey) -> Option<ManagedMachineDescriptor> {
        self.machine_ui.as_ref()?.managed_machine(key).cloned()
    }

    fn request_rename_client_machine(&mut self, key: MachineKey, name: String) {
        if !self.machine_ui.as_ref().is_some_and(|ui| ui.is_client_machine_renamable(key)) {
            return;
        }
        if let Some(ui) = self.machine_ui.as_mut() {
            ui.request = Some(MachineRequest::RenameClientMachine { machine: key, name });
        }
    }

    fn request_rename_managed_machine(&mut self, key: MachineKey, name: String) {
        let Some(machine) = self.managed_machine(key).filter(|machine| {
            machine.status == ManagedMachineStatus::Active && machine.capabilities.rename
        }) else {
            return;
        };
        if let Some(ui) = self.machine_ui.as_mut() {
            ui.request = Some(MachineRequest::RenameManagedMachine {
                machine: key,
                expected_version: machine.version,
                name,
            });
        }
    }

    fn request_delete_managed_machine(&mut self, key: MachineKey) {
        let Some(machine) = self.managed_machine(key).filter(|machine| {
            machine.status == ManagedMachineStatus::Active && machine.capabilities.delete
        }) else {
            return;
        };
        if let Some(ui) = self.machine_ui.as_mut() {
            ui.request = Some(MachineRequest::DeleteManagedMachine {
                machine: key,
                expected_version: machine.version,
            });
        }
    }

    fn request_restore_managed_machine(&mut self, key: MachineKey) {
        let Some(machine) = self.managed_machine(key).filter(|machine| {
            machine.status == ManagedMachineStatus::Recoverable && machine.capabilities.restore
        }) else {
            return;
        };
        if let Some(ui) = self.machine_ui.as_mut() {
            ui.request = Some(MachineRequest::RestoreManagedMachine {
                machine: key,
                expected_version: machine.version,
            });
        }
    }

    fn activate_machine(&mut self, key: MachineKey) {
        self.select_machine_intent(key);
        if self.managed_machine(key).is_some_and(|machine| {
            machine.status == ManagedMachineStatus::Recoverable && machine.capabilities.restore
        }) {
            self.request_restore_managed_machine(key);
        } else {
            let needs_switch = self.machine_presented != Some(key)
                || self.machine_ui.as_ref().is_some_and(|ui| !ui.session_available);
            if let Some(ui) = self.machine_ui.as_mut() {
                if needs_switch {
                    ui.request = Some(MachineRequest::Switch(key));
                } else if matches!(ui.request, Some(MachineRequest::Switch(_))) {
                    ui.request = None;
                }
            }
        }
    }

    fn request_purge_managed_machine(&mut self, key: MachineKey) {
        let Some(machine) = self.managed_machine(key).filter(|machine| {
            machine.status == ManagedMachineStatus::Recoverable && machine.capabilities.purge
        }) else {
            return;
        };
        if let Some(ui) = self.machine_ui.as_mut() {
            ui.request = Some(MachineRequest::PurgeManagedMachine {
                machine: key,
                expected_version: machine.version,
            });
        }
    }

    fn open_rename_managed_machine_prompt(&mut self, key: MachineKey) {
        let Some(machine) = self.managed_machine(key).filter(|machine| {
            machine.status == ManagedMachineStatus::Active && machine.capabilities.rename
        }) else {
            return;
        };
        self.cancel_pty_mouse_drag();
        self.prompt = Some(Prompt::new(
            localization::catalog().sidebar.rename_machine,
            machine.name,
            PromptTarget::ManagedMachine(key),
        ));
    }

    fn open_rename_client_machine_prompt(&mut self, key: MachineKey) {
        let Some(ui) = self.machine_ui.as_ref().filter(|ui| ui.is_client_machine_renamable(key))
        else {
            return;
        };
        let Some(name) = ui
            .snapshot
            .machines
            .iter()
            .find(|machine| machine.key == key)
            .map(|machine| machine.name.clone())
        else {
            return;
        };
        self.cancel_pty_mouse_drag();
        self.prompt = Some(Prompt::new(
            localization::catalog().sidebar.rename_machine,
            name,
            PromptTarget::ClientMachine(key),
        ));
    }

    fn open_rename_machine_prompt(&mut self, key: MachineKey) {
        if self.managed_machine(key).is_some() {
            self.open_rename_managed_machine_prompt(key);
        } else {
            self.open_rename_client_machine_prompt(key);
        }
    }

    fn open_delete_managed_machine_prompt(&mut self, key: MachineKey) {
        if self.managed_machine(key).is_some_and(|machine| {
            machine.status == ManagedMachineStatus::Active && machine.capabilities.delete
        }) {
            self.cancel_pty_mouse_drag();
            self.prompt = Some(Prompt::new(
                localization::catalog().sidebar.confirm_delete_machine,
                String::new(),
                PromptTarget::ConfirmDeleteManagedMachine(key),
            ));
        }
    }

    fn open_purge_managed_machine_prompt(&mut self, key: MachineKey) {
        if self.managed_machine(key).is_some_and(|machine| {
            machine.status == ManagedMachineStatus::Recoverable && machine.capabilities.purge
        }) {
            self.cancel_pty_mouse_drag();
            self.prompt = Some(Prompt::new(
                localization::catalog().sidebar.confirm_purge_machine,
                String::new(),
                PromptTarget::ConfirmPurgeManagedMachine(key),
            ));
        }
    }

    fn managed_workspace_for_view(
        &self,
        workspace_id: WorkspaceId,
    ) -> Option<ManagedWorkspaceDescriptor> {
        let workspace_key = self
            .tree
            .workspaces
            .iter()
            .find(|workspace| workspace.id == workspace_id)?
            .key
            .as_str();
        self.machine_ui
            .as_ref()?
            .managed_workspace(workspace_key)
            .filter(|workspace| workspace.status == ManagedWorkspaceStatus::Active)
            .cloned()
    }

    fn provider_manages_current_workspace_session(&self) -> bool {
        self.session.workspaces_are_provider_managed()
            || uses_provider_managed_workspaces(self.machine_ui.as_ref())
    }

    fn reject_inactive_managed_workspace_machine(&mut self) {
        self.status_message =
            Some(localization::catalog().sidebar.managed_workspace_machine_inactive.to_string());
    }

    fn reject_unavailable_managed_workspace_operation(&mut self) {
        self.status_message =
            Some(localization::catalog().sidebar.managed_workspace_unavailable.to_string());
    }

    fn reject_disallowed_managed_workspace_operation(&mut self) {
        self.status_message = Some(
            localization::catalog().sidebar.managed_workspace_operation_not_allowed.to_string(),
        );
    }

    fn request_rename_managed_workspace(&mut self, workspace_id: WorkspaceId, name: String) {
        let Some(machine) = self.machine_ui.as_ref().and_then(|ui| ui.snapshot.active) else {
            self.reject_inactive_managed_workspace_machine();
            return;
        };
        let Some(workspace) = self.managed_workspace_for_view(workspace_id) else {
            self.reject_unavailable_managed_workspace_operation();
            return;
        };
        if workspace.capabilities.rename
            && let Some(ui) = self.machine_ui.as_mut()
        {
            ui.request = Some(MachineRequest::RenameManagedWorkspace {
                machine,
                workspace_id: workspace.id,
                expected_version: workspace.version,
                name,
            });
        } else {
            self.reject_disallowed_managed_workspace_operation();
        }
    }

    fn request_rename_workspace(&mut self, workspace_id: WorkspaceId, name: String) {
        if self.provider_manages_current_workspace_session() {
            self.request_rename_managed_workspace(workspace_id, name);
        } else {
            self.session.rename_workspace(workspace_id, name);
        }
    }

    fn request_delete_workspace(&mut self, workspace_id: WorkspaceId) {
        if self.provider_manages_current_workspace_session() {
            let Some(machine) = self.machine_ui.as_ref().and_then(|ui| ui.snapshot.active) else {
                self.reject_inactive_managed_workspace_machine();
                return;
            };
            let Some(workspace) = self.managed_workspace_for_view(workspace_id) else {
                self.reject_unavailable_managed_workspace_operation();
                return;
            };
            if workspace.capabilities.delete
                && let Some(ui) = self.machine_ui.as_mut()
            {
                ui.request = Some(MachineRequest::DeleteManagedWorkspace {
                    machine,
                    workspace_id: workspace.id,
                    expected_version: workspace.version,
                });
            } else {
                self.reject_disallowed_managed_workspace_operation();
            }
            return;
        }
        self.session.close_workspace(workspace_id);
    }

    fn request_restore_managed_workspace(&mut self, workspace_id: &str) {
        let Some(workspace) = self
            .machine_ui
            .as_ref()
            .and_then(|ui| ui.managed_workspace(workspace_id))
            .filter(|workspace| {
                workspace.status == ManagedWorkspaceStatus::Recoverable
                    && workspace.capabilities.restore
            })
            .cloned()
        else {
            return;
        };
        let Some(machine) = self.machine_ui.as_ref().and_then(|ui| ui.snapshot.active) else {
            return;
        };
        if let Some(ui) = self.machine_ui.as_mut() {
            ui.request = Some(MachineRequest::RestoreManagedWorkspace {
                machine,
                workspace_id: workspace.id,
                expected_version: workspace.version,
            });
        }
    }

    fn request_purge_managed_workspace(&mut self, workspace_id: &str) {
        let Some(workspace) = self
            .machine_ui
            .as_ref()
            .and_then(|ui| ui.managed_workspace(workspace_id))
            .filter(|workspace| {
                workspace.status == ManagedWorkspaceStatus::Recoverable
                    && workspace.capabilities.purge
            })
            .cloned()
        else {
            return;
        };
        let Some(machine) = self.machine_ui.as_ref().and_then(|ui| ui.snapshot.active) else {
            return;
        };
        if let Some(ui) = self.machine_ui.as_mut() {
            ui.request = Some(MachineRequest::PurgeManagedWorkspace {
                machine,
                workspace_id: workspace.id,
                expected_version: workspace.version,
            });
        }
    }

    fn workspace_rail_targets(&self) -> Vec<WorkspaceRailTarget> {
        let mut targets = self
            .tree
            .workspaces
            .iter()
            .map(|workspace| WorkspaceRailTarget::Workspace(workspace.id))
            .collect::<Vec<_>>();
        targets.extend(
            self.machine_ui
                .as_ref()
                .into_iter()
                .flat_map(MachineUiState::recoverable_workspaces)
                .map(|workspace| WorkspaceRailTarget::Recoverable(workspace.id.clone())),
        );
        targets.extend(
            self.workspace_sidebar_action_rows()
                .into_iter()
                .map(|action| WorkspaceRailTarget::Action(action.target)),
        );
        targets
    }

    fn workspace_rail_target(&self) -> Option<WorkspaceRailTarget> {
        match self.workspace_rail_selection {
            WorkspaceRailSelection::Workspace => self
                .tree
                .workspaces
                .get(self.sidebar_workspace_selection)
                .map(|workspace| WorkspaceRailTarget::Workspace(workspace.id)),
            WorkspaceRailSelection::Recoverable => self
                .machine_ui
                .as_ref()
                .and_then(|ui| {
                    ui.recoverable_workspaces()
                        .get(self.sidebar_recoverable_workspace_selection)
                        .copied()
                })
                .map(|workspace| WorkspaceRailTarget::Recoverable(workspace.id.clone())),
            WorkspaceRailSelection::Action(action) => Some(WorkspaceRailTarget::Action(action)),
        }
    }

    fn select_workspace_rail_target(&mut self, target: WorkspaceRailTarget) {
        match target {
            WorkspaceRailTarget::Workspace(id) => {
                if let Some(index) =
                    self.tree.workspaces.iter().position(|workspace| workspace.id == id)
                {
                    if self.sidebar_workspace_selection != index {
                        self.tabs_rail_selection = 0;
                        self.tabs_rail_scroll = 0;
                    }
                    self.sidebar_workspace_selection = index;
                    self.workspace_rail_selection = WorkspaceRailSelection::Workspace;
                }
            }
            WorkspaceRailTarget::Recoverable(id) => {
                if let Some(index) = self.machine_ui.as_ref().and_then(|ui| {
                    ui.recoverable_workspaces().iter().position(|workspace| workspace.id == id)
                }) {
                    self.sidebar_recoverable_workspace_selection = index;
                    self.workspace_rail_selection = WorkspaceRailSelection::Recoverable;
                }
            }
            WorkspaceRailTarget::Action(action) => {
                self.workspace_rail_selection = WorkspaceRailSelection::Action(action);
            }
        }
    }

    fn new_screen(&mut self, semantic_intent: Option<u64>) -> anyhow::Result<()> {
        if !self.prepare_pty_input_before_mutation() {
            return Ok(());
        }
        let workspace = self.tree.active_workspace().map(|workspace| workspace.id);
        self.session.new_screen_for_semantic_intent(
            workspace,
            self.size_of_rect(self.content_area),
            semantic_intent,
        )
    }

    fn resolve_keyboard_ingress(&mut self, mut input: keys::KeyboardInput) -> KeyboardIngress {
        input.resolve_macos_option_as_alt(self.config.keys.macos_option_as_alt);
        if input.is_composing() || input.is_modifier_only() || input.is_release() {
            return KeyboardIngress::Ignored;
        }
        if self.menu.is_none() && !self.status_message_hovered() {
            self.status_message = None;
        }
        if self.pairing_dialog.is_some()
            || self.shortcut_help.is_some()
            || self.prompt.is_some()
            || self.menu.is_some()
            || self.omnibar.is_some()
        {
            return KeyboardIngress::Routed(TerminalInput::Keyboard(input));
        }
        let (binding_key, binding_fallback) = input.shortcut_keys();
        if self.prefix_armed {
            self.prefix_armed = false;
            if input.suppresses_alt_shortcut() {
                self.focus = FocusTarget::Pane;
                return KeyboardIngress::Handled(RenderAction::Draw);
            }
            if binding_matches(&self.config.keys.prefix, &binding_key, binding_fallback.as_ref()) {
                return KeyboardIngress::Routed(TerminalInput::Keyboard(input));
            }
            let Some(action) =
                action_for_binding(&self.config.keys, &binding_key, binding_fallback.as_ref())
            else {
                self.focus = FocusTarget::Pane;
                return KeyboardIngress::Handled(RenderAction::Draw);
            };
            let was_sidebar_focused = self.workspace_sidebar_focused();
            let keep_machine_rail_focus =
                self.machine_sidebar_focused() && action == Action::ProviderMenu;
            if !(keep_machine_rail_focus || was_sidebar_focused && action == Action::SendPrefix) {
                self.focus = FocusTarget::Pane;
            }
            if was_sidebar_focused && action == Action::FocusSidebar {
                return KeyboardIngress::Handled(RenderAction::Draw);
            }
            if browser_only_action(action)
                && !self
                    .active_surface_handle()
                    .is_some_and(|surface| surface.kind() == SurfaceKind::Browser)
            {
                return KeyboardIngress::Routed(TerminalInput::Keyboard(input));
            }
            let prefix = self.config.keys.prefix;
            return KeyboardIngress::Routed(TerminalInput::FrontendAction {
                action,
                prefix: KeyEvent::new(prefix.code, prefix.mods),
            });
        }
        if !input.suppresses_alt_shortcut()
            && binding_matches(&self.config.keys.prefix, &binding_key, binding_fallback.as_ref())
        {
            self.prefix_armed = true;
            return KeyboardIngress::Handled(RenderAction::Draw);
        }
        if !input.suppresses_alt_shortcut()
            && let Some(action) = modeless_action_for_binding(
                &self.config.keys,
                &binding_key,
                binding_fallback.as_ref(),
            )
        {
            if action == Action::ClearHistory {
                return KeyboardIngress::Routed(TerminalInput::ClearHistoryKey(input));
            }
            let prefix = self.config.keys.prefix;
            return KeyboardIngress::Routed(TerminalInput::FrontendAction {
                action,
                prefix: KeyEvent::new(prefix.code, prefix.mods),
            });
        }
        KeyboardIngress::Routed(TerminalInput::Keyboard(input))
    }

    #[cfg(test)]
    fn handle_key(&mut self, key: KeyEvent) -> anyhow::Result<RenderAction> {
        self.handle_keyboard(key.into())
    }

    #[cfg(test)]
    fn handle_keyboard(&mut self, input: keys::KeyboardInput) -> anyhow::Result<RenderAction> {
        match self.resolve_keyboard_ingress(input) {
            KeyboardIngress::Routed(TerminalInput::Keyboard(input)) => {
                self.handle_direct_keyboard(input)
            }
            KeyboardIngress::Routed(TerminalInput::FrontendAction { action, prefix }) => {
                self.run_resolved_action(action, prefix)
            }
            KeyboardIngress::Routed(TerminalInput::ClearHistoryKey(input)) => {
                Ok(self.run_clear_history_shortcut(input))
            }
            KeyboardIngress::Routed(_) => unreachable!("keyboard ingress returned non-key input"),
            KeyboardIngress::Handled(action) => Ok(action),
            KeyboardIngress::Ignored => Ok(RenderAction::None),
        }
    }

    #[cfg(test)]
    fn handle_direct_keyboard(
        &mut self,
        input: keys::KeyboardInput,
    ) -> anyhow::Result<RenderAction> {
        self.handle_direct_keyboard_to(input, None)
    }

    fn handle_direct_keyboard_to(
        &mut self,
        input: keys::KeyboardInput,
        destination: Option<SurfaceId>,
    ) -> anyhow::Result<RenderAction> {
        let visible_state = self.visible_input_state(destination);
        let action = self.handle_direct_keyboard_to_inner(input, destination)?;
        Ok(action.merge(self.visible_input_action(visible_state)))
    }

    fn handle_direct_keyboard_to_inner(
        &mut self,
        input: keys::KeyboardInput,
        destination: Option<SurfaceId>,
    ) -> anyhow::Result<RenderAction> {
        let key = input.ui_key();
        if key.kind == KeyEventKind::Release {
            return Ok(RenderAction::None);
        }
        // A context menu acts on the resources visible when it opened. Keep a
        // status message alive while the menu owns input so status actions can
        // still validate and copy that exact message.
        if self.menu.is_none() && !self.status_message_hovered() {
            self.status_message = None;
        }
        if self.pairing_dialog.is_some() {
            return self.handle_pairing_key(key);
        }
        if self.shortcut_help.is_some() {
            return Ok(self.handle_shortcut_help_key(key));
        }
        if self.prompt.is_some() {
            if let Some(text) = input.text_for_direct_input() {
                return self.handle_prompt_text(text);
            }
            return self.handle_prompt_key(key);
        }
        if self.menu.is_some() {
            if let Some(text) = input.text_for_direct_input()
                && self.menu.as_mut().is_some_and(|menu| menu.insert_search_text(text))
            {
                return Ok(RenderAction::Draw);
            }
            return self.handle_menu_key(key);
        }
        if self.omnibar.is_some() {
            if let Some(text) = input.text_for_direct_input() {
                return self.handle_omnibar_text(text);
            }
            return self.handle_omnibar_key(key);
        }
        if self.machine_sidebar_focused() {
            return Ok(self.handle_machine_sidebar_key(&key));
        }
        if self.tabs_sidebar_focused() {
            return self.handle_tabs_sidebar_key(&key);
        }
        if let FocusTarget::ProjectionRail(index) = self.focus {
            return self.handle_projection_sidebar_key(index, &key);
        }
        if self.workspace_sidebar_focused() {
            if self.config.sidebar.plugin.is_some() {
                self.forward_sidebar_key(input);
                return Ok(if self.status_message.is_some() {
                    RenderAction::Draw
                } else {
                    RenderAction::None
                });
            } else {
                if self.sidebar_view == SidebarView::Files
                    && let Some(text) = input.text_for_direct_input()
                    && self.sidebar_files.insert_filter_text(text)
                {
                    return Ok(RenderAction::Draw);
                }
                return self.handle_builtin_sidebar_key(&key);
            }
        }
        // Typing replaces any selection highlight.
        self.replace_selection(None);
        if let Some(surface) = destination {
            self.forward_key_to_surface(input, surface);
        } else {
            self.forward_key(input);
        }
        Ok(if self.status_message.is_some() { RenderAction::Draw } else { RenderAction::None })
    }

    fn handle_machine_sidebar_key(&mut self, key: &KeyEvent) -> RenderAction {
        if self.config.keys.action_for(key) == Some(Action::ProviderMenu)
            || (!self.config.keys.provider_menu_overridden
                && key.modifiers == KeyModifiers::NONE
                && key.code == KeyCode::Char('m'))
        {
            let _ = self.open_provider_rail_menu(1, 2);
            return RenderAction::Draw;
        }
        if matches!(key.code, KeyCode::Left | KeyCode::Char('h')) {
            self.focus_adjacent_rail(RailKind::Machine, -1);
            return RenderAction::Draw;
        }
        if matches!(key.code, KeyCode::Right | KeyCode::Char('l')) {
            if !self.focus_adjacent_rail(RailKind::Machine, 1) {
                self.focus = FocusTarget::Pane;
            }
            return RenderAction::Draw;
        }
        if key.code == KeyCode::Esc {
            self.focus = FocusTarget::Pane;
            return RenderAction::Draw;
        }
        if key.code == KeyCode::Enter
            && self.machine_ui.as_ref().is_some_and(|machine| {
                matches!(
                    machine.rail_target(),
                    Some(MachineRailTarget::Machine(key))
                        if Some(key) == machine.snapshot.active && machine.session_available
                )
            })
        {
            // Enter on the open machine means "enter the machine", not
            // "remain trapped in its rail row".
            self.focus = FocusTarget::Pane;
            return RenderAction::Draw;
        }
        if matches!(
            key.code,
            KeyCode::Up
                | KeyCode::Down
                | KeyCode::Char('j' | 'k')
                | KeyCode::Home
                | KeyCode::End
                | KeyCode::PageUp
                | KeyCode::PageDown
        ) {
            self.machine_rail_follow_selection = true;
        }
        let page = rail_page_size(self.sidebar_layout.machine);
        let command = {
            let Some(machine) = self.machine_ui.as_mut() else {
                self.focus = FocusTarget::Pane;
                return RenderAction::Draw;
            };
            let targets = machine.rail_targets();
            let current = machine
                .rail_target()
                .and_then(|selected| targets.iter().position(|target| *target == selected))
                .unwrap_or_default();
            let provider_menu = self.config.keys.action_for(key) == Some(Action::ProviderMenu)
                || (!self.config.keys.provider_menu_overridden
                    && key.modifiers == KeyModifiers::NONE
                    && key.code == KeyCode::Char('m'));
            if provider_menu {
                // Resolve the configured action before the built-in movement
                // keys. A valid provider-menu binding may intentionally use
                // j, k, h, l, or an arrow key.
                Some(MachineRailCommand::ProviderMenu)
            } else if let Some(next) = rail_navigation_index(key, current, targets.len(), page) {
                if let Some(target) = targets.get(next).copied() {
                    machine.select_rail_target(target);
                }
                None
            } else if let Some(MachineRailTarget::Machine(machine_key)) =
                targets.get(current).copied()
            {
                let managed = machine.managed_machine(machine_key);
                let client_renamable = machine.is_client_machine_renamable(machine_key);
                match key.code {
                    KeyCode::Char('r')
                        if client_renamable
                            || managed.is_some_and(|managed| {
                                managed.status == ManagedMachineStatus::Active
                                    && managed.capabilities.rename
                            }) =>
                    {
                        Some(MachineRailCommand::Rename(machine_key))
                    }
                    KeyCode::Char('d') | KeyCode::Delete
                        if managed.is_some_and(|managed| {
                            managed.status == ManagedMachineStatus::Active
                                && managed.capabilities.delete
                        }) =>
                    {
                        Some(MachineRailCommand::Delete(machine_key))
                    }
                    KeyCode::Char('p') | KeyCode::Delete
                        if managed.is_some_and(|managed| {
                            managed.status == ManagedMachineStatus::Recoverable
                                && managed.capabilities.purge
                        }) =>
                    {
                        Some(MachineRailCommand::Purge(machine_key))
                    }
                    KeyCode::Enter
                        if Some(machine_key) != machine.snapshot.active
                            || managed.is_some_and(|managed| {
                                managed.status == ManagedMachineStatus::Recoverable
                                    && managed.capabilities.restore
                            }) =>
                    {
                        Some(MachineRailCommand::Activate(machine_key))
                    }
                    _ => None,
                }
            } else if key.code == KeyCode::Enter {
                match targets.get(current).copied() {
                    Some(MachineRailTarget::NewVm) => Some(MachineRailCommand::Create),
                    Some(MachineRailTarget::ConnectMachine) => Some(MachineRailCommand::Connect),
                    Some(MachineRailTarget::Machine(_)) | None => None,
                }
            } else {
                None
            }
        };
        match command {
            Some(MachineRailCommand::Activate(machine)) => {
                self.activate_machine(machine);
                self.focus = FocusTarget::Pane;
            }
            Some(MachineRailCommand::Rename(machine)) => {
                self.open_rename_machine_prompt(machine);
            }
            Some(MachineRailCommand::Delete(machine)) => {
                self.open_delete_managed_machine_prompt(machine);
            }
            Some(MachineRailCommand::Purge(machine)) => {
                self.open_purge_managed_machine_prompt(machine);
            }
            Some(MachineRailCommand::ProviderMenu) => {
                self.open_provider_rail_menu(1, 2);
            }
            Some(MachineRailCommand::Create) => {
                self.open_machine_creation_menu(1, 3);
            }
            Some(MachineRailCommand::Connect) => {
                self.open_machine_connection_menu(1, 3);
            }
            None => {}
        }
        RenderAction::Draw
    }

    fn handle_projection_sidebar_key(
        &mut self,
        view_index: usize,
        key: &KeyEvent,
    ) -> anyhow::Result<RenderAction> {
        if key.code == KeyCode::Esc {
            self.focus = FocusTarget::Pane;
            return Ok(RenderAction::Draw);
        }
        let rows = self.projection_rows(view_index);
        let actions = self.sidebar_action_rows(view_index);
        let selectable_rows = rows.len().saturating_add(actions.len());
        let current = self
            .config
            .sidebar
            .views
            .get(view_index)
            .and_then(|view| self.projection_rails.get(&view.id))
            .map_or(0, |state| match state.selected_action {
                Some(index) if index < actions.len() => rows.len().saturating_add(index),
                Some(_) => selectable_rows,
                None => state.selected.min(selectable_rows.saturating_sub(1)),
            });
        let selected = rows.get(current).cloned();
        if matches!(key.code, KeyCode::Left | KeyCode::Char('h')) {
            if !key.modifiers.contains(KeyModifiers::ALT)
                && let Some(branch) = selected.as_ref().and_then(|row| row.branch)
                && selected.as_ref().is_some_and(|row| row.expanded)
            {
                self.projection_rail_state_mut(view_index).collapsed.insert(branch);
            } else {
                self.focus_adjacent_rail(RailKind::Projection(view_index), -1);
            }
            return Ok(RenderAction::Draw);
        }
        if matches!(key.code, KeyCode::Right | KeyCode::Char('l')) {
            if !key.modifiers.contains(KeyModifiers::ALT)
                && let Some(branch) = selected.as_ref().and_then(|row| row.branch)
                && selected.as_ref().is_some_and(|row| !row.expanded)
            {
                self.projection_rail_state_mut(view_index).collapsed.remove(&branch);
            } else if !self.focus_adjacent_rail(RailKind::Projection(view_index), 1) {
                self.focus = FocusTarget::Pane;
            }
            return Ok(RenderAction::Draw);
        }
        let page = self
            .projection_sidebar_area(view_index)
            .map_or(1, |area| usize::from(area.height.saturating_sub(2)).max(1));
        if let Some(next) = rail_navigation_index(key, current, selectable_rows, page) {
            let state = self.projection_rail_state_mut(view_index);
            if next < rows.len() {
                state.selected = next;
                state.selected_action = None;
            } else {
                state.selected_action = Some(next.saturating_sub(rows.len()));
            }
            state.follow_selection = true;
            return Ok(RenderAction::Draw);
        }
        if matches!(key.code, KeyCode::Char(' '))
            && let Some(branch) = selected.as_ref().and_then(|row| row.branch)
        {
            let state = self.projection_rail_state_mut(view_index);
            if !state.collapsed.remove(&branch) {
                state.collapsed.insert(branch);
            }
            return Ok(RenderAction::Draw);
        }
        if key.code == KeyCode::Enter {
            if let Some(row) = selected {
                self.activate_projection_target(row.target)?;
                self.focus = FocusTarget::Pane;
            } else if let Some(action) = current
                .checked_sub(rows.len())
                .and_then(|index| actions.get(index))
                .map(|action| action.target)
            {
                return self.invoke_sidebar_action(action);
            }
        }
        Ok(RenderAction::Draw)
    }

    fn open_machine_creation_menu(&mut self, x: u16, y: u16) {
        let sources =
            self.machine_ui.as_ref().map(|ui| ui.creation_sources.clone()).unwrap_or_default();
        match sources.as_slice() {
            [] => {
                if let Some(ui) = self.machine_ui.as_mut() {
                    ui.request = Some(MachineRequest::Create);
                }
            }
            [source] => {
                if let Some(ui) = self.machine_ui.as_mut() {
                    ui.request = Some(MachineRequest::CreateFrom { source_id: source.id.clone() });
                }
            }
            _ => {
                let items = sources
                    .iter()
                    .enumerate()
                    .map(|(index, source)| MenuItem::LabeledAction {
                        label: if source.subtitle.is_empty() {
                            source.name.clone()
                        } else {
                            format!("{} · {}", source.name, source.subtitle)
                        },
                        action: MenuAction::CreateMachineFrom(index),
                    })
                    .collect::<Vec<_>>();
                self.menu = Some(ContextMenu::with_groups(x, y, vec![items]));
                self.capture_menu_resources();
            }
        }
    }

    fn open_machine_connection_menu(&mut self, x: u16, y: u16) {
        if self.machine_ui.as_ref().is_some_and(|ui| ui.connect_accepts_pairing_code) {
            let prompt = self.connect_machine_prompt();
            self.prompt = Some(prompt);
            return;
        }
        let targets =
            self.machine_ui.as_ref().map(|ui| ui.connection_targets.clone()).unwrap_or_default();
        if targets.is_empty() {
            let prompt = self.connect_machine_prompt();
            self.prompt = Some(prompt);
            return;
        }
        let targets = targets
            .iter()
            .enumerate()
            .map(|(index, target)| MenuItem::LabeledAction {
                label: target.name.clone(),
                action: MenuAction::ConnectMachineTarget(index),
            })
            .collect::<Vec<_>>();
        let messages = &localization::catalog().sidebar;
        self.menu = Some(ContextMenu::searchable(
            x,
            y,
            messages.ssh_hosts,
            messages.type_to_filter,
            targets,
            vec![MenuItem::Action(MenuAction::ConnectOtherMachine)],
        ));
        self.capture_menu_resources();
    }

    fn connect_machine_prompt(&mut self) -> Prompt {
        let messages = &localization::catalog().sidebar;
        let (label, route) =
            if self.machine_ui.as_ref().is_some_and(|ui| ui.connect_accepts_pairing_code) {
                (messages.connect_prompt, MachineConnectRoute::Provider)
            } else {
                (messages.connect_host_prompt, MachineConnectRoute::Local)
            };
        self.connection_transaction = Some(ConnectionTransaction {
            attempt: self.next_connection_attempt,
            target: String::new(),
            route,
            phase: ConnectionDialogPhase::Editing,
        });
        Prompt::new(label, String::new(), PromptTarget::ConnectMachine(route))
    }

    fn begin_machine_connection(&mut self, target: String, route: MachineConnectRoute) {
        let target = target.trim().to_string();
        if target.is_empty() {
            return;
        }
        if let Some(ConnectionTransaction { phase: ConnectionDialogPhase::Failed(error), .. }) =
            self.connection_transaction.as_ref()
            && self.status_message.as_deref() == Some(error.as_str())
        {
            self.status_message = None;
            self.status_selection = None;
        }
        let attempt = self.next_connection_attempt;
        self.next_connection_attempt = self.next_connection_attempt.wrapping_add(1).max(1);
        self.connection_transaction = Some(ConnectionTransaction {
            attempt,
            target: target.clone(),
            route,
            phase: ConnectionDialogPhase::Connecting,
        });
        let label = match route {
            MachineConnectRoute::Local => localization::catalog().sidebar.connect_host_prompt,
            MachineConnectRoute::Provider => localization::catalog().sidebar.connect_prompt,
        };
        self.prompt = Some(Prompt::new(label, target.clone(), PromptTarget::ConnectMachine(route)));
        if let Some(machine) = self.machine_ui.as_mut() {
            machine.request = Some(MachineRequest::Connect { target, route });
        }
    }

    fn retry_machine_connection(&mut self) {
        let Some(transaction) = self.connection_transaction.clone() else { return };
        self.begin_machine_connection(transaction.target, transaction.route);
    }

    fn copy_connection_error(&mut self) {
        let Some(ConnectionTransaction { phase: ConnectionDialogPhase::Failed(error), .. }) =
            self.connection_transaction.as_ref()
        else {
            return;
        };
        let error = error.clone();
        self.copy_text_to_clipboard(&error);
        self.show_toast(localization::catalog().menu.copied.to_string());
    }

    /// Open the provider scope/actions menu near (x, y). The active scope
    /// starts selected, exactly like the removed dedicated scope row, so a
    /// plain Enter never switches scope by accident. False when the provider
    /// offers nothing to show.
    fn open_provider_rail_menu(&mut self, x: u16, y: u16) -> bool {
        let scopes = self.provider_scope_menu_items();
        let selected_scope = if scopes.is_empty() {
            None
        } else {
            self.machine_ui.as_ref().and_then(|ui| ui.provider.as_ref()).and_then(|provider| {
                provider.scopes.iter().position(|scope| scope.id == provider.selected_scope_id)
            })
        };
        let actions = self.provider_actions_menu_items();
        if scopes.is_empty() && actions.is_empty() {
            return false;
        }
        let has_scopes = !scopes.is_empty();
        let mut groups = Vec::new();
        if !scopes.is_empty() {
            groups.push(scopes);
        }
        if !actions.is_empty() {
            groups.push(actions);
        }
        groups.push(self.global_menu_items());
        let mut menu = ContextMenu::with_groups(x, y, groups);
        if let (Some(level), Some(selected)) = (menu.levels.first_mut(), selected_scope) {
            level.selected = selected;
            level.ensure_selection_visible();
        } else if !has_scopes {
            // One scope is not a switch choice. Keep the combined menu inert
            // until the user moves or clicks, so Enter cannot invoke its
            // first provider action as a side effect of opening the menu.
            if let Some(level) = menu.levels.first_mut() {
                level.selection_active = false;
            }
        }
        self.menu = Some(menu);
        self.capture_menu_resources();
        true
    }

    /// Scope-switch entries for the provider rail menu. Empty when only one
    /// scope exists (nothing to switch to).
    fn provider_scope_menu_items(&self) -> Vec<MenuItem> {
        let messages = &localization::catalog().sidebar;
        let Some(provider) = self.machine_ui.as_ref().and_then(|ui| ui.provider.as_ref()) else {
            return Vec::new();
        };
        if provider.scopes.len() < 2 {
            return Vec::new();
        }
        provider
            .scopes
            .iter()
            .enumerate()
            .map(|(index, scope)| {
                let selected = scope.id == provider.selected_scope_id;
                let kind = match scope.kind {
                    crate::machine::ProviderScopeKind::Personal => messages.personal_scope,
                    crate::machine::ProviderScopeKind::Team => messages.team_scope,
                };
                let marker = if selected { "✓ " } else { "  " };
                MenuItem::LabeledAction {
                    label: format!("{marker}{} ({kind})", scope.name),
                    action: MenuAction::SelectProviderScope(index),
                }
            })
            .collect()
    }

    fn provider_actions_menu_items(&self) -> Vec<MenuItem> {
        let Some(provider) = self.machine_ui.as_ref().and_then(|ui| ui.provider.as_ref()) else {
            return Vec::new();
        };
        provider
            .actions
            .iter()
            .enumerate()
            .map(|(index, action)| MenuItem::LabeledAction {
                label: if action.destructive {
                    format!(
                        "⚠ {}",
                        localization::catalog()
                            .sidebar
                            .provider_action_label(&action.id)
                            .unwrap_or(action.label.as_str())
                    )
                } else {
                    localization::catalog()
                        .sidebar
                        .provider_action_label(&action.id)
                        .map(str::to_owned)
                        .unwrap_or_else(|| action.label.clone())
                },
                action: MenuAction::InvokeProviderAction(index),
            })
            .collect()
    }

    fn begin_provider_action(&mut self, index: usize) {
        let Some(action) = self
            .machine_ui
            .as_ref()
            .and_then(|ui| ui.provider.as_ref())
            .and_then(|provider| provider.actions.get(index))
            .cloned()
        else {
            return;
        };
        match action.fields.as_slice() {
            [] => self.stage_provider_action(index, None),
            [field] => {
                self.prompt = Some(Prompt::new(
                    localization::catalog()
                        .sidebar
                        .provider_action_field_label(&action.id, &field.id)
                        .map(str::to_owned)
                        .unwrap_or_else(|| field.label.clone()),
                    String::new(),
                    PromptTarget::ProviderAction(index),
                ));
            }
            _ => {
                self.status_message = Some(
                    localization::catalog().sidebar.action_multiple_fields_unsupported.to_string(),
                );
            }
        }
    }

    fn provider_action_context(&self) -> ProviderActionContext {
        let Some(ui) = self.machine_ui.as_ref() else {
            return ProviderActionContext::default();
        };
        let Some(active) = ui.snapshot.active.filter(|active| ui.is_provider_machine(*active))
        else {
            return ProviderActionContext::default();
        };
        let machine_id = ui
            .snapshot
            .machines
            .iter()
            .find(|machine| machine.key == active)
            .map(|machine| machine.id.clone());
        // Provider runtimes expose a session only while its machine matches
        // the active provider machine. That ownership is sufficient for
        // session-created workspaces that have no lifecycle-catalog entry.
        let workspace_id = if ui.session_available {
            self.tree
                .active_workspace()
                .map(|workspace| workspace.key.clone())
                .filter(|id| !id.is_empty())
        } else {
            None
        };
        ProviderActionContext { machine_id, workspace_id }
    }

    fn bound_provider_action(
        &self,
        index: usize,
        input: Option<&str>,
    ) -> Option<Result<(MachineRequest, bool), ProviderActionInputError>> {
        let context = self.provider_action_context();
        self.machine_ui
            .as_ref()
            .and_then(|ui| ui.provider.as_ref())
            .and_then(|provider| provider.actions.get(index))
            .map(|action| {
                action.request(input, &context).map(|request| (request, action.destructive))
            })
    }

    fn stage_provider_action(&mut self, index: usize, input: Option<&str>) {
        let result = self.bound_provider_action(index, input);
        match result {
            Some(Ok((request, true))) => {
                self.pending_provider_action = Some(request);
                self.prompt = Some(Prompt::new(
                    localization::catalog().sidebar.confirm_destructive_action,
                    String::new(),
                    PromptTarget::ConfirmProviderAction,
                ));
            }
            Some(Ok((request, false))) => {
                if let Some(ui) = self.machine_ui.as_mut() {
                    ui.request = Some(request);
                }
            }
            Some(Err(error)) => {
                self.status_message = Some(provider_action_error_message(error).to_string());
            }
            None => {}
        }
    }

    fn handle_builtin_sidebar_key(&mut self, key: &KeyEvent) -> anyhow::Result<RenderAction> {
        if key.code == KeyCode::Tab {
            return self.run_action(Action::ToggleSidebarView);
        }
        if matches!(key.code, KeyCode::Left | KeyCode::Char('h')) {
            let moved = self.focus_adjacent_rail(RailKind::Workspace, -1);
            if moved
                || self.sidebar_view == SidebarView::Workspaces
                || key.modifiers.contains(KeyModifiers::ALT)
            {
                return Ok(RenderAction::Draw);
            }
        }
        if (self.sidebar_view == SidebarView::Workspaces
            || key.modifiers.contains(KeyModifiers::ALT))
            && matches!(key.code, KeyCode::Right | KeyCode::Char('l'))
        {
            if !self.focus_adjacent_rail(RailKind::Workspace, 1) {
                self.focus = FocusTarget::Pane;
            }
            return Ok(RenderAction::Draw);
        }
        if key.code == KeyCode::Esc {
            self.focus = FocusTarget::Pane;
            return Ok(RenderAction::Draw);
        }
        match self.sidebar_view {
            SidebarView::Files => {
                if let Some(command) = self.sidebar_files.handle_key(key) {
                    self.run_file_command(command);
                }
            }
            SidebarView::Workspaces => {
                if matches!(
                    key.code,
                    KeyCode::Up
                        | KeyCode::Down
                        | KeyCode::Char('j' | 'k')
                        | KeyCode::Home
                        | KeyCode::End
                        | KeyCode::PageUp
                        | KeyCode::PageDown
                ) {
                    self.workspace_rail_follow_selection = true;
                }
                let targets = self.workspace_rail_targets();
                let current = self
                    .workspace_rail_target()
                    .and_then(|selected| targets.iter().position(|target| target == &selected))
                    .unwrap_or_default();
                let page = rail_page_size(self.sidebar_layout.workspace);
                if let Some(next) = rail_navigation_index(key, current, targets.len(), page) {
                    if let Some(target) = targets.get(next).cloned() {
                        self.select_workspace_rail_target(target);
                    }
                } else if key.code == KeyCode::Enter {
                    match targets.get(current).cloned() {
                        Some(WorkspaceRailTarget::Workspace(id)) => {
                            if let Some(index) =
                                self.tree.workspaces.iter().position(|workspace| workspace.id == id)
                            {
                                self.select_workspace_for_client(Some(index), None);
                                self.focus = FocusTarget::Pane;
                            }
                        }
                        Some(WorkspaceRailTarget::Action(action)) => {
                            return self.invoke_sidebar_action(action);
                        }
                        Some(WorkspaceRailTarget::Recoverable(id)) => {
                            self.request_restore_managed_workspace(&id);
                            self.focus = FocusTarget::Pane;
                        }
                        None => {}
                    }
                }
            }
        }
        Ok(RenderAction::Draw)
    }

    fn handle_tabs_sidebar_key(&mut self, key: &KeyEvent) -> anyhow::Result<RenderAction> {
        if matches!(key.code, KeyCode::Left | KeyCode::Char('h')) {
            self.focus_adjacent_rail(RailKind::Tabs, -1);
            return Ok(RenderAction::Draw);
        }
        if matches!(key.code, KeyCode::Right | KeyCode::Char('l')) {
            if !self.focus_adjacent_rail(RailKind::Tabs, 1) {
                self.focus = FocusTarget::Pane;
            }
            return Ok(RenderAction::Draw);
        }
        if key.code == KeyCode::Esc {
            self.focus = FocusTarget::Pane;
            return Ok(RenderAction::Draw);
        }
        if matches!(
            key.code,
            KeyCode::Up
                | KeyCode::Down
                | KeyCode::Char('j' | 'k')
                | KeyCode::Home
                | KeyCode::End
                | KeyCode::PageUp
                | KeyCode::PageDown
        ) {
            self.tabs_rail_follow_selection = true;
        }
        let targets = self.sidebar_tab_targets();
        self.tabs_rail_selection = self.tabs_rail_selection.min(targets.len().saturating_sub(1));
        let page = rail_page_size(self.sidebar_layout.tabs);
        if let Some(next) =
            rail_navigation_index(key, self.tabs_rail_selection, targets.len(), page)
        {
            self.tabs_rail_selection = next;
        } else if key.code == KeyCode::Enter
            && let Some(target) = targets.get(self.tabs_rail_selection)
        {
            self.activate_sidebar_tab(target)?;
            self.focus = FocusTarget::Pane;
        }
        Ok(RenderAction::Draw)
    }

    fn run_file_command(&mut self, command: FileCommand) {
        if !self.session_available() {
            self.sidebar_files.set_message(localization::catalog().sidebar.no_active_session);
            return;
        }
        let result = match command {
            FileCommand::Reroot => {
                let cwd = self
                    .focused_surface_cwd()
                    .unwrap_or_else(|| self.sidebar_files.fallback_cwd().to_path_buf());
                self.sidebar_files.reroot(cwd);
                self.sidebar_followed_surface = self.tree.active_surface();
                return;
            }
            FileCommand::Cd(path) => {
                let Some(surface_id) = self.active_surface() else {
                    self.sidebar_files
                        .set_message(localization::catalog().sidebar.file_no_focused_pane);
                    return;
                };
                let Some(surface) = self.session.surface(surface_id) else {
                    self.sidebar_files
                        .set_message(localization::catalog().sidebar.file_surface_unavailable);
                    return;
                };
                let quoted = shell_single_quote(&path.to_string_lossy());
                let bytes = format!("cd {quoted}\n");
                if self.write_pty_bytes(
                    surface_id,
                    surface,
                    PtyInputBytes::from_slice(bytes.as_bytes()),
                    PtyInputKind::Ordered,
                ) {
                    Ok(())
                } else {
                    Err(anyhow::anyhow!(localization::catalog().sidebar.file_input_not_queued))
                }
            }
            FileCommand::OpenEditor(path) => {
                let editor = std::env::var("EDITOR")
                    .ok()
                    .filter(|value| !value.is_empty())
                    .unwrap_or_else(|| "vi".to_string());
                let cwd = path
                    .parent()
                    .unwrap_or_else(|| std::path::Path::new("/"))
                    .to_string_lossy()
                    .into_owned();
                self.session.run_command(
                    vec![editor, path.to_string_lossy().into_owned()],
                    self.active_pane(),
                    Some(cwd),
                    self.terminal_tab_size_hint(self.active_pane()),
                )
            }
            FileCommand::OpenBrowser(path) => self.session.new_browser_tab(
                file_url(&path),
                self.active_pane(),
                self.browser_tab_size_hint(self.active_pane()),
            ),
        };
        match result {
            Ok(()) => self
                .sidebar_files
                .set_message(localization::catalog().sidebar.file_sent_to_focused_pane),
            Err(error) => self.sidebar_files.set_message(
                localization::catalog()
                    .sidebar
                    .file_command_failed
                    .replace("{error}", &error.to_string()),
            ),
        }
    }

    /// Commit the open rename dialog (Enter or the OK button).
    fn commit_prompt(&mut self) {
        if let Some((route, input)) = self.prompt.as_ref().and_then(|prompt| {
            matches!(prompt.target, PromptTarget::ConnectMachine(_)).then(|| {
                let PromptTarget::ConnectMachine(route) = prompt.target else { unreachable!() };
                (route, prompt.input.as_str().to_string())
            })
        }) {
            self.begin_machine_connection(input, route);
            return;
        }
        let Some(prompt) = self.take_prompt() else { return };
        let input = prompt.input.as_str().to_string();
        if let PromptTarget::ClientMachine(key) = prompt.target {
            if !input.trim().is_empty() {
                self.request_rename_client_machine(key, input);
            }
            return;
        }
        if let PromptTarget::ManagedMachine(key) = prompt.target {
            if !input.is_empty() {
                self.request_rename_managed_machine(key, input);
            }
            return;
        }
        if let PromptTarget::ConfirmDeleteManagedMachine(key) = prompt.target {
            if input.trim() == "CONFIRM" {
                self.request_delete_managed_machine(key);
            } else {
                self.status_message =
                    Some(localization::catalog().sidebar.confirmation_mismatch.to_string());
                self.prompt = Some(prompt);
                self.shake_frames = 6;
            }
            return;
        }
        if let PromptTarget::ConfirmPurgeManagedMachine(key) = prompt.target {
            if input.trim() == "CONFIRM" {
                self.request_purge_managed_machine(key);
            } else {
                self.status_message =
                    Some(localization::catalog().sidebar.confirmation_mismatch.to_string());
                self.prompt = Some(prompt);
                self.shake_frames = 6;
            }
            return;
        }
        if let PromptTarget::ProviderAction(index) = prompt.target {
            let result = self.bound_provider_action(index, Some(&input));
            match result {
                Some(Ok((request, true))) => {
                    self.pending_provider_action = Some(request);
                    self.prompt = Some(Prompt::new(
                        localization::catalog().sidebar.confirm_destructive_action,
                        String::new(),
                        PromptTarget::ConfirmProviderAction,
                    ));
                }
                Some(Ok((request, false))) => {
                    if let Some(ui) = self.machine_ui.as_mut() {
                        ui.request = Some(request);
                    }
                }
                Some(Err(error)) => {
                    self.status_message = Some(provider_action_error_message(error).to_string());
                    self.prompt = Some(prompt);
                    self.shake_frames = 6;
                }
                None => {}
            }
            return;
        }
        if let PromptTarget::ConfirmProviderAction = prompt.target {
            if input.trim() == "CONFIRM" {
                if let (Some(request), Some(ui)) =
                    (self.pending_provider_action.take(), self.machine_ui.as_mut())
                {
                    ui.request = Some(request);
                }
            } else {
                self.status_message =
                    Some(localization::catalog().sidebar.confirmation_mismatch.to_string());
                self.prompt = Some(prompt);
                self.shake_frames = 6;
            }
            return;
        }
        if let PromptTarget::ManagedWorkspace(id) = prompt.target {
            if !input.is_empty() {
                self.request_rename_managed_workspace(id, input);
            }
            return;
        }
        if let PromptTarget::ConfirmPurgeManagedWorkspace(index) = prompt.target {
            if input.trim() == "CONFIRM" {
                let workspace_id = self
                    .machine_ui
                    .as_ref()
                    .and_then(|ui| ui.recoverable_workspaces().get(index).copied())
                    .map(|workspace| workspace.id.clone());
                if let Some(workspace_id) = workspace_id {
                    self.request_purge_managed_workspace(&workspace_id);
                }
            } else {
                self.status_message =
                    Some(localization::catalog().sidebar.confirmation_mismatch.to_string());
                self.prompt = Some(prompt);
                self.shake_frames = 6;
            }
            return;
        }
        if let PromptTarget::ConfirmLayoutUndo { pane, revision } = prompt.target {
            if input.trim() != "CONFIRM" {
                self.status_message =
                    Some(localization::catalog().sidebar.confirmation_mismatch.to_string());
                self.prompt = Some(prompt);
                self.shake_frames = 6;
                return;
            }
            if !self.prepare_pty_input_before_mutation() {
                self.prompt = Some(prompt);
                return;
            }
            if let Err(error) = self.session.undo_layout(pane, Some(revision), true) {
                self.status_message = Some(
                    localization::catalog()
                        .sidebar
                        .layout_undo_failed
                        .replace("{error}", &error.to_string()),
                );
            }
            return;
        }
        if !self.prepare_pty_input_before_mutation() {
            return;
        }
        match prompt.target {
            PromptTarget::Workspace(id) => {
                if !input.is_empty() {
                    self.request_rename_workspace(id, input);
                }
            }
            // Empty screen/tab names clear back to the default.
            PromptTarget::Screen(id) => self.session.rename_screen(id, input),
            PromptTarget::Surface(id) => self.session.rename_surface(id, input),
            PromptTarget::ConnectMachine(_)
            | PromptTarget::ClientMachine(_)
            | PromptTarget::ManagedMachine(_)
            | PromptTarget::ConfirmDeleteManagedMachine(_)
            | PromptTarget::ConfirmPurgeManagedMachine(_)
            | PromptTarget::ProviderAction(_)
            | PromptTarget::ConfirmProviderAction
            | PromptTarget::ManagedWorkspace(_)
            | PromptTarget::ConfirmPurgeManagedWorkspace(_)
            | PromptTarget::ConfirmLayoutUndo { .. } => {
                unreachable!("handled before session mutation")
            }
        }
    }

    fn take_prompt(&mut self) -> Option<Prompt> {
        self.shake_frames = 0;
        self.prompt.take()
    }

    fn close_prompt(&mut self) {
        self.shake_frames = 0;
        self.prompt = None;
        if let Some(transaction) = self.connection_transaction.take() {
            if let Some(machine) = self.machine_ui.as_mut()
                && machine.request.as_ref().is_some_and(|request| {
                    matches!(
                        request,
                        MachineRequest::Connect { target, route }
                            if target == &transaction.target && route == &transaction.route
                    )
                })
            {
                machine.request = None;
            }
            if self.machine_action_connection_attempt == Some(transaction.attempt) {
                self.canceled_machine_connection_attempt = Some(transaction.attempt);
            }
        }
        self.pending_provider_action = None;
    }

    fn handle_prompt_key(&mut self, key: KeyEvent) -> anyhow::Result<RenderAction> {
        if let Some(phase) =
            self.connection_transaction.as_ref().map(|transaction| transaction.phase.clone())
        {
            match phase {
                ConnectionDialogPhase::Editing => {}
                ConnectionDialogPhase::Connecting | ConnectionDialogPhase::Starting => {
                    if key.code == KeyCode::Esc {
                        self.close_prompt();
                    }
                    return Ok(RenderAction::Draw);
                }
                ConnectionDialogPhase::Failed(_) => {
                    match key.code {
                        KeyCode::Enter => self.retry_machine_connection(),
                        KeyCode::Esc => self.close_prompt(),
                        KeyCode::Char('c' | 'C')
                            if key.modifiers.contains(KeyModifiers::CONTROL) =>
                        {
                            self.copy_connection_error();
                        }
                        _ => {}
                    }
                    return Ok(RenderAction::Draw);
                }
            }
        }
        let Some(prompt) = self.prompt.as_mut() else { return Ok(RenderAction::None) };
        match prompt.input.handle_key(&key) {
            InputEvent::Commit => self.commit_prompt(),
            InputEvent::Cancel => self.close_prompt(),
            InputEvent::Changed | InputEvent::None => {}
        }
        Ok(RenderAction::Draw)
    }

    fn handle_prompt_text(&mut self, text: &str) -> anyhow::Result<RenderAction> {
        if self
            .connection_transaction
            .as_ref()
            .is_some_and(|transaction| !matches!(transaction.phase, ConnectionDialogPhase::Editing))
        {
            return Ok(RenderAction::Draw);
        }
        let Some(prompt) = self.prompt.as_mut() else { return Ok(RenderAction::None) };
        prompt.input.insert_str(text);
        Ok(RenderAction::Draw)
    }

    fn resolve_pairing(&mut self, approve: bool) {
        self.cancel_pointer_interaction();
        let Some(dialog) = self.pairing_dialog.take() else { return };
        if let Err(error) = self.session.respond_pairing(dialog.challenge.id, approve) {
            self.status_message = Some(
                localization::catalog()
                    .sidebar
                    .pairing_response_failed
                    .replace("{error}", &error.to_string()),
            );
        }
        self.pairing_dialog = self.pairing_queue.pop_front().map(PairingDialog::new);
    }

    fn handle_pairing_key(&mut self, key: KeyEvent) -> anyhow::Result<RenderAction> {
        match key.code {
            KeyCode::Enter | KeyCode::Char('y') | KeyCode::Char('Y') => self.resolve_pairing(true),
            KeyCode::Esc | KeyCode::Char('n') | KeyCode::Char('N') => self.resolve_pairing(false),
            _ => {}
        }
        Ok(RenderAction::Draw)
    }

    fn handle_shortcut_help_key(&mut self, key: KeyEvent) -> RenderAction {
        let Some(help) = self.shortcut_help.as_mut() else { return RenderAction::None };
        let total_rows = help.rows.len();
        let page = help.visible_rows.max(1) as isize;
        let previous_offset = help.scroll_offset;
        let mut close = false;
        match key.code {
            KeyCode::Esc => close = true,
            KeyCode::Char('?')
                if !key.modifiers.intersects(
                    KeyModifiers::CONTROL | KeyModifiers::ALT | KeyModifiers::SUPER,
                ) =>
            {
                close = true;
            }
            KeyCode::Up | KeyCode::Char('k') => help.scroll_by(-1, total_rows),
            KeyCode::Down | KeyCode::Char('j') => help.scroll_by(1, total_rows),
            KeyCode::PageUp => help.scroll_by(-page, total_rows),
            KeyCode::PageDown => help.scroll_by(page, total_rows),
            KeyCode::Home => help.scroll_offset = 0,
            KeyCode::End => help.scroll_offset = help.max_scroll(total_rows),
            _ => {}
        }
        if close {
            self.shortcut_help = None;
            RenderAction::Paint
        } else if help.scroll_offset != previous_offset {
            RenderAction::Paint
        } else {
            RenderAction::None
        }
    }

    fn handle_shortcut_help_mouse(&mut self, mouse: MouseEvent) -> RenderAction {
        let Some(help) = self.shortcut_help.as_mut() else { return RenderAction::None };
        let total_rows = help.rows.len();
        let mut changed = false;
        let mut close = false;
        match mouse.kind {
            MouseEventKind::ScrollUp | MouseEventKind::ScrollDown => {
                let previous_offset = help.scroll_offset;
                let delta = if mouse.kind == MouseEventKind::ScrollUp { -1 } else { 1 };
                help.scroll_by(delta, total_rows);
                changed = help.scroll_offset != previous_offset;
            }
            MouseEventKind::Down(MouseButton::Left)
                if help.close_button.contains(mouse.column, mouse.row) =>
            {
                close = true;
            }
            MouseEventKind::Down(MouseButton::Left)
                if help.scrollbar_track.contains(mouse.column, mouse.row) =>
            {
                let previous_offset = help.scroll_offset;
                let was_dragging = help.scrollbar_dragging();
                help.start_scrollbar_drag(mouse.row, total_rows);
                changed = help.scroll_offset != previous_offset || !was_dragging;
            }
            MouseEventKind::Drag(MouseButton::Left) => {
                let previous_offset = help.scroll_offset;
                help.drag_scrollbar(mouse.row, total_rows);
                changed = help.scroll_offset != previous_offset;
            }
            MouseEventKind::Up(MouseButton::Left) => {
                changed = help.scrollbar_dragging();
                help.scrollbar_drag = None;
            }
            MouseEventKind::Down(MouseButton::Left | MouseButton::Right)
                if !help.rect.contains(mouse.column, mouse.row) =>
            {
                close = true;
            }
            _ => {}
        }
        if close {
            self.shortcut_help = None;
            RenderAction::Paint
        } else if changed {
            RenderAction::Paint
        } else {
            RenderAction::None
        }
    }

    fn handle_pairing_click(&mut self, x: u16, y: u16) -> anyhow::Result<RenderAction> {
        let Some(dialog) = self.pairing_dialog.as_ref() else { return Ok(RenderAction::None) };
        if dialog.approve.contains(x, y) {
            self.resolve_pairing(true);
        } else if dialog.deny.contains(x, y) || !dialog.rect.contains(x, y) {
            self.resolve_pairing(false);
        }
        Ok(RenderAction::Draw)
    }

    /// Clicks while the rename dialog is open: OK commits, Cancel (or a
    /// click outside the dialog) dismisses; clicks inside are swallowed.
    fn handle_prompt_click(&mut self, x: u16, y: u16) -> anyhow::Result<RenderAction> {
        if let Some(phase) =
            self.connection_transaction.as_ref().map(|transaction| transaction.phase.clone())
        {
            let Some(prompt) = self.prompt.as_ref() else { return Ok(RenderAction::None) };
            match phase {
                ConnectionDialogPhase::Editing => {}
                ConnectionDialogPhase::Connecting | ConnectionDialogPhase::Starting => {
                    if prompt.cancel.contains(x, y) || !prompt.rect.contains(x, y) {
                        self.close_prompt();
                    }
                    return Ok(RenderAction::Draw);
                }
                ConnectionDialogPhase::Failed(_) => {
                    if prompt.ok.contains(x, y) {
                        self.retry_machine_connection();
                    } else if prompt.clear.contains(x, y) {
                        self.copy_connection_error();
                    } else if prompt.cancel.contains(x, y) || !prompt.rect.contains(x, y) {
                        self.close_prompt();
                    }
                    return Ok(RenderAction::Draw);
                }
            }
        }
        let Some(prompt) = self.prompt.as_mut() else { return Ok(RenderAction::None) };
        if prompt.ok.contains(x, y) {
            self.commit_prompt();
        } else if prompt.clear.contains(x, y) {
            prompt.input.clear();
        } else if prompt.input_rect.contains(x, y) {
            let column = x.saturating_sub(prompt.input_rect.x) as usize;
            prompt.input.set_cursor_from_visible_column(column, prompt.input_rect.width as usize);
        } else if prompt.cancel.contains(x, y) || !prompt.rect.contains(x, y) {
            self.close_prompt();
        }
        Ok(RenderAction::Draw)
    }

    fn handle_omnibar_key(&mut self, key: KeyEvent) -> anyhow::Result<RenderAction> {
        let Some(state) = self.omnibar.as_mut() else { return Ok(RenderAction::None) };
        let replace_selection = state.select_all
            && matches!(
                key.code,
                KeyCode::Backspace
                    | KeyCode::Delete
                    | KeyCode::Char(_)
                        if !key.modifiers.intersects(keys::SHORTCUT_MODIFIERS)
            );
        if replace_selection {
            state.input.clear();
            state.select_all = false;
        } else if matches!(
            key.code,
            KeyCode::Left
                | KeyCode::Right
                | KeyCode::Home
                | KeyCode::End
                | KeyCode::Backspace
                | KeyCode::Delete
        ) {
            state.select_all = false;
        }
        if matches!(key.code, KeyCode::Char('a') | KeyCode::Char('A'))
            && key.modifiers.contains(KeyModifiers::CONTROL)
        {
            state.select_all = true;
            state.input.cursor = state.input.buffer.len();
            return Ok(RenderAction::Draw);
        }
        match state.input.handle_key(&key) {
            InputEvent::Cancel => {
                self.omnibar = None;
            }
            InputEvent::Commit => {
                let Some(state) = self.omnibar.take() else { return Ok(RenderAction::Draw) };
                let input = state.input.as_str().trim();
                if input.is_empty() {
                    return Ok(RenderAction::Draw);
                }
                let url = cmux_tui_core::normalize_url(input);
                if !self.prepare_pty_input_before_mutation() {
                    return Ok(RenderAction::None);
                }
                self.enqueue_browser_command(state.surface, BrowserInputKind::Navigate(url));
            }
            InputEvent::Changed | InputEvent::None => {}
        }
        Ok(RenderAction::Draw)
    }

    fn handle_omnibar_text(&mut self, text: &str) -> anyhow::Result<RenderAction> {
        let Some(state) = self.omnibar.as_mut() else { return Ok(RenderAction::None) };
        clear_omnibar_selection(state);
        state.input.insert_str(text);
        Ok(RenderAction::Draw)
    }

    fn handle_menu_key(&mut self, key: KeyEvent) -> anyhow::Result<RenderAction> {
        let Some(menu) = self.menu.as_mut() else { return Ok(RenderAction::None) };
        menu.finish_scrollbar_drag();
        match key.code {
            KeyCode::Esc => {
                if !menu.close_submenu() {
                    self.menu = None;
                }
                Ok(RenderAction::Draw)
            }
            KeyCode::Up => {
                menu.select_previous();
                Ok(RenderAction::Draw)
            }
            KeyCode::Down => {
                menu.select_next();
                Ok(RenderAction::Draw)
            }
            KeyCode::Home => {
                menu.select_first();
                Ok(RenderAction::Draw)
            }
            KeyCode::End => {
                menu.select_last();
                Ok(RenderAction::Draw)
            }
            KeyCode::Left if menu.search.is_some() => {
                menu.handle_search_key(&key);
                Ok(RenderAction::Draw)
            }
            KeyCode::Left => {
                menu.close_submenu();
                Ok(RenderAction::Draw)
            }
            KeyCode::Right if menu.search.is_some() => {
                menu.handle_search_key(&key);
                Ok(RenderAction::Draw)
            }
            KeyCode::Right => {
                menu.open_selected_submenu();
                Ok(RenderAction::Draw)
            }
            KeyCode::Enter => {
                if menu.open_selected_submenu() {
                    return Ok(RenderAction::Draw);
                }
                let Some(action) = menu.selected_action() else { return Ok(RenderAction::Draw) };
                let expected_resource = menu.captured_resource(action);
                self.menu = None;
                if expected_resource
                    .is_none_or(|expected| self.menu_action_resource(action) == expected)
                {
                    self.activate_menu(action)?;
                }
                Ok(RenderAction::Draw)
            }
            _ => {
                menu.handle_search_key(&key);
                Ok(RenderAction::Draw) // swallow while a menu is open
            }
        }
    }

    fn run_resolved_action(
        &mut self,
        action: Action,
        prefix: KeyEvent,
    ) -> anyhow::Result<RenderAction> {
        self.run_resolved_action_with_semantic_intent(action, prefix, None, None, None)
    }

    fn run_resolved_action_with_semantic_intent(
        &mut self,
        action: Action,
        prefix: KeyEvent,
        semantic_intent: Option<u64>,
        action_destination: Option<SurfaceId>,
        action_fallback_destination: Option<SurfaceId>,
    ) -> anyhow::Result<RenderAction> {
        if action == Action::SendPrefix && self.workspace_sidebar_focused() {
            self.forward_sidebar_key(prefix.into());
            return Ok(RenderAction::Draw);
        }
        let pane = match action_destination {
            Some(surface) => self.pane_for_surface(surface),
            None => self.active_pane(),
        };
        let fallback_pane =
            action_fallback_destination.and_then(|surface| self.pane_for_surface(surface));
        let pane = pane.or(fallback_pane);
        if (action_destination.is_some() || action_fallback_destination.is_some()) && pane.is_none()
        {
            if let Some(intent) = semantic_intent {
                self.mark_semantic_destination_failed(intent);
            }
            return Ok(RenderAction::Draw);
        }
        let destination_started = self.session.destination_mutation_started();
        let result = self.run_action_for_pane_with_prefix(
            action,
            pane,
            fallback_pane.filter(|fallback| Some(*fallback) != pane),
            prefix,
            semantic_intent,
        );
        if let Some(intent) = semantic_intent
            && (result.is_err()
                || self.session.destination_mutation_started() == destination_started)
        {
            self.mark_semantic_destination_failed(intent);
        }
        result
    }

    /// Execute one bound action. Shared by the (configurable) prefix keys
    /// and any future command surface.
    fn run_action(&mut self, action: Action) -> anyhow::Result<RenderAction> {
        let prefix = self.config.keys.prefix;
        self.run_resolved_action(action, KeyEvent::new(prefix.code, prefix.mods))
    }

    /// Execute an action against an explicit pane. Context menus use this
    /// shared path because right-clicking does not change keyboard focus.
    fn run_action_for_pane(
        &mut self,
        action: Action,
        pane: Option<PaneId>,
    ) -> anyhow::Result<RenderAction> {
        let prefix = self.config.keys.prefix;
        self.run_action_for_pane_with_prefix(
            action,
            pane,
            None,
            KeyEvent::new(prefix.code, prefix.mods),
            None,
        )
    }

    fn run_action_for_pane_with_prefix(
        &mut self,
        action: Action,
        pane: Option<PaneId>,
        fallback_pane: Option<PaneId>,
        prefix: KeyEvent,
        semantic_intent: Option<u64>,
    ) -> anyhow::Result<RenderAction> {
        if !self.action_available(action) {
            return Ok(RenderAction::Draw);
        }
        if action_prepares_pty_release(action) && !self.prepare_pty_input_before_mutation() {
            return Ok(RenderAction::None);
        }
        match action {
            Action::SendPrefix => {
                self.forward_key_to_pane(&prefix, pane);
            }
            Action::NewTab => {
                self.new_terminal_tab(pane, fallback_pane, semantic_intent)?;
            }
            Action::NewBrowserTab => {
                self.create_browser_tab_for_edit(pane, fallback_pane, semantic_intent)?;
            }
            Action::NewPaneSmart => self.new_pane_smart(pane, fallback_pane, semantic_intent)?,
            Action::NextTab => self.select_tab_for_client(pane, None, Some(1)),
            Action::PrevTab => self.select_tab_for_client(pane, None, Some(-1)),
            Action::SelectTab(_) => {
                if let Some(index) = action.tab_index() {
                    self.select_tab_for_client(pane, Some(index), None);
                }
            }
            Action::SplitRight => {
                if let Some(pane) = pane {
                    self.split_pane(pane, fallback_pane, SplitDir::Right, semantic_intent)?;
                }
            }
            Action::SplitDown => {
                if let Some(pane) = pane {
                    self.split_pane(pane, fallback_pane, SplitDir::Down, semantic_intent)?;
                }
            }
            Action::CloseTab => {
                // Close the active tab; the pane collapses with its last
                // tab, so this is also "close pane" for single-tab panes.
                if let Some(surface) = pane
                    .and_then(|pane| self.tree.pane(pane))
                    .and_then(|pane| pane.active_surface())
                {
                    self.session.close_surface(surface);
                }
            }
            Action::ClosePane => {
                if let Some(pane) = pane {
                    self.session.close_pane(pane);
                }
            }
            Action::RenameTab => self.open_rename_tab_prompt(pane),
            Action::RenameScreen => self.open_rename_screen_prompt(),
            Action::RenameWorkspace => self.open_rename_workspace_prompt(),
            Action::CloseScreen => {
                if let Some(screen) = self.active_screen_id() {
                    self.session.close_screen(screen);
                }
            }
            Action::PrevScreen => self.select_screen_for_client(None, Some(-1)),
            Action::NextScreen => self.select_screen_for_client(None, Some(1)),
            Action::SelectScreen(_) => {
                if let Some(index) = action.screen_index() {
                    self.select_screen_for_client(Some(index), None);
                }
            }
            Action::NewScreen => self.new_screen(semantic_intent)?,
            Action::PrevWorkspace => self.select_workspace_for_client(None, Some(-1)),
            Action::NextWorkspace => self.select_workspace_for_client(None, Some(1)),
            Action::NewWorkspace => self.new_workspace(semantic_intent)?,
            Action::CloseWorkspace => {
                if let Some(workspace) = self.tree.active_workspace().map(|workspace| workspace.id)
                {
                    self.request_delete_workspace(workspace);
                }
            }
            Action::ToggleSidebar => {
                self.sidebar_visible = !self.sidebar_visible;
                if !self.sidebar_visible {
                    self.session.invalidate_sidebar_plugin_sync();
                    self.focus = FocusTarget::Pane;
                }
            }
            Action::ToggleSidebarCompact => {
                self.sidebar_compact = !self.sidebar_compact;
                self.sidebar_visible = true;
            }
            Action::ToggleSidebarView => self.toggle_sidebar_view(),
            Action::FocusSidebar => self.toggle_sidebar_focus(),
            Action::ProviderMenu => {
                if self.focus == FocusTarget::MachineRail {
                    self.open_provider_rail_menu(1, 2);
                }
            }
            Action::NewPaneRight => self.new_pane_right(pane, fallback_pane, semantic_intent)?,
            Action::UndoLayout => {
                if let Some(pane) = pane {
                    self.session.undo_layout(pane, None, false)?;
                }
            }
            Action::FocusLeft => self.move_focus(Direction::Left),
            Action::FocusRight => self.move_focus(Direction::Right),
            Action::FocusUp => self.move_focus(Direction::Up),
            Action::FocusDown => self.move_focus(Direction::Down),
            Action::FocusNextPane => self.focus_next_pane(),
            Action::SwapPanePrev => self.swap_pane_by_order(-1),
            Action::SwapPaneNext => self.swap_pane_by_order(1),
            Action::ZoomPane => self.session.zoom_pane(pane),
            Action::ResizeGrow => self.resize_focused_split(0.05),
            Action::ResizeShrink => self.resize_focused_split(-0.05),
            Action::ScrollUp => self.scroll_active(-10),
            Action::ScrollDown => self.scroll_active(10),
            Action::ClearHistory => {
                if let Some(surface) = self.active_surface()
                    && self.tree.surface_kind(surface) == SurfaceKind::Pty
                {
                    self.session.clear_history(
                        surface,
                        self.input_revision,
                        self.selection,
                        self.selection_generation,
                    );
                }
                return Ok(RenderAction::None);
            }
            Action::BrowserBack => {
                self.enqueue_active_browser_command(BrowserInputKind::Back);
                return Ok(RenderAction::Draw);
            }
            Action::BrowserForward => {
                self.enqueue_active_browser_command(BrowserInputKind::Forward);
                return Ok(RenderAction::Draw);
            }
            Action::BrowserReload => {
                self.enqueue_active_browser_command(BrowserInputKind::Reload);
                return Ok(RenderAction::Draw);
            }
            Action::BrowserEditUrl => {
                if let Some(pane) = pane {
                    self.focus_omnibar(pane);
                }
                return Ok(RenderAction::Draw);
            }
            Action::ShowShortcuts => {
                self.shortcut_help = if self.shortcut_help.is_some() {
                    None
                } else {
                    self.finish_active_drag();
                    Some(ShortcutHelp::from_config(&self.config, self.surface_only.is_some()))
                };
                self.menu = None;
                self.prompt = None;
                self.omnibar = None;
                self.replace_selection(None);
                return Ok(RenderAction::Draw);
            }
            Action::Detach => {
                // Only a session hosted inside this process ends with the
                // TUI; a session owned elsewhere (detached local owner or
                // remote daemon) keeps running after this client leaves.
                self.quit = true;
                return Ok(RenderAction::None);
            }
            Action::UserCommand(_) => {
                if let Some(index) = action.user_command_index() {
                    self.run_user_command(index, pane)?;
                }
            }
        }
        if !self.status_message_hovered() {
            self.status_message = None;
        }
        Ok(RenderAction::Draw)
    }

    fn open_rename_tab_prompt(&mut self, pane: Option<PaneId>) {
        let Some(pane) = pane else { return };
        let Some(surface) = self
            .tree
            .pane(pane)
            .and_then(|pane| pane.tabs.get(pane.active_tab))
            .map(|tab| tab.surface)
        else {
            return;
        };
        self.open_rename_surface_prompt(surface);
    }

    fn open_rename_surface_prompt(&mut self, surface: SurfaceId) {
        let Some(buffer) = self
            .tree
            .workspaces
            .iter()
            .flat_map(|workspace| workspace.screens.iter())
            .flat_map(|screen| screen.panes.iter())
            .flat_map(|pane| pane.tabs.iter())
            .find(|tab| tab.surface == surface)
            .map(|tab| tab.name.clone().unwrap_or_default())
        else {
            return;
        };
        let prompt = Prompt::new(
            localization::catalog().action_label(Action::RenameTab),
            buffer,
            PromptTarget::Surface(surface),
        );
        self.cancel_pty_mouse_drag();
        self.prompt = Some(prompt);
    }

    fn open_rename_workspace_prompt(&mut self) {
        let Some(workspace_id) = self.tree.active_workspace().map(|workspace| workspace.id) else {
            return;
        };
        self.open_rename_workspace_prompt_for(workspace_id);
    }

    fn open_rename_workspace_prompt_for(&mut self, workspace_id: WorkspaceId) {
        let Some(buffer) = self
            .tree
            .workspaces
            .iter()
            .find(|ws| ws.id == workspace_id)
            .map(|workspace| workspace.name.clone())
        else {
            return;
        };
        let provider_managed = self.provider_manages_current_workspace_session();
        let target = if provider_managed {
            if self.machine_ui.as_ref().and_then(|ui| ui.snapshot.active).is_none() {
                self.reject_inactive_managed_workspace_machine();
                return;
            }
            let Some(managed) = self.managed_workspace_for_view(workspace_id) else {
                self.reject_unavailable_managed_workspace_operation();
                return;
            };
            if !managed.capabilities.rename {
                self.reject_disallowed_managed_workspace_operation();
                return;
            }
            PromptTarget::ManagedWorkspace(workspace_id)
        } else {
            PromptTarget::Workspace(workspace_id)
        };
        let prompt = Prompt::new(localization::catalog().sidebar.rename_workspace, buffer, target);
        self.cancel_pty_mouse_drag();
        self.prompt = Some(prompt);
    }

    fn open_rename_screen_prompt(&mut self) {
        let Some(ws) = self.tree.active_workspace() else { return };
        let Some(screen) = ws.active_screen_ref() else { return };
        let buffer = screen.name.clone().unwrap_or_default();
        let prompt = Prompt::new(
            localization::catalog().action_label(Action::RenameScreen),
            buffer,
            PromptTarget::Screen(screen.id),
        );
        self.cancel_pty_mouse_drag();
        self.prompt = Some(prompt);
    }

    fn browser_tab_size_hint(&self, pane: Option<PaneId>) -> Option<(u16, u16)> {
        match pane {
            Some(pane) => self.pane_areas.iter().find(|area| area.pane == pane).and_then(|area| {
                browser_content_size_for_rect(
                    area.logical_rect(),
                    self.config.scrollbar.position,
                    self.config.pane.padding,
                )
            }),
            None => self
                .active_pane()
                .and_then(|pane| self.browser_tab_size_hint(Some(pane)))
                .or_else(|| {
                    browser_content_size_for_rect(
                        self.content_area,
                        self.config.scrollbar.position,
                        self.config.pane.padding,
                    )
                }),
        }
    }

    fn create_browser_tab_for_edit(
        &mut self,
        pane: Option<PaneId>,
        fallback_pane: Option<PaneId>,
        semantic_intent: Option<u64>,
    ) -> anyhow::Result<()> {
        if !self.prepare_pty_input_before_mutation() {
            return Ok(());
        }
        let pane = pane.or_else(|| self.active_pane());
        let selector_candidates = pane
            .map(|pane| self.pane_creation_selector_candidates(pane, fallback_pane))
            .transpose()?
            .unwrap_or_default();
        self.session.new_browser_tab_for_semantic_intent(
            "about:blank".to_string(),
            pane,
            self.browser_tab_size_hint(pane),
            selector_candidates,
            semantic_intent,
        )
    }

    fn focus_omnibar(&mut self, pane: PaneId) {
        let Some(surface_id) = self.tree.pane(pane).and_then(|pane| pane.active_surface()) else {
            return;
        };
        let Some(surface) = self.session.surface(surface_id) else { return };
        if surface.kind() != SurfaceKind::Browser {
            return;
        }
        let buffer = surface.browser_url().unwrap_or_default();
        self.focus_omnibar_with_buffer(pane, buffer, true);
    }

    fn focus_omnibar_with_buffer(&mut self, pane: PaneId, buffer: String, select_all: bool) {
        let Some(surface) = self.tree.pane(pane).and_then(|pane| pane.active_surface()) else {
            return;
        };
        if self.tree.surface_kind(surface) != SurfaceKind::Browser {
            return;
        }
        let Some(area) = self.pane_areas.iter().find(|area| area.pane == pane) else {
            return;
        };
        let has_omnibar = if area.surface == surface {
            area.omnibar.is_some()
        } else {
            let (_, omnibar, _, _) = pane_parts_for_rect(
                area.rect,
                self.config.scrollbar.position,
                self.config.pane.padding,
                true,
            );
            omnibar.is_some()
        };
        if !has_omnibar {
            return;
        }
        self.omnibar =
            Some(OmnibarState { pane, surface, input: TextInput::new(buffer), select_all });
    }

    fn browser_surface_for_pane(&self, pane: PaneId) -> anyhow::Result<(SurfaceId, SurfaceHandle)> {
        let Some(surface_id) = self.tree.pane(pane).and_then(|pane| pane.active_surface()) else {
            anyhow::bail!("pane has no active surface");
        };
        let Some(surface) = self.session.surface(surface_id) else {
            anyhow::bail!("unknown surface {surface_id}");
        };
        if surface.kind() != SurfaceKind::Browser {
            anyhow::bail!("active surface is not a browser");
        }
        Ok((surface_id, surface))
    }

    /// Dispatch a discrete browser control command (navigate/back/forward/
    /// reload/activate). Unlike disposable input, a full dispatcher queue
    /// (worker wedged in a blocking browser call) must not drop the command
    /// silently: surface backpressure through the status line so the user
    /// knows the action did not take effect.
    fn dispatch_browser_control(
        &mut self,
        surface_id: SurfaceId,
        surface: SurfaceHandle,
        kind: BrowserInputKind,
    ) {
        if self.browser_input.enqueue(BrowserInputEvent { surface_id, surface, kind }) {
            if !self.status_message_hovered() {
                self.status_message = None;
            }
        } else {
            self.status_message = Some(localization::catalog().browser.busy.to_string());
        }
    }

    fn enqueue_active_browser_command(&mut self, kind: BrowserInputKind) {
        let Some((surface_id, surface)) = self.active_surface_with_handle() else {
            self.status_message =
                Some(localization::catalog().browser.no_active_surface.to_string());
            return;
        };
        if surface.kind() != SurfaceKind::Browser {
            self.status_message = Some(localization::catalog().browser.not_browser.to_string());
            return;
        }
        self.dispatch_browser_control(surface_id, surface, kind);
    }

    fn enqueue_browser_command_for_pane(&mut self, pane: PaneId, kind: BrowserInputKind) {
        match self.browser_surface_for_pane(pane) {
            Ok((surface_id, surface)) => {
                self.dispatch_browser_control(surface_id, surface, kind);
            }
            Err(err) => self.status_message = Some(err.to_string()),
        }
    }

    fn enqueue_browser_command(&mut self, surface_id: SurfaceId, kind: BrowserInputKind) {
        let Some(surface) = self.session.surface(surface_id) else {
            self.status_message = Some(localization::catalog().browser.unknown_surface.to_string());
            return;
        };
        if surface.kind() != SurfaceKind::Browser {
            self.status_message = Some(localization::catalog().browser.not_browser.to_string());
            return;
        }
        self.dispatch_browser_control(surface_id, surface, kind);
    }

    fn browser_copy_url(&mut self, pane: PaneId) {
        let Some(surface_id) = self.tree.pane(pane).and_then(|pane| pane.active_surface()) else {
            return;
        };
        let Some(url) = self.session.surface(surface_id).and_then(|surface| surface.browser_url())
        else {
            return;
        };
        self.copy_text_to_clipboard(&url);
        self.show_toast(localization::catalog().menu.copied_url.to_string());
    }

    fn activate_menu(&mut self, action: MenuAction) -> anyhow::Result<()> {
        match action {
            MenuAction::TogglePaneZoom { pane, zoomed } => {
                if self.active_pane() != Some(pane) {
                    self.focus_pane_after_input(pane);
                }
                self.session.set_pane_zoom(pane, !zoomed);
                return Ok(());
            }
            MenuAction::NewPaneSmart(pane) => {
                self.run_action_for_pane(Action::NewPaneSmart, Some(pane))?;
                return Ok(());
            }
            MenuAction::NewTab(pane) => {
                self.run_action_for_pane(Action::NewTab, Some(pane))?;
                return Ok(());
            }
            MenuAction::NewBrowserTab(pane) => {
                self.run_action_for_pane(Action::NewBrowserTab, Some(pane))?;
                return Ok(());
            }
            MenuAction::SplitRight(pane) => {
                self.run_action_for_pane(Action::SplitRight, Some(pane))?;
                return Ok(());
            }
            MenuAction::SplitDown(pane) => {
                self.run_action_for_pane(Action::SplitDown, Some(pane))?;
                return Ok(());
            }
            MenuAction::ToggleSidebar { .. } => {
                self.run_action(Action::ToggleSidebar)?;
                return Ok(());
            }
            MenuAction::ToggleSidebarCompact { .. } => {
                self.run_action(Action::ToggleSidebarCompact)?;
                return Ok(());
            }
            MenuAction::FocusSidebar => {
                if !self.workspace_sidebar_focused() && self.prepare_pty_input_before_mutation() {
                    self.focus_sidebar();
                }
                return Ok(());
            }
            MenuAction::ActivateSidebarProfile(index) => {
                self.activate_sidebar_profile(index);
                return Ok(());
            }
            MenuAction::SetSidebarViewVisible { view, visible } => {
                self.set_sidebar_view_visible(view, visible);
                return Ok(());
            }
            MenuAction::ShowShortcuts => {
                self.run_action(Action::ShowShortcuts)?;
                return Ok(());
            }
            _ => {}
        }
        if menu_action_prepares_pty_release(action) && !self.prepare_pty_input_before_mutation() {
            return Ok(());
        }
        match action {
            MenuAction::RenameClientMachine(key) => {
                self.open_rename_client_machine_prompt(key);
            }
            MenuAction::RenameManagedMachine(key) => {
                self.open_rename_managed_machine_prompt(key);
            }
            MenuAction::DeleteManagedMachine(key) => {
                self.open_delete_managed_machine_prompt(key);
            }
            MenuAction::RestoreManagedMachine(key) => {
                self.request_restore_managed_machine(key);
            }
            MenuAction::PurgeManagedMachine(key) => {
                self.open_purge_managed_machine_prompt(key);
            }
            MenuAction::RenameWorkspace(id) => self.open_rename_workspace_prompt_for(id),
            MenuAction::RenameManagedWorkspace(id) => {
                self.open_rename_workspace_prompt_for(id);
            }
            MenuAction::CloseWorkspace(id) => self.request_delete_workspace(id),
            MenuAction::DeleteManagedWorkspace(id) => self.request_delete_workspace(id),
            MenuAction::RestoreManagedWorkspace(index) => {
                let workspace_id = self
                    .machine_ui
                    .as_ref()
                    .and_then(|ui| ui.recoverable_workspaces().get(index).copied())
                    .map(|workspace| workspace.id.clone());
                if let Some(workspace_id) = workspace_id {
                    self.request_restore_managed_workspace(&workspace_id);
                }
            }
            MenuAction::PurgeManagedWorkspace(index) => {
                self.prompt = Some(Prompt::new(
                    localization::catalog().sidebar.confirm_purge_workspace,
                    String::new(),
                    PromptTarget::ConfirmPurgeManagedWorkspace(index),
                ));
            }
            MenuAction::CopyWorkspaceId(id) => {
                if let Some(short_id) =
                    self.tree.workspaces.iter().find(|ws| ws.id == id).map(|ws| ws.short_id.clone())
                {
                    self.copy_short_id(short_id);
                }
            }
            MenuAction::RenameScreen(id) => {
                let buffer = self
                    .tree
                    .workspaces
                    .iter()
                    .flat_map(|ws| ws.screens.iter())
                    .find(|s| s.id == id)
                    .and_then(|s| s.name.clone())
                    .unwrap_or_default();
                self.prompt = Some(Prompt::new(
                    localization::catalog().action_label(Action::RenameScreen),
                    buffer,
                    PromptTarget::Screen(id),
                ));
            }
            MenuAction::CloseScreen(id) => self.session.close_screen(id),
            MenuAction::BrowserBack(id) => {
                self.enqueue_browser_command_for_pane(id, BrowserInputKind::Back);
            }
            MenuAction::BrowserForward(id) => {
                self.enqueue_browser_command_for_pane(id, BrowserInputKind::Forward);
            }
            MenuAction::BrowserReload(id) => {
                self.enqueue_browser_command_for_pane(id, BrowserInputKind::Reload);
            }
            MenuAction::BrowserEditUrl(id) => self.focus_omnibar(id),
            MenuAction::BrowserCopyUrl(id) => self.browser_copy_url(id),
            MenuAction::BrowserActivate(id) => {
                self.enqueue_browser_command_for_pane(id, BrowserInputKind::Activate);
            }
            MenuAction::RenameTab(id) => self.open_rename_tab_prompt(Some(id)),
            MenuAction::RenameSurface(surface) => self.open_rename_surface_prompt(surface),
            MenuAction::CopyTabId(id) => {
                if let Some(short_id) = self
                    .tree
                    .pane(id)
                    .and_then(|pane| pane.tabs.get(pane.active_tab))
                    .map(|tab| tab.short_id.clone())
                {
                    self.copy_short_id(short_id);
                }
            }
            MenuAction::CopyPaneId(id) => {
                if let Some(short_id) = self.tree.pane(id).map(|pane| pane.short_id.clone()) {
                    self.copy_short_id(short_id);
                }
            }
            MenuAction::CopyStatusMessage => self.copy_status_message(),
            MenuAction::NewPaneSmart(_)
            | MenuAction::NewTab(_)
            | MenuAction::NewBrowserTab(_)
            | MenuAction::SplitRight(_)
            | MenuAction::SplitDown(_) => unreachable!("shared menu actions return above"),
            MenuAction::CloseTab(id) => {
                if let Some(surface) = self.tree.pane(id).and_then(|p| p.active_surface()) {
                    self.session.close_surface(surface);
                }
            }
            MenuAction::ClosePane(id) => self.session.close_pane(id),
            MenuAction::TogglePaneZoom { .. }
            | MenuAction::ToggleSidebar { .. }
            | MenuAction::ToggleSidebarCompact { .. }
            | MenuAction::FocusSidebar
            | MenuAction::ActivateSidebarProfile(_)
            | MenuAction::SetSidebarViewVisible { .. }
            | MenuAction::ShowShortcuts => unreachable!("shared menu actions return above"),
            MenuAction::SetClientSizing { surface, client, enabled } => {
                self.session.set_client_sizing(surface, client, enabled);
            }
            MenuAction::UseClientSize { surface, client } => {
                self.session.use_only_client_sizing(surface, client);
            }
            MenuAction::RestoreAllClientSizing(surface) => {
                self.session.use_all_client_sizing(surface);
            }
            MenuAction::DisconnectClient(client) => {
                if self.clients.iter().any(|info| info.client == client && info.is_self) {
                    // Disconnecting this control connection would close the socket that must
                    // carry the response. Exit through the same local detach lifecycle as the
                    // keyboard action instead, without another request on that socket.
                    self.run_action(Action::Detach)?;
                } else {
                    // Peer disconnects can resize viewer-owned surfaces, so they pass through
                    // the pointer-map mutation barrier while running off the UI thread. A stale
                    // client id remains a harmless no-op.
                    self.session.disconnect_client(client);
                }
            }
            MenuAction::SelectProviderScope(index) => {
                let scope = self
                    .machine_ui
                    .as_ref()
                    .and_then(|ui| ui.provider.as_ref())
                    .and_then(|provider| provider.scopes.get(index))
                    .map(|scope| scope.id.clone());
                if let (Some(ui), Some(scope)) = (self.machine_ui.as_mut(), scope)
                    && ui
                        .provider
                        .as_ref()
                        .is_some_and(|provider| provider.selected_scope_id != scope)
                {
                    ui.request = Some(MachineRequest::SelectProviderScope(scope));
                }
            }
            MenuAction::InvokeProviderAction(index) => self.begin_provider_action(index),
            MenuAction::CreateMachineFrom(index) => {
                let source_id = self
                    .machine_ui
                    .as_ref()
                    .and_then(|ui| ui.creation_sources.get(index))
                    .map(|source| source.id.clone());
                if let (Some(ui), Some(source_id)) = (self.machine_ui.as_mut(), source_id) {
                    ui.request = Some(MachineRequest::CreateFrom { source_id });
                }
            }
            MenuAction::ConnectMachineTarget(index) => {
                let target = self
                    .machine_ui
                    .as_ref()
                    .and_then(|ui| ui.connection_targets.get(index))
                    .map(|target| target.target.clone());
                if let Some(target) = target {
                    self.begin_machine_connection(target, MachineConnectRoute::Local);
                }
            }
            MenuAction::RunConfigured { action, pane } => {
                self.run_action_for_pane(action, pane.or_else(|| self.active_pane()))?;
            }
            MenuAction::ConnectOtherMachine => {
                let prompt = self.connect_machine_prompt();
                self.prompt = Some(prompt);
            }
        }
        Ok(())
    }

    fn move_focus(&mut self, direction: Direction) {
        if self.move_focus_between_sidebar_rails(direction) {
            return;
        }
        let Some(screen) = self.tree.active_screen() else {
            if matches!(direction, Direction::Left) {
                self.focus_rightmost_sidebar_rail();
            }
            return;
        };
        if screen.zoomed_pane.is_some() {
            if matches!(direction, Direction::Left) {
                self.focus_rightmost_sidebar_rail();
            }
            return;
        }
        let active = screen.active_pane;
        let (dx, dy) = match direction {
            Direction::Left => (-1, 0),
            Direction::Right => (1, 0),
            Direction::Up => (0, -1),
            Direction::Down => (0, 1),
        };
        let panes = if self.viewport_layout.is_empty() {
            self.pane_areas.iter().map(|area| (area.pane, area.rect.into())).collect()
        } else {
            self.viewport_layout.clone()
        };
        let layout = ViewportLayoutResult { panes, ..Default::default() };
        if let Some(next) =
            layout.neighbor_by_recency(active, dx, dy, |pane| self.pane_focus_history.recency(pane))
        {
            self.focus_pane_after_input(next);
        } else if matches!(direction, Direction::Left) {
            self.focus_rightmost_sidebar_rail();
        }
    }

    fn active_screen_pane_order(&self) -> Vec<PaneId> {
        self.tree
            .active_screen()
            .map(|screen| screen.panes.iter().map(|pane| pane.id).collect())
            .unwrap_or_default()
    }

    fn adjacent_pane_by_order(&self, delta: isize) -> Option<PaneId> {
        let active = self.active_pane()?;
        let panes = self.active_screen_pane_order();
        let position = panes.iter().position(|pane| *pane == active)?;
        let len = panes.len();
        if len < 2 {
            return None;
        }
        let next = (position as isize + delta).rem_euclid(len as isize) as usize;
        panes.get(next).copied()
    }

    fn focus_next_pane(&mut self) {
        if let Some(next) = self.adjacent_pane_by_order(1) {
            self.focus_pane_after_input(next);
        }
    }

    fn swap_pane_by_order(&mut self, delta: isize) {
        let Some(active) = self.active_pane() else { return };
        if let Some(target) = self.adjacent_pane_by_order(delta)
            && self.prepare_pty_input_before_mutation()
        {
            self.session.swap_pane(active, target);
        }
    }

    fn scroll_active(&mut self, delta: isize) {
        if let Some(surface) = self.active_surface_handle() {
            if surface.kind() == SurfaceKind::Browser {
                return;
            }
            let _ = surface.scroll_delta(delta);
        }
    }

    fn toggle_sidebar_focus(&mut self) {
        if self.sidebar_rail_focused() {
            self.leave_workspace_sidebar();
            self.sidebar_focus_pending = false;
            return;
        }
        if self.sidebar_focus_pending {
            self.sidebar_focus_pending = false;
            return;
        }
        self.focus_sidebar();
    }

    fn focus_sidebar(&mut self) {
        if self.sidebar_rail_focused() || self.sidebar_focus_pending {
            return;
        }
        self.sidebar_visible = true;
        let requested = self.config.sidebar.plugin.is_some() && self.sync_sidebar_plugin(true);
        if self.config.sidebar.plugin.is_none() || self.sidebar_plugin_surface.is_some() {
            let order = self.focusable_rail_order();
            let preferred = order
                .iter()
                .copied()
                .find(|kind| {
                    self.view_index_for_rail(*kind)
                        .and_then(|index| self.config.sidebar.views.get(index))
                        .is_some_and(|view| view.includes(SidebarResourceKind::Workspaces))
                })
                .or_else(|| order.first().copied());
            if let Some(kind) = preferred {
                self.focus_rail(kind);
            }
            if self.config.sidebar.plugin.is_none() {
                if self.sidebar_view == SidebarView::Workspaces {
                    self.sidebar_workspace_selection = self.tree.active_workspace;
                    self.workspace_rail_selection = WorkspaceRailSelection::Workspace;
                    self.workspace_rail_follow_selection = true;
                } else if !self.sync_sidebar_files_to_focus(true) {
                    self.sidebar_files.refresh();
                }
            }
            self.menu = None;
            self.prompt = None;
            self.omnibar = None;
            self.replace_selection(None);
        } else if requested {
            self.sidebar_focus_pending = true;
        }
    }

    fn toggle_sidebar_view(&mut self) {
        self.sidebar_view = self.sidebar_view.toggled();
        if self.config.sidebar.plugin.is_some() {
            return;
        }
        match self.sidebar_view {
            SidebarView::Files => {
                self.sidebar_followed_surface = None;
                if !self.sync_sidebar_files_to_focus(true) {
                    self.sidebar_files.refresh();
                }
            }
            SidebarView::Workspaces => {
                self.sidebar_workspace_selection = self.tree.active_workspace;
                self.workspace_rail_selection = WorkspaceRailSelection::Workspace;
                self.workspace_rail_follow_selection = true;
            }
        }
    }

    fn sidebar_surface_handle(&self) -> Option<SurfaceHandle> {
        self.sidebar_plugin_surface.and_then(|surface| self.session.surface(surface))
    }

    #[cfg(test)]
    fn run_clear_history_shortcut(&mut self, input: keys::KeyboardInput) -> RenderAction {
        self.run_clear_history_shortcut_to(input, None)
    }

    fn run_clear_history_shortcut_to(
        &mut self,
        input: keys::KeyboardInput,
        destination: Option<SurfaceId>,
    ) -> RenderAction {
        let Some(surface_id) = destination.or_else(|| self.active_surface()) else {
            return RenderAction::None;
        };
        if !should_claim_clear_history_shortcut(
            self.tree.surface_kind(surface_id),
            self.session.supports_clear_history_key_fallback(surface_id),
        ) {
            let visible_state = self.visible_input_state(Some(surface_id));
            self.replace_selection(None);
            self.forward_key_to_surface(input, surface_id);
            let action =
                if self.status_message.is_some() { RenderAction::Draw } else { RenderAction::None };
            return action.merge(self.visible_input_action(visible_state));
        }
        let Some(key_input) = input.into_terminal_input() else {
            return RenderAction::None;
        };
        if self.session.surface(surface_id).is_none() {
            return RenderAction::None;
        }
        self.session.clear_history_or_send_key(
            surface_id,
            key_input,
            self.input_revision,
            self.selection,
            self.selection_generation,
        );
        if self.status_message.is_some() { RenderAction::Draw } else { RenderAction::None }
    }

    fn forward_key(&mut self, input: keys::KeyboardInput) {
        if !self.session_available() {
            // Coming back to a machine that paused or lost its stream: the
            // first keystroke wakes it instead of bouncing off a dead pane.
            if self.wake_presented_machine() {
                return;
            }
            self.status_message =
                Some(localization::catalog().sidebar.no_active_session.to_string());
            return;
        }
        let Some(surface_id) = self.active_surface() else { return };
        self.forward_key_to_surface(input, surface_id);
    }

    fn forward_key_to_surface(&mut self, input: keys::KeyboardInput, surface_id: SurfaceId) {
        if !self.session_available() {
            if self.wake_presented_machine() {
                return;
            }
            self.status_message =
                Some(localization::catalog().sidebar.no_active_session.to_string());
            return;
        }
        let Some(surface) = self.session.surface(surface_id) else { return };
        if surface.kind() == SurfaceKind::Browser {
            let key = input.ui_key();
            if matches!(key.code, KeyCode::Char('l') | KeyCode::Char('L'))
                && key.modifiers.contains(KeyModifiers::CONTROL)
            {
                if let Some(pane) = self.pane_for_surface(surface_id) {
                    self.focus_omnibar(pane);
                }
                return;
            }
            self.forward_browser_key_to(surface_id, surface, input);
            return;
        }
        let Some(input) = input.into_terminal_input() else {
            return;
        };
        self.encode_buf.clear();
        let _ = surface.scroll_to_bottom();
        let Some(encoded) = surface.with_terminal(|term| {
            self.encoder.sync_from_terminal(term);
            self.encoder.encode(&input, &mut self.encode_buf)
        }) else {
            return;
        };
        if encoded.is_ok() && !self.encode_buf.is_empty() {
            let _ = self.write_encoded_pty_bytes(surface_id, surface, PtyInputKind::Ordered);
        }
    }

    fn forward_key_to_pane(&mut self, key: &KeyEvent, pane: Option<PaneId>) {
        if pane == self.active_pane() {
            self.forward_key((*key).into());
            return;
        }
        if !self.session_available() {
            if self.wake_presented_machine() {
                return;
            }
            self.status_message =
                Some(localization::catalog().sidebar.no_active_session.to_string());
            return;
        }
        let Some(surface_id) =
            pane.and_then(|pane| self.tree.pane(pane)).and_then(|pane| pane.active_surface())
        else {
            return;
        };
        let Some(surface) = self.session.surface(surface_id) else { return };
        if surface.kind() == SurfaceKind::Pty {
            self.forward_pty_key_to_surface(key, surface_id, surface);
        }
    }

    fn forward_pty_key_to_surface(
        &mut self,
        key: &KeyEvent,
        surface_id: SurfaceId,
        surface: SurfaceHandle,
    ) {
        let Some(input) = keys::key_input_from(key) else { return };
        self.encode_buf.clear();
        let _ = surface.scroll_to_bottom();
        let Some(encoded) = surface.with_terminal(|term| {
            self.encoder.sync_from_terminal(term);
            self.encoder.encode(&input, &mut self.encode_buf)
        }) else {
            return;
        };
        if encoded.is_ok() && !self.encode_buf.is_empty() {
            let _ = self.write_encoded_pty_bytes(surface_id, surface, PtyInputKind::Ordered);
        }
    }

    fn forward_sidebar_key(&mut self, input: keys::KeyboardInput) {
        let Some(input) = input.into_terminal_input() else {
            return;
        };
        let Some(surface_id) = self.sidebar_plugin_surface else { return };
        let Some(surface) = self.sidebar_surface_handle() else { return };
        self.encode_buf.clear();
        let _ = surface.scroll_to_bottom();
        let Some(encoded) = surface.with_terminal(|term| {
            self.encoder.sync_from_terminal(term);
            self.encoder.encode(&input, &mut self.encode_buf)
        }) else {
            return;
        };
        if encoded.is_ok() && !self.encode_buf.is_empty() {
            let _ = self.write_encoded_pty_bytes(surface_id, surface, PtyInputKind::Ordered);
        }
    }

    fn forward_browser_key_to(
        &mut self,
        surface_id: SurfaceId,
        surface: SurfaceHandle,
        mut input: keys::KeyboardInput,
    ) {
        let key = input.ui_key();
        if let Some(text) = input.take_text_for_direct_input() {
            let _ = self.browser_input.enqueue(BrowserInputEvent {
                surface_id,
                surface,
                kind: BrowserInputKind::InsertText(text),
            });
            return;
        }
        if let KeyCode::Char(c) = key.code
            && !key.modifiers.intersects(keys::SHORTCUT_MODIFIERS)
        {
            let _ = self.browser_input.enqueue(BrowserInputEvent {
                surface_id,
                surface,
                kind: BrowserInputKind::InsertText(c.to_string()),
            });
            return;
        }
        let Some((key_name, code, vk, text)) =
            browser_key_mapping(key.code, input.base_layout_key())
        else {
            return;
        };
        let Some(modifiers) = browser_modifiers(key.modifiers) else {
            return;
        };
        let kind = if key.kind == KeyEventKind::Press {
            BrowserInputKind::KeyPress {
                key: key_name,
                code,
                windows_virtual_key_code: vk,
                modifiers,
                text,
            }
        } else {
            BrowserInputKind::Key {
                event_type: "keyDown",
                key: key_name,
                code,
                windows_virtual_key_code: vk,
                modifiers,
                text,
            }
        };
        let _ = self.browser_input.enqueue(BrowserInputEvent { surface_id, surface, kind });
    }

    fn paste(&mut self, text: &str) {
        if !self.session_available() {
            self.status_message =
                Some(localization::catalog().sidebar.no_active_session.to_string());
            return;
        }
        let Some(surface_id) = self.active_surface() else { return };
        self.paste_to_surface(text, surface_id);
    }

    fn paste_to_surface(&mut self, text: &str, surface_id: SurfaceId) {
        if !self.session_available() {
            self.status_message =
                Some(localization::catalog().sidebar.no_active_session.to_string());
            return;
        }
        let Some(surface) = self.session.surface(surface_id) else { return };
        if surface.kind() == SurfaceKind::Browser {
            let _ = self.browser_input.enqueue(BrowserInputEvent {
                surface_id,
                surface,
                kind: BrowserInputKind::InsertText(text.to_string()),
            });
            return;
        }
        let Some(bracketed) = surface.with_terminal(|t| t.mode(2004, false)) else {
            return;
        };
        if bracketed {
            let mut bytes = Vec::with_capacity(text.len() + 12);
            bytes.extend_from_slice(b"\x1b[200~");
            bytes.extend_from_slice(text.as_bytes());
            bytes.extend_from_slice(b"\x1b[201~");
            let _ = self.write_pty_bytes(surface_id, surface, bytes.into(), PtyInputKind::Ordered);
        } else {
            let _ = self.write_pty_bytes(
                surface_id,
                surface,
                PtyInputBytes::from_slice(text.as_bytes()),
                PtyInputKind::Ordered,
            );
        }
    }

    fn paste_sidebar(&mut self, text: &str) {
        let Some(surface_id) = self.sidebar_plugin_surface else { return };
        let Some(surface) = self.sidebar_surface_handle() else { return };
        let Some(bracketed) = surface.with_terminal(|t| t.mode(2004, false)) else {
            return;
        };
        if bracketed {
            let mut bytes = Vec::with_capacity(text.len() + 12);
            bytes.extend_from_slice(b"\x1b[200~");
            bytes.extend_from_slice(text.as_bytes());
            bytes.extend_from_slice(b"\x1b[201~");
            let _ = self.write_pty_bytes(surface_id, surface, bytes.into(), PtyInputKind::Ordered);
        } else {
            let _ = self.write_pty_bytes(
                surface_id,
                surface,
                PtyInputBytes::from_slice(text.as_bytes()),
                PtyInputKind::Ordered,
            );
        }
    }

    fn pane_area_at(&self, x: u16, y: u16) -> Option<&PaneArea> {
        self.pane_areas.iter().find(|a| a.rect.contains(x, y))
    }

    fn hit_at(&self, x: u16, y: u16) -> Option<Hit> {
        self.hits.iter().find(|(rect, _)| rect.contains(x, y)).map(|(_, hit)| *hit)
    }

    fn omnibar_hit_at(&self, x: u16, y: u16) -> Option<(PaneId, OmnibarHit)> {
        self.pane_areas.iter().find_map(|area| {
            let rect = area.omnibar?;
            if self.surface_kind(area.surface) != Some(SurfaceKind::Browser) {
                return None;
            }
            let editing = self
                .omnibar
                .as_ref()
                .is_some_and(|state| state.pane == area.pane && state.surface == area.surface);
            crate::ui::omnibar::hit(rect, area.omnibar_source_x(), x, y, editing)
                .map(|hit| (area.pane, hit))
        })
    }

    fn tab_drop_target_at(&self, x: u16, y: u16) -> Option<(PaneId, usize)> {
        let area = self.pane_areas.iter().find(|area| {
            area.bar.is_some_and(|bar| bar.contains(x, y)) || area.content.contains(x, y)
        })?;
        let pane = self.tree.pane(area.pane)?;
        let len = pane.tabs.len();
        if !area.bar.is_some_and(|bar| bar.contains(x, y)) {
            return Some((area.pane, len));
        }
        let mut tab_hits = self
            .hits
            .iter()
            .filter_map(|(rect, hit)| match hit {
                Hit::Tab { pane, index } if *pane == area.pane => Some((*rect, *index)),
                _ => None,
            })
            .collect::<Vec<_>>();
        tab_hits.sort_by_key(|(rect, index)| (rect.x, *index));
        for (rect, index) in &tab_hits {
            let mid = rect.x + rect.width / 2;
            if x < mid {
                return Some((area.pane, (*index).min(len)));
            }
            if rect.contains(x, y) {
                return Some((area.pane, (index + 1).min(len)));
            }
        }
        Some((area.pane, len))
    }

    fn workspace_drop_target_at(&self, x: u16, y: u16) -> Option<usize> {
        let area = self.workspace_sidebar_area(self.content_area.height.saturating_add(1))?;
        if area.width < 3 || x < area.x || x >= area.x + area.width.saturating_sub(1) || y < area.y
        {
            return None;
        }
        let len = self.tree.workspaces.len();
        for index in 0..len {
            let start = area.y + 2 + index as u16 * 3;
            if y < start {
                return Some(index);
            }
            if y <= start + 1 {
                return Some(if y == start { index } else { index + 1 }.min(len));
            }
        }
        Some(len)
    }

    fn tab_location(&self, surface: SurfaceId) -> Option<(PaneId, usize)> {
        self.tree
            .workspaces
            .iter()
            .flat_map(|ws| ws.screens.iter())
            .flat_map(|screen| screen.panes.iter())
            .find_map(|pane| {
                pane.tabs
                    .iter()
                    .position(|tab| tab.surface == surface)
                    .map(|index| (pane.id, index))
            })
    }

    #[cfg(test)]
    fn handle_mouse(&mut self, mouse: MouseEvent) -> anyhow::Result<RenderAction> {
        self.handle_mouse_with_sequence(mouse, None, None)
    }

    fn handle_mouse_with_sequence(
        &mut self,
        mouse: MouseEvent,
        replay_sequence: Option<u64>,
        terminal_admission: Option<TerminalPointerAdmission>,
    ) -> anyhow::Result<RenderAction> {
        // A live physical sample supersedes retained motion. Replayed input
        // only supersedes motion that was retained earlier in the same
        // sequence, preserving newer samples until their chronological turn.
        if replay_sequence.is_none_or(|sequence| {
            self.pending_pointer_motion.as_ref().is_none_or(|pending| pending.sequence <= sequence)
        }) {
            self.pending_pointer_motion = None;
        }
        if self.pairing_dialog.is_none() && self.shortcut_help.is_some() {
            return Ok(self.handle_shortcut_help_mouse(mouse));
        }
        if self.pairing_dialog.is_some() {
            if mouse.kind == MouseEventKind::Moved {
                let hover_region = |position: Option<(u16, u16)>| {
                    position.and_then(|(x, y)| {
                        self.pairing_dialog.as_ref().map(|dialog| {
                            (dialog.approve.contains(x, y), dialog.deny.contains(x, y))
                        })
                    })
                };
                let before = hover_region(self.hover);
                let after = hover_region(Some((mouse.column, mouse.row)));
                self.sync_pointer_shape(mouse.column, mouse.row);
                self.hover = Some((mouse.column, mouse.row));
                return Ok(if before != after { RenderAction::Draw } else { RenderAction::None });
            }
            if !matches!(mouse.kind, MouseEventKind::Down(MouseButton::Left)) {
                if let MouseEventKind::Up(button) = mouse.kind {
                    self.active_pointer_buttons.remove(&button);
                }
                return Ok(RenderAction::None);
            }
        }
        // This TUI tracks one active pointer button. Ignore additional presses
        // until its release so a second button cannot orphan the inner app's
        // pressed state.
        if let MouseEventKind::Down(button) = mouse.kind
            && let Some(Drag::PtyMouse { button: active, .. }) = &self.drag
        {
            if button != *active {
                self.ignored_pty_mouse_buttons.insert(button);
            }
            return Ok(RenderAction::None);
        }
        match mouse.kind {
            MouseEventKind::Down(button) => {
                self.active_pointer_buttons.insert(button);
            }
            MouseEventKind::Up(button) => {
                self.active_pointer_buttons.remove(&button);
            }
            _ => {}
        }
        match mouse.kind {
            MouseEventKind::Down(MouseButton::Left) => self.handle_left_down_with_admission(
                mouse.column,
                mouse.row,
                mouse.modifiers,
                terminal_admission,
            ),
            MouseEventKind::Drag(MouseButton::Left) => {
                if self.forward_pty_mouse_drag(
                    mouse.column,
                    mouse.row,
                    MouseButton::Left,
                    mouse.modifiers,
                ) {
                    Ok(RenderAction::None)
                } else {
                    self.handle_left_drag(mouse.column, mouse.row)
                }
            }
            MouseEventKind::Up(MouseButton::Left) => {
                if self.finish_pty_mouse_drag(
                    mouse.column,
                    mouse.row,
                    MouseButton::Left,
                    mouse.modifiers,
                ) {
                    Ok(RenderAction::Draw)
                } else {
                    self.handle_left_up(mouse.column, mouse.row)
                }
            }
            MouseEventKind::Down(MouseButton::Right) => {
                if self.prompt.is_some() {
                    self.shake_frames = 6;
                    return Ok(RenderAction::Draw);
                }
                if self.begin_pty_mouse_drag_with_admission(
                    mouse.column,
                    mouse.row,
                    MouseButton::Right,
                    mouse.modifiers,
                    terminal_admission,
                ) != PtyMousePressResult::NotOwned
                {
                    return Ok(RenderAction::Draw);
                }
                self.open_context_menu(mouse.column, mouse.row);
                Ok(RenderAction::Draw)
            }
            MouseEventKind::Drag(MouseButton::Right) => {
                if self.forward_pty_mouse_drag(
                    mouse.column,
                    mouse.row,
                    MouseButton::Right,
                    mouse.modifiers,
                ) {
                    Ok(RenderAction::None)
                } else {
                    self.handle_right_drag(mouse.column, mouse.row)
                }
            }
            MouseEventKind::Up(MouseButton::Right) => {
                if self.finish_pty_mouse_drag(
                    mouse.column,
                    mouse.row,
                    MouseButton::Right,
                    mouse.modifiers,
                ) {
                    Ok(RenderAction::Draw)
                } else {
                    self.handle_right_up(mouse.column, mouse.row)
                }
            }
            MouseEventKind::Down(MouseButton::Middle) => Ok(
                if self.begin_pty_mouse_drag_with_admission(
                    mouse.column,
                    mouse.row,
                    MouseButton::Middle,
                    mouse.modifiers,
                    terminal_admission,
                ) != PtyMousePressResult::NotOwned
                {
                    RenderAction::Draw
                } else {
                    RenderAction::None
                },
            ),
            MouseEventKind::Drag(MouseButton::Middle) => {
                self.forward_pty_mouse_drag(
                    mouse.column,
                    mouse.row,
                    MouseButton::Middle,
                    mouse.modifiers,
                );
                Ok(RenderAction::None)
            }
            MouseEventKind::Up(MouseButton::Middle) => Ok(
                if self.finish_pty_mouse_drag(
                    mouse.column,
                    mouse.row,
                    MouseButton::Middle,
                    mouse.modifiers,
                ) {
                    RenderAction::Draw
                } else {
                    RenderAction::None
                },
            ),
            MouseEventKind::Moved => self.handle_hover_with_admission(
                mouse.column,
                mouse.row,
                mouse.modifiers,
                terminal_admission,
            ),
            MouseEventKind::ScrollUp | MouseEventKind::ScrollDown => {
                let down = matches!(mouse.kind, MouseEventKind::ScrollDown);
                self.handle_scroll_with_admission(
                    mouse.column,
                    mouse.row,
                    down,
                    mouse.modifiers,
                    terminal_admission,
                )
            }
            MouseEventKind::ScrollLeft | MouseEventKind::ScrollRight => self
                .handle_horizontal_scroll_with_admission(
                    mouse.column,
                    mouse.row,
                    matches!(mouse.kind, MouseEventKind::ScrollRight),
                    mouse.modifiers,
                    terminal_admission,
                ),
        }
    }

    #[cfg(test)]
    fn begin_pty_mouse_drag(
        &mut self,
        x: u16,
        y: u16,
        button: MouseButton,
        modifiers: KeyModifiers,
    ) -> PtyMousePressResult {
        self.begin_pty_mouse_drag_with_admission(x, y, button, modifiers, None)
    }

    fn begin_pty_mouse_drag_with_admission(
        &mut self,
        x: u16,
        y: u16,
        button: MouseButton,
        modifiers: KeyModifiers,
        terminal_admission: Option<TerminalPointerAdmission>,
    ) -> PtyMousePressResult {
        if modifiers.contains(KeyModifiers::SHIFT)
            || (button == MouseButton::Right && modifiers.contains(KeyModifiers::ALT))
            || self.menu.is_some()
            || self.prompt.is_some()
            || self.drag.is_some()
        {
            return PtyMousePressResult::NotOwned;
        }
        let Some(area) = self.pane_area_at(x, y).copied() else {
            return PtyMousePressResult::NotOwned;
        };
        if !area.content.contains(x, y) || self.surface_kind(area.surface) != Some(SurfaceKind::Pty)
        {
            return PtyMousePressResult::NotOwned;
        }
        let content = self.canonical_pty_content(area.surface, area.logical_content_rect());
        let (logical_x, logical_y) = area.logical_content_point(x, y);
        if !content.contains(logical_x, logical_y) {
            return PtyMousePressResult::NotOwned;
        }
        let Some(handle) = self.session.surface(area.surface) else {
            return PtyMousePressResult::Consumed;
        };
        let semantics = terminal_admission.as_ref().map(|admission| admission.semantics).or_else(
            || match handle.try_pointer_semantics() {
                Some(PointerSemanticProbe::Ready(semantics)) => Some(semantics),
                Some(PointerSemanticProbe::Contended) | None => None,
            },
        );
        let (release_capture, forwarded) = self.prepare_pty_mouse_press(
            (area.surface, handle.clone()),
            content,
            (logical_x, logical_y),
            button,
            modifiers,
            terminal_admission,
        );
        if matches!(release_capture, PtyMouseReleaseCapture::Failed) {
            self.active_pointer_buttons.remove(&button);
            return PtyMousePressResult::Consumed;
        }
        if !forwarded.owned {
            return PtyMousePressResult::NotOwned;
        }
        if self.active_pane() != Some(area.pane) {
            self.focus_pane_after_input(area.pane);
        }
        self.leave_workspace_sidebar();
        self.replace_selection(None);
        if !forwarded.accepted {
            return PtyMousePressResult::Consumed;
        }
        let Some(reservation_id) = forwarded.reservation_id else {
            return PtyMousePressResult::Consumed;
        };
        let PtyMouseReleaseCapture::Bytes(release_bytes) = release_capture else {
            self.pty_input.cancel_release_reservation(reservation_id);
            return PtyMousePressResult::Consumed;
        };
        self.drag = Some(Drag::PtyMouse {
            surface: area.surface,
            handle: Some(handle),
            reservation_id,
            release_bytes,
            semantics,
            content,
            button,
            position: (logical_x, logical_y),
            modifiers,
        });
        self.ignored_pty_mouse_buttons.clear();
        PtyMousePressResult::Started
    }

    fn prepare_pty_mouse_press(
        &mut self,
        route: (SurfaceId, SurfaceHandle),
        content: Rect,
        position: (u16, u16),
        button: MouseButton,
        modifiers: KeyModifiers,
        terminal_admission: Option<TerminalPointerAdmission>,
    ) -> (PtyMouseReleaseCapture, PtyInputForwardResult) {
        let (surface_id, surface) = route;
        let (x, y) = position;
        let failed =
            || PtyInputForwardResult { owned: true, accepted: false, reservation_id: None };
        let cell_width = u32::from(self.cell_pixels.0.max(1));
        let cell_height = u32::from(self.cell_pixels.1.max(1));
        let position = (
            (x as f32 - content.x as f32 + 0.5) * cell_width as f32,
            (y as f32 - content.y as f32 + 0.5) * cell_height as f32,
        );
        let screen_size = (
            u32::from(content.width).saturating_mul(cell_width),
            u32::from(content.height).saturating_mul(cell_height),
        );
        let press = MouseInput {
            action: MouseAction::Press,
            button: Some(Self::ghostty_mouse_button(button)),
            mods: Self::ghostty_mouse_mods(modifiers),
            position,
            screen_size,
            cell_size: (cell_width, cell_height),
            any_button_pressed: true,
        };
        let release =
            MouseInput { action: MouseAction::Release, any_button_pressed: false, ..press };
        let (press_output, release_output, encoded) = match terminal_admission {
            Some(TerminalPointerAdmission {
                surface,
                encoding:
                    TerminalPointerEncoding::PressPair {
                        press: encoded_press,
                        release: encoded_release,
                    },
                ..
            }) if surface == surface_id => (encoded_press, encoded_release, true),
            Some(_) => (PtyInputBytes::new(), PtyInputBytes::new(), false),
            None => {
                let mut press_output = PtyInputBytes::new();
                let mut release_output = PtyInputBytes::new();
                let encoded = surface
                    .encode_mouse_press_pair(press, release, &mut press_output, &mut release_output)
                    .is_some_and(|encoded| encoded.is_ok());
                (press_output, release_output, encoded)
            }
        };
        self.encode_buf.clear();
        #[cfg(test)]
        self.encode_buf.extend_from_slice(&press_output);
        if !encoded {
            return (PtyMouseReleaseCapture::Failed, failed());
        }
        let release_capture = if release_output.is_empty() {
            PtyMouseReleaseCapture::NotReported
        } else {
            PtyMouseReleaseCapture::Bytes(release_output)
        };
        if press_output.is_empty() {
            return (
                release_capture,
                PtyInputForwardResult { owned: false, accepted: true, reservation_id: None },
            );
        }
        let kind = if matches!(release_capture, PtyMouseReleaseCapture::Bytes(_)) {
            PtyInputKind::Press
        } else {
            PtyInputKind::Ordered
        };
        let forwarded = self.enqueue_pty_bytes(surface_id, surface, press_output, kind);
        (release_capture, forwarded)
    }

    fn forward_pty_mouse_drag(
        &mut self,
        x: u16,
        y: u16,
        _reported_button: MouseButton,
        modifiers: KeyModifiers,
    ) -> bool {
        let Some(Drag::PtyMouse { surface, semantics, content, button: active_button, .. }) =
            self.drag
        else {
            return false;
        };
        // Some host protocols report a drag as left regardless of the
        // pressed button. This TUI owns one active button, so it is authoritative.
        if self.menu.is_some() || self.prompt.is_some() {
            self.cancel_pty_mouse_drag();
            return true;
        }
        let (content, x, y) = self.current_pty_pointer(surface, x, y).unwrap_or((content, x, y));
        if let Some(Drag::PtyMouse { position, modifiers: stored_modifiers, .. }) = &mut self.drag {
            *position = (x, y);
            *stored_modifiers = modifiers;
        }
        self.encode_buf.clear();
        let Some(semantics) = semantics else {
            return true;
        };
        let _ = self.forward_pty_mouse_motion_if_uncontended(
            (surface, content),
            (x, y),
            Some(Self::ghostty_mouse_button(active_button)),
            modifiers,
            true,
            Some(TerminalPointerAdmission {
                surface,
                semantics,
                encoding: TerminalPointerEncoding::None,
            }),
        );
        true
    }

    fn finish_pty_mouse_drag(
        &mut self,
        x: u16,
        y: u16,
        reported_button: MouseButton,
        modifiers: KeyModifiers,
    ) -> bool {
        let Some(Drag::PtyMouse {
            surface,
            handle,
            reservation_id,
            release_bytes,
            content,
            button,
            ..
        }) = &self.drag
        else {
            return false;
        };
        let (surface, handle, reservation_id, fallback, content, button) =
            (*surface, handle.clone(), *reservation_id, release_bytes.clone(), *content, *button);
        if reported_button != button {
            self.ignored_pty_mouse_buttons.remove(&reported_button);
            return true;
        }
        let (content, x, y) = self.current_pty_pointer(surface, x, y).unwrap_or((content, x, y));
        let release = self.capture_pty_mouse_release(surface, content, x, y, button, modifiers);
        self.drag = None;
        self.ignored_pty_mouse_buttons.clear();
        match release {
            PtyMouseReleaseCapture::Bytes(bytes) => {
                if !self.enqueue_pty_release(surface, handle, reservation_id, bytes) {
                    self.pty_input.cancel_release_reservation(reservation_id);
                }
            }
            PtyMouseReleaseCapture::Failed | PtyMouseReleaseCapture::NotReported => {
                if !self.enqueue_pty_release(surface, handle, reservation_id, fallback) {
                    self.pty_input.cancel_release_reservation(reservation_id);
                }
            }
        }
        true
    }

    fn capture_pty_mouse_release(
        &mut self,
        surface_id: SurfaceId,
        content: Rect,
        x: u16,
        y: u16,
        button: MouseButton,
        modifiers: KeyModifiers,
    ) -> PtyMouseReleaseCapture {
        let Some(surface) = self.session.surface(surface_id) else {
            return PtyMouseReleaseCapture::Failed;
        };
        let cell_width = u32::from(self.cell_pixels.0.max(1));
        let cell_height = u32::from(self.cell_pixels.1.max(1));
        let input = MouseInput {
            action: MouseAction::Release,
            button: Some(Self::ghostty_mouse_button(button)),
            mods: Self::ghostty_mouse_mods(modifiers),
            position: (
                (x as f32 - content.x as f32 + 0.5) * cell_width as f32,
                (y as f32 - content.y as f32 + 0.5) * cell_height as f32,
            ),
            screen_size: (
                u32::from(content.width).saturating_mul(cell_width),
                u32::from(content.height).saturating_mul(cell_height),
            ),
            cell_size: (cell_width, cell_height),
            any_button_pressed: false,
        };
        let mut output = PtyInputBytes::new();
        let Some(encoded) = surface.encode_mouse_release(input, &mut output) else {
            return PtyMouseReleaseCapture::Failed;
        };
        match encoded {
            Ok(()) if output.is_empty() => PtyMouseReleaseCapture::NotReported,
            Ok(()) => PtyMouseReleaseCapture::Bytes(output),
            Err(_) => PtyMouseReleaseCapture::Failed,
        }
    }

    fn enqueue_pty_release(
        &mut self,
        surface_id: SurfaceId,
        retained: Option<SurfaceHandle>,
        reservation_id: u64,
        bytes: PtyInputBytes,
    ) -> bool {
        let Some(surface) = retained.or_else(|| self.session.surface(surface_id)) else {
            return false;
        };
        self.encode_buf.clear();
        #[cfg(test)]
        self.encode_buf.extend_from_slice(bytes.as_ref());
        let (result, _) = self.pty_input.enqueue_with_reservation(PtyInputEvent::release(
            surface_id,
            surface,
            bytes,
            reservation_id,
        ));
        self.handle_pty_enqueue_result(result)
    }

    fn cancel_pointer_interaction(&mut self) -> bool {
        let menu_scrollbar_dragged =
            self.menu.as_mut().is_some_and(|menu| menu.finish_scrollbar_drag());
        let pointer_dragged = self.drag.is_some();
        if matches!(self.drag, Some(Drag::PtyMouse { .. })) {
            self.cancel_pty_mouse_drag();
        } else if let Some(Drag::Browser { surface, content, position, frame_seq }) = &self.drag {
            let (surface, content, position, frame_seq) =
                (*surface, *content, *position, *frame_seq);
            self.drag = None;
            let x = position.0.clamp(content.x, content.x + content.width.saturating_sub(1));
            let y = position.1.clamp(content.y, content.y + content.height.saturating_sub(1));
            let _ = self.send_browser_mouse(
                surface,
                content,
                x,
                y,
                frame_seq,
                BrowserMouseDispatch::new("mouseReleased", Some("left"), Some(1)),
            );
        } else {
            let settle_split = matches!(self.drag, Some(Drag::ResizeSplit { .. }));
            self.drag = None;
            if settle_split {
                self.session.settle_split_ratio();
            }
        }
        self.active_pointer_buttons.clear();
        self.ignored_pty_mouse_buttons.clear();
        menu_scrollbar_dragged || pointer_dragged
    }

    fn cancel_pty_mouse_drag(&mut self) {
        let Some(Drag::PtyMouse {
            surface,
            handle,
            reservation_id,
            release_bytes,
            content,
            button,
            position,
            modifiers,
            ..
        }) = &self.drag
        else {
            return;
        };
        let (surface, handle, reservation_id, fallback, content, button, position, modifiers) = (
            *surface,
            handle.clone(),
            *reservation_id,
            release_bytes.clone(),
            *content,
            *button,
            *position,
            *modifiers,
        );
        let content = self.current_pty_content(surface).unwrap_or(content);
        let release = self
            .capture_pty_mouse_release(surface, content, position.0, position.1, button, modifiers);
        self.drag = None;
        self.ignored_pty_mouse_buttons.clear();
        match release {
            PtyMouseReleaseCapture::Bytes(bytes) => {
                if !self.enqueue_pty_release(surface, handle, reservation_id, bytes) {
                    self.pty_input.cancel_release_reservation(reservation_id);
                }
            }
            PtyMouseReleaseCapture::Failed | PtyMouseReleaseCapture::NotReported => {
                if !self.enqueue_pty_release(surface, handle, reservation_id, fallback) {
                    self.pty_input.cancel_release_reservation(reservation_id);
                }
            }
        }
    }

    fn finish_active_drag(&mut self) {
        if let Some(menu) = self.menu.as_mut() {
            menu.finish_scrollbar_drag();
        }
        if matches!(self.drag, Some(Drag::PtyMouse { .. })) {
            self.cancel_pty_mouse_drag();
            return;
        }
        match self.drag.take() {
            Some(Drag::Browser { surface, content, position, frame_seq }) => {
                let content = self.current_browser_content(surface).unwrap_or(content);
                let position = (
                    position.0.clamp(content.x, content.x + content.width.saturating_sub(1)),
                    position.1.clamp(content.y, content.y + content.height.saturating_sub(1)),
                );
                let _ = self.send_browser_mouse(
                    surface,
                    content,
                    position.0,
                    position.1,
                    frame_seq,
                    BrowserMouseDispatch::new("mouseReleased", Some("left"), Some(1)),
                );
            }
            Some(Drag::ResizeSplit { .. }) => self.session.settle_split_ratio(),
            Some(
                Drag::TabArm { .. }
                | Drag::Tab { .. }
                | Drag::WorkspaceArm { .. }
                | Drag::Workspace { .. }
                | Drag::Select { .. }
                | Drag::StatusMessage { .. }
                | Drag::Scrollbar { .. }
                | Drag::HorizontalScrollbar { .. }
                | Drag::WorkspaceScrollbar { .. }
                | Drag::RailResize(_),
            )
            | None => {}
            Some(Drag::PtyMouse { .. }) => unreachable!("PTY drag returned before take"),
        }
    }

    #[cfg(test)]
    fn forward_pty_mouse_at(
        &mut self,
        x: u16,
        y: u16,
        action: MouseAction,
        button: Option<GhosttyMouseButton>,
        modifiers: KeyModifiers,
        any_button_pressed: bool,
    ) -> bool {
        self.forward_pty_mouse_at_with_admission(
            (x, y),
            action,
            button,
            modifiers,
            any_button_pressed,
            None,
        )
        .unwrap_or(true)
    }

    fn forward_pty_mouse_at_with_admission(
        &mut self,
        position: (u16, u16),
        action: MouseAction,
        button: Option<GhosttyMouseButton>,
        modifiers: KeyModifiers,
        any_button_pressed: bool,
        terminal_admission: Option<TerminalPointerAdmission>,
    ) -> Option<bool> {
        let (x, y) = position;
        if modifiers.contains(KeyModifiers::SHIFT) || self.menu.is_some() || self.prompt.is_some() {
            return Some(false);
        }
        let Some(area) = self.pane_area_at(x, y).copied() else { return Some(false) };
        if !area.content.contains(x, y) || self.surface_kind(area.surface) != Some(SurfaceKind::Pty)
        {
            return Some(false);
        }
        let content = self.canonical_pty_content(area.surface, area.logical_content_rect());
        let (logical_x, logical_y) = area.logical_content_point(x, y);
        if action == MouseAction::Motion {
            let inside = content.contains(logical_x, logical_y);
            let owned = self.forward_pty_mouse_motion_if_uncontended(
                (area.surface, content),
                (logical_x, logical_y),
                None,
                modifiers,
                any_button_pressed,
                terminal_admission,
            );
            // A no-button motion outside the canonical viewport is
            // intentionally suppressed by Ghostty. Reset dedupe so re-entering
            // through the same edge cell still reports a fresh hover sample.
            if !inside
                && !any_button_pressed
                && let Some(surface) = self.session.surface(area.surface)
            {
                surface.reset_mouse_motion_dedupe();
            }
            return Some(owned);
        }
        if !content.contains(logical_x, logical_y) {
            return Some(false);
        }
        self.forward_pty_mouse_to_surface(
            area.surface,
            content,
            logical_x,
            logical_y,
            action,
            button,
            modifiers,
            any_button_pressed,
            terminal_admission,
        )
        .map(|forwarded| forwarded.owned)
    }

    fn forward_pty_mouse_motion_if_uncontended(
        &mut self,
        route: (SurfaceId, Rect),
        position: (u16, u16),
        button: Option<GhosttyMouseButton>,
        modifiers: KeyModifiers,
        any_button_pressed: bool,
        terminal_admission: Option<TerminalPointerAdmission>,
    ) -> bool {
        let (surface_id, content) = route;
        let Some(surface) = self.session.surface(surface_id) else { return false };
        let (x, y) = position;
        let cell_width = u32::from(self.cell_pixels.0.max(1));
        let cell_height = u32::from(self.cell_pixels.1.max(1));
        let input = MouseInput {
            action: MouseAction::Motion,
            button,
            mods: Self::ghostty_mouse_mods(modifiers),
            position: (
                (x as f32 - content.x as f32 + 0.5) * cell_width as f32,
                (y as f32 - content.y as f32 + 0.5) * cell_height as f32,
            ),
            screen_size: (
                u32::from(content.width).saturating_mul(cell_width),
                u32::from(content.height).saturating_mul(cell_height),
            ),
            cell_size: (cell_width, cell_height),
            any_button_pressed,
        };

        self.encode_buf.clear();
        let bytes = match terminal_admission {
            Some(TerminalPointerAdmission {
                surface,
                encoding: TerminalPointerEncoding::Single(encoded),
                ..
            }) if surface == surface_id => encoded,
            Some(TerminalPointerAdmission {
                surface: admission_surface,
                semantics,
                encoding: TerminalPointerEncoding::None,
            }) if admission_surface == surface_id => {
                let mut output = PtyInputBytes::new();
                match surface.encode_mouse_if_semantics(semantics, input, &mut output) {
                    Some(GuardedMouseEncode::Encoded(Ok(()))) => output,
                    Some(
                        GuardedMouseEncode::Contended
                        | GuardedMouseEncode::SemanticsChanged
                        | GuardedMouseEncode::ContentChanged
                        | GuardedMouseEncode::Encoded(Err(_)),
                    )
                    | None => return true,
                }
            }
            Some(_) => return true,
            None => {
                let mut output = PtyInputBytes::new();
                match surface.encode_mouse(input, &mut output) {
                    Some(Ok(())) => output,
                    Some(Err(_)) | None => return true,
                }
            }
        };
        #[cfg(test)]
        self.encode_buf.extend_from_slice(&bytes);
        if bytes.is_empty() {
            return false;
        }
        let _ = self.enqueue_pty_bytes(surface_id, surface, bytes, PtyInputKind::Motion);
        true
    }

    #[allow(clippy::too_many_arguments)]
    fn forward_pty_mouse_to_surface(
        &mut self,
        surface_id: SurfaceId,
        content: Rect,
        x: u16,
        y: u16,
        action: MouseAction,
        button: Option<GhosttyMouseButton>,
        modifiers: KeyModifiers,
        any_button_pressed: bool,
        terminal_admission: Option<TerminalPointerAdmission>,
    ) -> Option<PtyInputForwardResult> {
        let Some(surface) = self.session.surface(surface_id) else {
            return Some(PtyInputForwardResult {
                owned: false,
                accepted: false,
                reservation_id: None,
            });
        };
        let cell_width = u32::from(self.cell_pixels.0.max(1));
        let cell_height = u32::from(self.cell_pixels.1.max(1));
        let position = (
            (x as f32 - content.x as f32 + 0.5) * cell_width as f32,
            (y as f32 - content.y as f32 + 0.5) * cell_height as f32,
        );
        let input = MouseInput {
            action,
            button,
            mods: Self::ghostty_mouse_mods(modifiers),
            position,
            screen_size: (
                u32::from(content.width).saturating_mul(cell_width),
                u32::from(content.height).saturating_mul(cell_height),
            ),
            cell_size: (cell_width, cell_height),
            any_button_pressed,
        };

        let (bytes, encoded) = match terminal_admission {
            Some(TerminalPointerAdmission {
                surface,
                encoding: TerminalPointerEncoding::Single(encoded),
                ..
            }) if surface == surface_id => (encoded, true),
            Some(_) => return None,
            None => {
                let mut output = PtyInputBytes::new();
                let encoded = surface.encode_mouse(input, &mut output)?.is_ok();
                (output, encoded)
            }
        };
        self.encode_buf.clear();
        #[cfg(test)]
        self.encode_buf.extend_from_slice(&bytes);
        if !encoded {
            return Some(PtyInputForwardResult {
                owned: true,
                accepted: false,
                reservation_id: None,
            });
        }
        if bytes.is_empty() {
            if action == MouseAction::Release {
                self.cancel_pty_release_reservation();
            }
            return Some(PtyInputForwardResult {
                owned: false,
                accepted: true,
                reservation_id: None,
            });
        }
        let kind = match action {
            MouseAction::Press
                if matches!(
                    button,
                    Some(
                        GhosttyMouseButton::Left
                            | GhosttyMouseButton::Right
                            | GhosttyMouseButton::Middle
                    )
                ) =>
            {
                PtyInputKind::Press
            }
            MouseAction::Press => PtyInputKind::Ordered,
            MouseAction::Release => PtyInputKind::Release,
            MouseAction::Motion => PtyInputKind::Motion,
        };
        let mut forwarded = self.enqueue_pty_bytes(surface_id, surface, bytes, kind);
        forwarded.owned = true;
        Some(forwarded)
    }

    fn write_encoded_pty_bytes(
        &mut self,
        surface_id: SurfaceId,
        surface: SurfaceHandle,
        kind: PtyInputKind,
    ) -> PtyInputForwardResult {
        let bytes = PtyInputBytes::from_slice(&self.encode_buf);
        self.enqueue_pty_bytes(surface_id, surface, bytes, kind)
    }

    fn write_pty_bytes(
        &mut self,
        surface_id: SurfaceId,
        surface: SurfaceHandle,
        bytes: PtyInputBytes,
        kind: PtyInputKind,
    ) -> bool {
        self.enqueue_pty_bytes(surface_id, surface, bytes, kind).accepted
    }

    fn enqueue_pty_bytes(
        &mut self,
        surface_id: SurfaceId,
        surface: SurfaceHandle,
        bytes: PtyInputBytes,
        kind: PtyInputKind,
    ) -> PtyInputForwardResult {
        if !self.session_available() {
            self.status_message =
                Some(localization::catalog().sidebar.no_active_session.to_string());
            return PtyInputForwardResult { owned: true, accepted: false, reservation_id: None };
        }
        if surface.is_dead() {
            self.status_message =
                Some(localization::catalog().terminal.pty_input_exited.to_string());
            return PtyInputForwardResult { owned: true, accepted: false, reservation_id: None };
        }
        let (result, reservation_id) = self
            .pty_input
            .enqueue_with_reservation(PtyInputEvent::input(surface_id, surface, bytes, kind));
        self.rollback_mouse_motion_for_enqueue_failure(surface_id, kind, result);
        PtyInputForwardResult {
            owned: true,
            accepted: self.handle_pty_enqueue_result(result),
            reservation_id,
        }
    }

    fn rollback_mouse_motion_for_enqueue_failure(
        &mut self,
        surface_id: SurfaceId,
        kind: PtyInputKind,
        result: PtyInputEnqueueResult,
    ) {
        if kind == PtyInputKind::Motion
            && matches!(result, PtyInputEnqueueResult::Saturated | PtyInputEnqueueResult::Failed)
            && let Some(surface) = self.session.surface(surface_id)
        {
            surface.reset_mouse_motion_dedupe();
        }
    }

    fn handle_pty_enqueue_result(&mut self, result: PtyInputEnqueueResult) -> bool {
        match result {
            PtyInputEnqueueResult::Accepted => true,
            PtyInputEnqueueResult::Oversized => {
                self.status_message =
                    Some(localization::catalog().terminal.pty_input_too_large.to_string());
                false
            }
            PtyInputEnqueueResult::Saturated => {
                self.status_message =
                    Some(localization::catalog().terminal.pty_input_queue_full.to_string());
                false
            }
            PtyInputEnqueueResult::Failed => {
                self.status_message =
                    Some(localization::catalog().terminal.pty_input_unavailable.to_string());
                false
            }
        }
    }

    fn prepare_pty_input_before_mutation(&mut self) -> bool {
        if !self.session_available() {
            self.status_message =
                Some(localization::catalog().sidebar.no_active_session.to_string());
            return false;
        }
        self.cancel_pty_mouse_drag();
        !matches!(self.drag, Some(Drag::PtyMouse { .. }))
    }

    fn focus_pane_after_input(&mut self, pane: PaneId) {
        if self.prepare_pty_input_before_mutation() {
            let focused = if let Some(screen) = self.tree.active_workspace_mut_screen()
                && screen.panes.iter().any(|candidate| candidate.id == pane)
            {
                screen.active_pane = pane;
                true
            } else {
                false
            };
            if focused {
                self.pane_focus_history.record(pane);
                self.claim_active_terminal_geometry(true);
            }
        }
    }

    fn select_tab_for_client(
        &mut self,
        pane: Option<PaneId>,
        index: Option<usize>,
        delta: Option<isize>,
    ) {
        let pane = pane.or_else(|| self.active_pane());
        if let Some(pane_id) = pane
            && let Some(pane) = self.tree.pane_mut(pane_id)
            && !pane.tabs.is_empty()
        {
            if let Some(index) = index.filter(|index| *index < pane.tabs.len()) {
                pane.active_tab = index;
            } else if let Some(delta) = delta {
                pane.active_tab = ((pane.active_tab as isize + delta)
                    .rem_euclid(pane.tabs.len() as isize))
                    as usize;
            }
        }
        self.claim_active_terminal_geometry(true);
    }

    fn select_screen_for_client(&mut self, index: Option<usize>, delta: Option<isize>) {
        let mut selected = false;
        if let Some(workspace) = self.tree.active_workspace_mut()
            && !workspace.screens.is_empty()
        {
            if let Some(index) = index.filter(|index| *index < workspace.screens.len()) {
                workspace.active_screen = index;
                selected = true;
            } else if let Some(delta) = delta {
                workspace.active_screen = ((workspace.active_screen as isize + delta)
                    .rem_euclid(workspace.screens.len() as isize))
                    as usize;
                selected = true;
            }
        }
        if selected && let Some(active) = self.active_pane() {
            self.pane_focus_history.record(active);
        }
        self.claim_active_terminal_geometry(true);
    }

    fn select_workspace_for_client(&mut self, index: Option<usize>, delta: Option<isize>) {
        let mut selected = false;
        if !self.tree.workspaces.is_empty() {
            if let Some(index) = index.filter(|index| *index < self.tree.workspaces.len()) {
                self.tree.active_workspace = index;
                selected = true;
            } else if let Some(delta) = delta {
                self.tree.active_workspace = ((self.tree.active_workspace as isize + delta)
                    .rem_euclid(self.tree.workspaces.len() as isize))
                    as usize;
                selected = true;
            }
        }
        if selected && let Some(active) = self.active_pane() {
            self.pane_focus_history.record(active);
        }
        self.claim_active_terminal_geometry(true);
    }

    fn terminal_input_rect(&self, area: &PaneArea) -> Option<Rect> {
        self.rendered_terminal_bounds.get(&area.surface).copied()
    }

    fn current_pty_content(&self, surface: SurfaceId) -> Option<Rect> {
        self.pane_areas
            .iter()
            .find(|area| area.surface == surface)
            .map(|area| self.canonical_pty_content(surface, area.logical_content_rect()))
    }

    fn current_browser_content(&self, surface: SurfaceId) -> Option<Rect> {
        self.pane_areas.iter().find(|area| area.surface == surface).map(|area| area.content)
    }

    fn current_selection_geometry(&self, surface: SurfaceId) -> Option<(Rect, u16)> {
        let area = self.pane_areas.iter().find(|area| area.surface == surface)?;
        Some((self.terminal_input_rect(area)?, area.content_source_x()))
    }

    fn current_pty_pointer(&self, surface: SurfaceId, x: u16, y: u16) -> Option<(Rect, u16, u16)> {
        let area = self.pane_areas.iter().find(|area| area.surface == surface)?;
        let content = self.canonical_pty_content(surface, area.logical_content_rect());
        let (x, y) = area.logical_content_point(x, y);
        Some((content, x, y))
    }

    fn canonical_pty_content(&self, surface: SurfaceId, content: Rect) -> Rect {
        canonical_terminal_content(content, self.rendered_terminal_sizes.get(&surface).copied())
    }

    fn cancel_pty_release_reservation(&self) {
        if let Some(Drag::PtyMouse { reservation_id, .. }) = &self.drag {
            self.pty_input.cancel_release_reservation(*reservation_id);
        }
    }

    fn ghostty_mouse_button(button: MouseButton) -> GhosttyMouseButton {
        match button {
            MouseButton::Left => GhosttyMouseButton::Left,
            MouseButton::Right => GhosttyMouseButton::Right,
            MouseButton::Middle => GhosttyMouseButton::Middle,
        }
    }

    fn ghostty_mouse_mods(modifiers: KeyModifiers) -> Mods {
        let mut mods = Mods::default();
        if modifiers.contains(KeyModifiers::SHIFT) {
            mods = mods | Mods::SHIFT;
        }
        if modifiers.contains(KeyModifiers::CONTROL) {
            mods = mods | Mods::CTRL;
        }
        if modifiers.contains(KeyModifiers::ALT) {
            mods = mods | Mods::ALT;
        }
        if modifiers.contains(KeyModifiers::SUPER) {
            mods = mods | Mods::SUPER;
        }
        mods
    }

    /// Whether the cell is over something clickable (any hit, a menu row,
    /// or a dialog button): these render the hand pointer.
    fn is_clickable(&self, x: u16, y: u16) -> bool {
        if let Some(dialog) = &self.pairing_dialog {
            return dialog.approve.contains(x, y) || dialog.deny.contains(x, y);
        }
        if let Some(prompt) = &self.prompt {
            return prompt.ok.contains(x, y)
                || prompt.cancel.contains(x, y)
                || prompt.clear.contains(x, y)
                || prompt.input_rect.contains(x, y);
        }
        if let Some(menu) = &self.menu {
            // Everything inside the menu rect is menu territory: item rows
            // and scrollbar tracks are clickable; border cells never inherit
            // clickability from hits underneath.
            if menu.contains(x, y) {
                return menu.hit_at(x, y).is_some() || menu.scrollbar_at(x, y).is_some();
            }
        }
        if self.omnibar_hit_at(x, y).is_some() {
            return true;
        }
        self.hit_at(x, y).is_some()
    }

    /// Keep the terminal's mouse pointer shape in sync: a hand over
    /// clickable UI, the default elsewhere (OSC 22; terminals without
    /// support ignore it).
    fn sync_pointer_shape(&mut self, x: u16, y: u16) {
        let want_pointer = self.is_clickable(x, y);
        if want_pointer == self.pointer_shape {
            return;
        }
        let shape = if want_pointer { "pointer" } else { "default" };
        let lock = self.stdout_lock.clone();
        let _guard = lock.lock();
        if lock.recover_stream_locked().is_err() {
            return;
        }
        if self.ensure_graphics_writer_healthy().is_err() {
            return;
        }
        self.pointer_shape = want_pointer;
        let mut stdout = std::io::stdout();
        let _ = write!(stdout, "\x1b]22;{shape}\x07");
        let _ = stdout.flush();
    }

    /// Mouse-move: sync the pointer shape, highlight the hovered menu
    /// item, and track the mouse position so tab-bar controls (+, ‹, ›)
    /// and the scrollbar render a hover state. Only redraws when the
    /// hovered element actually changes.
    fn handle_hover_with_admission(
        &mut self,
        x: u16,
        y: u16,
        modifiers: KeyModifiers,
        terminal_admission: Option<TerminalPointerAdmission>,
    ) -> anyhow::Result<RenderAction> {
        self.sync_pointer_shape(x, y);
        if let Some(menu) = self.menu.as_mut() {
            let before_scrollbar =
                self.hover.and_then(|(px, py)| menu.scrollbar_at(px, py).map(|(depth, _)| depth));
            let after_scrollbar = menu.scrollbar_at(x, y).map(|(depth, _)| depth);
            let selection_changed =
                menu.hit_at(x, y).is_some_and(|(depth, item)| menu.select_at(depth, item));
            self.hover = Some((x, y));
            return Ok(if selection_changed || before_scrollbar != after_scrollbar {
                RenderAction::Draw
            } else {
                RenderAction::None
            });
        }
        if self.menu.is_none() && self.prompt.is_none() && self.drag.is_none() {
            let _ = self.forward_pty_mouse_at_with_admission(
                (x, y),
                MouseAction::Motion,
                None,
                modifiers,
                false,
                terminal_admission,
            );
            let mut over_browser = false;
            if let Some(area) = self
                .pane_areas
                .iter()
                .find(|area| {
                    area.content.contains(x, y)
                        && self.surface_kind(area.surface) == Some(SurfaceKind::Browser)
                })
                .copied()
            {
                over_browser = true;
                let editing_same_pane =
                    self.omnibar.as_ref().is_some_and(|state| state.pane == area.pane);
                let status = self.session.surface(area.surface).and_then(|surface| {
                    (surface.kind() == SurfaceKind::Browser).then(|| surface.browser_status())
                });
                if browser_hover_forward_allowed(status.flatten(), editing_same_pane) {
                    let cell = (
                        area.content_source_x().saturating_add(x.saturating_sub(area.content.x)),
                        y.saturating_sub(area.content.y),
                    );
                    if let Some(frame_seq) = self.processed_browser_pointer_authority(area.surface)
                    {
                        let next = (area.surface, cell.0, cell.1, frame_seq);
                        if self.last_browser_hover != Some(next) {
                            let _ = self.send_browser_mouse(
                                area.surface,
                                area.content,
                                x,
                                y,
                                frame_seq,
                                BrowserMouseDispatch::new("mouseMoved", Some("none"), None),
                            );
                            self.last_browser_hover = Some(next);
                        }
                    }
                }
            }
            if !over_browser {
                self.last_browser_hover = None;
            }
        }
        let hoverable = |pos: Option<(u16, u16)>| {
            pos.and_then(|(px, py)| {
                self.hit_at(px, py)
                    .filter(|hit| {
                        matches!(
                            hit,
                            Hit::NewTab { .. }
                                | Hit::TabScroll { .. }
                                | Hit::Scrollbar { .. }
                                | Hit::HorizontalScrollbar { .. }
                                | Hit::WorkspaceScrollbar { .. }
                        )
                    })
                    .map(|hit| format!("{hit:?}"))
                    .or_else(|| {
                        self.omnibar_hit_at(px, py)
                            .filter(|(_, hit)| *hit != OmnibarHit::Edit)
                            .map(|(_, hit)| format!("{hit:?}"))
                    })
            })
        };
        let before = hoverable(self.hover);
        let after = hoverable(Some((x, y)));
        self.hover = Some((x, y));
        Ok(if before != after { RenderAction::Draw } else { RenderAction::None })
    }

    fn handle_right_drag(&mut self, x: u16, y: u16) -> anyhow::Result<RenderAction> {
        self.hover = Some((x, y));
        let Some(menu) = self.menu.as_mut() else { return Ok(RenderAction::None) };
        if (x, y) != menu.right_press {
            menu.right_drag_moved = true;
        }
        if let Some((depth, item)) = menu.hit_at(x, y)
            && menu.select_at(depth, item)
        {
            return Ok(RenderAction::Draw);
        }
        Ok(RenderAction::None)
    }

    fn handle_right_up(&mut self, x: u16, y: u16) -> anyhow::Result<RenderAction> {
        let Some(mut menu) = self.menu.take() else { return Ok(RenderAction::None) };
        let plain_open_click = !menu.right_drag_moved && (x, y) == menu.right_press;
        if plain_open_click {
            self.menu = Some(menu);
        } else if let Some((depth, item)) = menu.hit_at(x, y) {
            let action = menu.action_at(depth, item);
            menu.select_at(depth, item);
            if let Some(action) = action {
                let resource_matches = menu
                    .captured_resource(action)
                    .is_none_or(|expected| self.menu_action_resource(action) == expected);
                if resource_matches {
                    self.activate_menu(action)?;
                }
            } else {
                self.menu = Some(menu);
            }
        } else {
            self.menu = Some(menu);
        }
        Ok(RenderAction::Draw)
    }

    #[cfg(test)]
    fn handle_left_down(
        &mut self,
        x: u16,
        y: u16,
        modifiers: KeyModifiers,
    ) -> anyhow::Result<RenderAction> {
        self.handle_left_down_with_admission(x, y, modifiers, None)
    }

    fn handle_left_down_with_admission(
        &mut self,
        x: u16,
        y: u16,
        modifiers: KeyModifiers,
        terminal_admission: Option<TerminalPointerAdmission>,
    ) -> anyhow::Result<RenderAction> {
        self.replace_selection(None);
        self.status_selection = None;
        self.finish_active_drag();

        if self.pairing_dialog.is_some() {
            return self.handle_pairing_click(x, y);
        }
        // An open rename dialog captures the click.
        if self.prompt.is_some() {
            return self.handle_prompt_click(x, y);
        }

        // An open menu captures the click: activate or dismiss. Clicks on
        // the border chrome keep it open without activating.
        if let Some(mut menu) = self.menu.take() {
            if menu.start_scrollbar_drag(x, y) {
                self.menu = Some(menu);
            } else if let Some((depth, item)) = menu.hit_at(x, y) {
                let action = menu.action_at(depth, item);
                menu.select_at(depth, item);
                if let Some(action) = action {
                    let resource_matches = menu
                        .captured_resource(action)
                        .is_none_or(|expected| self.menu_action_resource(action) == expected);
                    if resource_matches {
                        self.activate_menu(action)?;
                    }
                } else {
                    self.menu = Some(menu);
                }
            } else if menu.contains(x, y) {
                self.menu = Some(menu); // padding click: keep it open
            }
            return Ok(RenderAction::Draw);
        }

        if let Some((pane, hit)) = self.omnibar_hit_at(x, y) {
            self.focus_pane_after_input(pane);
            if let Some(state) = self.omnibar.as_mut() {
                if state.pane == pane {
                    if hit == OmnibarHit::Edit
                        && let Some(area) = self
                            .pane_areas
                            .iter()
                            .find(|area| area.pane == pane && area.surface == state.surface)
                        && let Some(rect) = area.omnibar
                    {
                        state.select_all = false;
                        state.input.set_cursor_from_visible_column(
                            x.saturating_sub(rect.x) as usize,
                            rect.width as usize,
                        );
                    }
                    return Ok(RenderAction::Draw);
                }
                self.omnibar = None;
            }
            match hit {
                OmnibarHit::Back => {
                    self.enqueue_browser_command_for_pane(pane, BrowserInputKind::Back);
                }
                OmnibarHit::Forward => {
                    self.enqueue_browser_command_for_pane(pane, BrowserInputKind::Forward);
                }
                OmnibarHit::Reload => {
                    self.enqueue_browser_command_for_pane(pane, BrowserInputKind::Reload);
                }
                OmnibarHit::Edit => self.focus_omnibar(pane),
            }
            return Ok(RenderAction::Draw);
        }

        if let Some(state) = &self.omnibar {
            let editing_rect = self
                .pane_areas
                .iter()
                .find(|area| area.pane == state.pane && area.surface == state.surface)
                .and_then(|area| area.omnibar);
            if !editing_rect.is_some_and(|rect| rect.contains(x, y)) {
                self.omnibar = None;
            }
        }

        if self.config.sidebar.plugin.is_some()
            && self.sidebar_plugin_rect().contains(x, y)
            && self.sidebar_visible
        {
            let requested = self.sync_sidebar_plugin(true);
            if self.sidebar_plugin_surface.is_some() {
                self.focus = FocusTarget::WorkspaceRail;
            } else {
                self.leave_workspace_sidebar();
            }
            self.sidebar_focus_pending = requested && self.sidebar_plugin_surface.is_none();
            return Ok(RenderAction::Draw);
        }
        // Any click outside the plugin rect returns keyboard focus to the
        // panes; otherwise typing would keep going to the plugin PTY after
        // the user clicked into a pane.
        self.leave_workspace_sidebar();
        self.sidebar_focus_pending = false;

        if let Some(hit) = self.hit_at(x, y) {
            match hit {
                Hit::Machine { index, key } => {
                    self.machine_rail_follow_selection = true;
                    if let Some(machine) = self.machine_ui.as_mut() {
                        machine.selection = index;
                        machine.rail_selection = MachineRailSelection::Machine;
                    }
                    self.focus = FocusTarget::Pane;
                    self.activate_machine(key);
                }
                Hit::NewVm => {
                    self.machine_rail_follow_selection = true;
                    if let Some(machine) = self.machine_ui.as_mut() {
                        machine.rail_selection = MachineRailSelection::NewVm;
                    }
                    self.open_machine_creation_menu(x, y);
                }
                Hit::ConnectMachine => {
                    self.machine_rail_follow_selection = true;
                    if let Some(machine) = self.machine_ui.as_mut() {
                        machine.rail_selection = MachineRailSelection::ConnectMachine;
                    }
                    self.open_machine_connection_menu(x, y);
                }
                Hit::Workspace { index, id } => {
                    self.workspace_rail_follow_selection = true;
                    self.focus = FocusTarget::Pane;
                    self.activate_workspace(index);
                    self.drag = Some(Drag::WorkspaceArm { workspace: id, at: (x, y) });
                }
                Hit::SidebarTab { surface, .. } => {
                    let targets = self.sidebar_tab_targets();
                    if let Some((index, target)) =
                        targets.iter().enumerate().find(|(_, target)| target.surface == surface)
                    {
                        self.tabs_rail_follow_selection = true;
                        self.tabs_rail_selection = index;
                        self.activate_sidebar_tab(target)?;
                        self.focus = FocusTarget::Pane;
                    }
                }
                Hit::ProjectionToggle { view, branch } => {
                    let state = self.projection_rail_state_mut(view);
                    if !state.collapsed.remove(&branch) {
                        state.collapsed.insert(branch);
                    }
                }
                Hit::ProjectionRow { view, row, target } => {
                    let state = self.projection_rail_state_mut(view);
                    state.selected = row;
                    state.selected_action = None;
                    state.follow_selection = true;
                    self.activate_projection_target(target)?;
                    self.focus = FocusTarget::Pane;
                }
                Hit::RailPad(kind) => {
                    self.focus_rail(kind);
                }
                Hit::SidebarAction { view, action } => {
                    let kind = self.rail_kind_for_view(view);
                    match kind {
                        RailKind::Workspace => {
                            self.workspace_rail_selection = WorkspaceRailSelection::Action(action);
                            self.workspace_rail_follow_selection = true;
                        }
                        RailKind::Projection(_) => {
                            let action_index = self
                                .sidebar_action_rows(view)
                                .iter()
                                .position(|candidate| candidate.target == action)
                                .unwrap_or_default();
                            let state = self.projection_rail_state_mut(view);
                            state.selected_action = Some(action_index);
                            state.follow_selection = true;
                        }
                        RailKind::Machine | RailKind::Tabs => {}
                    }
                    return self.invoke_sidebar_action(action);
                }
                Hit::RecoverableWorkspace { index } => {
                    self.workspace_rail_follow_selection = true;
                    self.sidebar_recoverable_workspace_selection = index;
                    self.workspace_rail_selection = WorkspaceRailSelection::Recoverable;
                    self.focus = FocusTarget::Pane;
                    let workspace_id = self
                        .machine_ui
                        .as_ref()
                        .and_then(|ui| ui.recoverable_workspaces().get(index).copied())
                        .map(|workspace| workspace.id.clone());
                    if let Some(workspace_id) = workspace_id {
                        self.request_restore_managed_workspace(&workspace_id);
                    }
                }
                Hit::CreateWorkspace { mode } => {
                    self.workspace_rail_follow_selection = true;
                    self.workspace_rail_selection = workspace_creation_selection(mode);
                    self.create_workspace(mode, None)?;
                }
                Hit::SidebarFile { index } => {
                    self.focus = FocusTarget::WorkspaceRail;
                    self.sidebar_files.select(index);
                }
                Hit::SidebarFilterInput => {
                    self.focus = FocusTarget::WorkspaceRail;
                    if let Some(area) =
                        self.workspace_sidebar_area(self.content_area.height.saturating_add(1))
                    {
                        let input_width = area.width.saturating_sub(2);
                        let column = x.saturating_sub(area.x + 1) as usize;
                        self.sidebar_files
                            .set_filter_cursor_from_visible_column(column, input_width as usize);
                    }
                }
                Hit::ScreenEntry { index, .. } => {
                    self.focus = FocusTarget::Pane;
                    if self.prepare_pty_input_before_mutation() {
                        self.select_screen_for_client(Some(index), None);
                    }
                }
                Hit::StatusMessage => {
                    self.begin_status_message_selection(x);
                }
                Hit::CopyStatusMessage => self.copy_status_message(),
                Hit::NewScreen => {
                    self.focus = FocusTarget::Pane;
                    if let Some(action) = self.config.status_bar.screens_plus.action {
                        let pane = self.active_pane();
                        self.run_action_for_pane(action, pane)?;
                    } else {
                        self.new_screen(None)?;
                    }
                }
                Hit::Tab { pane, index } => {
                    if let Some(surface) = self
                        .tree
                        .pane(pane)
                        .and_then(|pane| pane.tabs.get(index))
                        .map(|t| t.surface)
                    {
                        self.drag = Some(Drag::TabArm { surface, at: (x, y) });
                    }
                }
                Hit::NewTab { pane } => {
                    self.focus_pane_after_input(pane);
                    if let Some(action) = self.config.tabs.plus.action {
                        self.run_action_for_pane(action, Some(pane))?;
                    } else if self.prepare_pty_input_before_mutation() {
                        self.session
                            .new_tab(Some(pane), self.terminal_tab_size_hint(Some(pane)))?;
                    }
                }
                Hit::Clients { surface } => self.open_clients_menu(x, y, surface),
                Hit::Scrollbar { surface, track, scrollbar } => {
                    self.start_scrollbar_drag(surface, track, scrollbar, y);
                }
                Hit::HorizontalScrollbar { track } => {
                    self.start_horizontal_scrollbar_drag(track, x);
                }
                Hit::WorkspaceScrollbar { track, total_rows, visible_rows } => {
                    self.workspace_rail_follow_selection = false;
                    self.start_workspace_scrollbar_drag(track, total_rows, visible_rows, y);
                }
                Hit::RailResize(kind) => {
                    self.drag = Some(Drag::RailResize(kind));
                }
                Hit::PaneResize { horizontal, vertical } => {
                    let horizontal = horizontal
                        .and_then(|(pane, edge)| self.resolve_pane_resize_drag(pane, edge));
                    let vertical =
                        vertical.and_then(|(pane, edge)| self.resolve_pane_resize_drag(pane, edge));
                    if horizontal.is_some() || vertical.is_some() {
                        self.drag = Some(Drag::ResizeSplit { horizontal, vertical });
                    }
                }
                Hit::TabScroll { pane, delta } => self.scroll_tabs(pane, delta),
            }
            return Ok(RenderAction::Draw);
        }

        if let Some(area) = self.pane_area_at(x, y).copied() {
            self.focus = FocusTarget::Pane;
            if area.content.contains(x, y) {
                if self.surface_kind(area.surface) == Some(SurfaceKind::Browser) {
                    if self.active_pane() != Some(area.pane) {
                        self.focus_pane_after_input(area.pane);
                    }
                    if let Some(frame_seq) = self.processed_browser_pointer_authority(area.surface)
                        && self.send_browser_mouse(
                            area.surface,
                            area.content,
                            x,
                            y,
                            frame_seq,
                            BrowserMouseDispatch::new("mousePressed", Some("left"), Some(1)),
                        )
                    {
                        self.drag = Some(Drag::Browser {
                            surface: area.surface,
                            content: area.content,
                            position: (x, y),
                            frame_seq,
                        });
                    }
                } else if self.begin_pty_mouse_drag_with_admission(
                    x,
                    y,
                    MouseButton::Left,
                    modifiers,
                    terminal_admission,
                ) != PtyMousePressResult::NotOwned
                {
                    return Ok(RenderAction::Draw);
                } else {
                    if self.active_pane() != Some(area.pane) {
                        self.focus_pane_after_input(area.pane);
                    }
                    let Some(content) = self.terminal_input_rect(&area) else {
                        return Ok(RenderAction::Draw);
                    };
                    if !content.contains(x, y) {
                        return Ok(RenderAction::Draw);
                    }
                    // Begin a text selection; it becomes visible once the
                    // mouse moves to a second cell.
                    let offset = self.surface_scroll_offset(area.surface);
                    let source_x = area.content_source_x();
                    let col = source_x.saturating_add(x - content.x);
                    let cell = (col, offset + (y - content.y) as u64);
                    self.replace_selection(Some(Selection {
                        surface: area.surface,
                        anchor: cell,
                        head: cell,
                    }));
                    self.drag = Some(Drag::Select { content, source_x, auto_scroll: None, col });
                }
            } else if self.active_pane() != Some(area.pane) {
                self.focus_pane_after_input(area.pane);
            }
            return Ok(RenderAction::Draw);
        }
        Ok(RenderAction::None)
    }

    fn handle_left_drag(&mut self, x: u16, y: u16) -> anyhow::Result<RenderAction> {
        if let Some(menu) = self.menu.as_mut()
            && menu.scrollbar_drag.is_some()
        {
            menu.drag_scrollbar(y);
            self.hover = Some((x, y));
            return Ok(RenderAction::Draw);
        }
        match &self.drag {
            Some(Drag::TabArm { surface, at }) => {
                let (surface, at) = (*surface, *at);
                if (x, y) != at {
                    let target = self.tab_drop_target_at(x, y);
                    self.drag = Some(Drag::Tab { surface, target });
                }
                Ok(RenderAction::Draw)
            }
            Some(Drag::Tab { surface, .. }) => {
                let surface = *surface;
                let target = self.tab_drop_target_at(x, y);
                self.drag = Some(Drag::Tab { surface, target });
                Ok(RenderAction::Draw)
            }
            Some(Drag::WorkspaceArm { workspace, at }) => {
                let (workspace, at) = (*workspace, *at);
                if (x, y) != at {
                    let target = self.workspace_drop_target_at(x, y);
                    self.drag = Some(Drag::Workspace { workspace, target });
                }
                Ok(RenderAction::Draw)
            }
            Some(Drag::Workspace { workspace, .. }) => {
                let workspace = *workspace;
                let target = self.workspace_drop_target_at(x, y);
                self.drag = Some(Drag::Workspace { workspace, target });
                Ok(RenderAction::Draw)
            }
            Some(Drag::Select { content, source_x, .. }) => {
                let fallback = (*content, *source_x);
                let (content, source_x) = self
                    .selection
                    .and_then(|selection| self.current_selection_geometry(selection.surface))
                    .unwrap_or(fallback);
                let cx = x.clamp(content.x, content.x + content.width.saturating_sub(1));
                let cy = y.clamp(content.y, content.y + content.height.saturating_sub(1));
                let col = source_x.saturating_add(cx - content.x);
                let offset =
                    self.selection.map(|sel| self.surface_scroll_offset(sel.surface)).unwrap_or(0);
                if let Some(mut selection) = self.selection {
                    selection.head = (col, offset + (cy - content.y) as u64);
                    self.replace_selection(Some(selection));
                }
                let auto_scroll = if y <= content.y {
                    Some(-1)
                } else if y >= content.y + content.height.saturating_sub(1) {
                    Some(1)
                } else {
                    None
                };
                self.drag = Some(Drag::Select { content, source_x, auto_scroll, col });
                Ok(RenderAction::Draw)
            }
            Some(Drag::StatusMessage { rect }) => {
                let rect = *rect;
                if rect.width == 0 {
                    self.drag = None;
                    self.status_selection = None;
                    return Ok(RenderAction::Draw);
                }
                let cell = x.clamp(rect.x, rect.x + rect.width - 1) - rect.x;
                if let Some(selection) = self.status_selection.as_mut() {
                    selection.head = cell;
                }
                Ok(RenderAction::Draw)
            }
            Some(Drag::Browser { surface, content, frame_seq, .. }) => {
                let (surface, frame_seq) = (*surface, *frame_seq);
                let content = self.current_browser_content(surface).unwrap_or(*content);
                let cx = x.clamp(content.x, content.x + content.width.saturating_sub(1));
                let cy = y.clamp(content.y, content.y + content.height.saturating_sub(1));
                self.drag = Some(Drag::Browser { surface, content, position: (cx, cy), frame_seq });
                let _ = self.send_browser_mouse(
                    surface,
                    content,
                    cx,
                    cy,
                    frame_seq,
                    BrowserMouseDispatch::new("mouseMoved", Some("left"), Some(1)),
                );
                Ok(RenderAction::Draw)
            }
            Some(Drag::PtyMouse { .. }) => Ok(RenderAction::None),
            Some(Drag::Scrollbar {
                surface,
                track,
                anchor_y,
                anchor_offset,
                position_y,
                scrollbar,
            }) => {
                let surface = *surface;
                let state = ScrollbarDragState {
                    track: *track,
                    anchor_y: *anchor_y,
                    anchor_offset: *anchor_offset,
                    position_y: *position_y,
                    scrollbar: *scrollbar,
                };
                let Some((rendered_track, rendered_scrollbar)) = self.rendered_scrollbar(surface)
                else {
                    self.drag = None;
                    return Ok(RenderAction::Draw);
                };
                if let Some(updated) =
                    self.drag_scrollbar(surface, state, (rendered_track, rendered_scrollbar), y)
                {
                    self.drag = Some(Drag::Scrollbar {
                        surface,
                        track: updated.track,
                        anchor_y: updated.anchor_y,
                        anchor_offset: updated.anchor_offset,
                        position_y: updated.position_y,
                        scrollbar: updated.scrollbar,
                    });
                }
                Ok(RenderAction::Draw)
            }
            Some(Drag::HorizontalScrollbar { track, anchor_x, anchor_offset }) => {
                let (track, anchor_x, anchor_offset) = (*track, *anchor_x, *anchor_offset);
                if let Some((content_width, viewport_width, _)) = self.horizontal_scrollbar_state()
                {
                    let target = horizontal_drag_offset(
                        content_width,
                        viewport_width,
                        track.width,
                        anchor_offset,
                        i128::from(x) - i128::from(anchor_x),
                    );
                    self.set_viewport_target(target, false);
                }
                Ok(RenderAction::Draw)
            }
            Some(Drag::WorkspaceScrollbar {
                track,
                total_rows,
                visible_rows,
                anchor_y,
                anchor_offset,
            }) => {
                let (track, total_rows, visible_rows, anchor_y, anchor_offset) =
                    (*track, *total_rows, *visible_rows, *anchor_y, *anchor_offset);
                self.workspace_rail_scroll = viewport_drag_offset(
                    total_rows,
                    visible_rows,
                    track.height,
                    anchor_offset,
                    y as i128 - anchor_y as i128,
                );
                Ok(RenderAction::Draw)
            }
            Some(Drag::RailResize(kind)) => {
                let kind = *kind;
                if let Some(width) = rail_drag_width(&self.config, &self.sidebar_layout, kind, x) {
                    match kind {
                        RailKind::Machine => self.machine_sidebar_width_override = Some(width),
                        RailKind::Workspace => {
                            self.sidebar_compact = false;
                            self.sidebar_width_override = Some(width);
                        }
                        RailKind::Tabs => self.tabs_sidebar_width_override = Some(width),
                        RailKind::Projection(index) => {
                            if let Some(id) =
                                self.config.sidebar.views.get(index).map(|view| view.id.clone())
                            {
                                self.projection_sidebar_width_overrides.insert(id, width);
                            }
                        }
                    }
                }
                Ok(RenderAction::Draw)
            }
            Some(Drag::ResizeSplit { horizontal, vertical }) => {
                let (horizontal, vertical) = (*horizontal, *vertical);
                if let Some(target) = horizontal {
                    self.resize_drag_target(target, x, y);
                }
                if let Some(target) = vertical {
                    self.resize_drag_target(target, x, y);
                }
                Ok(RenderAction::Draw)
            }
            None => Ok(RenderAction::None),
        }
    }

    fn handle_left_up(&mut self, x: u16, y: u16) -> anyhow::Result<RenderAction> {
        if let Some(menu) = self.menu.as_mut()
            && menu.finish_scrollbar_drag()
        {
            self.hover = Some((x, y));
            return Ok(RenderAction::Draw);
        }
        if let Some(Drag::TabArm { surface, .. }) = self.drag {
            self.drag = None;
            if let Some((pane, index)) = self.tab_location(surface) {
                self.focus_pane_after_input(pane);
                if self.prepare_pty_input_before_mutation() {
                    self.select_tab_for_client(Some(pane), Some(index), None);
                }
            }
            return Ok(RenderAction::Draw);
        }
        if let Some(Drag::Tab { surface, .. }) = self.drag {
            self.drag = None;
            if let Some((pane, index)) = self.tab_drop_target_at(x, y)
                && self.prepare_pty_input_before_mutation()
            {
                self.session.move_tab(surface, pane, index);
            }
            return Ok(RenderAction::Draw);
        }
        if matches!(self.drag, Some(Drag::WorkspaceArm { .. })) {
            self.drag = None;
            return Ok(RenderAction::Draw);
        }
        if let Some(Drag::Workspace { workspace, .. }) = self.drag {
            self.drag = None;
            if let Some(insertion) = self.workspace_drop_target_at(x, y)
                && self.prepare_pty_input_before_mutation()
            {
                self.session.move_workspace(workspace, insertion);
            }
            return Ok(RenderAction::Draw);
        }
        if let Some(Drag::Browser { surface, content, frame_seq, .. }) = self.drag {
            self.drag = None;
            let content = self.current_browser_content(surface).unwrap_or(content);
            let cx = x.clamp(content.x, content.x + content.width.saturating_sub(1));
            let cy = y.clamp(content.y, content.y + content.height.saturating_sub(1));
            let _ = self.send_browser_mouse(
                surface,
                content,
                cx,
                cy,
                frame_seq,
                BrowserMouseDispatch::new("mouseReleased", Some("left"), Some(1)),
            );
            return Ok(RenderAction::Draw);
        }
        if matches!(self.drag, Some(Drag::ResizeSplit { .. })) {
            self.drag = None;
            self.session.settle_split_ratio();
            return Ok(RenderAction::Draw);
        }
        if matches!(self.drag, Some(Drag::StatusMessage { .. })) {
            self.drag = None;
            match self.status_selection.as_ref() {
                Some(selection) if selection.anchor != selection.head => {
                    self.copy_status_message_selection();
                }
                _ => self.status_selection = None,
            }
            return Ok(RenderAction::Draw);
        }
        let was_select = matches!(self.drag, Some(Drag::Select { .. }));
        let was_drag = self.drag.is_some();
        self.drag = None;
        if !was_select {
            return Ok(if was_drag { RenderAction::Draw } else { RenderAction::None });
        }
        match self.selection {
            Some(sel) if sel.anchor != sel.head => {
                self.copy_selection(sel);
                Ok(RenderAction::Draw)
            }
            _ => {
                // A plain click: no selection to keep.
                self.replace_selection(None);
                Ok(RenderAction::Draw)
            }
        }
    }

    /// Copy the selected text to the host clipboard via OSC 52 (the host
    /// terminal owns the clipboard; this works over SSH too).
    fn copy_selection(&mut self, sel: Selection) {
        let Some(surface) = self.session.surface(sel.surface) else { return };
        let (start, end) = sel.range();
        let Some(text) = surface.with_terminal(|t| t.selection_text_absolute(start, end)).flatten()
        else {
            return;
        };
        if text.is_empty() {
            return;
        }
        if let SurfaceHandle::Local(local, _) = &surface {
            local.set_selection_text(Some(text.clone()));
        }
        self.copy_text_to_clipboard(&text);
        self.show_toast(localization::catalog().menu.copied.to_string());
    }

    fn copy_status_message_selection(&mut self) {
        let Some(text) = self
            .status_selection
            .as_ref()
            .map(StatusMessageSelection::selected_text)
            .filter(|text| !text.is_empty())
        else {
            return;
        };
        self.copy_text_to_clipboard(&text);
        self.show_toast(localization::catalog().menu.copied.to_string());
    }

    fn copy_status_message(&mut self) {
        let Some(message) = self.status_message.clone() else { return };
        self.copy_text_to_clipboard(&message);
        self.show_toast(localization::catalog().menu.copied.to_string());
    }

    fn copy_text_to_clipboard(&self, text: &str) {
        let encoded = base64::engine::general_purpose::STANDARD.encode(text.as_bytes());
        let lock = self.stdout_lock.clone();
        let _guard = lock.lock();
        if lock.recover_stream_locked().is_err() {
            return;
        }
        if self.ensure_graphics_writer_healthy().is_err() {
            return;
        }
        let mut stdout = std::io::stdout();
        let _ = write!(stdout, "\x1b]52;c;{encoded}\x07");
        let _ = stdout.flush();
    }

    fn copy_short_id(&mut self, short_id: String) {
        self.copy_text_to_clipboard(&short_id);
        self.show_toast(format!("{} {short_id}", localization::catalog().menu.copied));
    }

    fn show_toast(&mut self, text: String) {
        crate::client_log::info("toast", &text);
        self.toast = Some(Toast { text, deadline: Instant::now() + Duration::from_millis(1500) });
    }

    fn expire_toast(&mut self) -> bool {
        if self.toast.as_ref().is_some_and(|toast| Instant::now() >= toast.deadline) {
            self.toast = None;
            true
        } else {
            false
        }
    }

    /// Shift a pane's tab bar left/right. The renderer clamps to the
    /// valid range next frame.
    fn scroll_tabs(&mut self, pane: PaneId, delta: isize) {
        let entry = self.tab_scroll.entry(pane).or_insert(0);
        *entry = entry.saturating_add_signed(delta);
    }

    /// Start a scrollbar drag. Clicking the thumb only anchors; clicking
    /// outside it jumps first, then anchors at the clicked position.
    fn start_scrollbar_drag(
        &mut self,
        surface: SurfaceId,
        track: Rect,
        scrollbar: Scrollbar,
        y: u16,
    ) {
        let Some(handle) = self.session.surface(surface) else { return };
        let rel_y = y.saturating_sub(track.y).min(track.height.saturating_sub(1));
        let (thumb_y, thumb_len) = thumb_geometry(&scrollbar, track.height);
        let on_thumb = rel_y >= thumb_y && rel_y < thumb_y + thumb_len;
        let target = if on_thumb {
            scrollbar.offset
        } else {
            let denom = track.height.saturating_sub(1).max(1) as f64;
            let frac = (rel_y as f64 / denom).clamp(0.0, 1.0);
            ((scrollbar.total - scrollbar.len) as f64 * frac).round() as u64
        };
        let delta = (target as i128 - scrollbar.offset as i128)
            .clamp(isize::MIN as i128, isize::MAX as i128) as isize;
        let Some(scrollbar) = handle.scroll_delta_if_scrollbar(scrollbar, delta) else {
            return;
        };
        self.drag = Some(Drag::Scrollbar {
            surface,
            track,
            anchor_y: y,
            anchor_offset: scrollbar.offset,
            position_y: y,
            scrollbar,
        });
    }

    fn rendered_scrollbar(&self, surface: SurfaceId) -> Option<(Rect, Scrollbar)> {
        self.rendered_pointer_frame.hits.iter().find_map(|route| match route.hit {
            Hit::Scrollbar { surface: candidate, track, scrollbar } if candidate == surface => {
                Some((track, scrollbar))
            }
            _ => None,
        })
    }

    /// Start a workspace viewport scrollbar drag, jumping on track clicks.
    fn start_workspace_scrollbar_drag(
        &mut self,
        track: Rect,
        total_rows: usize,
        visible_rows: usize,
        y: u16,
    ) {
        if track.height == 0 {
            return;
        }
        let relative = y.saturating_sub(track.y).min(track.height.saturating_sub(1));
        let (thumb_y, thumb_height) = viewport_thumb_geometry(
            total_rows,
            visible_rows,
            self.workspace_rail_scroll,
            track.height,
        );
        if relative < thumb_y || relative >= thumb_y.saturating_add(thumb_height) {
            self.workspace_rail_scroll =
                viewport_jump_offset(total_rows, visible_rows, track.height, relative);
        }
        self.drag = Some(Drag::WorkspaceScrollbar {
            track,
            total_rows,
            visible_rows,
            anchor_y: y,
            anchor_offset: self.workspace_rail_scroll,
        });
    }

    /// Map an anchored scrollbar drag delta to a viewport offset.
    fn drag_scrollbar(
        &mut self,
        surface: SurfaceId,
        state: ScrollbarDragState,
        rendered: (Rect, Scrollbar),
        y: u16,
    ) -> Option<ScrollbarDragState> {
        let handle = self.session.surface(surface)?;
        let (rendered_track, rendered_scrollbar) = rendered;
        let drag_delta = |track: Rect, anchor_y: u16, anchor_offset: u64, state: Scrollbar| {
            let (_, thumb_len) = thumb_geometry(&state, track.height);
            let range = state.total.saturating_sub(state.len);
            let travel = track.height.saturating_sub(thumb_len).max(1) as i128;
            let dy = y as i128 - anchor_y as i128;
            let delta = dy * range as i128 / travel;
            let target = (anchor_offset as i128 + delta).clamp(0, range as i128);
            (target - state.offset as i128).clamp(isize::MIN as i128, isize::MAX as i128) as isize
        };

        if state.track == rendered_track {
            let delta =
                drag_delta(state.track, state.anchor_y, state.anchor_offset, state.scrollbar);
            if let Some(updated) = handle.scroll_delta_if_scrollbar(state.scrollbar, delta) {
                return Some(ScrollbarDragState { position_y: y, scrollbar: updated, ..state });
            }
        }

        let anchor_y = state.position_y;
        let anchor_offset = rendered_scrollbar.offset;
        let delta = drag_delta(rendered_track, anchor_y, anchor_offset, rendered_scrollbar);
        handle.scroll_delta_if_scrollbar(rendered_scrollbar, delta).map(|updated| {
            ScrollbarDragState {
                track: rendered_track,
                anchor_y,
                anchor_offset,
                position_y: y,
                scrollbar: updated,
            }
        })
    }

    fn resize_focused_split(&mut self, delta: f32) {
        let Some(pane) = self.active_pane() else { return };
        let Some(screen) = self.tree.active_screen() else { return };
        if screen.zoomed_pane.is_none()
            && !screen.viewport_splits.is_empty()
            && let Some(owner) = screen.layout.viewport_column_owner(pane, &screen.viewport_splits)
        {
            let current = match owner {
                ViewportColumn::Base => screen.viewport_base_width.unwrap_or(1.0),
                ViewportColumn::Split(split) => {
                    let Some(width) = screen.viewport_splits.get(&split).copied() else {
                        return;
                    };
                    width
                }
            };
            let width = (current + delta).clamp(MIN_VIEWPORT_PANE_WIDTH, MAX_VIEWPORT_PANE_WIDTH);
            if (width - current).abs() >= f32::EPSILON && self.prepare_pty_input_before_mutation() {
                self.session.set_viewport_pane_width(pane, width);
            }
            return;
        }
        let Some(area) = self.pane_areas.iter().find(|area| area.pane == pane) else {
            return;
        };
        let candidates = [
            (SplitEdge::Right, PaneEdge::Right),
            (SplitEdge::Left, PaneEdge::Left),
            (SplitEdge::Bottom, PaneEdge::Bottom),
            (SplitEdge::Top, PaneEdge::Top),
        ];
        let Some((edge, target)) = candidates
            .into_iter()
            .filter_map(|(split_edge, pane_edge)| {
                if screen.viewport_splits.is_empty() {
                    exact_split_for_pane_edge(
                        &screen.layout,
                        self.content_area,
                        Some(screen.active_pane),
                        pane,
                        split_edge,
                    )
                    .map(Into::into)
                } else {
                    exact_split_for_pane_edge_with_viewport(
                        &screen.layout,
                        self.content_area,
                        Some(screen.active_pane),
                        pane,
                        split_edge,
                        screen.viewport_base_width.unwrap_or(1.0),
                        &screen.viewport_splits,
                    )
                }
                .map(|target| (pane_edge, target))
            })
            .filter(|(_, target)| !screen.viewport_splits.contains_key(&target.split))
            .min_by_key(|(_, target)| {
                u128::from(target.area.width) * u128::from(target.area.height)
            })
        else {
            return;
        };
        let pane_rect = self
            .viewport_layout
            .iter()
            .find(|(candidate, _)| *candidate == pane)
            .map_or_else(|| area.rect.into(), |(_, rect)| *rect);
        let (current, sign) = match edge {
            PaneEdge::Left => (
                (pane_rect.x.saturating_sub(target.area.x)) as f32
                    / target.area.width.max(1) as f32,
                -1.0,
            ),
            PaneEdge::Right => (
                (pane_rect.x + pane_rect.width).saturating_sub(target.area.x) as f32
                    / target.area.width.max(1) as f32,
                1.0,
            ),
            PaneEdge::Top => (
                f32::from(pane_rect.y.saturating_sub(target.area.y))
                    / f32::from(target.area.height.max(1)),
                -1.0,
            ),
            PaneEdge::Bottom => (
                f32::from(
                    pane_rect.y.saturating_add(pane_rect.height).saturating_sub(target.area.y),
                ) / f32::from(target.area.height.max(1)),
                1.0,
            ),
        };
        let ratio = clamp_split_ratio_for_tab_bars(
            &screen.layout,
            target.split,
            target.area.height,
            current + delta * sign,
        );
        if self.prepare_pty_input_before_mutation() {
            self.session.set_split_ratio(target.split, ratio);
        }
    }

    fn resolve_pane_resize_drag(
        &self,
        pane: PaneId,
        edge: PaneEdge,
    ) -> Option<PaneResizeDragTarget> {
        if self.content_area.width == 0 {
            return None;
        }
        let screen = self.tree.active_screen()?;
        if screen.zoomed_pane.is_none()
            && !screen.viewport_splits.is_empty()
            && matches!(edge, PaneEdge::Left | PaneEdge::Right)
        {
            let layout = layout_screen_with_viewport(
                &screen.layout,
                self.content_area,
                Some(screen.active_pane),
                screen.viewport_base_width.unwrap_or(1.0),
                &screen.viewport_splits,
            );
            let pane_rect = layout.rect_of(pane)?;
            let pane_right = pane_rect.x.saturating_add(pane_rect.width);
            let index = layout.columns.iter().position(|column| {
                pane_rect.width > 0
                    && pane_rect.x >= column.rect.x
                    && pane_right <= column.rect.x.saturating_add(column.rect.width)
            })?;
            let current = layout.columns[index];
            let target = match edge {
                PaneEdge::Right
                    if pane_right == current.rect.x.saturating_add(current.rect.width) =>
                {
                    Some(current)
                }
                PaneEdge::Left if pane_rect.x == current.rect.x && index > 0 => {
                    Some(layout.columns[index - 1])
                }
                _ => None,
            };
            if let Some(column) = target {
                return Some(PaneResizeDragTarget::ViewportColumn {
                    pane: column.representative,
                    edge,
                    column_x: column.rect.x,
                    viewport_x: self.content_area.x,
                    viewport_width: self.content_area.width,
                    viewport_offset: self.viewport_offset,
                });
            }
        }
        let split_edge = match edge {
            PaneEdge::Left => SplitEdge::Left,
            PaneEdge::Right => SplitEdge::Right,
            PaneEdge::Top => SplitEdge::Top,
            PaneEdge::Bottom => SplitEdge::Bottom,
        };
        let target = if screen.viewport_splits.is_empty() {
            exact_split_for_pane_edge(
                &screen.layout,
                self.content_area,
                Some(screen.active_pane),
                pane,
                split_edge,
            )
            .map(Into::into)
        } else {
            exact_split_for_pane_edge_with_viewport(
                &screen.layout,
                self.content_area,
                Some(screen.active_pane),
                pane,
                split_edge,
                screen.viewport_base_width.unwrap_or(1.0),
                &screen.viewport_splits,
            )
        };
        let target = target?;
        if screen.viewport_splits.contains_key(&target.split) {
            return None;
        }
        let minimum_ratio =
            clamp_split_ratio_for_tab_bars(&screen.layout, target.split, target.area.height, 0.0);
        let maximum_ratio =
            clamp_split_ratio_for_tab_bars(&screen.layout, target.split, target.area.height, 1.0);
        Some(PaneResizeDragTarget::Split {
            split: target.split,
            edge,
            area: target.area,
            minimum_ratio,
            maximum_ratio,
            viewport_x: self.content_area.x,
            viewport_offset: self.viewport_offset,
        })
    }

    fn resize_drag_target(&mut self, target: PaneResizeDragTarget, x: u16, y: u16) {
        match target {
            PaneResizeDragTarget::ViewportColumn {
                pane,
                edge,
                column_x,
                viewport_x,
                viewport_width,
                viewport_offset,
            } => {
                let virtual_x = u64::from(viewport_x)
                    .saturating_add(viewport_offset)
                    .saturating_add(u64::from(x.saturating_sub(viewport_x)));
                let boundary =
                    if edge == PaneEdge::Right { virtual_x.saturating_add(1) } else { virtual_x };
                let cells = boundary.saturating_sub(column_x);
                let width = (((cells as f64) / f64::from(viewport_width)) as f32)
                    .clamp(MIN_VIEWPORT_PANE_WIDTH, MAX_VIEWPORT_PANE_WIDTH);
                if self.prepare_pty_input_before_mutation() {
                    self.session.set_viewport_pane_width_deferred(pane, width);
                }
            }
            PaneResizeDragTarget::Split {
                split,
                edge,
                area,
                minimum_ratio,
                maximum_ratio,
                viewport_x,
                viewport_offset,
            } => {
                let virtual_x = u64::from(viewport_x)
                    .saturating_add(viewport_offset)
                    .saturating_add(u64::from(x.saturating_sub(viewport_x)));
                let (coord, start, extent) = match edge {
                    PaneEdge::Left => (virtual_x, area.x, area.width),
                    PaneEdge::Right => (virtual_x.saturating_add(1), area.x, area.width),
                    PaneEdge::Top => (u64::from(y), u64::from(area.y), u64::from(area.height)),
                    PaneEdge::Bottom => {
                        (u64::from(y.saturating_add(1)), u64::from(area.y), u64::from(area.height))
                    }
                };
                if extent == 0 {
                    return;
                }
                let requested = (coord.saturating_sub(start) as f64 / extent as f64) as f32;
                let ratio = requested.clamp(minimum_ratio, maximum_ratio);
                if self.prepare_pty_input_before_mutation() {
                    self.session.set_split_ratio_deferred(split, ratio);
                }
            }
        }
    }

    fn menu_item(&self, action: MenuAction) -> MenuItem {
        self.menu_action_matches_keyboard_target(action)
            .then(|| keyboard_action_for_menu(action))
            .flatten()
            .and_then(|bound| self.config.keys.shortcut_label(bound))
            .map(|shortcut| MenuItem::ActionWithShortcut { action, shortcut })
            .unwrap_or(MenuItem::Action(action))
    }

    fn menu_action_matches_keyboard_target(&self, action: MenuAction) -> bool {
        match action {
            MenuAction::RenameWorkspace(workspace) | MenuAction::CloseWorkspace(workspace) => {
                self.tree.active_workspace().is_some_and(|active| active.id == workspace)
            }
            MenuAction::RenameScreen(screen) | MenuAction::CloseScreen(screen) => {
                self.tree.active_screen().is_some_and(|active| active.id == screen)
            }
            MenuAction::BrowserBack(pane)
            | MenuAction::BrowserForward(pane)
            | MenuAction::BrowserReload(pane)
            | MenuAction::BrowserEditUrl(pane)
            | MenuAction::RenameTab(pane)
            | MenuAction::NewPaneSmart(pane)
            | MenuAction::NewTab(pane)
            | MenuAction::NewBrowserTab(pane)
            | MenuAction::SplitRight(pane)
            | MenuAction::SplitDown(pane)
            | MenuAction::CloseTab(pane)
            | MenuAction::ClosePane(pane)
            | MenuAction::TogglePaneZoom { pane, .. } => self.active_pane() == Some(pane),
            _ => true,
        }
    }

    fn menu_group(&self, actions: impl IntoIterator<Item = MenuAction>) -> Vec<MenuItem> {
        actions
            .into_iter()
            .filter(|action| {
                keyboard_action_for_menu(*action)
                    .is_none_or(|keyboard_action| self.action_available(keyboard_action))
            })
            .map(|action| self.menu_item(action))
            .collect()
    }

    pub(crate) fn action_available(&self, action: Action) -> bool {
        action_available_in_mode(action, self.surface_only.is_some())
    }

    /// The display label for an action: the localized catalog label, or the
    /// user's configured command name for `Action::UserCommand`.
    pub(crate) fn action_display_label(&self, action: Action) -> &str {
        if let Some(index) = action.user_command_index()
            && let Some(command) = self.config.commands.get(index)
        {
            return command.name.as_str();
        }
        localization::catalog().action_label(action)
    }

    fn sidebar_menu_actions(&self) -> Vec<MenuAction> {
        vec![
            MenuAction::ToggleSidebar { visible: self.sidebar_visible },
            MenuAction::ToggleSidebarCompact { compact: self.sidebar_compact },
            MenuAction::FocusSidebar,
        ]
    }

    fn sidebar_view_name(&self, index: usize) -> String {
        let messages = &localization::catalog().sidebar;
        let Some(view) = self.config.sidebar.views.get(index) else { return String::new() };
        match view.levels.as_slice() {
            [SidebarResourceKind::Machines] => messages.machines.to_string(),
            [SidebarResourceKind::Workspaces] => messages.workspaces.to_string(),
            [SidebarResourceKind::Tabs] => messages.tabs.to_string(),
            _ => view.id.clone(),
        }
    }

    fn sidebar_view_visibility_item(&self, index: usize) -> Option<MenuItem> {
        let view = self.config.sidebar.views.get(index)?;
        let hidden = self
            .hidden_sidebar_views
            .get(&self.config.sidebar.active_profile)
            .is_some_and(|hidden| hidden.contains(&view.id));
        let template = if hidden {
            localization::catalog().menu.show_sidebar_view
        } else {
            localization::catalog().menu.hide_sidebar_view
        };
        Some(MenuItem::LabeledAction {
            label: template.replace("{view}", &self.sidebar_view_name(index)),
            action: MenuAction::SetSidebarViewVisible { view: index, visible: hidden },
        })
    }

    fn sidebar_presentation_menu_item(&self) -> MenuItem {
        let mut items = Vec::new();
        if self.config.sidebar.profiles.len() > 1 {
            items.push(MenuItem::Submenu {
                label: localization::catalog().menu.sidebar_profiles.to_string(),
                items: self
                    .config
                    .sidebar
                    .profiles
                    .iter()
                    .enumerate()
                    .map(|(index, profile)| MenuItem::LabeledAction {
                        label: format!(
                            "{}{}",
                            if profile.id == self.config.sidebar.active_profile {
                                "✓ "
                            } else {
                                "  "
                            },
                            profile.name
                        ),
                        action: MenuAction::ActivateSidebarProfile(index),
                    })
                    .collect(),
            });
        }
        if !self.config.sidebar.views.is_empty() {
            if !items.is_empty() {
                items.push(MenuItem::Separator);
            }
            items.extend(
                (0..self.config.sidebar.views.len())
                    .filter_map(|index| self.sidebar_view_visibility_item(index)),
            );
        }
        MenuItem::Submenu { label: localization::catalog().menu.sidebar_layout.to_string(), items }
    }

    fn global_menu_items(&self) -> Vec<MenuItem> {
        let mut items =
            self.menu_group([MenuAction::ToggleSidebar { visible: self.sidebar_visible }]);
        if self.surface_only.is_none() {
            items.push(self.sidebar_presentation_menu_item());
        }
        items.push(self.menu_item(MenuAction::ShowShortcuts));
        items
    }

    fn set_sidebar_view_visible(&mut self, index: usize, visible: bool) {
        let Some(view) = self.config.sidebar.views.get(index) else { return };
        let view_id = view.id.clone();
        let hides_focused = !visible && self.focused_sidebar_view_id().as_deref() == Some(&view_id);
        let hidden = self
            .hidden_sidebar_views
            .entry(self.config.sidebar.active_profile.clone())
            .or_default();
        if visible {
            hidden.remove(&view_id);
            self.sidebar_visible = true;
        } else {
            hidden.insert(view_id);
            if hides_focused {
                self.focus = FocusTarget::Pane;
            }
        }
    }

    fn activate_sidebar_profile(&mut self, index: usize) {
        let Some(profile) = self.config.sidebar.profiles.get(index).cloned() else { return };
        let focused_view = self.focused_sidebar_view_id();
        self.config.sidebar.active_profile = profile.id;
        self.config.sidebar.views = profile.views;
        self.config.sidebar.columns = self
            .config
            .sidebar
            .views
            .iter()
            .filter_map(|view| {
                view.legacy_kind().map(|kind| SidebarColumn {
                    kind,
                    width: view.width,
                    max_width: view.max_width,
                })
            })
            .collect();
        self.sidebar_visible = true;
        if let Some(focused_view) = focused_view {
            let hidden = self
                .hidden_sidebar_views
                .get(&self.config.sidebar.active_profile)
                .is_some_and(|hidden| hidden.contains(&focused_view));
            if !hidden
                && let Some(index) =
                    self.config.sidebar.views.iter().position(|view| view.id == focused_view)
            {
                self.focus_rail(self.rail_kind_for_view(index));
                return;
            }
            self.focus = FocusTarget::Pane;
        }
    }

    fn open_context_menu(&mut self, x: u16, y: u16) {
        self.build_context_menu(x, y);
        self.capture_menu_resources();
    }

    fn capture_menu_resources(&mut self) {
        let captured_resources = self.menu.as_ref().map(|menu| {
            menu.actions()
                .into_iter()
                .map(|action| (action, self.menu_action_resource(action)))
                .collect()
        });
        if let (Some(menu), Some(captured_resources)) = (&mut self.menu, captured_resources) {
            menu.captured_resources = captured_resources;
        }
    }

    fn build_context_menu(&mut self, x: u16, y: u16) {
        self.cancel_pty_mouse_drag();
        self.menu = None;
        self.omnibar = None;
        self.session.refresh_clients_background();
        let hit = self.hit_at(x, y);
        if matches!(hit, Some(Hit::StatusMessage)) {
            self.menu = Some(ContextMenu::with_groups(
                x,
                y,
                vec![self.menu_group([MenuAction::CopyStatusMessage]), self.global_menu_items()],
            ));
            return;
        }
        // Configurable `+` buttons: a right click opens their configured
        // menu when one exists; without one the generic paths below apply.
        if let Some(Hit::NewTab { pane }) = hit {
            let items = self.plus_menu_items(&self.config.tabs.plus, Some(pane));
            if !items.is_empty() {
                self.menu =
                    Some(ContextMenu::with_groups(x, y, vec![items, self.global_menu_items()]));
                return;
            }
        }
        // "+ new vm" and the machine rail's top pad carry the provider
        // scope switcher and provider actions since their dedicated rail
        // rows were removed (`m` is the keyboard twin).
        if matches!(hit, Some(Hit::NewVm) | Some(Hit::RailPad(RailKind::Machine)))
            && self.open_provider_rail_menu(x, y)
        {
            return;
        }
        if matches!(hit, Some(Hit::NewScreen)) {
            let items =
                self.plus_menu_items(&self.config.status_bar.screens_plus, self.active_pane());
            if !items.is_empty() {
                self.menu =
                    Some(ContextMenu::with_groups(x, y, vec![items, self.global_menu_items()]));
                return;
            }
        }
        if self.total_sidebar_width() > 0 && x < self.total_sidebar_width() {
            let mut groups = Vec::new();
            match hit {
                Some(Hit::Machine { key, .. }) => {
                    if let Some(machine) = self.managed_machine(key) {
                        let mut actions = Vec::new();
                        match machine.status {
                            ManagedMachineStatus::Active => {
                                if machine.capabilities.rename {
                                    actions.push(MenuAction::RenameManagedMachine(key));
                                }
                                if machine.capabilities.delete {
                                    actions.push(MenuAction::DeleteManagedMachine(key));
                                }
                            }
                            ManagedMachineStatus::Recoverable => {
                                if machine.capabilities.restore {
                                    actions.push(MenuAction::RestoreManagedMachine(key));
                                }
                                if machine.capabilities.purge {
                                    actions.push(MenuAction::PurgeManagedMachine(key));
                                }
                            }
                        }
                        groups.push(self.menu_group(actions));
                    } else if self
                        .machine_ui
                        .as_ref()
                        .is_some_and(|ui| ui.is_client_machine_renamable(key))
                    {
                        groups.push(self.menu_group([MenuAction::RenameClientMachine(key)]));
                    }
                }
                Some(Hit::Workspace { id, .. }) => {
                    if self.provider_manages_current_workspace_session() {
                        if let Some(workspace) = self.managed_workspace_for_view(id) {
                            let mut actions = Vec::new();
                            if workspace.capabilities.rename {
                                actions.push(MenuAction::RenameManagedWorkspace(id));
                            }
                            if workspace.capabilities.delete {
                                actions.push(MenuAction::DeleteManagedWorkspace(id));
                            }
                            groups.push(self.menu_group(actions));
                        }
                    } else {
                        groups.push(self.menu_group([
                            MenuAction::RenameWorkspace(id),
                            MenuAction::CloseWorkspace(id),
                        ]));
                        groups.push(self.menu_group([MenuAction::CopyWorkspaceId(id)]));
                    }
                }
                Some(Hit::RecoverableWorkspace { index }) => {
                    if let Some(workspace) = self
                        .machine_ui
                        .as_ref()
                        .and_then(|ui| ui.recoverable_workspaces().get(index).copied())
                    {
                        let mut actions = Vec::new();
                        if workspace.capabilities.restore {
                            actions.push(MenuAction::RestoreManagedWorkspace(index));
                        }
                        if workspace.capabilities.purge {
                            actions.push(MenuAction::PurgeManagedWorkspace(index));
                        }
                        groups.push(self.menu_group(actions));
                    }
                }
                Some(Hit::SidebarTab { surface, .. }) => {
                    groups.push(self.menu_group([MenuAction::RenameSurface(surface)]));
                }
                Some(Hit::ProjectionRow {
                    target: ProjectionTarget::Workspace { id, .. }, ..
                })
                | Some(Hit::ProjectionToggle { branch: ProjectionBranch::Workspace(id), .. }) => {
                    if self.provider_manages_current_workspace_session() {
                        if let Some(workspace) = self.managed_workspace_for_view(id) {
                            let mut actions = Vec::new();
                            if workspace.capabilities.rename {
                                actions.push(MenuAction::RenameManagedWorkspace(id));
                            }
                            if workspace.capabilities.delete {
                                actions.push(MenuAction::DeleteManagedWorkspace(id));
                            }
                            groups.push(self.menu_group(actions));
                        }
                    } else {
                        groups.push(self.menu_group([
                            MenuAction::RenameWorkspace(id),
                            MenuAction::CloseWorkspace(id),
                        ]));
                        groups.push(self.menu_group([MenuAction::CopyWorkspaceId(id)]));
                    }
                }
                Some(Hit::ProjectionRow {
                    target: ProjectionTarget::Surface { surface, .. },
                    ..
                }) => {
                    groups.push(self.menu_group([MenuAction::RenameSurface(surface)]));
                }
                _ => {}
            }
            if let Some(view_index) = self
                .sidebar_layout
                .ordered
                .iter()
                .find(|placement| placement.rect.contains(x, y))
                .map(|placement| placement.view_index)
                && let Some(item) = self.sidebar_view_visibility_item(view_index)
            {
                groups.push(vec![item]);
            }
            groups.push(self.menu_group(self.sidebar_menu_actions()));
            groups.push(vec![self.sidebar_presentation_menu_item()]);
            groups.push(self.menu_group([MenuAction::ShowShortcuts]));
            self.menu = Some(ContextMenu::with_groups(x, y, groups));
            // Provider scope/action entries dispatch by displayed index;
            // capture the stable resources behind them (see the identity
            // tests) exactly like the dedicated menus used to.
            self.capture_menu_resources();
            return;
        }
        match hit {
            Some(Hit::Tab { pane, index }) => {
                let Some(surface) = self
                    .tree
                    .pane(pane)
                    .and_then(|pane| pane.tabs.get(index))
                    .map(|tab| tab.surface)
                else {
                    return;
                };
                let is_browser = self.surface_kind(surface) == Some(SurfaceKind::Browser);
                let external_browser =
                    self.browser_source(surface) == Some(BrowserSource::External);
                let mut actions = pane_context_menu_groups(pane, is_browser, external_browser);
                if let Some(rename) = actions.first_mut().and_then(|group| group.first_mut()) {
                    *rename = MenuAction::RenameSurface(surface);
                }
                let mut groups = actions
                    .into_iter()
                    .map(|group| self.menu_group(group))
                    .collect::<Vec<Vec<MenuItem>>>();
                if self.surface_only.is_none() {
                    let zoomed = self
                        .tree
                        .active_screen()
                        .is_some_and(|screen| screen.zoomed_pane == Some(pane));
                    groups.push(self.menu_group([MenuAction::TogglePaneZoom { pane, zoomed }]));
                }
                if self.surface_only.is_none()
                    && let Some(clients) = client_menu_item(&self.clients, surface)
                {
                    groups.push(vec![clients]);
                }
                groups.push(self.global_menu_items());
                self.menu = Some(ContextMenu::with_groups(x, y, groups));
                return;
            }
            Some(Hit::ScreenEntry { id, .. }) => {
                self.menu = Some(ContextMenu::with_groups(
                    x,
                    y,
                    vec![
                        self.menu_group([
                            MenuAction::RenameScreen(id),
                            MenuAction::CloseScreen(id),
                        ]),
                        self.global_menu_items(),
                    ],
                ));
                return;
            }
            Some(Hit::Clients { surface }) => {
                self.open_clients_menu(x, y, surface);
                return;
            }
            _ => {}
        }
        if let Some(area) = self.pane_area_at(x, y) {
            let is_browser = self.surface_kind(area.surface) == Some(SurfaceKind::Browser);
            let external_browser =
                self.browser_source(area.surface) == Some(BrowserSource::External);
            let mut groups = pane_context_menu_groups(area.pane, is_browser, external_browser)
                .into_iter()
                .map(|group| self.menu_group(group))
                .collect::<Vec<Vec<MenuItem>>>();
            if self.surface_only.is_none() {
                let zoomed = self
                    .tree
                    .active_screen()
                    .is_some_and(|screen| screen.zoomed_pane == Some(area.pane));
                groups.push(
                    self.menu_group([MenuAction::TogglePaneZoom { pane: area.pane, zoomed }]),
                );
            }
            if self.surface_only.is_none()
                && let Some(clients) = client_menu_item(&self.clients, area.surface)
            {
                groups.push(vec![clients]);
            }
            groups.push(self.global_menu_items());
            self.menu = Some(ContextMenu::with_groups(x, y, groups));
            return;
        }
        self.menu = Some(ContextMenu::with_groups(x, y, vec![self.global_menu_items()]));
    }

    fn replace_clients(&mut self, clients: Vec<ClientInfo>) {
        self.client_border_labels = crate::ui::pane::client_border_labels(&clients);
        self.clients = clients;
    }

    fn open_clients_menu(&mut self, x: u16, y: u16, surface: SurfaceId) {
        self.session.refresh_clients_background();
        let mut groups = Vec::new();
        if let Some(MenuItem::Submenu { items, .. }) = client_menu_item(&self.clients, surface) {
            groups.push(items);
        }
        groups.push(self.global_menu_items());
        self.menu = Some(ContextMenu::with_groups(x, y, groups));
    }

    #[cfg(test)]
    fn handle_scroll(
        &mut self,
        x: u16,
        y: u16,
        down: bool,
        modifiers: KeyModifiers,
    ) -> anyhow::Result<RenderAction> {
        self.handle_scroll_with_admission(x, y, down, modifiers, None)
    }

    fn handle_scroll_with_admission(
        &mut self,
        x: u16,
        y: u16,
        down: bool,
        modifiers: KeyModifiers,
        terminal_admission: Option<TerminalPointerAdmission>,
    ) -> anyhow::Result<RenderAction> {
        if let Some(menu) = self.menu.as_mut() {
            return Ok(if menu.scroll_at(x, y, down) {
                RenderAction::Draw
            } else {
                RenderAction::None
            });
        }
        if self.prompt.is_some() {
            return Ok(RenderAction::None);
        }
        if let Some(area) = self
            .machine_sidebar_area(self.content_area.height.saturating_add(1))
            .filter(|area| area.contains(x, y))
        {
            let footer_rows = self.machine_ui.as_ref().map_or(0, |ui| {
                usize::from(ui.snapshot.capabilities.create)
                    + usize::from(ui.snapshot.capabilities.connect)
            });
            let footer_is_clipped = footer_rows > usize::from(area.height.saturating_sub(2));
            if footer_is_clipped {
                self.machine_footer_scroll = if down {
                    self.machine_footer_scroll.saturating_add(1)
                } else {
                    self.machine_footer_scroll.saturating_sub(1)
                };
            } else {
                self.machine_rail_scroll = if down {
                    self.machine_rail_scroll.saturating_add(3)
                } else {
                    self.machine_rail_scroll.saturating_sub(3)
                };
            }
            self.machine_rail_follow_selection = false;
            return Ok(RenderAction::Draw);
        }
        if let Some(area) = (self.config.sidebar.plugin.is_none()
            && self.sidebar_view == SidebarView::Workspaces)
            .then(|| self.workspace_sidebar_area(self.content_area.height.saturating_add(1)))
            .flatten()
            .filter(|area| area.contains(x, y))
        {
            let footer_rows = self.workspace_sidebar_action_rows().len();
            let footer_is_clipped = footer_rows > usize::from(area.height.saturating_sub(2));
            if footer_is_clipped {
                self.workspace_footer_scroll = if down {
                    self.workspace_footer_scroll.saturating_add(1)
                } else {
                    self.workspace_footer_scroll.saturating_sub(1)
                };
            } else {
                self.workspace_rail_scroll = if down {
                    self.workspace_rail_scroll.saturating_add(3)
                } else {
                    self.workspace_rail_scroll.saturating_sub(3)
                };
            }
            self.workspace_rail_follow_selection = false;
            return Ok(RenderAction::Draw);
        }
        if let Some(_area) = self
            .tabs_sidebar_area(self.content_area.height.saturating_add(1))
            .filter(|area| area.contains(x, y))
        {
            self.tabs_rail_scroll = if down {
                self.tabs_rail_scroll.saturating_add(3)
            } else {
                self.tabs_rail_scroll.saturating_sub(3)
            };
            self.tabs_rail_follow_selection = false;
            return Ok(RenderAction::Draw);
        }
        if let Some(view_index) = self.sidebar_layout.ordered.iter().find_map(|placement| {
            matches!(placement.kind, RailKind::Projection(_))
                .then_some((placement.view_index, placement.rect))
                .filter(|(_, area)| area.contains(x, y))
                .map(|(view_index, _)| view_index)
        }) {
            let footer_rows = self.sidebar_action_rows(view_index).len();
            let footer_is_clipped = self
                .projection_sidebar_area(view_index)
                .is_some_and(|area| footer_rows > usize::from(area.height.saturating_sub(2)));
            let state = self.projection_rail_state_mut(view_index);
            if footer_is_clipped {
                state.footer_scroll = if down {
                    state.footer_scroll.saturating_add(1)
                } else {
                    state.footer_scroll.saturating_sub(1)
                };
            } else {
                state.scroll = if down {
                    state.scroll.saturating_add(3)
                } else {
                    state.scroll.saturating_sub(3)
                };
            }
            state.follow_selection = false;
            return Ok(RenderAction::Draw);
        }
        let Some(area) = self.pane_area_at(x, y).copied() else { return Ok(RenderAction::None) };
        if self.surface_kind(area.surface) == Some(SurfaceKind::Pty)
            && area.content.contains(x, y)
            && !self.terminal_input_rect(&area).is_some_and(|rect| rect.contains(x, y))
        {
            return Ok(RenderAction::None);
        }
        if self.active_pane() != Some(area.pane) {
            self.focus_pane_after_input(area.pane);
        }
        // Wheel over the tab bar scrolls the tabs, not the terminal.
        if area.bar.is_some_and(|bar| bar.contains(x, y)) {
            self.scroll_tabs(area.pane, if down { 1 } else { -1 });
            return Ok(RenderAction::Draw);
        }
        let (surface_id, _) = (area.surface, area.pane);
        let Some(surface) = self.session.surface(surface_id) else { return Ok(RenderAction::None) };
        if surface.kind() == SurfaceKind::Browser {
            if area.content.contains(x, y) {
                let Some(frame_seq) = self.processed_browser_pointer_authority(surface_id) else {
                    return Ok(RenderAction::None);
                };
                let (px, py) = self.browser_point(surface_id, area.content, x, y);
                let delta = if down { 3.0 } else { -3.0 } * f64::from(self.cell_pixels.1);
                let _ = self.browser_input.enqueue(BrowserInputEvent {
                    surface_id,
                    surface,
                    kind: BrowserInputKind::Wheel { x: px, y: py, delta_y: delta, frame_seq },
                });
                return Ok(RenderAction::Draw);
            }
            return Ok(RenderAction::None);
        }
        let canonical_content = self.canonical_pty_content(surface_id, area.logical_content_rect());
        let (logical_x, logical_y) = area.logical_content_point(x, y);
        if !canonical_content.contains(logical_x, logical_y) {
            return Ok(RenderAction::None);
        }
        if area.content.contains(x, y) {
            let forwarded = self.forward_pty_mouse_at_with_admission(
                (x, y),
                MouseAction::Press,
                Some(if down {
                    GhosttyMouseButton::WheelDown
                } else {
                    GhosttyMouseButton::WheelUp
                }),
                modifiers,
                false,
                terminal_admission.clone(),
            );
            match forwarded {
                None => return Ok(RenderAction::None),
                Some(true) => return Ok(RenderAction::Draw),
                Some(false) => {}
            }
        }
        let sent_arrows = if let Some(admission) = terminal_admission {
            if admission.surface != surface_id {
                return Ok(RenderAction::None);
            }
            admission.semantics.active_screen == Screen::Alternate
                && !admission.semantics.mouse_tracking
        } else {
            let Some(sent_arrows) = surface.with_terminal(|term| {
                term.active_screen() == Screen::Alternate && !term.mouse_tracking()
            }) else {
                return Ok(RenderAction::None);
            };
            sent_arrows
        };
        if sent_arrows {
            let _ = surface.scroll_to_bottom();
            // Alt-screen apps without mouse support get arrow keys
            // (the usual alternate-scroll behavior).
            let seq: &[u8] = if down { b"\x1b[B\x1b[B\x1b[B" } else { b"\x1b[A\x1b[A\x1b[A" };
            let _ = self.write_pty_bytes(
                surface_id,
                surface,
                PtyInputBytes::from_slice(seq),
                PtyInputKind::Ordered,
            );
        } else {
            let _ = surface.scroll_delta(if down { 3 } else { -3 });
        }
        Ok(RenderAction::Draw)
    }

    #[cfg(test)]
    fn handle_horizontal_scroll(
        &mut self,
        x: u16,
        y: u16,
        right: bool,
        modifiers: KeyModifiers,
    ) -> anyhow::Result<RenderAction> {
        self.handle_horizontal_scroll_with_admission(x, y, right, modifiers, None)
    }

    fn handle_horizontal_scroll_with_admission(
        &mut self,
        x: u16,
        y: u16,
        right: bool,
        modifiers: KeyModifiers,
        terminal_admission: Option<TerminalPointerAdmission>,
    ) -> anyhow::Result<RenderAction> {
        if self.menu.is_some() || self.prompt.is_some() {
            return Ok(RenderAction::None);
        }
        let over_scrollbar = matches!(self.hit_at(x, y), Some(Hit::HorizontalScrollbar { .. }));
        let over_pane = self.pane_area_at(x, y).is_some();
        if self.horizontal_scrollbar_state().is_some() && (over_scrollbar || over_pane) {
            let step = (self.content_area.width / 6).max(1) as i16;
            self.scroll_horizontal_viewport(if right { step } else { -step }, true);
            return Ok(RenderAction::Draw);
        }
        let Some(area) = self.pane_area_at(x, y).copied() else {
            return Ok(RenderAction::None);
        };
        if self.surface_kind(area.surface) == Some(SurfaceKind::Pty)
            && area.content.contains(x, y)
            && !self.terminal_input_rect(&area).is_some_and(|rect| rect.contains(x, y))
        {
            return Ok(RenderAction::None);
        }
        if self.active_pane() != Some(area.pane) {
            self.focus_pane_after_input(area.pane);
        }
        if self.surface_kind(area.surface) == Some(SurfaceKind::Pty) && {
            let content = self.canonical_pty_content(area.surface, area.logical_content_rect());
            let (x, y) = area.logical_content_point(x, y);
            !content.contains(x, y)
        } {
            return Ok(RenderAction::None);
        }
        if area.content.contains(x, y) {
            let forwarded = self.forward_pty_mouse_at_with_admission(
                (x, y),
                MouseAction::Press,
                Some(if right {
                    GhosttyMouseButton::WheelRight
                } else {
                    GhosttyMouseButton::WheelLeft
                }),
                modifiers,
                false,
                terminal_admission,
            );
            return Ok(match forwarded {
                Some(true) => RenderAction::Draw,
                Some(false) | None => RenderAction::None,
            });
        }
        Ok(RenderAction::None)
    }

    fn surface_kind(&self, surface: SurfaceId) -> Option<SurfaceKind> {
        self.tab_locations
            .get(&surface)
            .and_then(|[workspace, screen, pane, tab]| {
                self.tree
                    .workspaces
                    .get(*workspace)
                    .and_then(|workspace| workspace.screens.get(*screen))
                    .and_then(|screen| screen.panes.get(*pane))
                    .and_then(|pane| pane.tabs.get(*tab))
            })
            .map(|tab| tab.kind)
            .or_else(|| self.session.surface(surface).map(|surface| surface.kind()))
    }

    fn browser_source(&self, surface: SurfaceId) -> Option<BrowserSource> {
        self.tree
            .workspaces
            .iter()
            .flat_map(|ws| ws.screens.iter())
            .flat_map(|screen| screen.panes.iter())
            .flat_map(|pane| pane.tabs.iter())
            .find(|tab| tab.surface == surface)
            .and_then(|tab| tab.browser_source)
    }

    fn browser_point(&self, surface: SurfaceId, content: Rect, x: u16, y: u16) -> (f64, f64) {
        let source_x = self
            .pane_areas
            .iter()
            .find(|area| area.surface == surface)
            .map_or(0, PaneArea::content_source_x);
        let col = source_x.saturating_add(x.saturating_sub(content.x)) as f64 + 0.5;
        let row = y.saturating_sub(content.y) as f64 + 0.5;
        (col * f64::from(self.cell_pixels.0), row * f64::from(self.cell_pixels.1))
    }

    fn processed_browser_pointer_authority(&self, surface: SurfaceId) -> Option<u64> {
        match self.rendered_pointer_frame.pane_content_generations.get(&surface) {
            Some(PaneContentGeneration::Browser(frame_seq)) => Some(*frame_seq),
            Some(PaneContentGeneration::Terminal(_)) | None => None,
        }
    }

    /// Queue a mouse event for the off-loop browser input worker; the
    /// event loop never waits on the CDP/socket round trip.
    fn send_browser_mouse(
        &self,
        surface_id: SurfaceId,
        content: Rect,
        x: u16,
        y: u16,
        frame_seq: u64,
        dispatch: BrowserMouseDispatch,
    ) -> bool {
        if !self.session_available() {
            return false;
        }
        let Some(surface) = self.session.surface(surface_id) else { return false };
        let (px, py) = self.browser_point(surface_id, content, x, y);
        self.browser_input.enqueue(BrowserInputEvent {
            surface_id,
            surface,
            kind: BrowserInputKind::Mouse {
                event_type: dispatch.event_type,
                x: px,
                y: py,
                button: dispatch.button,
                click_count: dispatch.click_count,
                frame_seq,
            },
        })
    }
}

fn canonical_terminal_content(content: Rect, rendered_size: Option<(u16, u16)>) -> Rect {
    let (cols, rows) = rendered_size.unwrap_or((content.width, content.height));
    Rect {
        x: content.x,
        y: content.y,
        width: content.width.min(cols),
        height: content.height.min(rows),
    }
}

fn outer_cursor_escape_if_changed(
    applied: Option<OuterCursorSpec>,
    desired: OuterCursorSpec,
) -> Option<String> {
    (applied != Some(desired)).then(|| outer_cursor_escape(desired))
}

/// Host input modes asserted at client startup, before any inner-terminal
/// state is known. A scoped single-terminal attach (`attach --terminal`) is a
/// transparent passthrough: it must not assert mouse capture or the
/// shift-bypass report on the host, because the host terminal owns clicks and
/// selection until the inner application requests mouse tracking. Focus
/// reporting and bracketed paste stay enabled in both modes: the client
/// consumes those events itself and re-encodes paste for the inner terminal
/// according to the mode the inner application actually requested, so they
/// are transparent to the user.
fn host_startup_input_modes(surface_only: bool) -> String {
    let mut out = String::new();
    if !surface_only {
        out.push_str(&host_mouse_capture_sequence(true));
    }
    let _ = crossterm::Command::write_ansi(&EnableFocusChange, &mut out);
    let _ = crossterm::Command::write_ansi(&EnableBracketedPaste, &mut out);
    out
}

fn host_mouse_capture_sequence(enable: bool) -> String {
    let mut out = String::new();
    if enable {
        let _ = crossterm::Command::write_ansi(&EnableMouseCapture, &mut out);
        // Ask the host terminal to report Shift-modified mouse events so
        // Shift remains cmux's selection/context-menu escape while the inner
        // application owns ordinary mouse input.
        out.push_str("\x1b[>1s");
    } else {
        // Restore the conventional behavior where Shift bypasses capture.
        out.push_str("\x1b[>0s");
        let _ = crossterm::Command::write_ansi(&DisableMouseCapture, &mut out);
    }
    out
}

fn host_mouse_capture_escape_if_changed(applied: Option<bool>, desired: bool) -> Option<String> {
    (applied != Some(desired)).then(|| host_mouse_capture_sequence(desired))
}

/// Initial host-cursor bookkeeping. A full TUI starts with unknown applied
/// state, so its first frame restores host cursor globals to defaults. A
/// scoped attach starts from an applied Reset so it emits no cursor escapes
/// until the inner application authors a cursor style.
fn initial_applied_outer_cursor(surface_only: bool) -> Option<OuterCursorSpec> {
    surface_only.then_some(OuterCursorSpec::Reset)
}

/// Startup already asserted capture for full-TUI clients and asserted
/// nothing for scoped attach clients.
fn initial_host_mouse_capture(surface_only: bool) -> Option<bool> {
    Some(!surface_only)
}

fn outer_cursor_escape(spec: OuterCursorSpec) -> String {
    match spec {
        OuterCursorSpec::Reset => "\x1b]112\x07\x1b[0 q".to_string(),
        OuterCursorSpec::Terminal { color, shape, blinking } => {
            let style = match (shape, blinking) {
                (CursorShape::Block, true) => 1,
                (CursorShape::Block, false) => 2,
                (CursorShape::Underline, true) => 3,
                (CursorShape::Underline, false) => 4,
                (CursorShape::Bar, true) => 5,
                (CursorShape::Bar, false) => 6,
                // DECSCUSR has no hollow-block form. A steady block preserves
                // shape and avoids inventing blink behavior.
                (CursorShape::BlockHollow, _) => 2,
            };
            format!("\x1b]12;#{:02x}{:02x}{:02x}\x07\x1b[{style} q", color.r, color.g, color.b)
        }
    }
}

fn browser_modifiers(modifiers: KeyModifiers) -> Option<u32> {
    if modifiers.contains(KeyModifiers::HYPER) {
        return None;
    }
    let mut out = 0;
    if modifiers.contains(KeyModifiers::ALT) {
        out |= 1;
    }
    if modifiers.contains(KeyModifiers::CONTROL) {
        out |= 2;
    }
    if modifiers.intersects(KeyModifiers::SUPER | KeyModifiers::META) {
        out |= 4;
    }
    if modifiers.contains(KeyModifiers::SHIFT) {
        out |= 8;
    }
    Some(out)
}

